window.EXPL={"공인회2016_51-01-4":{"f":"소득세는 납세의무자가 과세표준 및 세액을 정부에 신고하는 때에 그 납세의무가 확정되지만, 신고의 내용에 잘못이 있는 경우에는 정부가 새로이 확정시킬 수 있고 정부가 스스로 확정한 세액도 다시 고칠 수 있다.","w":"소득세는 신고하는 때 확정되고, 신고 내용에 탈루나 오류가 있으면 정부가 경정한다. 정부가 결정·경정한 뒤에도 탈루나 오류가 발견되면 즉시 다시 경정한다(국세기본법 제22조 제2항, 소득세법 제80조 제4항).","c":"중","v":1},"공인회2016_51-03-5":{"f":"법인이 해산한 경우 그 법인에 부과된 세금을 다 내지 아니하고 잔여재산을 분배하였을 때에 해당 법인의 납세의무를 2차적으로 부담하는 자는 잔여재산의 분배업무를 처리한 청산인과 그 잔여재산을 가져간 출자자이다.","w":"해산한 법인이 세금을 내지 않고 잔여재산을 나누면 청산인과 잔여재산을 분배받은 자가 모두 제2차 납세의무를 진다(국세기본법 제38조). 분배받은 자는 받은 재산가액이 한도다.","c":"상","v":1},"공인회2016_51-05-2":{"f":"납세의무자 을이 300만원의 소득세를 법에서 정한 기한이 지난 후 6개월 내에 신고한 경우 기한후신고만으로는 세액이 확정되지 않고 세무서장이 결정·통지하는 때 확정된다.","w":"기한후신고는 신고서를 낸 것만으로 세액이 확정되지 않는다. 세무서장이 신고일부터 3개월 이내에 결정해 통지하면 그때 확정된다(국세기본법 제45조의3).","c":"상","v":1},"공인회2017_52-02-1":{"f":"국외에 있는 상속재산을 상속인이 취득하면서 사기나 그 밖의 부정한 행위로 상속세를 포탈한 경우라도, 상속인이 사망하였다면 해당 재산의 상속이 있음을 안 날부터 1년 이내에 상속세를 부과할 수 있는 특례는 적용되지 않는다.","w":"국외 상속재산을 부정행위로 포탈한 경우 상속이 있음을 안 날부터 1년 이내에 부과할 수 있는 특례가 있다. 다만 상속인이 사망한 경우와 포탈 기준 재산가액이 50억원 이하인 경우에는 이 특례를 적용하지 않는다(국세기본법 제26조의2 제5항).","c":"상","v":1},"공인회2017_52-04-1":{"f":"세무조사 결과통지 및 과세예고통지를 하는 날부터 국세부과 제척기간의 만료일까지의 기간이 3개월 이하인 경우에는 과세전적부심사를 청구할 수 없다.","w":"제척기간 만료가 3개월 이하로 임박하면 청구할 수 없다. 6개월이 남은 경우에는 청구할 수 있다(국세기본법 제81조의15).","c":"상","v":1},"공인회2018_53-01-1":{"f":"가산세의 납세의무 성립시기는 가산할 국세의 납세의무가 성립하는 때이다.","w":"가산세는 본세의 납세의무가 성립하는 때 함께 성립한다(국세기본법 제21조). 확정되는 때가 아니다. 무신고가산세 등은 법정신고기한이 지나는 때 성립하는 예외가 있다.","c":"상","v":1},"공인회2018_53-01-2":{"f":"원천징수하는 소득세·법인세는 소득금액 또는 수입금액을 지급하는 때에 납세의무가 성립하고 성립과 동시에 확정된다.","w":"원천징수 소득세·법인세는 지급하는 달의 말일이 아니라 지급하는 때에 성립하고 특별한 절차 없이 확정된다(국세기본법 제21조, 제22조).","c":"상","v":1},"공인회2018_53-01-3":{"f":"10억원의 국세에 대한 징수권은 이를 행사할 수 있는 때부터 10년 동안 행사하지 않으면 소멸시효가 완성된다.","w":"징수권은 5억원 이상이면 10년, 5억원 미만이면 5년이다(국세기본법 제27조). 10억원이므로 10년이다.","c":"상","v":1},"공인회2018_53-01-4":{"f":"사기로 법인세를 포탈한 경우 그 법인세를 부과할 수 있는 날부터 10년의 기간이 끝난 날 이후에는 부과할 수 없다.","w":"부정행위로 국세를 포탈한 경우의 부과제척기간은 기산일(부과할 수 있는 날)부터 10년이다. 상속세·증여세는 15년이다(국세기본법 제26조의2).","c":"상","v":1},"공인회2018_53-02-3":{"f":"사업소득이 발생하는「소득세법」에 따른 공동사업의 소득금액에 대해서는 공동사업자 각자가 분배받은 소득금액에 대하여 소득세 납세의무를 진다.","w":"공동사업 소득은 공동사업자별로 납세의무를 진다. 다만 특수관계인끼리의 공동사업이어서 주된 공동사업자에게 소득이 합산과세되면, 그 특수관계인은 자기 손익분배비율 몫을 한도로 주된 공동사업자와 연대하여 납세의무를 진다(소득세법 제2조의2 제1항).","c":"상","v":1},"공인회2018_53-03-4":{"f":"납세자가 상속세를 물납(2017년 2월 5일)한 후 그 부과의 일부를 감액하는 경정 결정에 따라 환급하는 경우에는 해당 물납재산으로 환급하여야 하며, 이 경우 국세환급가산금은 지급하지 아니한다.","w":"물납재산으로 환급할 때는 금전이 아닌 재산으로 돌려주므로 환급가산금을 붙이지 않는다. 물납재산이 없어지는 등 환급할 수 없을 때에는 금전으로 환급한다.","c":"중","v":1},"공인회2018_53-05-5":{"f":"심사청구 또는 심판청구에 대한 재조사 결정에 따른 처분청의 처분에 대해서는 심사청구 또는 심판청구를 거치지 않고도 행정소송을 제기할 수 있다.","w":"국세 처분에 대한 행정소송은 심사청구나 심판청구를 거쳐야 하는 것이 원칙이지만, 재조사 결정에 따른 처분청의 처분에 대한 행정소송은 이 절차를 거치지 않아도 된다(국세기본법 제56조 제2항 단서). 이때는 처분 결과 통지를 받은 날부터 90일 이내에 제기한다.","c":"상","v":1},"공인회2019_54-01-1":{"f":"둘 이상의 행위 또는 거래를 거치는 방법으로 세법의 혜택을 부당하게 받기 위한 것으로 인정되는 경우에는 그 경제적 실질 내용에 따라 연속된 하나의 행위 또는 거래로 보아 세법을 적용한다.","w":"거래를 쪼개 세 부담을 줄이는 경우 하나의 거래로 재구성해 과세한다(국세기본법 제14조 제3항). 각 거래를 따로 기준으로 삼지 않는다.","c":"상","v":1},"공인회2019_54-02-3":{"f":"「국제조세조정에 관한 법률」에 의한 국제거래 중 국외 제공 용역거래에서 발생한 부정행위로 법인세를 포탈하거나 환급·공제받은 경우, 그 법인세를 부과할 수 있는 날부터 15년이 지나면 부과할 수 없다.","w":"국제거래에서 발생한 부정행위의 부과제척기간은 15년이다. 국내 부정행위의 10년보다 길다(국세기본법 제26조의2).","c":"상","v":1},"공인회2019_54-03-1":{"f":"공과금의 체납처분을 할 때 그 체납처분금액 중에서 국세·가산금 또는 강제징수비를 징수하는 경우, 그 공과금의 체납처분비는 국세·가산금 또는 강제징수비보다 우선하여 징수된다.","w":"공과금 체납처분금액에서 국세를 징수할 때 우선하는 것은 그 공과금 자체가 아니라 공과금의 체납처분비다(국세기본법 제35조).","c":"중","v":1},"공인회2019_54-04-1":{"f":"국세환급금을 충당할 경우에는 체납된 국세·가산금과 강제징수비에 우선 충당하여야 하나, 납세자가 납부고지에 의하여 납부하는 국세에 충당하는 것을 동의한 경우에는 해당 국세에 우선 충당하여야 한다.","w":"국세환급금은 체납된 국세와 강제징수비에 먼저 충당한다. 납세자가 동의하거나 신청하면 우선 충당되는 것은 납부고지에 따라 납부하는 국세이고, 자진납부하는 국세는 여기에 들어가지 않는다(국세기본법 시행령 제31조 제2항).","c":"상","v":1},"공인회2019_54-05-5":{"f":"과세예고통지를 받은 자가 과세전적부심사를 청구하지 아니하고 통지를 한 세무서장에게 통지받은 내용에 대하여 과세표준 및 세액을 조기에 결정해 줄 것을 신청한 경우, 해당 세무서장은 신청받은 내용대로 즉시 결정하여야 한다.","w":"조기결정 신청을 받은 세무서장은 신청받은 내용대로 즉시 결정이나 경정결정을 해야 한다(국세기본법 제81조의15 제8항). 2개월의 검토 기간은 없다.","c":"상","v":1},"공인회2020_55-01-1":{"f":"납세의무자란 세법에 따라 국세를 납부할 의무가 있는 자를 말하며 국세를 징수하여 납부할 의무가 있는 자는 제외한다.","w":"국세를 징수하여 납부하는 원천징수의무자는 납세의무자가 아니다(국세기본법 제2조).","c":"상","v":1},"공인회2020_55-02-1":{"f":"경매절차에 따라 재산을 매각할 때 그 매각금액 중에서 국세를 징수하는 경우 경매절차에 든 비용은 국세에 우선하여 징수한다.","w":"강제집행·경매·파산절차에 든 비용은 국세보다 먼저 변제된다(국세기본법 제35조).","c":"상","v":1},"공인회2020_55-02-2":{"f":"납세조합으로부터 징수하는 소득세를 납세의무의 확정일 전에 저당권이 설정된 재산을 매각하여 그 매각금액에서 징수하는 경우 그 저당권에 의하여 담보된 채권이 그 소득세에 우선한다.","w":"법정기일 전에 설정된 저당권의 담보채권은 국세보다 앞선다(국세기본법 제35조). 해당 재산에 부과된 당해세 같은 예외가 아니면 저당권이 우선이다.","c":"중","v":1},"공인회2020_55-02-4":{"f":"강제집행절차에 의하여 경락된 재산을 양수한 자는 양도인의 국세에 대해 제2차 납세의무를 지지 않는다.","w":"사업양수인이 제2차 납세의무를 지는 것은 사업장별로 사업에 관한 권리·의무를 포괄 승계한 자로서 양도인의 특수관계인이거나 조세회피 목적으로 양수한 경우다(국세기본법 제41조, 같은 법 시행령 제22조). 강제집행절차에서 경락으로 재산을 산 사람은 사업을 포괄 승계한 양수인이 아니다.","c":"중","v":1},"공인회2020_55-02-5":{"f":"납세자가 국세 및 강제징수비를 체납한 경우에 그 국세의 법정기일 후에 담보의 목적이 된 그 납세자의 양도담보재산으로써 국세 및 강제징수비를 징수할 수 있다.","w":"법정기일 전에 설정된 양도담보는 국세에 우선하므로 징수할 수 없고, 법정기일 후에 담보로 제공된 재산은 징수할 수 있다(국세기본법 제42조).","c":"상","v":1},"공인회2020_55-03-1":{"f":"가산세는 해당 의무가 규정된 세법의 해당 국세의 세목으로 하며, 해당 국세를 감면하는 경우에는 가산세는 그 감면대상에 포함하지 아니한다.","w":"본세를 감면해도 가산세는 감면대상에 포함되지 않는다. 가산세를 감면 대상에 넣는다고 따로 정한 경우만 예외다(국세기본법 제47조).","c":"상","v":1},"공인회2020_55-03-2":{"f":"납세의무자가 법정신고기한까지 「종합부동산세법」에 따른 과세표준 신고를 하지 아니한 경우에도 무신고가산세를 부과하지 아니한다.","w":"종합부동산세는 정부가 결정하는 것이 원칙이고 납세자가 원하는 경우에만 신고한다. 신고하지 않아도 무신고가산세 대상이 아니다.","c":"상","v":1},"공인회2020_55-03-3":{"f":"신고 당시 소유권에 대한 소송으로 상속재산으로 확정되지 아니하여 상속세 과세표준을 과소신고한 경우 과소신고가산세를 부과하지 아니한다.","w":"상속세 신고 당시 소유권 소송 등으로 상속재산으로 확정되지 않아 과소신고한 부분은 법이 과소신고가산세 적용 대상에서 뺀다. 국세기본법 제47조의3 제4항 제1호.","c":"중","v":1},"공인회2020_55-03-4":{"f":"「부가가치세법」에 따른 사업자가 아닌 자가 부가가치세액을 환급받은 경우에도 납부지연가산세를 적용한다.","w":"사업자가 아닌 자가 부가가치세액을 환급받은 경우에도 납부지연가산세 규정을 적용한다고 명시되어 있다(국세기본법 제47조의4 제2항).","c":"상","v":1},"공인회2020_55-04-3":{"f":"심사청구는 세법에 특별한 규정이 있는 것을 제외하고는 해당 처분의 집행에 효력을 미치지 아니하나, 처분의 집행 때문에 심사청구인에게 중대한 손해가 생기는 것을 예방할 필요성이 긴급하다고 인정할 때에는 집행정지를 결정할 수 있다.","w":"재결청은 처분의 집행이나 절차의 속행으로 청구인에게 중대한 손해가 생기는 것을 예방할 필요성이 긴급하다고 인정하면 집행정지를 결정할 수 있다(국세기본법 제57조 제1항). 재해를 입은 경우로 한정되지 않는다.","c":"상","v":1},"공인회2020_55-05-5":{"f":"세무공무원은 납세자가 납세관리인을 정하지 아니하고 국내에 주소 또는 거소를 두지 아니한 경우에는 세무조사결과를 통지하지 않을 수 있다.","w":"통지할 상대방이 국내에 없고 납세관리인도 없으면 통지가 현실적으로 어려워 결과통지 의무가 면제된다(국세기본법 제81조의12).","c":"상","v":1},"공인회2021_56-02-4":{"f":"법정기일 전에 저당권이 설정된 재산을 매각하여 그 매각금액에서 해당 재산에 대하여 부과된 종합부동산세를 징수하는 경우 그 종합부동산세 및 강제징수비가 저당권에 의하여 담보된 채권에 우선한다.","w":"종합부동산세는 해당 재산에 부과된 당해세이므로 법정기일 전에 설정된 저당권보다 앞선다(국세기본법 제35조).","c":"중","v":1},"공인회2021_56-03-1":{"f":"세무서장이 납세자의 환급청구를 촉구하기 위하여 납세자에게 환급청구의 안내·통지를 하더라도 국세환급금에 관한 권리의 소멸시효는 중단되지 아니한다.","w":"국세환급금 소멸시효는 세무서장이 환급청구를 촉구하려고 하는 안내·통지로는 중단되지 않는다(국세기본법 제54조 제3항). 행정소송으로 환급금을 청구한 경우에는 민법상 청구로 보아 시효가 중단된다.","c":"상","v":1},"공인회2021_56-04-1":{"f":"국세청장은 심사청구에 대한 결정을 할 때 심사청구를 한 처분 외의 처분에 대해서는 그 처분의 전부 또는 일부를 취소 또는 변경하는 결정을 하지 못한다.","w":"심사청구 결정에는 불고불리 원칙이 적용되어, 국세청장은 청구한 처분 외의 처분을 취소·변경하거나 새로운 처분을 결정하지 못한다(국세기본법 제65조의3 제1항). 청구인에게 더 불리한 결정도 하지 못한다.","c":"상","v":1},"공인회2022_57-01-1":{"f":"사업자등록의 명의자와는 별도로 사실상의 사업자가 있는 경우에는 경제적 실질이 법적 형식에 우선하므로 사실상의 사업자를 납세의무자로 하여 세법을 적용한다.","w":"실질과세원칙에 따라 명의가 아니라 실제로 사업을 한 사람에게 과세한다(국세기본법 제14조).","c":"상","v":1},"공인회2022_57-01-2":{"f":"납세의무자가 세법에 따라 장부를 갖추어 기록하고 있으나 장부의 기록에 일부 누락된 것이 있을 때에는 그 부분에 대해서만 정부가 조사한 사실에 따라 결정할 수 있다.","w":"근거과세원칙상 장부에 누락이 있어도 장부 전체를 부인하지 않고 누락된 부분만 조사한 사실로 결정한다(국세기본법 제16조).","c":"상","v":1},"공인회2022_57-01-3":{"f":"세법을 해석·적용할 때에는 과세의 형평과 해당 조항의 합목적성에 비추어 납세자의 재산권이 부당하게 침해되지 아니하도록 하여야 한다.","w":"세법은 과세의 형평과 해당 조항의 합목적성에 비추어 납세자의 재산권이 부당하게 침해되지 않도록 해석·적용한다(국세기본법 제18조 제1항). 보호 대상은 국가의 과세권이 아니라 납세자의 재산권이다.","c":"상","v":1},"공인회2022_57-01-4":{"f":"세무공무원이 국세의 과세표준을 조사·결정할 때에는 세법에 특별한 규정이 없으면 납세의무자가 계속하여 적용하고 있는 기업회계의 기준 또는 관행으로서 일반적으로 공정·타당하다고 인정되는 것은 존중하여야 한다.","w":"세법에 특별한 규정이 있으면 그 규정이 앞서고, 규정이 없을 때에 기업회계 기준 또는 관행을 존중한다(국세기본법 제20조).","c":"상","v":1},"공인회2022_57-02-2":{"f":"법인이 합병한 경우 합병 후 존속하는 법인 또는 합병으로 설립된 법인은 합병으로 소멸된 법인에 부과되거나 그 법인이 납부할 국세 및 강제징수비를 납부할 의무를 진다.","w":"합병 후 존속하거나 합병으로 설립된 법인은 소멸법인의 국세와 강제징수비를 한도 없이 승계한다(국세기본법 제23조). 받은 재산가액을 한도로 하는 것은 상속으로 인한 승계(제24조)와 분할 시 연대납세의무(제25조)다.","c":"상","v":1},"공인회2022_57-03-1":{"f":"과세표준과 세액의 신고에 따라 납세의무가 확정되는 국세의 경우 신고한 해당 세액의 법정기일은 신고일이다.","w":"신고납세 국세에서 신고한 세액의 법정기일은 그 신고일이다(국세기본법 제35조). 법정신고납부기한의 다음 날이 아니다.","c":"상","v":1},"공인회2022_57-04-4":{"f":"국세에 대한 경정청구는 당초 확정된 과세표준과 세액을 감액하여 확정하는 효력이 없다.","w":"경정청구는 감액해 달라는 청구일 뿐이고 세무서장이 이유 있다고 인정해 경정해야 감액이 확정된다(국세기본법 제45조의2).","c":"상","v":1},"공인회2022_57-05-5":{"f":"과세표준신고서를 법정신고기한까지 제출한 자가 법정신고기한이 지난 후 1개월 이내에 수정신고한 경우에는 과소신고·초과환급신고가산세의 90%를 감면한다.","w":"수정신고 시점에 따라 감면율이 다르다. 1개월 이내는 90%, 3개월 이내는 75%, 6개월 이내는 50%이다(국세기본법 제48조). 가산세를 아예 부과하지 않는 것은 아니다.","c":"상","v":1},"공인회2023_58-01-1":{"f":"납세자가 역외거래에서 이중장부를 작성하여 법인세를 포탈한 경우 부과제척기간은 그 법인세를 부과할 수 있는 날부터 15년이다.","w":"역외거래의 부정행위는 15년이다(국세기본법 제26조의2). 일반 부정행위는 10년이다.","c":"상","v":1},"공인회2023_58-01-2":{"f":"납세자가 부정행위로 상속세를 포탈하는 경우로서 제3자의 명의로 되어 있는 피상속인의 재산을 취득한 상속인이 사망한 때에는 과세관청은 해당 재산의 상속이 있음을 안 날부터 1년 이내에 상속세를 부과할 수 있는 특례를 적용할 수 없다.","w":"제3자 명의의 피상속인 재산을 상속인이 취득한 경우 등에는 상속이 있음을 안 날부터 1년 이내에 부과할 수 있지만, 상속인이 사망한 경우와 포탈 기준 재산가액이 50억원 이하인 경우에는 이 특례를 적용하지 않는다(국세기본법 제26조의2 제5항).","c":"상","v":1},"공인회2023_58-01-3":{"f":"「종합부동산세법」에 따라 신고하는 종합부동산세의 부과제척기간 기산일은 해당 종합부동산세의 납세의무가 성립한 날이다.","w":"신고하는 국세는 보통 과세표준신고기한의 다음 날이 기산일이지만, 종합부동산세는 신고하는 경우에도 납세의무가 성립한 날(과세기준일)이 기산일이다(국세기본법 시행령 제12조의3 제1항).","c":"상","v":1},"공인회2023_58-01-5":{"f":"공제세액을 의무불이행의 사유로 징수하는 경우 해당 공제세액의 부과제척기간 기산일은 그 의무불이행 사유가 발생한 날이다.","w":"공제·면제·비과세 등으로 줄어든 세액을 의무불이행 등의 사유로 징수할 때 부과제척기간은 그 세액을 징수할 수 있는 사유가 발생한 날부터 센다(국세기본법 시행령 제12조의3 제2항 제3호). 과세관청이 안 날이 기준이 아니다.","c":"상","v":1},"공인회2023_58-03-4":{"f":"기한후과세표준신고서를 제출한 자가 과세표준수정신고서를 제출한 경우 관할 세무서장은 신고일부터 3개월 이내에 해당 국세의 과세표준과 세액을 결정 또는 경정하여 신고인에게 통지하여야 한다.","w":"기한후신고와 그 수정신고 모두 신고일부터 3개월 이내에 결정·경정해 통지해야 한다(국세기본법 제45조의3).","c":"중","v":1},"공인회2023_58-04-1":{"f":"심판청구의 대상이 된 처분의 취소·경정 또는 필요한 처분을 하기 위하여 사실관계 확인 등 추가적으로 조사가 필요하여 재조사 결정을 한 경우, 해당 재조사 결정에 따른 처분청의 처분에 대하여도 그 재조사 결정을 한 재결청에 심판청구를 제기할 수 있다.","w":"재조사 결정에 따른 처분청의 처분에 대해서는 그 재조사 결정을 한 재결청에 다시 심사청구나 심판청구를 할 수 있다(국세기본법 제55조 제5항 단서).","c":"상","v":1},"공인회2023_58-05-3":{"f":"세무공무원은 세무조사의 중지기간 중에는 납세자에게 국세의 과세표준과 세액을 결정 또는 경정하기 위한 질문을 하거나 장부등의 제출을 요구할 수 없다.","w":"세무조사 중지기간에는 과세표준과 세액을 결정·경정하기 위한 질문, 장부등의 검사·조사나 제출 요구를 할 수 없다(국세기본법 제81조의8 제5항). 조세채권 확보 등 긴급한 필요가 있으면 중지기간 중이라도 조사를 재개할 수 있다(같은 조 제6항).","c":"상","v":1},"공인회2024_59-01-2":{"f":"납부의 고지에 관한 서류는 연대납세의무자 각각에게 송달하여야 한다.","w":"서류를 연대납세의무자의 대표자 명의로 송달하는 규정은 일반 서류에 적용된다. 납부고지와 독촉에 관한 서류는 각 연대납세의무자에게 따로 보내야 한다(국세기본법 제8조).","c":"상","v":1},"공인회2024_59-02-2":{"f":"법정기일 전에 전세권이 설정된 재산이 국세의 강제징수 또는 경매 절차 등을 통하여 매각되어 그 매각금액에서 국세를 징수하는 경우, 그 전세권에 의하여 담보된 채권 또는 임대차보증금반환채권보다 해당 재산에 대하여 부과된 증여세가 우선한다.","w":"해당 재산에 부과된 상속세·증여세·종합부동산세(당해세)는 법정기일 전에 설정된 저당권이나 전세권 담보채권보다도 앞선다(국세기본법 제35조).","c":"상","v":1},"공인회2024_59-02-3":{"f":"지방세 체납처분에 의하여 납세자의 재산을 압류한 경우에 국세 및 강제징수비의 교부청구가 있으면 교부청구된 국세 및 강제징수비는 압류에 관계되는 지방세의 다음으로 징수한다.","w":"압류선착수주의에 따라 먼저 압류한 지방세가 앞서고 교부청구된 국세는 그 다음이다. 같은 순위가 아니다(국세기본법 제36조).","c":"상","v":1},"공인회2024_59-02-4":{"f":"납세자가 국세 및 강제징수비를 체납한 경우 그 납세자에게 그 국세의 법정기일 후에 담보의 목적이 된 양도담보재산이 있을 때에는 「국세징수법」에서 정하는 바에 따라 그 양도담보재산으로써 납세자의 국세 및 강제징수비를 징수할 수 있다.","w":"법정기일 전에 담보로 제공된 양도담보재산은 국세보다 앞서므로 징수할 수 없다. 법정기일 후에 제공된 재산만 징수할 수 있다(국세기본법 제42조).","c":"상","v":1},"공인회2024_59-02-5":{"f":"과세표준과 세액의 신고에 따라 납세의무가 확정되는 국세의 경우 신고한 해당 세액의 법정기일은 그 신고일이다.","w":"신고납세 국세에서 신고한 세액의 법정기일은 신고일이다(국세기본법 제35조). 법정신고납부기한의 다음 날이 아니다.","c":"상","v":1},"공인회2024_59-03-1":{"f":"납세자가 「상속세 및 증여세법」에 따라 상속세를 물납한 후 그 부과의 전부 또는 일부를 취소하거나 감액하는 경정결정에 따라 환급하는 경우에는 해당 물납재산으로 환급하여야 하며 국세환급가산금을 지급하지 아니한다.","w":"물납재산으로 환급하면 재산을 돌려주는 것이라 금전 이자 성격의 환급가산금은 붙이지 않는다.","c":"중","v":1},"공인회2024_59-03-2":{"f":"국세환급금을 체납된 국세 및 강제징수비에 충당하는 것은 납세자의 동의 없이도 한다.","w":"세무서장은 환급할 국세환급금이 있고 체납된 국세와 강제징수비가 있으면 납세자 동의를 받지 않고 충당해야 한다(국세기본법 제51조).","c":"상","v":1},"공인회2024_59-03-4":{"f":"물납재산을 환급하는 경우에 국가가 물납재산을 유지 또는 관리하기 위하여 지출한 비용은 국가의 부담으로 한다.","w":"물납재산을 환급할 때 국가가 그 재산을 유지·관리하려고 쓴 비용은 국가가 부담한다. 다만 국가가 자본적 지출을 한 경우에는 그 금액을 납세자가 부담한다(국세기본법 시행령 제43조의2 제3항).","c":"상","v":1},"공인회2024_59-03-5":{"f":"체납된 국세 및 강제징수비가 있는 납세자가 국세환급금을 납부고지에 따라 납부하는 국세에 충당하는 것을 동의하거나 신청한 경우에는 국세환급금을 그 납부하는 국세에 충당한다.","w":"국세환급금은 체납된 국세와 강제징수비에 먼저 충당하는 것이 원칙이지만, 납세자가 납부고지에 따라 내는 국세에 충당하는 데 동의하거나 신청하면 그 국세에 먼저 충당한다(국세기본법 시행령 제31조 제2항).","c":"상","v":1},"공인회2024_59-04-4":{"f":"국세징수권의 소멸시효는 세법에 따른 분납기간 중에는 진행하지 아니한다.","w":"분납기간, 납부고지 유예·징수유예기간, 압류·매각 유예기간, 연부연납기간 등에는 국세징수권의 소멸시효가 진행되지 않는다(국세기본법 제28조 제3항). 새로 진행하는 것은 납부고지·독촉 등으로 시효가 중단된 경우다(같은 조 제2항).","c":"상","v":1},"공인회2024_59-05-2":{"f":"재조사 결정에 따른 처분청의 처분에 대해서는 해당 재조사 결정을 한 재결청에 대하여 심사청구 또는 심판청구를 제기할 수 있다.","w":"심사청구나 심판청구에 대한 처분에는 다시 불복할 수 없는 것이 원칙이지만, 재조사 결정에 따른 처분청의 처분은 예외로 그 재조사 결정을 한 재결청에 심사청구나 심판청구를 할 수 있다(국세기본법 제55조 제5항 단서).","c":"상","v":1},"공인회2025_60-01-5":{"f":"납세자가 과세표준신고서를 국세정보통신망을 이용하여 제출하는 경우에는 해당 신고서가 국세청장에게 전송된 때에 신고된 것으로 보고, 과세관청이 송달서류를 국세정보통신망에 저장하여 전자송달하는 경우에는 해당 서류가 저장된 때 송달받아야 할 자에게 도달한 것으로 본다.","w":"전자신고는 국세청장에게 전송된 때 신고된 것으로 본다(국세기본법 제5조의2 제2항). 국세정보통신망에 저장하는 전자송달은 저장된 때 도달한 것으로 보며, 납세자가 열어 본 때가 기준이 아니다(같은 법 제12조 제1항).","c":"상","v":1},"공인회2025_60-02-2":{"f":"법인은 납부기간 만료일 현재 법인의 무한책임사원 또는 과점주주가 납부할 국세 및 강제징수비에 대하여 제2차 납세의무를 진다.","w":"법인이 출자자의 국세에 대해 제2차 납세의무를 지는 경우 그 출자자는 무한책임사원과 과점주주뿐이다(국세기본법 제40조 제1항). 영농·영어조합법인의 과점조합원은 조합의 국세에 대해 자신이 제2차 납세의무를 지는 대상(제39조)에 들어갈 뿐, 법인이 이들의 국세를 대신 지는 대상에는 없다. 법인의 제2차 납세의무도 출자자 재산으로 부족하고 그 주식을 매각하기 어려운 경우 등에만 생긴다.","c":"상","v":1},"공인회2025_60-03-1":{"f":"중간예납하는 소득세는 중간예납기간이 끝나는 때 성립하고 정부가 결정하는 때 그 세액이 확정된다.","w":"중간예납 소득세는 원칙적으로 세무서장이 고지하는 결정으로 확정되며, 납세자가 신고를 선택하면 신고로 확정된다. 특별한 절차 없이 확정되는 것은 원천징수 소득세·법인세, 인지세 등이다(국세기본법 제22조).","c":"중","v":1},"공인회2025_60-04-1":{"f":"국내원천 이자소득만 있는 비거주자의 소득에 대하여 최초 신고와 다르게 조세조약에 따른 상호합의가 이루어져 세액이 감액된 경우 경정청구는 원천징수의무자와 원천징수대상자가 모두 할 수 있다.","w":"비거주자의 국내원천소득에 대한 경정청구는 실질귀속자뿐 아니라 원천징수의무자도 할 수 있다(소득세법 제156조의2 제5항, 제156조의6 제5항). 상호합의처럼 국세기본법 제45조의2 제2항의 사유가 생기면 그 사실을 안 날부터 3개월 이내에 청구한다.","c":"중","v":1},"공인회2026_61-01-2":{"f":"납세의무자가 세법에 따라 장부를 갖추어 기록하고 있으나 사실과 다른 부분이 있는 경우 그 부분에 한정하여 세무공무원이 조사한 사실에 따라 국세를 조사·결정할 수 있다.","w":"근거과세원칙상 장부 전체를 부인하지 않고 사실과 다른 부분에 대해서만 조사한 사실로 결정한다(국세기본법 제16조).","c":"상","v":1},"공인회2026_61-03-5":{"f":"과세전적부심사 청구를 받은 날부터 30일 이내에 그 결과를 청구인에게 통지하지 아니한 경우 결정·통지가 지연되는 기간에 부과되는 납부지연가산세의 100분의 50을 감면한다.","w":"과세전적부심사 결정·통지기간에 결과를 통지하지 않으면 그 지연 기간에 붙는 납부지연가산세는 절반을 감면한다(국세기본법 제48조 제2항 제3호 가목). 전액을 면제하는 것은 아니다.","c":"상","v":1},"공인회2026_61-04-1":{"f":"과세표준 및 세액의 결정 또는 경정결정은 그 처분 당시 그 국세의 납세지를 관할하는 세무서장이 한다.","w":"결정·경정결정은 신고 당시가 아니라 그 처분 당시의 납세지 관할 세무서장이 한다(국세기본법 제44조).","c":"상","v":1},"공인회2026_61-04-2":{"f":"기한후과세표준신고서를 제출한 자는 기한후과세표준신고서에 기재된 환급세액이 세법에 따라 신고하여야 할 환급세액에 미치지 못할 때에는 국세의 과세표준 및 세액의 결정 또는 경정을 청구할 수 있다.","w":"환급을 덜 받게 신고했을 때 경정청구 이유가 생긴다. 환급세액을 신고할 세액보다 많이 기재한 경우는 청구할 이유가 없다(국세기본법 제45조의2).","c":"상","v":1},"공인회2026_61-04-3":{"f":"결정 또는 경정으로 인하여 과세표준 및 세액이 증가한 때에는 해당 처분이 있음을 안 날(처분의 통지를 받은 때에는 그 받은 날)부터 3개월 이내(법정신고기한이 지난 후 5년 이내로 한정)에 경정을 청구할 수 있다.","w":"정부의 결정·경정으로 늘어난 과세표준과 세액은 처분이 있음을 안 날(통지를 받았으면 받은 날)부터 3개월 이내에 경정청구한다. 다만 법정신고기한이 지난 후 5년 이내여야 한다(국세기본법 제45조의2 제1항 단서).","c":"상","v":1},"공인회2026_61-04-5":{"f":"결정 또는 경정의 대상이 된 과세표준 및 세액과 연동된 다른 세목(같은 과세기간으로 한정)이나 연동된 다른 과세기간(같은 세목으로 한정)의 과세표준 또는 세액이 세법에 따라 신고하여야 할 과세표준 또는 세액을 초과할 때에는 결정 또는 경정을 청구할 수 있다.","w":"연동 경정청구는 같은 과세기간의 다른 세목이나 같은 세목의 다른 과세기간에만 할 수 있다. 과세기간과 세목이 모두 다른 경우는 대상이 아니다(국세기본법 제45조의2 제2항 제4호).","c":"상","v":1},"공인회2026_61-05-1":{"f":"종합소득금액이 5천만원 이하인 개인이 5천만원 이하인 세액의 상속세에 대하여 심사청구를 하는 경우에는 재결청에 국선대리인을 선정하여 줄 것을 신청할 수 없다.","w":"국선대리인은 상속세·증여세·종합부동산세가 아닌 세목에 대한 청구에서만 신청할 수 있다(국세기본법 제59조의2 제1항 제4호). 소득·재산·청구금액 요건을 갖추어도 상속세 청구에는 선정을 신청할 수 없다.","c":"상","v":1},"공인회2026_61-05-2":{"f":"국세청장은 심사청구를 받으면 국세심사위원회의 의결에 따라 결정하여야 한다.","w":"국세청장은 심사청구를 국세심사위원회의 의결에 따라 결정한다. 심사청구기간이 지난 뒤 제기된 청구 등은 예외다(국세기본법 제64조 제1항). 의결이 법령에 명백히 어긋나면 한 차례에 한해 다시 심의를 요청할 수 있다(같은 조 제2항).","c":"상","v":1},"공인회2026_61-05-4":{"f":"국세청장은 심사청구에 대한 결정을 할 때 심사청구를 한 처분 외의 처분에 대해서는 취소 또는 변경하는 결정을 할 수 없다.","w":"국세청장은 심사청구 결정에서 청구한 처분 외의 처분을 취소·변경하거나 새로운 처분을 결정하지 못하고, 청구한 처분보다 청구인에게 불리한 결정도 하지 못한다(국세기본법 제65조의3).","c":"상","v":1},"공인회2026_61-05-5":{"f":"납세자의 동거가족이 질병으로 6개월 이상의 치료가 필요한 경우는 심판청구 기한연장 사유에 해당한다.","w":"납세자 또는 동거가족이 질병이나 중상해로 6개월 이상 치료가 필요한 경우는 기한연장 사유이며(국세기본법 시행령 제2조 제2호), 이런 사유로 청구기간에 청구하지 못하면 그 사유가 소멸한 날부터 14일 이내에 청구할 수 있다(국세기본법 제61조 제4항, 제80조의2).","c":"상","v":1},"공인회2016_51-07-3":{"f":"자기주식처분이익을 자본금에 전입하는 경우 주주가 받은 무상주는 의제배당에 해당한다.","w":"자기주식처분이익의 자본전입은 의제배당 제외 항목이 아니므로 무상주를 받은 주주는 의제배당소득이 생긴다. 자기주식의 취득 시기와는 무관하다(법인세법 제16조).","c":"중","v":1},"공인회2017_52-05-3":{"f":"내국법인의 법인세 납세지는 그 법인의 등기부에 따른 본점이나 주사무소의 소재지로 한다. 다만, 법인으로 보는 단체의 경우에는 당해 단체의 사업장 소재지(주된 소득이 부동산임대소득인 단체는 그 부동산의 소재지)로 한다.","w":"법인으로 보는 단체의 납세지는 신고하는 장소가 아니라 그 단체의 사업장 소재지이고, 주된 소득이 부동산임대소득이면 그 부동산 소재지다(법인세법 제9조 제1항 단서, 같은 법 시행령 제7조 제1항). 신고하는 장소를 납세지로 하는 것은 둘 이상의 자산이 있는 외국법인 등의 경우다.","c":"상","v":1},"공인회2019_54-06-5":{"f":"관할 지방국세청장 또는 국세청장은 내국법인의 본점 소재지가 등기된 주소와 동일하지 아니한 경우 납세지를 지정할 수 있다.","w":"납세지를 지정하는 권한은 납세지 관할 세무서장이 아니라 관할 지방국세청장 또는 국세청장에게 있다(법인세법 제12조).","c":"중","v":1},"공인회2020_55-06-4":{"f":"비영리외국법인과 비영리내국법인 모두 청산소득에 대한 법인세 납세의무가 없다.","w":"청산소득에 대한 법인세는 영리내국법인만 부담한다. 비영리내국법인도 청산소득에는 과세되지 않는다(법인세법 제4조).","c":"상","v":1},"공인회2020_55-07-5":{"f":"익금에 산입한 금액 중 사외로 유출되어 그 귀속자가 당해 법인의 주주이면서 임원인 경우 그 출자임원에 대한 상여로 처분한다.","w":"귀속자가 임원 또는 직원이면 상여로 처분한다. 출자임원이라도 임원의 지위가 있으면 배당이 아니라 상여다(법인세법 시행령 제106조).","c":"상","v":1},"공인회2020_55-09-1":{"f":"법인세 과세표준을 추계결정하는 법인은 주택임대보증금을 포함한 임대보증금에 대한 간주임대료를 익금에 산입한다.","w":"추계결정하는 법인은 부동산임대에 따른 전세금·임대보증금에 정기예금이자율을 곱한 금액을 사업수입금액으로 하며, 주택임대보증금을 빼는 규정이 없다(법인세법 시행령 제11조 제1호 단서). 주택을 빼는 것은 차입금과다법인의 간주임대료(조세특례제한법 제138조)다.","c":"상","v":1},"공인회2021_56-16-3":{"f":"수탁자의 변경에 따라 수탁자가 그 법인과세 신탁재산에 대한 자산과 부채를 변경되는 수탁자에게 이전하는 경우 수탁자 변경일 현재의 장부가액을 그 자산과 부채의 이전가액으로 보아 이전에 따른 손익은 없는 것으로 한다.","w":"수탁자가 바뀌어도 신탁이라는 동일한 납세주체의 재산이 그대로 이어지므로 장부가액으로 이전하고 손익을 인식하지 않는다.","c":"중","v":1},"공인회2021_56-17-5":{"f":"법인의 채무 6,000,000원을 출자전환하면서 교부한 주식(액면가액 3,500,000원, 시가 4,000,000원)에 대해 채무감소액과 액면가액의 차액 2,500,000원을 손익계산서상 채무조정이익으로 회계처리한 경우, 익금불산입 500,000원(기타)으로 처리하여야 한다.","w":"출자전환 주식은 시가 4,000,000원까지만 주식발행액면초과액으로 보므로 시가와 액면의 차액 500,000원은 익금불산입하고, 시가를 넘는 2,000,000원은 채무면제이익으로 익금이다(법인세법 제17조 제1항 제1호 단서). 회사가 수익으로 잡은 2,500,000원 중 500,000원만 익금불산입(기타)하면 되고, 자산·부채 금액은 세법과 같아 유보가 생기지 않는다.","c":"중","v":1},"공인회2022_57-16-3":{"f":"내국법인이 사업연도 중에 「상법」의 규정에 따라 조직변경을 한 경우에는 조직변경 전의 사업연도가 계속되는 것으로 본다.","w":"조직변경은 법인격이 동일하게 이어지는 것이라 사업연도를 나누지 않는다. 합병·해산 같은 경우와 다르다(법인세법 제8조).","c":"상","v":1},"공인회2022_57-29-2":{"f":"비영리내국법인이 주식 또는 출자지분을 양도함에 따라 생기는 수입에 대하여는 각 사업연도 소득에 대한 법인세가 과세된다.","w":"주식·출자지분 양도 수입은 비영리내국법인의 수익사업 소득에 해당해 법인세가 과세된다(법인세법 제4조 제3항).","c":"상","v":1},"공인회2022_57-29-3":{"f":"청산소득에 대한 법인세의 납부의무가 있는 내국법인은 잔여재산가액 확정일이 속하는 달의 말일부터 3개월 이내에 청산소득에 대한 법인세의 과세표준과 세액을 신고하여야 한다.","w":"청산소득 법인세의 신고기한은 해산등기일이 아니라 잔여재산가액 확정일이 속하는 달의 말일부터 3개월 이내다(법인세법 제84조 제1항 제1호).","c":"상","v":1},"공인회2022_57-29-4":{"f":"비영리내국법인은 원천징수된 비영업대금의 이익에 대하여는 각 사업연도 소득에 대한 법인세 과세표준 신고를 하여야 한다.","w":"비영리내국법인이 신고하지 않아도 되는 소득은 이자소득과 배당소득이다. 비영업대금의 이익은 신고 생략 대상에서 빠진다(법인세법 제62조).","c":"상","v":1},"공인회2022_57-29-5":{"f":"건축 장소는 국내에 6개월을 초과하여 존속하면 외국법인의 국내사업장에 포함된다.","w":"건설, 설치, 조립 공사를 하는 장소는 6개월을 넘으면 국내사업장이 된다(법인세법 제94조). 2년 존속하면 당연히 포함된다.","c":"상","v":1},"공인회2024_59-12-5":{"f":"내국법인 ㈜C(사업연도: 1월 1일∼12월 31일)가 2024년 6월 30일 조직변경을 한 경우에도 2024년 1월 1일부터 12월 31일까지를 1사업연도로 본다.","w":"조직변경은 사업연도를 나누지 않고 조직변경 전 사업연도가 계속된다(법인세법 제8조).","c":"상","v":1},"공인회2024_59-13-1":{"f":"비영리내국법인은 원천징수된 투자신탁의 이익에 대하여 과세표준 신고를 하지 아니할 수 있다. 이 경우 과세표준 신고를 하지 아니한 투자신탁의 이익은 그 법인의 해당 각 사업연도 소득금액에 산입하지 아니한다.","w":"신고를 생략한 원천징수 소득은 원천징수로 납세의무가 끝난 분리과세 소득이라 소득금액에 합산하지 않는다(법인세법 제62조).","c":"상","v":1},"공인회2025_60-16-2":{"f":"납세지가 변경된 법인이 「부가가치세법」에 따라 그 변경된 사실을 신고한 경우에는 법인세 납세지 변경신고를 한 것으로 본다.","w":"납세지가 바뀐 법인이 부가가치세법에 따라 그 사실을 신고하면 법인세 납세지 변경신고를 한 것으로 본다(법인세법 제11조 제1항 후단). 따로 변경신고를 하지 않아도 된다.","c":"상","v":1},"공인회2026_61-16-5":{"f":"「국세기본법」상 수정신고기한내에 매출누락, 가공경비 등 부당하게 사외유출된 금액을 회수하고 세무조정으로 익금에 산입하여 신고하는 경우에는 사내유보로 소득처분한다.","w":"수정신고기한 안에 부당하게 사외유출된 금액을 회수하고 익금에 산입해 신고하면 사내유보로 처분한다. 다만 세무조사 통지를 받는 등 경정이 있을 것을 미리 알고 회수한 경우는 제외한다(법인세법 시행령 제106조 제4항).","c":"상","v":1},"공인회2016_51-08-1":{"f":"법인이 임원에 대하여 퇴직 시까지 부담한 확정기여형 퇴직연금의 부담금은 임원 퇴직급여 지급 한도 안에서 손금에 산입한다.","w":"임원의 퇴직금은 정관이나 퇴직급여 지급규정에 따른 한도를 넘으면 손금불산입한다. 확정기여형 부담금도 이 한도의 적용을 받는다.","c":"중","v":1},"공인회2016_51-08-2":{"f":"상근이 아닌 법인의 임원에게 지급하는 보수는「법인세법」상 부당행위계산 부인에 해당하는 경우에는 손금에 산입하지 아니한다.","w":"비상근임원 보수는 원칙적으로 손금이지만 부당행위계산에 해당하면 손금불산입한다(법인세법 시행령 제43조).","c":"상","v":1},"공인회2016_51-08-3":{"f":"「파견근로자보호 등에 관한 법률」에 따른 파견근로자를 위하여 지출한 직장연예비와 직장회식비는 복리후생비로 본다.","w":"파견근로자를 위한 직장체육비, 직장문화비(직장연예비), 직장회식비는 복리후생비에 해당해 전액 손금이다. 기업업무추진비 한도 계산 대상이 아니다(법인세법 시행령 제45조).","c":"중","v":1},"공인회2016_51-08-5":{"f":"내국법인이 임원에게 이익처분에 의하여 지급하는 상여금은 임원과 성과산정지표 및 그 목표, 성과의 측정 및 배분방법 등에 대하여 사전에 서면으로 약정하였더라도 손금에 산입하지 아니한다.","w":"임원에게 이익처분으로 지급하는 상여금은 사전에 서면으로 성과 배분 약정을 했더라도 손금에 산입하지 않는다(법인세법 시행령 제43조 제1항). 출제 당시 사전 약정에 따른 성과배분상여금을 손금으로 보던 규정도 임원은 대상에서 뺐다.","c":"중","v":1},"공인회2018_53-11-1":{"f":"법인이 출자임원(지배주주와 특수관계에 있는 자)에게 지급한 여비 또는 교육훈련비는 업무와 관련된 지출이라면 손금에 산입한다.","w":"출자임원이라도 업무와 관련해 지출한 여비와 교육훈련비는 손금이다. 업무와 관련 없이 지출하면 손금불산입하고 상여 등으로 처분한다.","c":"상","v":1},"공인회2018_53-11-2":{"f":"회수할 수 없는 부가가치세 매출세액미수금은 「부가가치세법」에 따라 대손세액공제를 받지 아니한 것에 한정하여 손금으로 인정한다.","w":"대손세액공제를 받은 매출세액은 부가가치세에서 이미 정산되었으므로 손금이 아니다. 공제를 받지 못한 매출세액 미수금만 대손금으로 손금에 산입한다.","c":"중","v":1},"공인회2018_53-11-3":{"f":"비출자공동사업자가 지출한 공동광고선전비는 비출자공동사업자 사이에 특수관계가 있으면 매출액 총액과 총자산가액 총액 중 법인이 선택하는 금액의 비율에 따라, 특수관계가 없으면 약정에 따른 분담비율에 따라 분담하며, 이를 초과하는 분담금액은 손금에 산입하지 아니한다.","w":"비출자공동사업자의 공동경비는 특수관계가 있으면 매출액 총액과 총자산가액 총액 중 법인이 선택한 기준으로, 특수관계가 없으면 약정 분담비율(약정이 없으면 앞의 기준)로 나눈다(법인세법 시행령 제48조 제1항 제2호). 약정비율과 매출액 비율 중에서 고르는 방식이 아니다.","c":"상","v":1},"공인회2018_53-11-5":{"f":"업무와 관련하여 발생한 교통사고 벌과금은 손금으로 인정되지 아니한다.","w":"벌금·과료·과태료는 업무와 관련해 발생했더라도 손금불산입이다(법인세법 제21조). 손해배상금과는 구별된다.","c":"상","v":1},"공인회2021_56-20-3":{"f":"법인이 영리내국법인으로부터 건당 3만원(부가가치세 포함)을 초과하는 용역을 공급받고 그 대가를 지급하는 경우 법정증명서류 이외의 증명서류를 수취하더라도 손금에 산입하며 증명서류 수취 불성실 가산세를 적용한다.","w":"적격증빙을 받지 못해도 지출 사실이 확인되면 손금이다. 지급금액의 2%를 가산세로 낸다(법인세법 제75조의5).","c":"상","v":1},"공인회2025_60-06-1":{"f":"","w":"식품 제조업을 하는 법인이 잉여 식품을 「식품등 기부 활성화에 관한 법률」에 따른 제공자에게 무상으로 기증하면 그 장부가액을 손금에 산입한다(법인세법 시행령 제19조 제13호의2). 비용처리한 1,200만원이 그대로 인정되어 세무조정이 필요 없다.","c":"상","v":1},"공인회2025_60-06-2":{"f":"","w":"여러 사람이 볼 수 있는 공간에 늘 전시하는 미술품은 거래단위별 취득가액이 1천만원 이하이면 취득한 사업연도에 비용으로 처리한 금액을 손금으로 인정한다(법인세법 시행령 제19조 제17호). 800만원이므로 세무조정이 필요 없다.","c":"상","v":1},"공인회2025_60-06-4":{"f":"","w":"직장체육비는 손금으로 인정되는 복리후생비이고, 이때 직원에는 파견근로자도 포함된다(법인세법 시행령 제45조 제1항). 비용처리한 500만원은 세무조정이 필요 없다.","c":"상","v":1},"공인회2025_60-06-5":{"f":"","w":"지배주주등이 아닌 임원·직원이 사망한 뒤 유족에게 학자금 등으로 일시 지급하는 금액은 요건을 갖추면 손금이다(법인세법 시행령 제19조 제21호). 사망 전 이사회 결의로 정해 임직원에게 공통으로 적용하는 기준에 따른 1,500만원이므로 세무조정이 필요 없다.","c":"중","v":1},"공인회2026_61-17-5":{"f":"영업자가 조직한 단체로서 주무관청에 등록된 조합에 경상경비에 충당할 목적으로 지급한 회비는 손금에 산입한다.","w":"조합·협회에 낸 회비 중 손금이 되는 것은 법령이나 정관에 따른 정상적인 징수 방식으로 경상경비 충당 등을 위해 부과된 회비다(법인세법 시행령 제19조 제11호, 같은 법 시행규칙 제10조 제2항). 경상경비 외의 목적으로 낸 회비는 여기에 들지 않는다.","c":"상","v":1},"공인회2017_52-16-2":{"f":"사용인에게 주택자금을 무상으로 대여한 경우에도 부당행위계산의 부인 규정이 적용된다.","w":"직원도 법인의 특수관계인이어서 주택자금을 무상으로 빌려주면 인정이자를 익금에 산입한다(법인세법 시행령 제88조 제1항 제6호). 다만 현행은 중소기업 직원(지배주주등 제외)에게 빌려준 주택구입·전세자금은 인정이자 계산에서 뺀다(같은 법 시행규칙 제44조 제7호의2).","c":"중","v":1},"공인회2017_52-16-3":{"f":"토지의 시가가 불분명한 경우로「부동산가격공시 및 감정평가에 관한 법률」에 의한 감정평가법인이 감정한 가액이 2 이상인 경우에는 그 감정한 가액의 평균액으로 평가한다.","w":"감정가액이 둘 이상이면 평균액을 시가로 본다(법인세법 시행령 제89조).","c":"상","v":1},"공인회2017_52-16-4":{"f":"금전, 그 밖의 자산 또는 용역을 무상 또는 시가보다 낮은 이율ㆍ요율이나 임대료로 대부하거나 제공한 경우에는 시가와 거래가액의 차액이 시가의 5% 이상이거나 3억원 이상인 경우에 부당행위계산의 부인 규정을 적용한다.","w":"특수관계인과의 거래는 시가와 거래가액의 차액이 시가의 5% 이상이거나 3억원 이상일 때 부인한다(법인세법 시행령 제88조 제3항). 무상 제공이어도 이 요건은 같다.","c":"중","v":1},"공인회2017_52-16-5":{"f":"특수관계인에 대한 금전 대여의 경우 대여기간이 5년을 초과하는 대여금이 있으면 해당 대여금에 한정하여 당좌대출이자율을 시가로 한다.","w":"가지급금 인정이자는 가중평균차입이자율이 원칙이다. 대여기간이 5년을 넘는 대여금은 예외로 당좌대출이자율을 쓴다(법인세법 시행령 제89조).","c":"상","v":1},"공인회2018_53-10-1":{"f":"기업업무추진비를 신용카드로 결제한 경우 대금청구일이 속하는 사업연도가 아니라 실제로 접대행위를 한 사업연도를 손금의 귀속시기로 한다.","w":"기업업무추진비의 귀속시기는 접대행위를 한 사업연도이며, 카드 결제 시점이나 대금청구일과 무관하다.","c":"상","v":1},"공인회2018_53-10-2":{"f":"기부금 한도는 해당 사업연도의 소득금액에 일정률을 곱해 산출하며, 기업업무추진비 한도는 기업회계기준에 따라 계산한 수입금액(매출액)에 일정률을 곱해 산출한다.","w":"기부금 한도는 소득금액 기준(법인세법 제24조)이고, 기업업무추진비 한도는 기본한도와 수입금액 기준 한도의 합이다(제25조).","c":"상","v":1},"공인회2018_53-10-3":{"f":"채권자가 불분명한 사채이자 1,000,000원(소득세 등으로 원천징수된 금액 418,000원 포함)을 비용으로 계상한 경우, 1,000,000원을 손금 불산입하고 원천징수세액 418,000원은 기타사외유출로, 나머지 582,000원은 대표자에 대한 상여로 소득처분한다.","w":"원천징수세액 상당액은 국가에 납부되므로 기타사외유출이고, 이를 제외한 금액만 대표자 상여로 처분한다.","c":"상","v":1},"공인회2018_53-10-5":{"f":"사용인에게 주택자금을 대여한 경우 적정이자를 수령하였더라도 업무무관 가지급금에 해당하면 업무무관자산 등에 대한 지급이자의 손금불산입 규정이 적용된다.","w":"업무무관 가지급금은 이자 수령 여부와 상관없이 지급이자 손금불산입 계산에 들어간다. 중소기업 직원 주택자금 등 시행령에서 따로 제외한 대여만 빠진다.","c":"중","v":1},"공인회2018_53-15-4":{"f":"법인이 과세표준 신고와 함께 재정경제부령으로 정하는 바에 따라 당좌대출이자율을 시가로 선택하는 경우 선택한 사업연도와 이후 2개 사업연도에 재정경제부령으로 정하는 당좌대출이자율을 시가로 하여 가지급금 인정이자를 계산한다.","w":"당좌대출이자율을 시가로 선택하면 선택한 사업연도와 그 뒤 2개 사업연도에 당좌대출이자율을 적용한다(법인세법 시행령 제89조 제3항 제2호). 선택한 해 한 번으로 끝나지 않는다.","c":"상","v":1},"공인회2020_55-16-3":{"f":"기계를 임대하고 임대료를 계산할 때 당해 자산 시가의 100분의 50에 상당하는 금액에서 그 자산의 제공과 관련하여 받은 보증금을 차감한 금액에 정기예금이자율을 곱하여 산출한 금액을 시가로 한다.","w":"유형·무형자산을 빌려줄 때 시가를 알 수 없으면 자산 시가의 50%에서 받은 전세금·보증금을 뺀 금액에 정기예금이자율을 곱한 금액을 시가로 본다(법인세법 시행령 제89조 제4항 제1호). 시가 전액에서 출발하지 않는다.","c":"하","v":1},"공인회2021_56-22-5":{"f":"사업용 유형자산의 건설에 소요된 것이 분명한 특정차입금의 연체로 인하여 생긴 이자를 원본에 가산한 경우 그 가산한 금액은 이를 해당 사업연도의 자본적 지출로 한다.","w":"연체이자를 원본에 가산한 금액은 자본적 지출이지만, 그 원본 가산액에 대한 이후 지급이자는 건설자금이자 대상이 아니고 일반 지급이자로 손금이다(법인세법 시행령 제52조).","c":"중","v":1},"공인회2023_58-10-2":{"f":"법인이 기부금을 금전 외의 자산으로 제공한 경우 특수관계인이 아닌 자에게 기부한 일반기부금은 기부했을 때의 장부가액으로 해당 자산가액을 산정한다.","w":"특례기부금과 특수관계인이 아닌 자에게 한 일반기부금은 장부가액이다. 특수관계인에게 한 일반기부금과 비지정기부금은 장부가액과 시가 중 큰 금액이다(법인세법 시행령 제36조).","c":"상","v":1},"공인회2023_58-17-2":{"f":"내국법인이 특수관계인의 출연금을 대신 부담하는 것은 조세의 부담을 부당하게 감소시킨 것으로 인정된다.","w":"특수관계인의 출연금을 대신 내주는 것은 법인의 이익을 분여하는 행위여서 부당행위계산 부인 대상이다(법인세법 시행령 제88조).","c":"중","v":1},"공인회2023_58-17-3":{"f":"내국법인B에 과반수 이상을 출자하고 있는 내국법인C에 40%를 출자하고 있는 내국법인이나 개인은 내국법인B의 특수관계인에 해당한다.","w":"해당 법인에 30% 이상 출자한 법인에 다시 30% 이상 출자한 법인이나 개인은 특수관계인이다. C가 B에 과반수를 출자했고 그 C에 40%를 출자했으므로 B의 특수관계인에 해당한다(법인세법 시행령 제2조 제8항 제6호).","c":"상","v":1},"공인회2023_58-17-4":{"f":"부당행위계산의 부인규정을 적용할 때 토지의 시가가 불분명한 경우에는 「감정평가 및 감정평가사에 관한 법률」에 따른 감정평가법인등이 감정한 가액을 우선 적용하고, 감정한 가액이 없으면 「상속세 및 증여세법」에 따른 보충적 평가방법을 준용하여 평가한 가액을 적용한다.","w":"시가가 불분명하면 감정평가법인등의 감정가액(둘 이상이면 평균액)을 먼저 쓰고, 상속세 및 증여세법의 보충적 평가방법은 그다음 순서다. 주식등과 가상자산에는 감정가액을 쓰지 않는다(법인세법 시행령 제89조 제2항).","c":"상","v":1},"공인회2023_58-17-5":{"f":"특수관계가 있는 내국법인간의 합병(분할합병 포함)에 있어서 주식을 시가보다 높거나 낮게 평가하여 불공정한 비율로 합병한 경우 조세의 부담을 부당하게 감소시킨 것으로 인정된다.","w":"불공정 합병 규정은 분할합병도 포함한다(법인세법 시행령 제88조).","c":"중","v":1},"공인회2025_60-12-1":{"f":"업무무관자산등에 대한 지급이자 손금불산입액을 계산할 때 중소기업에 근무하는 직원(지배주주등인 직원은 제외)에 대한 주택구입 또는 전세자금의 대여액은 특수관계인 가지급금에 포함하지 아니한다.","w":"제외되는 것은 지배주주등이 아닌 직원에 대한 대여액이다. 지배주주등인 직원의 대여는 가지급금에 포함된다.","c":"상","v":1},"공인회2026_61-06-5":{"f":"법인이 기부금을 금전 외의 자산으로 제공한 경우 특수관계인이 아닌 자에게 기부한 일반기부금은 기부했을 때의 장부가액으로 산정한다.","w":"특수관계인이 아닌 자에게 한 일반기부금은 장부가액이다. 큰 금액(장부가액과 시가 중)으로 보는 것은 특수관계인에게 한 일반기부금과 비지정기부금이다.","c":"상","v":1},"공인회2016_51-11-5":{"f":"건물을 2016년 10월 1일부터 2년간 임대하고 2년치의 임대료 2,400만원을 임대만료일에 회수하기로 약정하여 당기 임대료수익을 계상하지 아니한 경우 당기 경과분 300만원을 익금에 산입하는 세무조정이 필요하다.","w":"임대료 지급기간이 1년을 초과하면 지급 약정일이 아니라 기간 경과분을 월수로 안분해 귀속시킨다. 당기 3개월분은 2,400만원×3/24=300만원이다.","c":"중","v":1},"공인회2016_51-13-1":{"f":"적격물적분할에 따라 분할법인이 취득하는 주식의 세무상 취득가액은 물적분할한 순자산의 시가이다.","w":"물적분할로 받은 주식은 순자산을 양도한 대가로 취득한 것이므로 시가가 취득가액이다. 양도차익은 압축기장충당금으로 과세를 이연한다.","c":"중","v":1},"공인회2017_52-07-3":{"f":"상품매매업을 영위하는 법인이 보유하는 화폐성 외화자산·부채에 대한 평가방법을 사업연도 종료일 현재의 매매기준율로 신고하면 그 후의 사업연도에도 계속하여 적용하여야 하나, 그 평가방법을 적용한 사업연도를 포함하여 5개 사업연도가 지난 후에는 다른 방법으로 신고하여 변경할 수 있다.","w":"신고한 외화 평가방법은 계속 적용해야 하지만, 적용한 사업연도를 포함해 5개 사업연도가 지나면 다른 방법으로 신고해 바꿀 수 있다(법인세법 시행령 제76조 제3항).","c":"상","v":1},"공인회2017_52-11-2":{"f":"중소기업인 법인이 장기할부조건으로 자산을 판매하고 인도기준으로 회계처리한 경우, 그 장기할부조건에 따라 각 사업연도에 회수하였거나 회수할 금액과 이에 대응하는 비용을 신고조정에 의하여 해당 사업연도의 익금과 손금에 산입할 수 있다.","w":"회수기준 선택은 결산에 반영하지 않고 신고조정으로 가능한 것은 중소기업에 한정한다. 일반법인은 결산서에 회수기준으로 계상해야 한다.","c":"상","v":1},"공인회2017_52-11-3":{"f":"약정에 의한 지급기일이 2017.12.15.인 매출할인금액을 2018.1.15.에 지급한 경우 그 매출할인금액은 제17기의 매출액에서 차감한다.","w":"매출할인은 약정에 의한 지급기일이 속하는 사업연도의 매출에서 차감하며, 실제 지급일이 아니다.","c":"상","v":1},"공인회2017_52-11-4":{"f":"이미 경과한 기간에 대응하는 이자 300,000원을 제17기의 비용으로 계상한 경우 그 이자는 차입일부터 이자지급일이 1년을 초과하는 특수관계인과의 거래에 따른 이자에 해당하지 않는 경우에만 제17기의 손금으로 한다.","w":"법인이 지급하는 이자의 경과분을 결산에 비용으로 계상하면 그 사업연도의 손금이 된다. 여기서 빠지는 것은 차입일부터 이자지급일이 1년을 넘는 특수관계인과의 거래에 따른 이자다. 원천징수되는 이자를 빼는 규정은 법인이 받는 이자(수익)에 적용된다(법인세법 시행령 제70조 제1항).","c":"상","v":1},"공인회2017_52-11-5":{"f":"임대료 12,000,000원(임대계약기간: 2017.10.1.～2018.9.30.)을 2017.10.1. 선불로 받는 조건으로 임대계약을 체결하고, 그 임대료를 제17기의 수익으로 계상하지 않은 경우 제17기의「법인세법」상 임대료수익은 12,000,000원이다.","w":"임대료 지급기간이 1년 이하이면 계약상 지급일이 귀속시기다. 선불로 받기로 했으므로 전액이 제17기 수익이다.","c":"중","v":1},"공인회2018_53-08-3":{"f":"","w":"출제 당시에는 즉시상각 의제 대상인 공구에서 금형이 빠져 있어, 수선비로 계상한 금형 취득가액을 감가상각비로 보아 상각범위액과 비교하는 세무조정이 필요했다. (2020 개정 전 기준 X. 현행 법인세법 시행령 제31조 제6항 제2호는 공구에서 금형을 빼지 않으므로, 사업에 사용한 해에 손비로 계상하면 그대로 손금이다.)","c":"중","v":1,"old":1,"ow":"출제 당시 정답 X. 2020년 법인세법 시행령 개정 뒤로는 현행 기준으로 맞는 문장이다(금형 즉시상각)."},"공인회2018_53-12-1":{"f":"㈜A가 2018년 3월 1일에 파산한 ㈜C의 주식을 2018년 12월 31일 현재 시가로 감액하고, 그 감액한 금액을 당해 사업연도의 손금으로 계상한 경우 ㈜A와 ㈜C의 특수관계 여부와 관계없이 ㈜C 주식의 장부가액을 감액할 수 있다.","w":"발행법인이 파산한 주식은 특수관계 여부와 상관없이 사업연도 종료일 현재 시가로 감액할 수 있다. 특수관계가 없어야 한다는 요건은 비상장법인이 부도, 회생계획인가, 부실징후기업 지정에 해당한 경우에만 붙는다(법인세법 제42조 제3항 제3호, 시행령 제78조 제2항).","c":"상","v":1},"공인회2018_53-12-2":{"f":"회사가 보유한 화폐성 외화자산ㆍ부채는 취득일 또는 발생일 현재의 매매기준율 등으로 평가하는 방법과 사업연도 종료일 현재의 매매기준율 등으로 평가하는 방법 중 납세지 관할세무서장에게 신고한 방법에 따라 평가해야 한다.","w":"선택 대상은 화폐성 외화자산·부채다. 비화폐성은 취득일 환율로 계속 평가한다.","c":"상","v":1},"공인회2018_53-12-4":{"f":"2018년 7월 2일에 취득 즉시 사업에 사용한 기계장치에 대한 상각범위액은 7월 2일부터 12월 31일까지 월수에 따라 계산한다. 이 때 월수는 역에 따라 계산하되 1월 미만의 일수는 1월로 한다.","w":"감가상각 월수에서 1개월에 못 미치는 일수는 1개월로 계산한다(법인세법 시행령 제26조).","c":"상","v":1},"공인회2018_53-12-5":{"f":"제18기부터 「법인세법」상 재고자산의 평가방법을 선입선출법(적법하게 신고)에서 총평균법으로 변경할 경우, 회사는 재고자산 등 평가방법변경신고서를 2018년 9월 30일까지 납세지 관할세무서장에게 제출해야 한다.","w":"변경신고는 변경하려는 사업연도 종료일 전 3개월이 되는 날까지 한다. 사업연도가 역년인 18기는 2018년 9월 30일이다.","c":"상","v":1},"공인회2019_54-11-4":{"f":"제조업을 영위하는 법인이 보유하는 화폐성외화자산·부채의 평가방법을 관할세무서장에게 신고하여 적용하기 이전 사업연도의 경우 취득일 또는 발생일 현재의 매매기준율로 평가하여야 한다.","w":"금융회사가 아닌 법인은 신고하지 않으면 취득일·발생일 환율로 평가한다. 종료일 환율 평가는 신고한 경우에 적용한다.","c":"중","v":1},"공인회2020_55-13-1":{"f":"금융보험업 이외의 법인이 원천징수되는 이자로서 이미 경과한 기간에 대응하는 이자를 해당 사업연도의 수익으로 계상한 경우에도 그 계상한 사업연도의 익금으로 보지 아니한다.","w":"경과분 이자를 결산에 수익으로 계상하면 그 사업연도 익금이 되지만, 원천징수되는 이자는 이 특례에서 빠져 소득세법 시행령 제45조의 수입시기가 속하는 사업연도의 익금이 된다. 원천징수 이자 제외는 금융보험업 법인에도 똑같이 적용된다. 법인세법 시행령 제70조 제1항 제1호.","c":"중","v":1},"공인회2022_57-22-3":{"f":"법인이 결산을 확정함에 있어서 차입일부터 이자지급일이 1년을 초과하는 특수관계인과의 거래에 따른 기간경과분 미지급이자를 해당 사업연도의 손비로 계상한 경우에는 그 계상한 사업연도의 손금으로 하지 아니한다.","w":"기간경과 미지급이자를 결산에 계상하면 손금으로 인정하나, 특수관계인에게서 차입해 이자지급일이 1년을 초과하는 경우는 제외한다. 실제 지급할 때 손금이다(법인세법 시행령 제70조).","c":"상","v":1},"공인회2023_58-12-2":{"f":"법인이 신고한 화폐성외화자산·부채의 평가방법은 그 후의 사업연도에도 계속하여 적용하여야 한다. 다만, 신고한 평가방법을 적용한 사업연도를 포함하여 5개 사업연도가 지난 후에는 다른 방법으로 신고하여 변경된 평가방법을 적용할 수 있다.","w":"평가방법을 바꿀 수 있는 시점은 신고한 평가방법을 적용한 사업연도를 포함해 5개 사업연도가 지난 후다(법인세법 시행령 제76조 제3항).","c":"상","v":1},"공인회2024_59-09-2":{"f":"납품계약 또는 수탁가공계약에 따라 검사를 거쳐 인수 및 인도가 확정되는 물품의 경우에는 당해 물품의 검수완료일이 속하는 사업연도의 손익으로 한다.","w":"검사를 거쳐 인수·인도가 확정되는 물품은 검사가 끝난 날을 인도한 날로 본다. 계약상 인도 장소에 보관한 날을 쓰는 것은 검사 조건이 없는 납품·수탁가공 물품이다(법인세법 시행규칙 제33조 제1항 제1호).","c":"상","v":1},"공인회2025_60-11-3":{"f":"「은행법」에 따른 은행 등의 금융회사가 금융채무등 불이행자의 신용회복 지원과 채권의 공동추심을 위하여 공동으로 출자하여 설립한 「자산유동화에 관한 법률」에 따른 유동화전문회사로부터 수입하는 배당금은 실제로 지급받은 날이 속하는 사업연도의 익금에 산입한다.","w":"배당금은 보통 소득세법 시행령 제46조의 수입시기(잉여금처분결의일 등)에 귀속되지만, 금융회사 등이 신용회복 지원과 채권 공동추심을 위해 공동출자한 유동화전문회사에서 받는 배당금은 실제로 지급받은 날이 속하는 사업연도의 익금이다(법인세법 시행령 제70조 제2항 단서).","c":"상","v":1},"공인회2026_61-18-4":{"f":"제26기에 특수관계인으로부터 2년 후 원리금 일시 상환 조건으로 차입한 후 결산을 확정할 때 이미 경과한 기간에 대한 차입금 미지급이자 10만원을 이자비용으로 계상하고 이를 손금불산입(유보)으로 세무조정하였다.","w":"특수관계인과 차입일부터 이자지급일까지 1년을 넘는 거래의 경과이자는 결산 계상해도 손금이 아니다. 별도 세무조정이 필요하다.","c":"상","v":1},"공인회2016_51-15-1":{"f":"법인이 기업회계기준에 따라 제품보증충당부채를 손금으로 계상한 때에도 이를 손금에 산입하지 아니하고 실제 보증비용을 지출할 때 손금에 산입한다.","w":"법인세법이 손금 산입을 인정하는 충당금은 퇴직연금충당금, 대손충당금 등 한정되어 있고 제품보증충당부채는 해당하지 않는다.","c":"상","v":1},"공인회2016_51-15-2":{"f":"동일인에 대하여 매출채권과 매입채무가 함께 있는 경우에는 당사자간에 상계하기로 약정한 경우를 제외하고 당해 매입채무를 상계하지 않고 대손충당금을 계상할 수 있다.","w":"약정이 없으면 매입채무를 상계하지 않고 채권 전체를 대손충당금 설정 대상으로 삼을 수 있다. 상계하기로 약정한 때는 상계한 잔액만 설정한다(법인세법 시행령 제61조).","c":"상","v":1},"공인회2016_51-15-3":{"f":"대손충당금을 손금에 산입한 내국법인이 합병한 경우 피합병법인의 대손충당금은 합병법인이 승계할 수 있다.","w":"합병법인이 채권을 승계하면 관련 대손충당금도 승계해 합병등기일에 가지고 있는 충당금으로 본다(법인세법 제34조 제4항).","c":"상","v":1},"공인회2016_51-15-4":{"f":"내국법인이 건물의 화재로 인하여 보험금을 지급받아 그 지급받은 날이 속하는 사업연도에 건물의 취득에 사용한 경우, 건물의 취득에 사용된 보험차익에 상당하는 금액은 일시상각충당금 설정을 통해 손금산입이 가능하다.","w":"보험차익 손금산입은 멸실한 자산과 같은 종류의 자산을 대체 취득하거나 손괴된 자산을 개량할 때만 적용되므로, 건물이 멸실했는데 토지를 산 경우는 해당하지 않는다. 대체 취득한 건물은 감가상각자산이라 일시상각충당금으로 손금에 넣는다. 법인세법 제38조.","c":"중","v":1},"공인회2016_51-19-4":{"f":"해당 법인의 고유목적사업 또는 일반기부금에 지출하기 위하여 고유목적사업준비금을 손금으로 계상한 경우에는 법정한도까지 이를 손금에 산입한다.","w":"고유목적사업준비금은 고유목적사업이나 일반기부금(옛 지정기부금)에 지출하려고 쌓는 준비금이다. 특례기부금은 대상에 들어가지 않는다(법인세법 제29조 제1항).","c":"상","v":1},"공인회2021_56-24-2":{"f":"손금에 산입한 고유목적사업준비금의 잔액이 있는 비영리내국법인이 고유목적사업을 전부 폐지한 경우 그 잔액은 해당 사유가 발생한 날이 속하는 사업연도의 소득금액을 계산할 때 익금에 산입한다.","w":"익금산입 사유는 해산하거나 고유목적사업을 전부 폐지한 경우다. 일부 폐지는 사유가 아니다(법인세법 제29조).","c":"상","v":1},"공인회2021_56-24-3":{"f":"고유목적사업준비금을 손금으로 계상한 사업연도의 종료일 이후 5년이 되는 날까지 고유목적사업등에 사용하지 아니한 때에는 그 잔액을 익금에 산입한다.","w":"사용 기한은 10년이 아니라 5년이다. 5년 안에 쓰지 않은 잔액은 익금에 산입하고 이자상당액도 더해 낸다(법인세법 제29조).","c":"상","v":1},"공인회2021_56-24-4":{"f":"법인으로 보는 단체가 거주자로 변경된 경우 손금에 산입한 고유목적사업준비금 잔액을 익금에 산입한다.","w":"거주자로 변경되면 남은 준비금을 익금에 산입하지만 이자상당액은 붙지 않는다. 이자상당액을 더해 내는 경우는 5년 안에 쓰지 않은 잔액, 고유목적사업등 외의 용도에 쓴 금액, 스스로 잔액을 줄여 익금에 넣은 금액이다(법인세법 제29조 제5항·제7항).","c":"상","v":1},"공인회2021_56-24-5":{"f":"고유목적사업준비금은「소득세법」상 이자소득금액 및 배당소득금액 전액을 한도로 손금에 산입한다.","w":"이자소득금액과 배당소득금액은 100%를 한도로 손금에 산입한다(비영업대금의 이익은 제외). 50%를 곱하는 것은 그 밖의 수익사업에서 생긴 소득이다(법인세법 제29조 제1항).","c":"상","v":1},"공인회2023_58-16-3":{"f":"대손충당금을 손금에 산입한 내국법인이 합병하는 경우 그 법인의 합병등기일 현재 해당 대손충당금 중 합병법인이 승계받은 금액은 그 합병법인이 합병등기일에 가지고 있는 대손충당금으로 본다.","w":"승계받은 충당금은 합병법인이 합병등기일 현재 가진 것으로 본다(법인세법 제34조 제4항).","c":"상","v":1},"공인회2016_51-18-1":{"f":"이월결손금공제는 중소기업과 회생계획을 이행 중인 법인 등을 제외하고 각사업연도소득의 80%까지만 할 수 있다.","w":"일반 법인은 각 사업연도 소득의 80%까지 공제하지만, 중소기업과 회생계획을 이행 중인 기업 등은 100%까지 공제한다(법인세법 제13조 제1항 단서).","c":"상","v":1},"공인회2017_52-18-2":{"f":"외국정부에 납부하였거나 납부할 외국법인세액이 공제한도를 초과하는 경우 그 초과하는 금액은 다음 사업연도로 이월하여 공제받을 수 있다.","w":"한도초과 외국납부세액은 이월 공제가 가능하다(법인세법 제57조).","c":"상","v":1},"공인회2018_53-18-2":{"f":"재해손실세액공제 대상이 되는 법인세에는 재해발생일이 속하는 사업연도의 소득에 대한 법인세, 재해발생일 현재 부과되지 아니한 법인세와 부과된 법인세로서 미납된 법인세가 포함된다.","w":"재해발생일 현재 아직 부과되지 않은 법인세도 공제 대상이다(법인세법 제58조).","c":"상","v":1},"공인회2018_53-18-3":{"f":"국외사업장이 2개 이상의 국가에 있는 경우 외국납부세액 공제의 한도액은 국가별로 구분하여 계산한다.","w":"외국납부세액 공제 한도는 국가별로 각각 계산한다(법인세법 시행령 제94조).","c":"상","v":1},"공인회2018_53-18-4":{"f":"외국정부에 납부하였거나 납부할 외국법인세액이 외국납부세액 공제한도를 초과하는 경우 그 초과하는 금액은 해당 사업연도의 다음 사업연도 개시일부터 10년 이내에 끝나는 각 사업연도에 이월하여 그 이월된 사업연도의 공제한도 범위에서 공제받을 수 있다.","w":"(2020 개정 전 기준 X. 현행은 이월공제기간이 10년이라 맞는 문장이다.) 출제 당시에는 다음 사업연도 개시일부터 5년 이내였다(법인세법 제57조 제2항).","c":"상","v":1,"old":1,"ow":"출제 당시 정답 X. 지금은 외국납부세액 이월공제 기간이 10년으로 늘어 맞는 문장이다."},"공인회2018_53-18-5":{"f":"내국법인이 사실과 다른 회계처리로 인하여 경정을 받음으로써 각 사업연도의 법인세에서 과다 납부한 세액을 공제하는 경우 그 공제하는 금액은 과다 납부한 세액의 100분의 20을 한도로 하며, 공제 후 남아 있는 과다 납부한 세액은 이후 사업연도에 이월하여 공제한다.","w":"각 사업연도에 공제하는 금액은 과다 납부한 세액의 20%가 한도이고, 남은 금액은 이후 사업연도로 넘겨 공제한다(법인세법 제58조의3 제1항).","c":"상","v":1},"공인회2019_54-16-1":{"f":"각사업연도소득금액에서 이월결손금, 비과세소득, 소득공제의 순서로 차감하여 과세표준을 계산한다.","w":"과세표준은 각 사업연도 소득에서 이월결손금, 비과세소득, 소득공제를 순서대로 공제한 금액이다(법인세법 제13조).","c":"상","v":1},"공인회2019_54-16-3":{"f":"법인이 합병시 승계한 이월결손금은 자산수증이익 및 채무면제이익으로 보전할 수 없다.","w":"자산수증이익과 채무면제이익을 이월결손금 보전에 쓰면 익금에 넣지 않지만, 적격합병·적격분할로 승계한 결손금은 보전할 수 있는 이월결손금에서 빠진다(법인세법 제18조 제6호, 시행령 제16조 제1항 제1호).","c":"상","v":1},"공인회2019_54-16-4":{"f":"중소기업이 전기 사업연도에 대한 법인세 과세표준과 세액을 신고기한 내에 신고하고, 당기 사업연도에 대한 법인세 과세표준과 세액도 신고기한 내에 신고한 경우 결손금소급공제를 받을 수 있다.","w":"결손금소급공제는 직전 사업연도와 결손이 발생한 사업연도의 신고를 모두 기한 안에 한 법인에 한한다. 당기 신고를 기한 후에 한 경우에는 받을 수 없다(법인세법 제72조).","c":"상","v":1},"공인회2019_54-16-5":{"f":"결손금소급공제 한도인 직전 사업연도 법인세액에는 가산세를 포함하지 아니하며 토지 등 양도소득에 대한 법인세는 제외한다.","w":"환급 한도는 직전 사업연도 법인세 산출세액에서 공제·감면세액을 뺀 금액이다. 산출세액 기준이므로 가산세는 들어가지 않고, 토지등 양도소득에 대한 법인세도 뺀다(법인세법 제72조 제1항, 시행령 제110조 제1항).","c":"상","v":1},"공인회2019_54-19-1":{"f":"해당 중간예납기간의 법인세액을 기준으로 중간예납세액을 계산할 경우 중간예납기간의 수시부과세액은 차감한다.","w":"중간예납기간 실적으로 계산한 세액에서 감면세액, 원천징수세액과 함께 수시부과세액도 뺀다(법인세법 제63조의2).","c":"상","v":1},"공인회2019_54-19-2":{"f":"내국법인이 납부하여야 할 중간예납세액의 일부를 납부하지 아니한 경우 납부지연가산세가 적용된다.","w":"중간예납세액도 법정 납부기한이 있어 미납하면 납부지연가산세를 부과한다.","c":"중","v":1},"공인회2019_54-19-4":{"f":"합병이나 분할에 의한 신설 내국법인은 최초사업연도의 기간이 6개월을 초과하는 경우 최초사업연도에 대한 중간예납의무가 있다.","w":"새로 설립된 법인의 최초 사업연도는 중간예납을 하지 않지만, 합병이나 분할로 신설된 법인은 이 제외 대상이 아니다. 최초 사업연도가 6개월을 넘으면 중간예납 의무가 있다(법인세법 제63조 제1항).","c":"상","v":1},"공인회2019_54-19-5":{"f":"중간예납의무자는 중간예납기간이 지난 날부터 2개월 이내에 중간예납세액을 신고·납부하여야 한다.","w":"중간예납세액은 중간예납기간이 지난 날부터 2개월 이내에 납부한다(법인세법 제63조 제3항).","c":"상","v":1},"공인회2020_55-19-2":{"f":"납부할 중간예납세액이 1,500만원인 경우 500만원을 납부기한이 지난 날부터 1개월 이내에 분납할 수 있다.","w":"중간예납세액이 1천만원을 넘으면 분납할 수 있고, 2천만원 이하이면 1천만원을 넘는 금액을 분납한다. 1,500만원이면 500만원까지다. 분납 기한은 납부기한이 지난 날부터 1개월(중소기업은 2개월)이다(법인세법 제63조 제4항, 제64조 제2항, 시행령 제101조 제2항).","c":"상","v":1},"공인회2021_56-28-2":{"f":"「조세특례제한법」에 의한 비과세소득을 적용받는 법인은 별도 신청 없이 과세표준 신고서의 소득 계산 과정에서 적용한다.","w":"재해손실세액공제는 신청서를 제출해야 하지만 비과세소득은 신청 절차가 없다.","c":"중","v":1},"공인회2022_57-27-1":{"f":"내국법인의 각 사업연도 소득에 대한 법인세의 과세표준을 계산할 때 공제되지 아니한 소득공제액은 해당 사업연도의 다음 사업연도로 이월하여 공제할 수 없다.","w":"소득공제는 소득이 부족해도 다음 사업연도로 이월되지 않고 소멸한다. 이월이 되는 것은 이월결손금이다(법인세법 제13조).","c":"상","v":1},"공인회2022_57-27-2":{"f":"「자산유동화에 관한 법률」에 따른 유동화전문회사가 배당가능이익의 90% 이상을 배당한 경우 그 금액은 해당 배당의 대상이 되는 사업연도의 소득금액에서 공제한다.","w":"유동화전문회사의 배당 공제는 배당을 결의한 날이 아니라 배당의 대상이 되는 사업연도(귀속 사업연도)의 소득에서 한다(법인세법 제51조의2).","c":"중","v":1},"공인회2022_57-27-3":{"f":"내국법인의 각 사업연도 소득에 대한 법인세의 과세표준은 각 사업연도 소득의 범위에서 이월결손금, 비과세소득 및 소득공제액을 차례로 공제한 금액으로 한다.","w":"공제 순서는 이월결손금, 비과세소득, 소득공제다. 비과세소득이 이월결손금보다 먼저가 아니다(법인세법 제13조).","c":"상","v":1},"공인회2022_57-27-4":{"f":"법인세의 과세표준과 세액을 추계결정하는 경우에는 이월결손금 공제규정을 적용하지 아니하며, 과세표준과 세액을 추계결정함에 따라 공제되지 못한 이월결손금은 그 후의 사업연도 과세표준을 계산할 때 공제할 수 있다.","w":"추계 사업연도에는 이월결손금 공제를 못 하지만, 공제 기간이 남았다면 이후 사업연도에 공제할 수 있다(법인세법 제68조).","c":"중","v":1},"공인회2025_60-13-5":{"f":"직전 사업연도의 산출세액을 기준으로 하는 방법을 적용하여 중간예납세액을 계산할 경우 직전 사업연도에 대한 법인세로서 확정된 산출세액에는 가산세는 포함하나 토지등 양도소득에 대한 법인세액은 포함하지 않는다.","w":"직전 사업연도 산출세액 기준으로 계산할 때 그 산출세액에는 가산세를 넣고, 토지등 양도소득에 대한 법인세액은 뺀다(법인세법 제63조의2 제1항 제1호).","c":"상","v":1},"공인회2026_61-14-1":{"f":"「주식회사 등의 외부감사에 관한 법률」에 따라 감사인에 의한 감사를 받아야 하는 내국법인이 해당 사업연도의 감사가 종결되지 아니하여 결산이 확정되지 아니하였다는 사유로 법정신고기한 종료일 3일 전까지 신고기한의 연장을 신청한 경우에는 그 신고기한을 1개월의 범위에서 연장할 수 있다.","w":"감사가 끝나지 않아 신고기한 연장을 받으려면 신고기한 종료일 3일 전까지 신고기한연장신청서를 내야 한다. 종료일 당일에 낸 신청으로는 연장되지 않는다(법인세법 제60조 제7항, 시행령 제97조 제12항).","c":"상","v":1},"공인회2026_61-14-2":{"f":"「주식회사 등의 외부감사에 관한 법률」에 따라 감사인에 의한 감사를 받아야 하는 영리내국법인이 과세표준신고를 할 때 현금흐름표를 첨부하지 않은 경우에도 무신고로 보지 않는다.","w":"무신고로 보는 것은 재무상태표, 포괄손익계산서, 이익잉여금처분계산서, 세무조정계산서를 첨부하지 않은 경우다. 현금흐름표는 이에 포함되지 않는다(법인세법 제60조).","c":"상","v":1},"공인회2026_61-14-4":{"f":"중소기업에 해당하는 내국법인이 자진납부할 세액이 2천만원 이하인 경우에는 1천만원을 초과하는 금액에 대해 분납할 수 있다.","w":"납부세액이 2천만원을 넘으면 세액의 50% 이하를 분납한다. 2천만원 이하일 때 1천만원 초과분을 분납한다(법인세법 제64조).","c":"상","v":1},"공인회2026_61-14-5":{"f":"직전 사업연도 종료일 현재 「독점규제 및 공정거래에 관한 법률」에 따른 공시대상기업집단에 속하는 기업(업종별 매출액 등을 고려하여 대통령령으로 정한 법인은 제외한다)은 해당 중간예납기간의 법인세액을 기준으로 하는 방법에 따라 중간예납세액을 계산하여야 한다.","w":"공시대상기업집단 소속 법인은 중간예납기간 실적을 기준으로 중간예납세액을 계산해야 한다. 업종별 매출액 등을 고려해 대통령령으로 정한 법인(조세특례제한법 시행령 제2조 제1항 제1호의 요건을 갖춘 기업)은 이 의무에서 빠져 직전 사업연도 산출세액 기준을 고를 수 있다(법인세법 제63조의2 제1항 단서, 시행령 제100조 제4항).","c":"상","v":1},"공인회2017_52-15-1":{"f":"「법인세법」상 요건을 모두 갖춘 적격합병에 해당하여 피합병법인이 합병으로 인한 양도손익이 없는 것으로 한 경우 합병법인은 피합병법인의 자산을 장부가액으로 양도받은 것으로 한다.","w":"적격합병은 양도손익을 이연하므로 합병법인은 장부가액으로 승계한다. 시가로 양도받는 것은 비적격합병이다(법인세법 제44조의3).","c":"상","v":1},"공인회2017_52-15-3":{"f":"「법인세법」상 요건을 모두 갖춘 적격합병의 경우에도 합병법인의 합병등기일 현재 이월결손금은 합병법인의 각 사업연도의 과세표준을 계산할 때 피합병법인으로부터 승계받은 사업에서 발생한 소득금액의 범위에서 공제할 수 없다.","w":"합병법인의 기존 결손금은 합병법인 자신의 사업 소득에서만 공제한다. 승계 사업 소득에서 공제하는 것은 허용되지 않는다(법인세법 제45조).","c":"상","v":1},"공인회2017_52-15-4":{"f":"「법인세법」상 요건을 모두 갖춘 적격합병이 아닌 경우에도 합병법인이 피합병법인의 대손충당금 관련 세무조정사항을 승계할 수 있다.","w":"비적격합병이라도 합병법인이 대손충당금을 채권과 함께 승계하면 그와 관련된 세무조정사항도 승계한다. 그 밖의 세무조정사항을 모두 승계하는 것은 적격합병일 때다(법인세법 제34조 제4항, 시행령 제85조).","c":"상","v":1},"공인회2017_52-15-5":{"f":"합병법인이 합병등기일이 속하는 사업연도의 종료일까지 피합병법인으로부터 승계받은 사업을 계속하여야 한다는 것은 적격합병의 요건 중 하나이다.","w":"사업 계속 요건의 기간은 합병등기일이 속하는 사업연도 종료일까지다. 다음 사업연도부터 5년이 아니다(법인세법 제44조 제2항).","c":"상","v":1},"공인회2022_57-28-2":{"f":"피합병법인의 주주등이 합병으로 인하여 받은 합병대가의 총합계액 중 합병법인의 주식등의 가액이 80% 이상이어야 한다는 것은 적격합병의 요건 중 하나이다.","w":"합병대가의 80% 이상이 합병법인 주식이면 충족한다. 전액이어야 하는 것은 아니다(법인세법 제44조 제2항).","c":"상","v":1},"공인회2023_58-19-2":{"f":"청산소득에 대한 법인세의 납부의무가 있는 법인은 과세표준과 세액을 납세지 관할 세무서장에게 신고하여야 하며 청산소득의 금액이 없는 경우에도 신고하여야 한다.","w":"청산소득 확정신고는 청산소득 금액이 없는 경우에도 해야 한다(법인세법 제84조 제3항).","c":"상","v":1},"공인회2024_59-15-1":{"f":"합병법인이 피합병법인의 자산을 시가로 양도받은 것으로 보는 경우로서 피합병법인에 지급한 양도가액이 피합병법인의 합병등기일 현재의 자산총액에서 부채총액을 뺀 금액보다 작은 경우, 합병법인은 그 차액을 합병등기일부터 5년간 균등하게 나누어 익금에 산입한다.","w":"양도가액이 순자산시가보다 작으면 합병매수차익이 생겨 5년 균등 익금산입한다. 양도가액이 더 크면 합병매수차손으로 5년간 균등하게 손금산입한다(법인세법 제44조의2).","c":"중","v":1},"공인회2025_60-14-1":{"f":"토지등 양도소득에 대한 법인세액은 세액감면과 세액공제의 대상이 되는 법인세 산출세액에 포함되지 않는다.","w":"세액감면은 토지등 양도소득에 대한 법인세액을 뺀 산출세액을 기준으로 계산하고, 감면·공제액 합계의 상한이 되는 납부할 법인세액에서도 이 세액은 뺀다(법인세법 제59조 제1항·제2항).","c":"상","v":1},"공인회2025_60-14-2":{"f":"파산선고에 의해 등기된 비사업용 토지를 처분함으로써 발생하는 소득에 대해서는 토지등 양도소득에 대한 법인세가 과세되지 아니한다.","w":"파산선고에 따른 처분은 토지 등 양도소득 법인세 과세 제외 대상이다(법인세법 제55조의2).","c":"중","v":1},"공인회2025_60-14-3":{"f":"주택을 취득하기 위한 권리인 조합원입주권 및 분양권을 양도한 경우 양도소득에 100분의 20을 곱하여 산출한 세액을 각 사업연도의 소득에 대한 법인세액에 추가하여 납부하여야 한다.","w":"조합원입주권과 분양권 양도소득에는 100분의 20을 곱한 세액을 더해 낸다. 비사업용 토지는 100분의 10이다(법인세법 제55조의2 제1항 제3호·제4호).","c":"상","v":1},"공인회2025_60-14-5":{"f":"주주등이나 출연자가 아닌 임원에게 사택으로 제공하는 법인 소유의 주택(사택제공기간 12년)을 양도하여 발생한 소득은 토지등 양도소득에 대한 법인세 과세대상에 해당하지 아니한다.","w":"주주등이나 출연자가 아닌 임원·직원에게 사택으로 10년 이상 제공한 주택은 과세 대상 주택에서 빠진다. 12년 제공했으므로 과세대상이 아니다(법인세법 시행령 제92조의2).","c":"상","v":1},"공인회2026_61-15-1":{"f":"적격합병을 한 합병법인은 피합병법인의 합병등기일 현재의 특례기부금 및 일반기부금 한도초과액을 피합병법인으로부터 승계한다.","w":"적격합병이면 이월결손금과 함께 기부금 한도초과 이월액도 승계한다(법인세법 제44조의3).","c":"중","v":1},"공인회2026_61-15-3":{"f":"적격합병의 여부와 관계없이 합병등기일 현재의 합병법인의 결손금은 피합병법인으로부터 승계받은 사업의 소득금액에서 공제할 수 없다.","w":"합병법인의 기존 결손금은 합병법인 자신의 사업에서 발생한 소득에서만 공제한다. 승계 사업의 소득금액과 섞어 공제하지 못한다.","c":"상","v":1},"공인회2026_61-15-4":{"f":"적격합병이 아닌 경우 피합병법인의 합병으로 발생하는 양도손익 계산 시 양도가액을 피합병법인이 합병법인으로부터 받은 합병대가의 시가로 한다.","w":"순자산 장부가액을 양도가액으로 보아 양도손익이 없는 것으로 하는 것은 적격합병이다. 비적격합병은 시가로 양도한 것으로 본다(법인세법 제44조).","c":"상","v":1},"공인회2026_61-15-5":{"f":"적격합병의 경우 피합병법인의 주주가 합병대가로 받는 합병법인의 주식가액은 종전의 주식 장부가액으로 평가한다.","w":"의제배당 계산에서 적격합병이면 주주가 받는 합병법인 주식을 종전 주식의 장부가액으로 보아 배당이 생기지 않게 한다(법인세법 시행령 제14조). 시가가 아니다.","c":"중","v":1},"공인회2016_51-20-3":{"f":"미국국적인 A는 내국법인 ㈜한국IT에 네트워크관련 기술자로 근무하고 있으며, 해당 과세기간 종료일 10년 전부터 서울에 주소나 거소를 둔 기간의 합계는 3년이다. 이 경우 A는 국내원천소득과 국외원천소득 중 국내에서 지급되거나 국내로 송금된 소득에 대하여 납세의무를 진다.","w":"국내 주소·거소 기간이 10년 중 5년 이하인 외국인 단기거주자는 국외원천소득에 대해 국내에서 지급되거나 송금된 부분만 납세의무를 진다(소득세법 제3조).","c":"상","v":1},"공인회2017_52-19-4":{"f":"납세지 지정사유가 소멸한 경우 국세청장 또는 관할 지방국세청장은 납세의무자의 요청 여부와 관계없이 납세지의 지정을 취소하여야 한다.","w":"지정 사유가 없어지면 지정을 취소하는 것이 의무다. 납세의무자의 요청에 한정되지 않는다(소득세법 제9조).","c":"중","v":1},"공인회2019_54-20-3":{"f":"내국법인이 발행주식총수의 100분의 100을 직접 또는 간접 출자한 해외현지법인에 파견된 직원은 거주자로 본다.","w":"해외현지법인 파견 임직원을 거주자로 보는 것은 내국법인이 그 현지법인에 100% 직접·간접 출자한 경우에 한한다. 50% 출자 현지법인 파견 직원에게는 이 규정이 적용되지 않는다(소득세법 시행령 제3조).","c":"상","v":1},"공인회2020_55-20-3":{"f":"거주자가 특수관계인에게 자산을 증여한 후 그 자산을 증여받은 자가 그 증여일부터 5년(2023년 이후 증여분은 10년) 이내에 다시 타인에게 양도하여 증여자가 그 자산을 직접 양도한 것으로 보는 경우, 그 양도소득에 대해서는 증여자와 증여받은 자가 연대하여 납세의무를 진다.","w":"부당행위 양도소득세에서는 증여자가 납세의무자이고 증여받은 자가 연대납세의무를 진다(소득세법 제2조의2). 증여자만 납세의무를 지는 것이 아니다. 기간은 2023년 1월 1일 이후 증여분부터 10년으로 늘었다.","c":"상","v":1},"공인회2020_55-21-5":{"f":"비거주자에 대하여 종합과세하는 경우 종합소득공제는 비거주자 본인에 대한 인적공제 등 일부만 적용되고 배우자 등 부양가족 공제와 특별소득공제는 적용되지 않는다.","w":"비거주자는 본인 분 인적공제 외의 부양가족 공제를 받을 수 없고 특별소득공제도 적용하지 않는다(소득세법 제122조).","c":"중","v":1},"공인회2022_57-06-5":{"f":"공동사업에 대한 소득금액을 계산할 때 특수관계인의 소득금액이 주된 공동사업자에게 합산과세되는 경우, 그 합산과세되는 소득금액에 대해서는 주된 공동사업자의 특수관계인은 자신에게 분배된 소득금액을 한도로 주된 공동사업자와 연대하여 납세의무를 진다.","w":"특수관계인은 합산과세되는 소득금액 중 자신에게 분배된 몫의 범위에서 연대납세의무를 진다. 한도 없이 지는 것이 아니다(소득세법 제2조의2).","c":"중","v":1},"공인회2024_59-20-3":{"f":"이축권을 별도로 적법하게 감정평가하여 신고하는 경우 그 이축권을 토지·건물과 함께 양도함으로써 발생하는 소득은 기타소득이다.","w":"이축권을 토지·건물과 함께 양도하면 양도소득이지만, 그 가액을 감정평가법인등의 감정가액으로 구분해 신고하면 양도소득에서 빠진다(소득세법 제94조 제1항 제4호 마목 단서, 시행령 제158조의2). 이때 이축권 대가는 기타소득이다(같은 법 제21조 제1항 제7호).","c":"상","v":1},"공인회2024_59-25-4":{"f":"한국 국적 병은 2024년 5월 7일 미국 소재 IT 회사에 근무하기 위하여 가족과 함께 같은 날 출국하고 거소를 국외로 이전하였다. 병은 2024년 5월 8일부터 국내원천소득에 대해서만 소득세 납세의무를 진다.","w":"거주자가 출국하여 비거주자가 되는 날은 출국한 다음 날이다. 출국일 당일까지는 거주자다.","c":"중","v":1},"공인회2025_60-20-1":{"f":"거주자는 납세지가 변경된 경우 변경된 날부터 15일 이내에 그 변경 후의 납세지 관할세무서장에게 신고하여야 한다.","w":"납세지 변경신고는 변경된 날부터 15일 이내에 변경 후의 납세지 관할 세무서장에게 한다(소득세법 제10조).","c":"상","v":1},"공인회2025_60-20-2":{"f":"거주자의 납세지가 불분명한 경우로서 주소지가 2이상인 때에는 주민등록법에 따라 등록된 곳을 납세지로 한다.","w":"주소지가 둘 이상이면 주민등록법에 따라 등록된 곳이 납세지다. 생활관계가 더 밀접한 곳을 납세지로 하는 것은 거소지가 둘 이상인 경우다(소득세법 시행령 제5조 제1항 제1호).","c":"상","v":1},"공인회2025_60-20-3":{"f":"납세지 지정신청을 하려는 자는 해당 과세기간의 10월 1일부터 12월 31일까지 재정경제부령으로 정하는 납세지 지정신청서를 사업장 관할세무서장에게 제출하여야 한다.","w":"사업장 소재지를 납세지로 지정해 달라는 신청은 해당 과세기간의 10월 1일부터 12월 31일까지 낸다. 관할 지방국세청장은 다음 연도 2월 말일까지 지정 여부를 통지한다(소득세법 시행령 제6조 제1항·제2항).","c":"상","v":1},"공인회2025_60-20-4":{"f":"비거주자의 소득세 납세지는 국내사업장(국내사업장이 둘 이상 있는 경우에는 주된 국내사업장)의 소재지로 하고, 국내사업장이 없는 경우에는 국내원천소득이 발생하는 장소로 한다.","w":"비거주자의 납세지는 국내사업장 소재지이고, 국내사업장이 없으면 거류지·체류지가 아니라 국내원천소득이 발생하는 장소다(소득세법 제6조 제2항).","c":"상","v":1},"공인회2026_61-25-2":{"f":"공동으로 소유한 자산에 대한 양도소득금액을 계산하는 경우에는 해당 자산을 공동으로 소유하는 각 거주자가 각각 납세의무를 진다.","w":"공동소유 자산의 양도소득은 지분에 따라 각자 계산해 각자 납세의무를 진다. 연대납세의무는 없다.","c":"상","v":1},"공인회2019_54-26-3":{"f":"직계존비속에게 주택을 무상으로 사용하게 하고 직계존비속이 해당 주택에 실제 거주하는 경우에는 부당행위계산부인 규정을 적용하지 아니한다.","w":"직계존비속이 실제로 거주하는 주택의 무상 제공은 시가 임대료 상당액을 과세하지 않는다(소득세법 시행령 제98조).","c":"중","v":1},"공인회2021_56-12-2":{"f":"외국납부세액공제의 한도를 초과하는 외국소득세액은 해당 과세기간의 다음 과세기간부터 10년 이내에 끝나는 과세기간에 이월하여 공제받을 수 있으며, 이월공제기간 내에 공제받지 못한 외국소득세액은 그 다음 과세기간의 필요경비에 산입한다.","w":"이월공제기간이 끝날 때까지 공제하지 못한 금액은 소멸하지 않고 필요경비로 산입한다(소득세법 제57조).","c":"중","v":1},"공인회2022_57-11-4":{"f":"근로소득이 있는 거주자는 형제자매의 신용카드등사용금액을 그 거주자의 신용카드등소득공제금액에 포함시킬 수 없다.","w":"신용카드등 사용금액 소득공제에는 본인, 배우자, 직계존비속(기본공제대상자)의 사용분만 넣는다. 형제자매 사용분은 들어가지 않는다(조세특례제한법 제126조의2).","c":"상","v":1},"공인회2024_59-22-1":{"f":"비치ㆍ기록한 장부에 의하여 신고하여야 할 소득금액의 20% 이상을 누락하여 신고한 경우 기장세액공제를 적용하지 않는다.","w":"기장세액공제 배제 기준은 소득금액의 20% 이상 누락이다(소득세법 제56조의2).","c":"상","v":1},"공인회2024_59-22-2":{"f":"재해손실세액공제와 관련하여 자산상실비율을 계산할 때, 상실한 타인소유의 자산으로서 그 상실에 대한 변상책임이 당해 사업자에게 있는 것은 상실 전 자산총액에 포함된다.","w":"변상책임이 사업자에게 있는 타인 소유 자산도 사업자의 손실이므로 자산총액과 상실 자산가액에 포함한다(소득세법 시행령 제118조).","c":"상","v":1},"공인회2024_59-22-4":{"f":"생계를 같이하는 부양가족 중 소득요건을 충족하지 않아 기본공제대상자가 아닌 자에게 지출한 의료비도 의료비 세액공제대상이 될 수 있다.","w":"의료비 세액공제는 나이와 소득금액 요건을 따지지 않고 부양가족을 위해 지출한 의료비를 대상으로 한다(소득세법 제59조의4).","c":"중","v":1},"공인회2024_59-22-5":{"f":"부양가족을 위하여 지급한 학자금대출 원리금 상환액은 교육비 세액공제 대상이 될 수 없다.","w":"학자금대출 원리금 상환액은 대출을 받은 거주자 본인의 교육비로만 공제한다. 부양가족 교육비 항목에는 이 상환액이 없다(소득세법 제59조의4 제3항 제2호 라목).","c":"상","v":1},"공인회2026_61-26-5":{"f":"공제대상부양가족을 서로 자기의 공제대상부양가족으로 하여 신고서에 적은 경우로서 거주자의 공제대상부양가족이 다른 거주자의 공제대상부양가족에 해당하는 때에는 직전 과세기간에 부양가족으로 인적공제를 받은 거주자의 공제대상부양가족으로 한다.","w":"부양가족이 겹치면 직전 과세기간에 그 사람을 부양가족으로 공제받은 거주자의 부양가족으로 한다. 그런 거주자가 없을 때에만 해당 과세기간 종합소득금액이 가장 많은 거주자로 정한다(소득세법 시행령 제106조 제2항 제2호).","c":"상","v":1},"공인회2016_51-23-4":{"f":"퇴직소득에 대하여 외국정부에 납부하였던 외국소득세액에 의한 외국납부세액공제의 한도초과액은 이월공제를 적용받을 수 없다.","w":"한도초과액의 이월공제는 종합소득에 대한 외국납부세액 공제에 적용한다. 분류과세되는 퇴직소득에는 적용하지 않는다.","c":"상","v":1},"공인회2023_58-26-2":{"f":"거주자가 퇴직소득을 지급받은 날부터 60일이 되는 날에 연금계좌에 입금하는 경우 해당 거주자는 퇴직소득의 원천징수세액에 대한 환급을 신청할 수 있다.","w":"퇴직소득을 받은 날부터 60일 이내에 연금계좌에 입금해야 원천징수세액 환급을 신청할 수 있다. 90일째 입금은 해당하지 않는다(소득세법 제146조 제2항).","c":"상","v":1},"공인회2025_60-27-3":{"f":"종업원이 임원이 된 경우에는 퇴직급여를 실제로 받지 않았으면 퇴직으로 보지 않을 수 있다.","w":"종업원이 임원이 되었더라도 퇴직급여를 실제로 받지 않았으면 퇴직으로 보지 않을 수 있다. 퇴직으로 보아야 한다는 의무 규정이 아니다(소득세법 시행령 제43조 제1항 제1호).","c":"상","v":1},"공인회2016_51-28-3":{"f":"반기별 납부를 승인받은 원천징수의무자는 근로소득 등에 대한 원천징수세액을 그 징수일이 속하는 반기의 마지막 달의 다음 달 10일까지 납부할 수 있으나, 「법인세법」상 소득처분된 배당·기타소득은 반기별 납부 대상에서 제외한다.","w":"반기별 납부 승인을 받았어도 법인세법에 따라 소득처분된 상여·배당·기타소득의 원천징수세액은 반기별 납부 대상에서 빠지므로 징수일이 속하는 달의 다음 달 10일까지 내야 한다(소득세법 제128조 제2항 제1호).","c":"상","v":1},"공인회2017_52-28-5":{"f":"간편장부사업자 이외의 사업자가 복식부기에 따라 기장한 경우에도 기장세액공제를 받을 수 없으며, 기장하지 않은 경우에는 무기장가산세가 적용된다.","w":"기장세액공제는 간편장부대상자가 복식부기로 기장했을 때 주는 혜택이다. 복식부기의무자는 원래 의무라 공제가 없다.","c":"상","v":1},"공인회2018_53-27-4":{"f":"직전 연도의 상시고용인원이 20명 이하인 원천징수의무자(금융·보험업자는 제외)로서 원천징수 관할세무서장의 승인을 받거나 국세청장의 지정을 받은 자는 원천징수세액을 그 징수일이 속하는 반기의 마지막 달의 다음 달 10일까지 납부할 수 있다.","w":"특례 납부는 분기가 아니라 반기 단위다. 상시고용인원 20명 이하 요건은 직전 연도 매월 말일 인원의 평균으로 따진다(소득세법 제128조 제2항, 시행령 제186조 제1항·제2항).","c":"상","v":1},"공인회2019_54-29-3":{"f":"원천징수대상 소득으로서 발생 후 지급되지 아니함으로써 원천징수되지 아니한 소득이 종합소득에 합산되어 종합소득에 대한 소득세가 과세된 경우에는 그 소득을 지급할 때 소득세를 원천징수하지 아니한다.","w":"이미 종합소득세로 과세된 소득이므로 나중에 지급할 때는 원천징수하지 않는다. 낸 세금을 돌려주는 절차도 없다(소득세법 제155조).","c":"상","v":1},"공인회2020_55-27-5":{"f":"제조업을 영위하는 사업자의 해당 과세기간의 수입금액의 합계액이 5억원인 경우 성실신고확인대상사업자에 해당하지 아니한다.","w":"제조업은 수입금액 7억5천만원 이상이어야 성실신고확인대상이다. 5억원 기준은 부동산임대업, 전문·과학·기술서비스업 등이다(소득세법 시행령 제133조 제1항).","c":"상","v":1},"공인회2021_56-06-5":{"f":"계약의 위약으로 인하여 계약금이 위약금으로 대체되는 경우에는 소득세를 원천징수하지 아니한다.","w":"계약금이 위약금·배상금으로 대체되는 경우는 원천징수 대상 기타소득에서 빠진다(소득세법 제127조 제1항 제6호 나목).","c":"상","v":1},"공인회2022_57-14-1":{"f":"토지 등 매매차익 예정신고·납부를 한 부동산매매업자도 중간예납의무가 있으며, 중간예납기준액의 2분의 1에서 그 신고·납부한 금액을 뺀 금액을 중간예납세액으로 한다.","w":"부동산매매업자가 중간예납기간 중 매도한 토지·건물의 매매차익을 예정신고·납부했으면 중간예납기준액의 2분의 1에서 그 납부액을 뺀 금액이 중간예납세액이다. 납부액이 2분의 1을 넘을 때만 중간예납세액이 없다(소득세법 제65조 제10항).","c":"상","v":1},"공인회2023_58-27-5":{"f":"부동산매매업자는 토지 또는 건물의 매매차익과 그 세액을 매매일이 속하는 달의 말일부터 2개월이 되는 날까지 납세지 관할세무서장에게 신고하여야 하며, 매매차익이 없거나 매매차손이 발생한 경우에도 신고하여야 한다.","w":"예정신고 대상은 토지뿐 아니라 건물도 포함한다. 차익이 없거나 차손이 나도 신고해야 한다(소득세법 제69조).","c":"상","v":1},"공인회2024_59-27-2":{"f":"법인이 잉여금의 처분에 따라 12월 15일 상여로 처분결정하고 처분결정일부터 3개월이 되는 날까지 지급하지 아니한 경우, 다음연도 2월 말일에 그 상여를 지급한 것으로 보아 소득세를 원천징수한다.","w":"11월 1일부터 12월 31일 사이에 결정한 잉여금 처분은 다음 연도 2월 말일에 지급한 것으로 본다(소득세법 제131조).","c":"상","v":1},"공인회2026_61-20-3":{"f":"직전연도 상시고용인원이 20명 이하인 원천징수의무자로서 원천징수 관할 세무서장의 승인을 받은 자도「법인세법」에 따라 처분된 상여에 대한 원천징수세액은 반기별 납부 대상이 아니므로 그 징수일이 속하는 달의 다음 달 10일까지 납부한다.","w":"소득처분된 상여·배당·기타소득의 원천징수세액은 반기별 납부 특례에서 빠지므로 징수일이 속하는 달의 다음 달 10일까지 낸다(소득세법 제128조 제2항 제1호).","c":"상","v":1},"공인회2018_53-24-1":{"f":"거주자 1인과 그와 생계를 같이 하는 특수관계인이 공동사업자에 포함되어 있는 경우로서 손익분배비율을 거짓으로 정하는 등의 사유가 있는 경우에는 그 특수관계인의 소득금액은 그 손익분배비율이 큰 공동사업자의 소득금액으로 본다.","w":"손익분배비율을 거짓으로 정하면 그 비율에 따른 분배를 인정하지 않고 특수관계인의 소득을 주된 공동사업자에게 합산한다(소득세법 제43조 제3항).","c":"상","v":1},"공인회2018_53-24-2":{"f":"대통령령으로 정하는 중소기업을 영위하는 거주자는 사업소득에서 결손금이 발생되는 경우 종합소득금액에서 먼저 공제하고, 남은 이월결손금을 직전 과세기간으로 소급공제하여 직전 과세기간의 사업소득에 부과된 소득세액을 한도로 환급신청할 수 있다.","w":"소급공제 대상은 해당 과세기간 사업소득 결손금을 근로·연금·기타·이자·배당소득금액에서 먼저 공제하고도 남은 이월결손금이다. 다른 종합소득금액이 있으면 거기서 공제하지 않고 소급공제를 고를 수는 없다(소득세법 제85조의2 제1항, 제45조 제1항·제3항).","c":"상","v":1},"공인회2018_53-24-3":{"f":"거주자가 채권을 내국법인에게 매도하는 경우에는 그 거주자의 보유기간 이자등 상당액을 이자소득으로 보고, 그 채권을 매수하는 법인이 원천징수의무자가 된다.","w":"거주자가 채권을 발행법인이나 대통령령으로 정하는 법인에 매도하면 보유기간 이자등 상당액을 이자소득으로 보고, 그 채권을 사들인 법인이 원천징수한다. 매도한 거주자가 원천징수하지 않는다(소득세법 제133조의2 제1항).","c":"중","v":1},"공인회2018_53-24-4":{"f":"사업소득에서 발생한 결손금은 그 과세기간의 종합소득과세표준을 계산할 때 근로소득금액, 연금소득금액, 기타소득금액, 이자소득금액, 배당소득금액에서 순서대로 공제한다.","w":"결손금 공제 순서는 근로, 연금, 기타, 이자, 배당소득금액 순이다(소득세법 제45조).","c":"상","v":1},"공인회2020_55-25-2":{"f":"공동사업에서 발생한 채무에 대하여 무한책임을 부담하기로 약정한 자는 출자공동사업자에 해당하지 아니한다.","w":"출자공동사업자는 경영에 참여하지 않고 출자만 하는 공동사업자다. 공동사업 채무에 무한책임을 지기로 약정한 자와 자기 성명·상호를 쓰게 한 자는 출자공동사업자에서 빠진다(소득세법 시행령 제100조 제1항).","c":"상","v":1},"공인회2020_55-25-3":{"f":"공동사업장의 해당 공동사업을 경영하는 각 거주자는 사업장 관할 세무서장에게 사업자등록을 해야 한다.","w":"공동사업자는 공동사업장을 1사업자로 보아 사업장 소재지 관할 세무서장에게 사업자등록을 한다(소득세법 제87조 제3항, 제168조 제1항).","c":"상","v":1},"공인회2020_55-25-4":{"f":"출자공동사업자의 배당소득 수입시기는 그 배당소득이 발생한 과세기간의 종료일이다.","w":"출자공동사업자의 배당은 지급일이 아니라 과세기간 종료일에 수입한 것으로 본다(소득세법 시행령 제46조).","c":"상","v":1},"공인회2020_55-25-5":{"f":"출자공동사업자의 배당소득 원천징수세율은 25%이다.","w":"출자공동사업자의 배당소득은 14%가 아니라 25%의 세율로 원천징수한다(소득세법 제129조).","c":"상","v":1},"공인회2021_56-07-2":{"f":"지급일 현재 주민등록표등본에 의하여 그 거주사실이 확인된 채권자가 차입금을 변제받은 후 소재불명이 된 경우 그 차입금의 이자는 사업소득금액을 계산할 때 필요경비에 산입한다.","w":"채권자 불분명 이자는 필요경비 불산입이다. 다만 지급 시점에 주민등록표 등으로 거주 사실이 확인되었으면 이후 소재불명이 되어도 필요경비로 인정한다.","c":"중","v":1},"공인회2022_57-07-2":{"f":"거주자가 채권을 내국법인에게 매도하는 경우에는 그 거주자의 보유기간 이자등 상당액을 이자소득으로 보아 그 법인이 소득세를 원천징수하여야 한다.","w":"원천징수의무자는 이자소득 지급자인 매수 법인이며, 매도한 거주자가 아니다.","c":"중","v":1},"공인회2023_58-21-4":{"f":"사업자가 조직한 납세조합이 조합원에 대한 매월분의 소득세를 징수할 때에는 그 세액의 100분의 5에 해당하는 금액을 공제하여 징수하되, 공제하는 금액은 연 100만원을 한도로 한다.","w":"납세조합공제 한도는 연 100만원이다(소득세법 제150조 제4항). 사업자가 조직한 납세조합의 5% 공제는 2024년 12월 31일 이전에 징수하는 분까지만 적용된다(같은 조 제2항).","c":"상","v":1},"공인회2025_60-22-5":{"f":"부가가치세법시행령에 따른 조제용역의 공급으로 발생하는 사업소득 중 재정경제부령으로 정하는 바에 따라 계산한 의약품가격이 차지하는 비율에 상당하는 소득은 원천징수대상 사업소득에서 제외한다.","w":"원천징수대상 사업소득은 면세 의료보건용역과 인적용역에서 생기는 소득이지만, 조제용역 대가 중 의약품가격 비율에 해당하는 소득은 제외한다(소득세법 시행령 제184조 제1항 제1호).","c":"상","v":1},"공인회2025_60-23-3":{"f":"연금계좌의 가입자가 사망하였으나 그 배우자가 연금외수령 없이 해당 연금계좌를 상속으로 승계하는 경우 상속인이 승계한 연금계좌의 소득금액은 상속인의 소득금액으로 본다.","w":"배우자가 연금외수령 없이 연금계좌를 상속으로 승계하면 그 계좌에 있는 피상속인의 소득금액을 상속인의 소득금액으로 보아 소득세를 계산한다(소득세법 제44조 제2항).","c":"상","v":1},"공인회2018_53-25-3":{"f":"거주자의 퇴직소득이 퇴직일 현재 연금계좌에 있거나 연금계좌로 지급되는 경우에는 해당 퇴직소득에 대한 소득세를 연금외수령하기 전까지 원천징수하지 아니한다.","w":"연금계좌로 옮긴 퇴직소득은 비과세가 아니라 과세이연이다. 연금외수령하면 그때 원천징수한다.","c":"상","v":1},"공인회2021_56-09-1":{"f":"공무원이 국가 또는 지방자치단체로부터 공무 수행과 관련하여 받는 상금과 부상은 근로소득이다.","w":"공무원이 공무 수행과 관련해 국가·지방자치단체에서 받는 상금과 부상은 근로소득이다(소득세법 시행령 제38조 제1항 제20호). 이 가운데 연 240만원 이내 금액은 비과세 근로소득이다(같은 영 제17조의4 제4호).","c":"상","v":1},"공인회2023_58-23-3":{"f":"연금계좌에서 인출된 금액이 연금수령한도를 초과하는 경우에는 연금수령분이 먼저 인출되고 그 다음으로 연금외수령분이 인출되는 것으로 본다.","w":"인출된 금액이 연금수령한도를 넘으면 연금수령분이 먼저 인출되고 그 다음에 연금외수령분이 인출된 것으로 본다(소득세법 시행령 제40조의3 제3항).","c":"상","v":1},"공인회2026_61-27-1":{"f":"퇴직연금계좌에 있는 일부 금액이 연금수령이 개시되기 전의 다른 연금계좌로 이체되는 경우에는 이를 인출로 본다.","w":"연금수령 개시 전의 다른 연금계좌로 옮기는 이체는 원칙적으로 인출로 보지 않지만, 퇴직연금계좌에 있는 일부 금액을 이체하는 경우는 인출로 본다(소득세법 시행령 제40조의4 제1항 제3호).","c":"상","v":1},"공인회2025_60-32-1":{"f":"일반과세자는 공급가액의 합계액을 과세표준으로 하나, 간이과세자는 공급대가의 합계액을 과세표준으로 한다.","w":"간이과세자의 과세표준은 부가가치를 차감한 금액이 아니라 부가가치세가 포함된 공급대가다. 여기에 업종별 부가가치율과 세율을 곱해 세액을 계산한다(부가가치세법 제61조).","c":"상","v":1},"공인회2025_60-32-2":{"f":"사업자가 음식·숙박 용역을 공급하고 그 대가와 함께 받는 종업원의 봉사료를 신용카드매출전표등에 구분하여 적고 자기의 수입금액으로 계상하지 않은 경우에는 그 봉사료를 공급가액에 포함하지 않는다.","w":"봉사료를 구분 기재하더라도 사업자가 수입금액에 넣었다면 공급가액에 포함한다. 종업원에게 전달하는 돈으로 처리한 경우만 제외한다(부가가치세법 시행령 제61조).","c":"상","v":1},"공인회2025_60-32-3":{"f":"사업자가 재화나 용역을 공급받는 자에게 지급하는 장려금은 과세표준에서 공제하지 않으며, 회수불능으로 확정된 대손금액도 과세표준에서 공제하지 않는다.","w":"대손금은 과세표준에서 빼지 않고 대손세액공제로 납부세액에서 공제한다(부가가치세법 제29조, 제45조).","c":"상","v":1},"공인회2025_60-32-4":{"f":"할부판매의 경우 공급한 재화의 총가액을 과세표준으로 하는 것이 원칙이나, 장기할부판매의 경우에는 계약에 따라 받기로 한 대가의 각 부분을 공급가액으로 하며 할부이자 상당액을 공급가액에서 공제하지 않는다.","w":"할부판매는 공급한 재화의 총가액, 장기할부판매는 계약에 따라 받기로 한 대가의 각 부분이 공급가액이다(부가가치세법 시행령 제61조 제2항). 할부이자 상당액은 어느 경우든 공급가액에 포함된다.","c":"중","v":1},"공인회2017_52-29-1":{"f":"사업자 단위 과세 사업자가 자기의 사업과 관련하여 생산 또는 취득한 재화를 판매할 목적으로 자기의 다른 사업장에 반출하는 경우 재화의 공급으로 보지 아니한다.","w":"사업자 단위 과세는 본점이나 주사무소에서 사업장 전체를 하나로 신고하므로 사업장 간 반출을 공급으로 보지 않는다. 사업장별 과세 사업자는 판매 목적 타 사업장 반출을 공급으로 본다(부가가치세법 제10조).","c":"상","v":1},"공인회2017_52-29-3":{"f":"전기, 가스, 열등 관리할 수 있는 자연력은 재화로 본다.","w":"물건뿐 아니라 관리할 수 있는 자연력도 재화에 포함된다(부가가치세법 제2조).","c":"상","v":1},"공인회2017_52-29-4":{"f":"주된 사업에 부수된 거래로 주된 사업과 관련하여 우연히 또는 일시적으로 공급되는 재화 또는 용역의 공급은 별도의 공급으로 보되, 과세 및 면세 여부 등은 주된 사업의 과세 및 면세 여부 등을 따른다.","w":"주된 사업과 관련해 우연히 또는 일시적으로 공급되는 재화·용역은 별도의 공급으로 보지만, 과세·면세 여부는 주된 사업을 따른다(부가가치세법 제14조 제2항).","c":"상","v":1},"공인회2017_52-29-5":{"f":"질권, 저당권 또는 양도담보의 목적으로 동산, 부동산 및 부동산상의 권리를 제공하는 것은 재화의 공급으로 보지 아니한다.","w":"담보로 제공하는 것은 소유권을 넘기는 거래가 아니므로 재화의 공급이 아니다(부가가치세법 제10조).","c":"상","v":1},"공인회2017_52-31-2":{"f":"영세율적용대상 거래만 있는 사업자도 「부가가치세법」상 신고의무가 있다.","w":"영세율 사업자도 과세표준 신고를 해야 하고, 매입세액 환급을 받으려면 신고가 필요하다.","c":"상","v":1},"공인회2017_52-31-3":{"f":"과세의 대상이 되는 행위 또는 거래의 귀속이 명의일 뿐이고 사실상 귀속되는 자가 따로 있는 경우에는 사실상 귀속되는 자에 대하여 「부가가치세법」을 적용한다.","w":"실질과세원칙에 따라 명의자가 아니라 사실상 귀속되는 자를 납세의무자로 하여 세법을 적용한다(국세기본법 제14조 제1항).","c":"상","v":1},"공인회2017_52-31-4":{"f":"국가 및 지방자치단체도 부가가치세 납세의무자가 될 수 있다.","w":"납세의무자는 영리 목적 여부와 관계없이 사업상 독립적으로 재화·용역을 공급하는 자다. 국가와 지방자치단체도 포함된다.","c":"상","v":1},"공인회2017_52-31-5":{"f":"「여객자동차 운수사업법」에 따른 여객자동차 운수사업 중 관광용 전세버스 운송사업을 영위하는 내국법인은 부가가치세 납세의무를 부담한다.","w":"여객운송 용역은 면세지만 전세버스운송사업에 제공되는 자동차의 여객운송은 면세에서 빠져 과세된다(부가가치세법 제26조 제1항 제7호, 같은 법 시행령 제37조 제1호).","c":"상","v":1},"공인회2017_52-32-1":{"f":"외국인도수출(수출대금을 국내에서 영수하지만 국내에서 통관되지 아니한 수출물품 등을 외국으로 인도하거나 제공하는 수출)로서 국내사업장에서 계약과 대가수령 등 거래가 이루어지는 것은 영세율을 적용한다.","w":"외국인도수출은 수출로 보아 영세율을 적용한다(부가가치세법 시행령 제31조).","c":"중","v":1},"공인회2017_52-33-5":{"f":"재화의 수입시기는 당해 재화가 수입신고가 수리된 때로 한다.","w":"수입 재화에 대한 부가가치세는 세관장이 수입신고를 수리하는 때 부과한다. 보세창고 입고 시점이 아니다.","c":"중","v":1},"공인회2018_53-32-1":{"f":"국내사업장에서 계약하고 대가를 수령한 위탁판매수출(물품 등을 무환으로 수출하여 해당 물품이 판매된 범위에서 대금을 결제하는 계약에 의한 수출)을 하고 판매대금을 외화로 수령하는 경우에는 영세율을 적용한다.","w":"위탁판매수출은 수출에 해당해 영세율을 적용한다. 외화로 대금을 받는 것이 영세율을 배제하는 사유가 아니다.","c":"중","v":1},"공인회2018_53-32-2":{"f":"내국신용장에 의해 공급되는 재화(금지금은 제외)는 수출업자에게 공급하는 경우 영세율을 적용한다.","w":"내국신용장·구매확인서로 국내 수출업자에게 공급하는 재화는 영세율 적용 대상이다(부가가치세법 시행령 제31조). 비거주자가 지정하는 사업자에게 인도하는 것으로 한정하지 않는다.","c":"중","v":1},"공인회2018_53-32-3":{"f":"외국에서 수입한 관상용 거북이는 과세대상 재화이다.","w":"면세 대상은 식용 미가공 식료품과 국산 비식용 농·축·수·임산물이다. 외국에서 수입한 관상용 동물은 과세한다.","c":"중","v":1},"공인회2018_53-32-4":{"f":"법인이 물적 시설 없이 근로자를 고용하여 작곡용역을 공급한 후 대가를 받는 용역은 면세대상이 아니다.","w":"인적용역 면세는 개인이 물적 시설 없이 근로자를 고용하지 않고 용역을 제공할 때 적용한다. 법인은 해당하지 않는다(부가가치세법 제26조).","c":"상","v":1},"공인회2019_54-32-2":{"f":"국민주택규모 이하 주택의 임대용역뿐 아니라 국민주택규모를 초과하는 주택의 임대용역도 면세대상이다.","w":"주택과 부수 토지의 임대용역은 규모와 관계없이 면세다(부가가치세법 제26조). 국민주택규모는 주택 공급(분양)의 면세 기준이다.","c":"상","v":1},"공인회2020_55-30-1":{"f":"사업자가 재화의 공급시기가 되기 전에 세금계산서를 발급하고, 그 세금계산서 발급일로부터 7일 이내에 대가를 받으면 해당 세금계산서 발급일을 재화의 공급시기로 본다.","w":"7일 이내에 대가를 받으면 세금계산서를 발급한 때를 공급시기로 본다(부가가치세법 제17조). 대가를 받은 때가 아니다.","c":"상","v":1},"공인회2020_55-33-1":{"f":"사업자가 부가가치세를 별도로 적은 세금계산서를 발급하여 수출업자와 직접도급계약에 의한 수출재화 임가공용역을 제공한 경우 영세율을 적용하지 아니한다.","w":"수출업자와 직접 도급계약으로 수출재화를 임가공하는 용역은 영세율 대상이지만, 부가가치세를 별도로 적은 세금계산서를 발급한 경우는 제외한다(부가가치세법 시행령 제33조 제2항 제3호).","c":"상","v":1},"공인회2021_56-30-3":{"f":"사업자가 대가의 전부를 자기적립마일리지로만 결제받고 재화를 인도하는 경우 재화의 공급으로 보지 아니한다.","w":"사업을 위한 증여 가운데 자기적립마일리지등으로만 전부를 결제받고 공급하는 재화는 재화의 공급으로 보지 않는다(부가가치세법 제10조 제5항 단서, 같은 법 시행령 제20조 제3호).","c":"상","v":1},"공인회2022_57-30-1":{"f":"외국 선박에 의하여 공해(公海)에서 잡힌 수산물을 국내로 반입하는 거래는 재화의 수입으로 과세대상이다.","w":"국내로 반입하는 외국 물품은 재화의 수입이므로 과세대상이다.","c":"중","v":1},"공인회2022_57-30-2":{"f":"사업자가 아닌 개인이 중고자동차를 사업자에게 판매하는 거래는 과세대상이 아니지만, 사업자가 아닌 개인이 소형승용차를 외국으로부터 수입하는 거래는 과세대상이다.","w":"부가가치세는 사업자의 공급에 과세하므로 비사업자 개인의 판매는 대상이 아니다. 재화의 수입은 수입자가 사업자인지와 관계없이 과세한다.","c":"상","v":1},"공인회2022_57-30-4":{"f":"사업자가 「민사집행법」에 따른 경매로 재화를 공급하는 경우와 「국세징수법」에 따른 공매로 재화를 공급하는 경우는 모두 과세대상이 아니다.","w":"법에 따른 경매와 공매는 재화의 공급에서 제외한다(부가가치세법 시행령 제18조).","c":"상","v":1},"공인회2022_57-30-5":{"f":"사업자가 주요자재를 전혀 부담하지 아니하고 인도받은 재화를 단순히 가공만 해 주는 경우는 용역의 공급으로서 과세대상이다.","w":"주요자재를 전혀 부담하지 않고 상대방에게서 인도받은 재화를 단순히 가공만 해 주는 것은 용역의 공급이다(부가가치세법 제11조, 같은 법 시행령 제25조 제2호).","c":"상","v":1},"공인회2022_57-33-1":{"f":"사업자가 국내사업장이 없는 외국법인에게 공급한 컨테이너 수리용역은 그 대금을 외국환은행에서 원화로 받는 등 정해진 방법으로 받은 경우에 영세율 대상이다.","w":"국내사업장이 없는 외국법인에게 국내에서 공급하는 컨테이너수리용역은 대금을 외국환은행에서 원화로 받거나 재정경제부령으로 정하는 방법으로 받아야 영세율을 적용한다(부가가치세법 시행령 제33조 제2항 제1호 마목). 대금수취 방법과 관계없이 영세율을 적용하는 것은 국외에서 공급하는 용역이다.","c":"상","v":1},"공인회2023_58-31-5":{"f":"「관광진흥법」에 따른 종합여행업자가 외국인 관광객에게 공급하는 관광알선용역은 그 대가를 외국환은행에서 원화로 받거나 외화 현금으로 받아 외국인 관광객과의 거래임이 확인되는 경우에만 영세율을 적용한다.","w":"종합여행업자의 외국인 관광객 관광알선용역은 대가를 외국환은행에서 원화로 받거나, 외화 현금으로 받은 것 중 관광알선수수료명세표와 외화매입증명서로 외국인 관광객과의 거래임이 확인되는 경우에만 영세율을 적용한다(부가가치세법 시행령 제33조 제2항 제7호).","c":"상","v":1},"공인회2024_59-31-5":{"f":"수출업자(A)에게 내국신용장으로 재화를 공급하는 사업자(B)와 직접 도급계약에 의하여 수출재화임가공용역을 제공하는 사업자(C)의 수출재화임가공용역은 영세율을 적용하지 않는다.","w":"수출재화임가공용역은 수출업자와 직접 도급계약을 맺어 제공하거나 내국신용장·구매확인서에 의하여 공급해야 영세율을 적용한다(부가가치세법 시행령 제33조 제2항 제3호·제4호). C는 수출업자가 아닌 B와 도급계약을 맺었고 내국신용장·구매확인서도 없으므로 영세율 대상이 아니다.","c":"중","v":1},"공인회2024_59-33-5":{"f":"재화의 공급으로 보는 가공의 경우 가공된 재화를 인도하는 때를 공급시기로 본다.","w":"자기가 주요자재를 부담해 가공하는 것은 재화의 공급이고, 공급시기는 가공이 끝난 때가 아니라 인도하는 때다.","c":"상","v":1},"공인회2025_60-30-5":{"f":"영리를 목적으로 상가를 임대하는 사업자가 특수관계인에게 사업용 부동산임대용역을 무상으로 제공하는 것은 부가가치세 과세대상이다.","w":"특수관계인에게 사업용 부동산 임대용역을 무상으로 제공하면 시가를 과세표준으로 하는 용역의 공급으로 본다(부가가치세법 제12조).","c":"상","v":1},"공인회2026_61-34-4":{"f":"스포츠센터를 운영하는 사업자가 연회비를 선불로 받고 회원들에게 시설을 이용하게 하였으나 당해 과세기간의 종료일 전에 폐업한 경우에는 폐업일을 용역의 공급시기로 본다.","w":"스포츠센터 연회비처럼 선불로 받는 용역의 공급시기는 원래 예정신고기간 또는 과세기간의 종료일이지만, 폐업 전에 공급한 용역의 공급시기가 폐업일 이후에 오면 폐업일을 공급시기로 본다(부가가치세법 시행령 제29조 제2항 제3호, 제3항).","c":"상","v":1},"공인회2026_61-35-1":{"f":"신탁재산과 관련된 재화 또는 용역을 위탁자 명의로 공급하는 경우에는 위탁자가 부가가치세를 납부할 의무가 있다.","w":"신탁재산 관련 거래는 공급 명의에 따라 납세의무자가 정해진다. 위탁자 명의면 위탁자, 수탁자 명의면 수탁자다(부가가치세법 제3조).","c":"중","v":1},"공인회2026_61-35-2":{"f":"공동수탁자는 부가가치세를 연대하여 납부할 의무가 있으며, 이 경우 신탁사무를 주로 처리하는 대표수탁자가 부가가치세를 신고·납부해야 한다.","w":"공동수탁자는 부가가치세를 연대하여 납부할 의무를 지고, 신고·납부는 공동수탁자 중 신탁사무를 주로 처리하는 대표수탁자가 한다(부가가치세법 제3조 제4항).","c":"상","v":1},"공인회2026_61-35-3":{"f":"수탁자가 납부하여야 하는 부가가치세를 신탁재산으로 충당하여도 부족한 경우에는 그 신탁의 수익자가 그 부족한 금액에 대하여 제2차 납세의무를 진다.","w":"수탁자가 낼 부가가치세를 신탁재산으로 충당해도 부족하면 위탁자가 아니라 신탁의 수익자가, 지급받은 수익과 귀속된 재산의 가액을 합한 금액을 한도로 제2차 납세의무를 진다(부가가치세법 제3조의2 제1항).","c":"상","v":1},"공인회2026_61-35-4":{"f":"위탁자가 부가가치세를 체납한 경우 그 위탁자의 다른 재산에 대하여 강제징수를 하여도 징수할 금액에 미치지 못할 때에는 해당 신탁재산의 수탁자가 그 신탁재산으로써 부족한 금액을 납부할 의무가 있다.","w":"부족액은 수익자가 아니라 신탁재산을 가진 수탁자가 신탁재산을 한도로 부담한다(물적납세의무, 부가가치세법 제3조의2).","c":"중","v":1},"공인회2016_51-33-1":{"f":"3월 25일 재화를 인도하고 6월 25일 대금을 수령하면서 6월 25일자로 세금계산서가 발행된 경우, 해당 세금계산서로 공급받는 자는 매입세액을 공제받을 수 있다.","w":"공급시기가 속하는 과세기간(1기) 내에 발급된 세금계산서로 지연 발급분이다. 공급자에게 가산세가 있을 뿐 공급받는 자는 매입세액을 공제받는다.","c":"중","v":1},"공인회2016_51-35-3":{"f":"간이과세자도 간이과세를 포기하지 않고 수출에 대하여 영세율을 적용받을 수 있다.","w":"영세율은 간이과세자에게도 적용되나, 매입세액 환급을 받으려면 간이과세 포기가 필요하다.","c":"중","v":1},"공인회2017_52-35-3":{"f":"2017년 납부의무가 면제되는 간이과세자 C는 2017년 부가가치세 23,000원을 납부하였다. 이 경우 관할 세무서장은 납부금액에 대한 환급의무를 진다.","w":"납부의무가 면제되는 간이과세자가 자진 납부한 사실이 확인되면 관할 세무서장은 납부한 금액을 환급해야 한다(부가가치세법 제69조 제4항).","c":"상","v":1},"공인회2018_53-34-2":{"f":"면세농산물을 공급받아 과세재화와 면세재화를 공급하는 사업자가 당기 중에 매입하였으나 사용하지 않은 면세농산물도 의제매입세액공제를 적용한다.","w":"의제매입세액공제는 면세농산물을 공급받은 날이 속하는 과세기간에 적용한다. 사용 여부와 상관없이 한도 내에서 공제한다.","c":"중","v":1},"공인회2018_53-34-3":{"f":"일반과세자가 간이과세를 적용받게 되면 이미 공제받은 재고품 등의 매입세액을 간이과세자의 납부세액에 가산한다.","w":"일반과세로 공제받은 재고 매입세액을 간이과세로 바뀔 때 돌려내는 재고납부세액이다. 추가 공제 규정이 아니다(부가가치세법 제64조).","c":"상","v":1},"공인회2018_53-34-4":{"f":"2018년 6월 25일에 사업을 개시하고 2018년 7월 15일 사업자등록 신청을 한 도매업자가 2018년 6월 28일에 매입한 상품에 대한 매입세액은 공제받을 수 있다.","w":"공급시기가 속하는 과세기간 종료 후 20일 이내에 등록을 신청하면 등록 전 매입세액도 공제한다. 1기 종료 후 20일인 7월 20일 안이다.","c":"상","v":1},"공인회2018_53-34-5":{"f":"과세사업에만 사용하던 감가상각대상 재화를 면세사업에만 사용하게 된 경우에는 재화의 공급으로 보아 과세표준을 계산하여 납부세액에 가산한다.","w":"면세사업으로 전용하면 재화의 공급(면세전용 간주공급)이다. 감가상각 후 금액을 공급가액으로 하여 세액을 낸다(부가가치세법 제10조).","c":"중","v":1},"공인회2018_53-35-1":{"f":"위탁에 의하여 재화를 공급하는 위탁판매의 경우에는 수탁자가 위탁자의 명의로 세금계산서를 발급하며, 이 경우 수탁자의 등록번호를 덧붙여 적어야 한다.","w":"수탁자가 재화를 인도하는 위탁판매에서는 수탁자가 위탁자 명의로 세금계산서를 발급하고 수탁자의 등록번호를 덧붙여 적는다. 위탁자가 직접 재화를 인도할 때는 위탁자가 발급할 수 있고, 이때도 수탁자의 등록번호를 덧붙인다(부가가치세법 시행령 제69조 제1항).","c":"상","v":1},"공인회2018_53-35-3":{"f":"세금계산서 교부의무가 있는 일반과세자로부터 재화를 공급받은 간이과세자는 공급하는 자가 세금계산서를 발급하지 아니한 경우 매입자발행 세금계산서를 발급할 수 있다.","w":"매입자발행 세금계산서는 공급받는 사업자라면 과세 유형과 관계없이 요건(거래 건당 5만원 이상 등)을 갖추면 발급할 수 있다.","c":"중","v":1},"공인회2018_53-35-4":{"f":"사업자는 15일 단위로 거래처별 공급가액을 합하여 그 기간의 종료일을 작성 연월일로 하여 세금계산서를 발급할 수 있다.","w":"달의 1일부터 말일까지의 기간 안에서 사업자가 임의로 정한 기간의 공급가액을 거래처별로 합하여 발급할 때는 그 기간의 종료일을 작성 연월일로 한다. 해당 달의 말일을 작성 연월일로 하는 것은 1일부터 말일까지 한 달 치를 합할 때다(부가가치세법 제34조 제3항).","c":"상","v":1},"공인회2018_53-35-5":{"f":"미용업을 영위하는 일반과세자가 미용용역을 제공하는 경우에 세금계산서 발급의무가 면제되며 공급받은 자가 사업자등록증을 제시하고 세금계산서 발급을 요구하더라도 세금계산서를 발급할 수 없다.","w":"미용·욕탕 및 유사 서비스업은 영수증만 발급하는 업종이라 요구가 있어도 세금계산서를 발급하지 않는다(부가가치세법 시행령 제73조).","c":"상","v":1},"공인회2018_53-37-1":{"f":"","w":"(2020 개정 전 기준 X. 당시에는 간이과세자의 신용카드매출전표 발급 세액공제율이 음식점업·숙박업과 그 밖의 업종으로 나뉘어 달랐다. 현행은 업종 구분 없이 발급금액의 1%, 2026년 12월 31일까지는 1.3%를 공제하므로 맞는 문장이다(부가가치세법 제46조 제1항 제3호).)","c":"중","v":1,"old":1,"ow":"출제 당시 정답 X. 2020년 부가가치세법 개정으로 간이과세자 신용카드 매출세액공제율이 바뀌어, 현행 기준으로는 맞는 문장이다."},"공인회2018_53-37-2":{"f":"일반과세자 중 사업장을 기준으로 직전 사업연도 공급가액 합계액이 10억원 이하인 영수증 발급대상 개인사업자가 부가가치세가 과세되는 재화·용역을 공급하고 신용카드매출전표를 발급한 경우에는 연간 한도 내에서 그 발급금액의 일정률을 공제한다.","w":"신용카드매출전표 발급 세액공제에는 연간 한도가 있다(부가가치세법 제46조). 한도 없이 공제하지 않는다.","c":"상","v":1},"공인회2018_53-37-3":{"f":"국내사업장이 없는 외국법인으로부터 용역을 공급받은 면세사업자는 그 대가를 지급하는 때에 부가가치세를 징수하여야 한다.","w":"재화는 수입 단계에서 세관이 과세한다. 국내사업장이 없는 외국법인의 용역을 공급받은 면세사업자가 대리납부한다(부가가치세법 제52조).","c":"상","v":1},"공인회2018_53-37-5":{"f":"국내사업장이 없는 비거주자로부터 용역의 공급을 받는 자는 공급받은 용역을 과세사업에 사용하지 않는 경우에만 부가가치세를 징수하여 납부하여야 한다.","w":"과세사업에 쓰면 어차피 매입세액을 공제받으므로 대리납부 의무가 없다. 면세사업이나 비사업용으로 쓸 때 대리납부한다(부가가치세법 제52조).","c":"상","v":1},"공인회2019_54-31-4":{"f":"전자세금계산서 의무발급 사업자가 세금계산서의 발급시기가 지난 후 해당 재화 또는 용역의 공급시기가 속하는 과세기간에 대한 확정신고 기한까지 세금계산서를 발급하지 아니한 경우에는 그 공급가액의 2%의 가산세가 적용된다.","w":"확정신고 기한 안에 발급하면 지연발급 1%이고, 그때까지도 발급하지 않으면 미발급 2%다(부가가치세법 제60조).","c":"상","v":1},"공인회2019_54-33-4":{"f":"주사업장 총괄납부 사업자의 세금계산서 발급·수취 의무와 부가가치세 신고 의무는 각 사업장 단위로 이행하고, 납부 의무만 주사업장에서 총괄하여 이행한다.","w":"총괄납부는 납부만 모아서 하는 제도다. 신고는 사업장별로 한다(부가가치세법 제51조).","c":"상","v":1},"공인회2019_54-37-5":{"f":"관할세무서장의 경정에 따라 2019년 9월 9일 환급세액이 발생한 경우, 지체 없이 환급하여야 한다.","w":"경정에 따른 환급은 기한 없이 지체 없이 환급한다. 30일, 15일 같은 기한은 일반환급·조기환급에 적용한다.","c":"중","v":1},"공인회2020_55-34-5":{"f":"세금계산서를 발급한 후 계약의 해제로 재화가 공급되지 않아 수정세금계산서를 작성하고자 하는 경우 그 작성일에는 계약해제일을 기입한다.","w":"계약 해제에 따른 수정세금계산서의 작성일은 처음 세금계산서의 작성일이 아니라 계약 해제일이다(부가가치세법 시행령 제70조).","c":"상","v":1},"공인회2021_56-36-1":{"f":"법인사업자로부터 전자세금계산서를 발급받았으나 그 전자세금계산서가 국세청장에게 전송되지 아니한 경우에도 발급한 사실이 확인되면 매입세액을 공제할 수 있다.","w":"미전송은 공급자의 가산세 문제이고, 발급 사실이 확인되면 공급받는 자는 매입세액을 공제받는다(부가가치세법 제39조).","c":"중","v":1},"공인회2021_56-37-1":{"f":"일반과세자 중 직전 과세기간 공급가액이 1억5천만원 이상인 법인사업자는 예정신고기간이 끝난 후 25일 이내에 신고하여야 하고, 1억5천만원 미만인 법인사업자는 예정고지를 받는다.","w":"법인사업자는 예정신고가 원칙이나 직전 과세기간 공급가액이 1억5천만원 미만이면 개인사업자처럼 예정고지를 받는다. 모든 법인이 신고하는 것은 아니다.","c":"중","v":1},"공인회2021_56-37-2":{"f":"영수증 발급대상 일반과세자는 세금계산서를 발급하지 않고 영수증을 발급한다.","w":"소매업, 음식점업 등 최종소비자에게 공급하는 일반과세자는 영수증을 발급한다. 모든 일반과세자가 세금계산서를 발급하는 것은 아니다(부가가치세법 제36조).","c":"상","v":1},"공인회2021_56-37-3":{"f":"간이과세자도 영세율을 적용받을 수 있다.","w":"영세율은 간이과세자에게도 적용된다. 대손세액공제처럼 일반과세자에게만 적용되는 제도와 구분된다.","c":"중","v":1},"공인회2021_56-37-4":{"f":"납세지 관할 세무서장은 일반과세자가 예정신고기간에 대한 환급세액을 예정신고기한까지 신고하더라도 조기환급 대상이 아닌 경우에는 환급하지 않고 확정신고 때 정산한다.","w":"예정신고 환급세액은 조기환급 대상일 때만 환급하고, 아니면 확정신고 시 정산한다(부가가치세법 제59조).","c":"중","v":1},"공인회2022_57-31-3":{"f":"공급시기가 속하는 과세기간이 끝난 후 20일 이내에 사업자등록을 신청한 경우에는 공급시기가 속하는 과세기간의 기산일까지 역산한 기간 내의 매입세액을 공제한다.","w":"등록 신청이 늦어도 이 기한 안에 하면 사업자등록 전 매입세액을 공제한다(부가가치세법 제39조).","c":"상","v":1},"공인회2022_57-37-1":{"f":"비거주자 또는 외국법인으로부터 국내에서 용역 또는 권리를 공급받아 과세사업에 사용하지 않는 자는 대리납부의무가 있다.","w":"과세사업에 사용하면 매입세액으로 공제되므로 대리납부하지 않는다.","c":"상","v":1},"공인회2022_57-37-2":{"f":"사업자가 조기환급신고를 한 경우에 관할 세무서장은 조기환급신고기한이 지난 후 15일 이내에 사업자에게 환급하여야 한다.","w":"기산점은 조기환급기간이 끝난 날이 아니라 신고기한이 지난 날이다(부가가치세법 제59조).","c":"중","v":1},"공인회2022_57-37-3":{"f":"과세표준과 납부세액을 추계결정하는 경우에도 그 기재내용이 분명한 세금계산서를 발급받아 관할 세무서장에게 제출하면 매입세액을 공제할 수 있다.","w":"추계결정이어도 세금계산서를 제출하면 그 매입세액은 공제한다(부가가치세법 제39조, 제57조).","c":"중","v":1},"공인회2022_57-37-5":{"f":"일반과세자인 개인사업자는 예정고지를 원칙으로 하며, 사업부진 등 사유가 있는 경우에 예정신고를 할 수 있다.","w":"개인사업자는 관할 세무서장이 예정고지서를 발급해 납부하는 것이 원칙이다.","c":"상","v":1},"공인회2023_58-30-1":{"f":"주된 사업장에서 총괄하여 납부하는 사업자가 되려는 자는 그 납부하려는 과세기간 개시 20일 전에 주사업장총괄납부 신청서를 주된 사업장의 관할 세무서장에게 제출하여야 한다.","w":"주사업장 총괄 납부를 하려면 납부하려는 과세기간이 시작하기 20일 전까지 주된 사업장 관할 세무서장에게 신청서를 내야 한다(부가가치세법 시행령 제92조 제2항).","c":"상","v":1},"공인회2023_58-30-2":{"f":"주사업장총괄납부 사업자가 종된 사업장을 신설하는 경우 그 신설하는 종된 사업장 관할 세무서장에게 주사업장총괄납부 변경신청서를 제출하여야 한다.","w":"종된 사업장을 새로 만들 때의 변경신청서는 그 신설하는 종된 사업장 관할 세무서장에게 낸다. 주된 사업장 관할 세무서장에게 내는 것은 일부 종된 사업장을 총괄 납부에서 빼거나 기존 사업장을 추가하는 경우 등이다(부가가치세법 시행령 제93조 제1항).","c":"상","v":1},"공인회2023_58-30-3":{"f":"주사업장총괄납부 사업자가 세금계산서 발급 없이 재화를 판매목적으로 자기의 다른 사업장에 반출한 경우 재화의 공급으로 보지 아니한다.","w":"판매 목적의 타 사업장 반출은 원칙적으로 재화의 공급이지만, 주사업장 총괄 납부를 적용받는 과세기간에 반출하면 공급으로 보지 않는다. 세금계산서를 발급하고 신고한 경우에만 공급으로 본다(부가가치세법 제10조 제3항 제2호).","c":"상","v":1},"공인회2023_58-30-4":{"f":"사업자단위과세 사업자가 법인인 경우 본점 소재지를 납세지로 하며 지점소재지를 납세지로 할 수 없다.","w":"사업자 단위로 신고하는 법인의 납세지는 본점 또는 주사무소다.","c":"상","v":1},"공인회2023_58-35-1":{"f":"전자세금계산서 의무발행 사업자가 전자세금계산서를 공급시기인 10월 25일 발행하고, 전자세금계산서 발급명세를 다음달 25일 국세청장에게 전송한 경우에는 매출처별세금계산서합계표를 제출하지 않아도 된다.","w":"과세기간 종료 후 다음 달 11일까지 전송했다면 합계표를 제출할 필요가 없다(부가가치세법 제54조).","c":"중","v":1},"공인회2024_59-30-2":{"f":"건설업을 영위하는 법인은 법인 등기부상 소재지를 사업장으로 한다.","w":"건설업, 운수업, 부동산매매업은 법인이면 법인 등기부상 소재지, 개인이면 업무를 총괄하는 장소를 사업장으로 한다(부가가치세법 시행령 제8조).","c":"중","v":1},"공인회2024_59-30-3":{"f":"둘 이상의 사업장이 있는 사업자가 사업자 단위로 사업자등록을 신청한 경우에는 사업자 단위로 부가가치세를 신고·납부한다.","w":"사업자단위과세는 사업장별이 아니라 본점이나 주사무소에서 합산해 신고와 납부를 한다.","c":"상","v":1},"공인회2024_59-30-4":{"f":"사업자등록을 신청하기 전의 매입세액은 매출세액에서 공제하지 않는다. 다만, 공급시기가 속하는 과세기간이 끝난 후 20일 이내에 등록을 신청한 경우 등록신청일부터 공급시기가 속하는 과세기간 기산일까지 역산한 기간 내의 것은 제외한다.","w":"등록 전 매입세액 불공제의 예외는 공급시기가 속하는 과세기간이 끝난 후 20일 이내에 등록을 신청한 경우다. 과세기간의 신고기간(끝난 후 25일) 내 신청이 기준이 아니다(부가가치세법 제39조 제1항 제8호).","c":"상","v":1},"공인회2024_59-30-5":{"f":"신규로 사업을 시작하려는 자는 사업개시일 이전이라도 사업자등록을 신청할 수 있으며, 해당 법인의 설립등기 전 또는 사업의 허가ㆍ등록이나 신고 전에도 사업자등록을 신청할 수 있다.","w":"법인 설립등기 전이나 사업의 허가·등록·신고 전에도 사업허가신청서 사본, 사업등록신청서 사본, 사업신고서 사본 또는 사업계획서를 첨부해 사업자등록을 신청할 수 있다(부가가치세법 제8조 제1항 단서, 같은 법 시행령 제11조 제4항).","c":"상","v":1},"공인회2025_60-34-1":{"f":"위탁판매의 경우 수탁자가 재화를 인도할 때에는 수탁자가 위탁자의 명의로 세금계산서를 발급한다.","w":"수탁자가 재화를 인도하는 위탁판매에서는 수탁자가 위탁자 명의로 세금계산서를 발급하고 수탁자의 등록번호를 덧붙여 적는다(부가가치세법 시행령 제69조 제1항).","c":"상","v":1},"공인회2025_60-34-3":{"f":"2024년 사업장별 재화 및 용역의 공급가액(면세공급가액을 포함)의 연간 합계액이 8천만원 이상인 개인사업자는 2025년 7월 1일(제2기 과세기간)부터 전자세금계산서를 발급해야 한다.","w":"전자세금계산서 의무 개시 시점은 직전 연도 공급가액이 기준 이상이 된 해의 다음 해 7월 1일이다(부가가치세법 시행령 제68조).","c":"중","v":1},"공인회2025_60-34-4":{"f":"계약의 해제로 재화 또는 용역이 공급되지 아니한 경우 계약해제일을 작성일자로 하여 수정세금계산서를 발급한다.","w":"작성일자는 당초 발급일이 아니라 계약이 해제된 날이다.","c":"상","v":1},"공인회2025_60-34-5":{"f":"사업자가 재화를 인도하기 전에 재화에 대한 대가의 전부 또는 일부를 받고, 그 받은 대가에 대하여 세금계산서를 발급하는 경우 세금계산서를 발급하는 때를 공급시기로 본다.","w":"대가를 먼저 받았더라도 세금계산서를 발급하지 않으면 공급시기가 아니다. 발급하는 때가 공급시기다(부가가치세법 제17조).","c":"상","v":1},"공인회2025_60-37-2":{"f":"재화 또는 용역을 공급하고 세금계산서등의 공급가액을 과다하게 기재한 경우 그 과다하게 기재한 공급가액의 2퍼센트를 가산세로 부과한다.","w":"공급가액을 실제보다 과다하게 기재하면 과다하게 기재한 부분의 공급가액에 2%를 가산세로 부과한다(부가가치세법 제60조 제3항 제5호).","c":"상","v":1},"공인회2025_60-37-3":{"f":"배우자가 아닌 타인의 명의로 사업자등록을 하는 경우 그 타인 명의의 사업 개시일부터 실제 사업을 하는 것으로 확인되는 날의 직전일까지의 공급가액 합계액의 2퍼센트를 가산세로 부과한다.","w":"타인 명의로 사업자등록을 하거나 타인 명의 등록을 이용해 사업하면 공급가액 합계액의 2%를 가산세로 부과한다(부가가치세법 제60조 제1항 제2호). 출제 당시에는 1%였고 2024년 12월 개정으로 2%가 되었다.","c":"상","v":1},"공인회2025_60-37-4":{"f":"세금계산서의 발급시기가 지난 후 해당 재화 또는 용역의 공급시기가 속하는 과세기간에 대한 확정신고 기한까지 세금계산서를 발급하는 경우에도 지연발급 가산세로 공급가액의 1퍼센트를 부과한다.","w":"확정신고 기한 안에 발급해도 발급시기를 지났으므로 지연발급 가산세 1%가 붙는다.","c":"상","v":1},"공인회2025_60-37-5":{"f":"재화 또는 용역을 공급하지 아니하고 세금계산서를 발급한 경우 그 공급가액의 3퍼센트를 가산세로 부과한다.","w":"가공 세금계산서는 사실과 다른 정도가 가장 커 3%다. 2%는 실제 공급자가 아닌 자의 명의로 발급한 경우다(부가가치세법 제60조).","c":"상","v":1},"공인회2016_51-38-1":{"f":"유가증권시장에서 거래되는 주식은 평가기준일 이전·이후 각 2개월 동안 공표된 매일의 최종시세가액의 평균액에 의한다.","w":"평가기준일 하루의 시세만 쓰지 않고 앞뒤 2개월 평균으로 일시적 가격 변동을 줄인다(상속세 및 증여세법 제63조).","c":"상","v":1},"공인회2016_51-38-3":{"f":"비상장주식의 1주당 순자산가치를 산정함에 있어서 해당 법인의 자산가액은 상속세 및 증여세법에 따라 평가한 가액과 장부가액 중 큰 금액으로 한다.","w":"순자산가액은 자산을 상속세 및 증여세법에 따라 평가한 가액에서 부채를 빼서 구하는데, 평가한 가액이 장부가액(취득가액에서 감가상각비를 뺀 금액)보다 적으면 장부가액으로 한다. 다만 장부가액보다 적은 정당한 사유가 있으면 평가한 가액을 쓴다(상속세 및 증여세법 시행령 제55조 제1항).","c":"상","v":1},"공인회2016_51-38-4":{"f":"비상장주식의 1주당 순손익가치를 산정함에 있어서 최근 3년간의 순손익액의 가중평균액은 과거 순손익액을 기준으로 계산한다.","w":"순손익가치는 최근 3년간 순손익액의 가중평균액으로 구한다. 일시적이고 우발적인 사건으로 순손익액이 늘어난 경우 등 요건을 갖춘 때에만 회계법인 등 둘 이상이 산출한 추정이익의 평균가액을 쓸 수 있고, 둘 중 적은 금액을 고르는 규정은 없다(상속세 및 증여세법 시행령 제56조 제1항·제2항).","c":"상","v":1},"공인회2016_51-38-5":{"f":"최대주주의 주식에 대하여 할증평가를 하는 경우 할증비율은 최대주주의 지분율에 관계없이 20%가 적용된다.","w":"현행 최대주주 주식 할증률은 지분율과 관계없이 20%이고, 중소기업 주식 등은 할증하지 않는다(상속세 및 증여세법 제63조 제3항). 출제 당시에는 지분율 50% 이하 20%, 50% 초과 30%로 나뉘어 있었다.","c":"상","v":1},"공인회2017_52-37-2":{"f":"피상속인의 상속인이 그 배우자 단독인 경우 일괄공제를 적용받을 수 없다.","w":"배우자 단독 상속에는 일괄공제 5억원을 적용하지 않고 기초공제와 인적공제를 합한 금액을 공제한다(상속세 및 증여세법 제21조).","c":"상","v":1},"공인회2017_52-38-1":{"f":"증여세의 과세대상이 되는 증여재산에 대하여 수증자에게 소득세가 부과되는 경우에는 증여세를 부과하지 아니한다.","w":"같은 소득에 증여세와 소득세를 이중으로 매기지 않기 위해 소득세를 우선 과세한다(상속세 및 증여세법 제4조의2).","c":"상","v":1},"공인회2018_53-38-1":{"f":"상속개시일 전 10년 이내에 피상속인이 상속인에게 증여한 재산 가액은 상속세 과세가액에 가산하며 증여일 현재의 가액으로 평가한다.","w":"상속세 과세가액에 더하는 사전증여재산은 상속개시일이 아니라 증여일 현재의 시가로 평가한다(상속세 및 증여세법 제13조, 제60조 제4항).","c":"상","v":1},"공인회2018_53-38-3":{"f":"「정당법」에 따른 정당에 유증을 한 재산에 대해서는 상속세를 부과하지 아니한다.","w":"「정당법」에 따른 정당에 유증한 재산은 국가·지방자치단체에 유증한 재산과 함께 상속세를 부과하지 않는 비과세 상속재산이다. 상속세 및 증여세법 제12조 제4호.","c":"중","v":1},"공인회2018_53-38-4":{"f":"수증자가 비거주자인 경우 또는 수증자의 주소 및 거소가 분명하지 아니한 경우에는 증여자의 주소지를 관할하는 세무서장이 증여세를 과세한다.","w":"수증자가 거주자면 수증자 주소지, 비거주자나 불분명이면 증여자 주소지가 관할이다(상속세 및 증여세법 제6조).","c":"상","v":1},"공인회2018_53-38-5":{"f":"증여재산을 증여세 과세표준 신고기한이 지난 후 3개월 이내에 증여자에게 반환하거나 증여자에게 다시 증여하는 경우에는 그 반환하거나 다시 증여하는 것에 대해서는 증여세를 부과하지 아니한다.","w":"반환·재증여의 비과세 기간은 신고기한 후 3개월이다. 5개월은 틀리다(상속세 및 증여세법 제4조).","c":"상","v":1},"공인회2019_54-38-4":{"f":"거주자의 사망으로 인하여 배우자 단독으로 상속 받는 경우에는 기초공제와 그 밖의 인적공제에 따른 공제액을 합친 금액이 5억원 미만이더라도 일괄공제 5억원을 공제받을 수 없다.","w":"배우자 단독 상속에서는 일괄공제가 배제된다(상속세 및 증여세법 제21조).","c":"상","v":1},"공인회2020_55-38-1":{"f":"거주자나 비거주자의 사망으로 상속이 개시되는 경우에는 상속세 과세가액에서 기초공제 2억원을 공제한다.","w":"비거주자도 기초공제 2억원은 받는다. 인적공제와 배우자상속공제 등은 거주자에게만 적용한다(상속세 및 증여세법 제18조).","c":"상","v":1},"공인회2020_55-38-3":{"f":"거주자의 사망으로 그 배우자가 실제 상속받은 금액이 없는 경우에도 5억원을 배우자상속공제로 적용한다.","w":"배우자 상속공제는 실제 상속분이 5억원 미만이면 5억원까지 공제한다(상속세 및 증여세법 제19조).","c":"상","v":1},"공인회2020_55-38-4":{"f":"피상속인의 배우자가 단독으로 상속받는 경우 기초공제와 그 밖의 인적공제에 따른 공제액을 합친 금액으로 공제받는다.","w":"배우자 단독 상속은 일괄공제 5억원을 선택할 수 없고 기초공제와 인적공제의 합계만 공제한다.","c":"상","v":1},"공인회2020_55-38-5":{"f":"거주자의 사망으로 상속이 개시되는 경우로서 상속개시일 현재 상속재산가액 중 순금융재산의 가액이 1억원을 초과하면 그 가액의 20%(2억원 한도)를 공제한다.","w":"금융재산상속공제는 순금융재산이 2천만원 이하이면 전액, 2천만원을 넘으면 그 20%와 2천만원 중 큰 금액을 2억원 한도로 공제한다(상속세 및 증여세법 제22조 제1항). 1억원을 넘을 때 1억원을 공제하는 규정은 없다.","c":"상","v":1},"공인회2021_56-38-2":{"f":"항시 치료를 요하는 중증환자인 장애인을 수익자로 하는 보험의 보험금은 연간 4천만원을 한도로 비과세한다.","w":"장애인 보험금의 증여세 비과세는 연간 4천만원 한도다. 전액 비과세가 아니다(상속세 및 증여세법 제46조).","c":"상","v":1},"공인회2022_57-38-2":{"f":"수증자가 비거주자인 경우에는 증여자의 주소지를 관할하는 세무서장 등이 증여세를 과세한다.","w":"수증자가 비거주자이면 증여재산 소재지가 아니라 증여자 주소지가 관할이다.","c":"상","v":1},"공인회2023_58-39-2":{"f":"손해보험계약자가 피상속인이 아닌 경우라도 피상속인이 실질적으로 보험료를 납부하였다면 피상속인의 사망으로 인하여 받는 보험금은 상속재산으로 본다.","w":"계약자 명의와 관계없이 피상속인이 보험료를 낸 만큼 보험금을 상속재산으로 본다(상속세 및 증여세법 제8조).","c":"상","v":1},"공인회2023_58-39-3":{"f":"피상속인이 신탁한 재산은 상속재산으로 보나, 수익자의 증여재산가액으로 하는 신탁의 이익을 받을 권리의 가액은 상속재산에서 제외한다.","w":"증여세가 과세되는 수익권을 상속재산으로 다시 포함하면 이중과세다(상속세 및 증여세법 제9조).","c":"상","v":1},"공인회2023_58-39-4":{"f":"피상속인의 사망으로 인하여 「국민연금법」에 따라 지급되는 반환일시금은 상속재산으로 보지 아니한다.","w":"유족이 법에 따라 고유의 권리로 받는 급여는 피상속인의 재산이 아니다.","c":"중","v":1},"공인회2023_58-39-5":{"f":"제사를 주재하는 상속인이 상속받은 족보와 제구에 대하여는 재산가액 합계액 1천만원을 한도로 상속세를 부과하지 아니한다.","w":"금양임야와 묘토는 2억원 한도이고, 족보와 제구는 1천만원 한도다(상속세 및 증여세법 제12조).","c":"상","v":1},"공인회2024_59-38-5":{"f":"비거주자의 사망으로 인하여 상속이 개시되는 경우 상속개시일 전 10년 이내에 피상속인이 상속인에게 증여한 국내의 재산가액을 상속재산가액에 가산하여 상속세 과세가액을 산정한다.","w":"비거주자는 국내 소재 재산에 대해서만 상속세 납세의무가 있으므로 가산 대상도 국내 재산으로 한정한다.","c":"중","v":1},"공인회2016_51-02":{"w":"ㄱ: 공과금의 체납처분 중 국세를 징수할 때 공과금의 강제징수비는 국세에 우선한다. O\nㄴ: 국세는 공과금(강제징수비 제외)보다 우선한다. O\nㄷ: 국세는 담보물권이 없는 민사채권보다 발생시기와 관계없이 우선한다. O\nㄹ: 납세고지서 발송일이 저당권 설정 등기일보다 앞서면 국세가 저당권부 채권보다 우선한다. O\n모두 옳다.","c":"상","v":1},"공인회2016_51-04":{"w":"ㄱ: 연대납세의무자, 제2차 납세의무자, 보증인뿐 아니라 이해관계가 있는 제3자가 납세의무자 명의로 납부해도 납세의무가 소멸한다. X\nㄴ: 물납은 세법에 규정이 있는 경우에만 허용된다. X\nㄷ: 환급받을 세액의 충당을 청구하면 그 청구한 날에 납부한 것으로 본다. O\nㄹ: 국세환급금의 체납세액 충당은 납세자의 동의 없이 할 수 있다. X","c":"상","v":1},"공인회2016_51-06":{"w":"배당기준일(2015.12.31) 전 3개월 이내에 취득한 주식(2015.10.13 취득 10,000주)은 익금불산입 대상에서 제외한다. 처분 5,000주는 먼저 취득한 주식에서 처분한 것으로 본다. 대상 주식은 55,000주로 출자비율 55%(50% 초과 → 익금불산입률 50%).\n대상 수입배당금=39,000,000×55,000/65,000=33,000,000원 → 33,000,000×50%=16,500,000원.\n차입금 이자 차감: 지급이자에서 현재가치할인차금 상각액을 제외한 190,000,000원×(대상 주식 장부가액 825,000,000원/자산총액 250억원)×50%=3,135,000원.\n익금불산입액=16,500,000-3,135,000=13,365,000원.","c":"중","v":1},"공인회2016_51-09":{"w":"수입금액 기준 한도를 일반수입금액(400억원) 먼저, 특수관계인 수입금액(200억원)을 이어서 구간별로 적용한다.\n기본한도 12,000,000원. 일반수입금액 400억원: 20,000,000+300억원×0.1%=50,000,000원.\n특수관계인 수입금액 200억원: (400억~500억원 구간 100억원×0.1%+500억원 초과 100억원×0.03%)=13,000,000원의 10%=1,300,000원.\n한도=12,000,000+50,000,000+1,300,000=63,300,000원. 기업업무추진비 해당액 100,000,000원(재고자산에 포함된 20,000,000원 포함)에서 한도를 뺀 한도초과액=36,700,000원.","c":"중","v":1},"공인회2016_51-10":{"w":"채권자 불분명 사채이자 2,000,000원은 손금불산입하고, 원천징수세액 836,000원은 기타사외유출, 나머지 1,164,000원은 대표자상여로 처분한다.\n업무무관 가지급금 지급이자: 은행차입금 이자 3,000,000원(차입금 6천만원 상당). 대표자 소득세 대납액과 사용인 자녀 학자금 대여액은 업무무관 가지급금에서 제외하고, 주택자금 대여액 10,000,000원만 해당. 3,000,000×10,000,000/60,000,000=500,000원은 기타사외유출.\n기타사외유출=836,000+500,000=1,336,000원.","c":"중","v":1},"공인회2016_51-12":{"w":"제16기 자본적 지출 1,000,000원은 600만원 미만이라 소액수선비로 손금이 되고 즉시상각의제가 아니다. 제15기 10,000,000원은 600만원 이상이라 즉시상각의제다.\n제15기: 상각범위 (100,000,000 + 10,000,000) × 0.2 = 22,000,000원, 회사 계상 20,000,000 + 10,000,000 = 30,000,000원, 상각부인 8,000,000원(유보).\n제16기: 세무상 미상각잔액 = 110,000,000 − 30,000,000 + 8,000,000 = 88,000,000원, 상각범위 17,600,000원, 회사 계상 18,000,000원, 상각부인 400,000원.\n제16기말 유보 = 8,000,000 + 400,000 = 8,400,000원(3번).","c":"중","v":1},"공인회2016_51-14":{"w":"당기 대손금(세법상): 거래처 C 3,000,000원(파산)+거래처 D 2,000,000원(전기 대손부인액, 2016.3.23 소멸시효 완성으로 손금추인)=5,000,000원.\n전기말 세무상 채권=장부 248,000,000원+대손부인 유보 2,000,000원=250,000,000원.\n대손실적률=5,000,000/250,000,000=2%(1%보다 크므로 2% 적용).\n당기말 설정대상 채권=220,000,000원(D 채권은 장부에서 이미 빠져 있고 당기에 세무상으로도 대손되었다).\n한도액=220,000,000×2%=4,400,000원.\n한도초과액=장부 기말잔액 33,000,000-4,400,000=28,600,000원.","c":"상","v":1},"공인회2016_51-16":{"w":"(2018 개정 전 기준) 출제 당시 법인세법 제56조(기업소득 환류세제) 기준이다.\n투자제외방법: 기업소득 800억원×30%=240억원-(임금증가액 100억원+배당 120억원+상생협력 출연금 30억원)=-10억원 → 초과환류액 10억원.\n직전 사업연도에 차기환류적립금 50억원을 적립했으므로 (50억원-초과환류액 10억원)×10%=4억원을 추가 납부한다(제56조제6항).\n이 제도는 2018년부터 조세특례제한법의 투자·상생협력 촉진 과세특례로 바뀌어 적용 대상·계산식이 달라졌다.","c":"상","v":1,"old":1,"ow":"(2018 개정 전 기준) 출제 당시 법인세법 제56조(기업소득 환류세제) 기준이다.\n투자제외방법: 기업소득 800억원×30%=240억원-(임금증가액 100억원+배당 120억원+상생협력 출연금 30억원)=-10억원 → 초과환류액 10억원.\n직전 사업연도에 차기환류적립금 50억원을 적립했으므로 (50억원-초과환류액 10억원)×10%=4억원을 추가 납부한다(제56조제6항).\n이 제도는 2018년부터 조세특례제한법의 투자·상생협력 촉진 과세특례로 바뀌어 적용 대상·계산식이 달라졌다."},"공인회2016_51-17":{"w":"잔여재산가액=환가금액 40,000,000+70,000,000+15,000,000-차입금 상환 35,000,000=90,000,000원.\n자기자본총액: 세무상 이월결손금 37,000,000원으로 잉여금 28,000,000원(자본잉여금 10,000,000+이익잉여금 18,000,000)을 먼저 보전하고 잔액은 자본금과 상계하지 않으므로 납입자본금 50,000,000원.\n청산소득금액=90,000,000-50,000,000=40,000,000원.","c":"중","v":1},"공인회2016_51-21":{"w":"기본공제(150만원): 본인, 배우자(총급여 500만원 이하), 부친(72세, 정기예금이자 2,000만원은 분리과세되어 소득금액 0, 사망일 전날 기준), 모친(68세, 식량작물재배업 소득은 비과세), 장남, 장녀 6명=9,000,000원. 별거해도 주거형편상이면 동거로 본다.\n추가공제: 경로우대(70세 이상 부친) 1,000,000원, 장애인(장남) 2,000,000원.\n보험료공제: 국민건강보험료 등 500,000원, 국민연금 2,000,000원.\n합계=9,000,000+1,000,000+2,000,000+500,000+2,000,000=14,500,000원.","c":"상","v":1},"공인회2016_51-22":{"w":"(2016 개정 전 기준) 출제 당시 난임시술비도 일반 의료비와 같은 15% 공제율이었다(2017년부터 20%, 현행 30%).\n상황1(근로소득자): 보장성보험료 본인 자동차보험 400,000+부친 상해보험 600,000=1,000,000원×12%=120,000원, 장애인전용보장성보험 1,000,000원×15%=150,000원 → 270,000원.\n의료비: 부친(65세 미만) 1,000,000원에서 총급여 3% 1,500,000원을 빼면 -500,000원, 이를 본인·난임시술비에서 차감. (1,000,000+2,500,000-500,000)×15%=450,000원.\n합계 720,000원.\n상황2(성실사업자): 보험료 세액공제는 근로소득자만 받는다. 의료비 세액공제는 사업소득금액 3%(1,500,000원)를 기준으로 같은 방식 → 450,000원.\n현행 공제율(난임 30%)로 계산하면 상황1이 1,095,000원이 되어 선지에 없다.","c":"상","v":1,"old":1,"ow":"(2016 개정 전 기준) 출제 당시 난임시술비도 일반 의료비와 같은 15% 공제율이었다(2017년부터 20%, 현행 30%).\n상황1(근로소득자): 보장성보험료 본인 자동차보험 400,000+부친 상해보험 600,000=1,000,000원×12%=120,000원, 장애인전용보장성보험 1,000,000원×15%=150,000원 → 270,000원.\n의료비: 부친(65세 미만) 1,000,000원에서 총급여 3% 1,500,000원을 빼면 -500,000원, 이를 본인·난임시술비에서 차감. (1,000,000+2,500,000-500,000)×15%=450,000원.\n합계 720,000원.\n상황2(성실사업자): 보험료 세액공제는 근로소득자만 받는다. 의료비 세액공제는 사업소득금액 3%(1,500,000원)를 기준으로 같은 방식 → 450,000원.\n현행 공제율(난임 30%)로 계산하면 상황1이 1,095,000원이 되어 선지에 없다."},"공인회2016_51-24":{"w":"(2018 개정 전 기준) 출제 당시 산업재산권 양도대가의 필요경비 의제율은 80%였고 고배당기업 배당소득 분리과세 특례가 있었다.\n가. 2012.6.30 발행 상환기간 10년 이상 장기채권 이자, 분리과세 신청: 2,000,000×30%=600,000원.\n나. 고배당기업 배당, 분리과세 신청: 4,000,000×25%=1,000,000원.\n다. 산업재산권 양도대가(기타소득): 10,000,000×(1-80%)=2,000,000원×20%=400,000원.\n원천징수세액 합계=2,000,000원.\n현행은 필요경비 60%라 다.가 800,000원이 되고 고배당기업 특례도 없다.","c":"상","v":1,"old":1,"ow":"(2018 개정 전 기준) 출제 당시 산업재산권 양도대가의 필요경비 의제율은 80%였고 고배당기업 배당소득 분리과세 특례가 있었다.\n가. 2012.6.30 발행 상환기간 10년 이상 장기채권 이자, 분리과세 신청: 2,000,000×30%=600,000원.\n나. 고배당기업 배당, 분리과세 신청: 4,000,000×25%=1,000,000원.\n다. 산업재산권 양도대가(기타소득): 10,000,000×(1-80%)=2,000,000원×20%=400,000원.\n원천징수세액 합계=2,000,000원.\n현행은 필요경비 60%라 다.가 800,000원이 되고 고배당기업 특례도 없다."},"공인회2016_51-25":{"w":"당기순이익 50,000,000원에서 조정한다.\n가산: 소득세비용 2,500,000원(필요경비 불산입), 사무용 비품 처분손실 1,000,000원(출제 당시 사업용 유형자산 처분손익은 사업소득이 아니었다), 가사용 소비 재고자산 시가 3,500,000원(총수입금액).\n차감: 사업과 무관한 채무면제이익 1,000,000원, 예금이자 1,500,000원(이자소득), 가사용 재고자산 원가 2,000,000원(필요경비).\n장려금 2,000,000원은 총수입금액, 경과실 손해배상금과 경리 일을 하는 배우자 급여는 필요경비라 조정이 없다.\n사업소득금액=50,000,000+2,500,000+1,000,000+3,500,000-1,000,000-1,500,000-2,000,000=52,500,000원.\n2018년부터 복식부기의무자는 사업용 유형자산(토지·건물 제외) 처분손익도 사업소득에 넣는다.","c":"상","v":1},"공인회2016_51-26":{"w":"(2018 개정 전 기준) 출제 당시 일시적 강연료(기타소득)의 필요경비 의제율은 80%였다.\n금융소득 33,000,000원(이자 10,000,000+비상장법인 주식배당 20,000,000+원천징수 안 된 외국법인 배당 3,000,000)이 2,000만원을 넘어 종합과세된다. 2,000만원은 이자와 외국법인 배당 13,000,000원이 먼저 채우고 Gross-up 대상 주식배당 중 7,000,000원이 들어간다. 나머지 13,000,000원×11%=1,430,000원 가산 → 금융소득금액 34,430,000원.\n사업소득금액=100,000,000-70,000,000=30,000,000원.\n기타소득금액=특강료 20,000,000×(1-80%)=4,000,000원(300만원 초과라 종합과세).\n종합소득금액=34,430,000+30,000,000+4,000,000=68,430,000원.\n현행은 필요경비 60%라 기타소득금액이 8,000,000원, 종합소득금액은 72,430,000원이 된다.","c":"상","v":1,"old":1,"ow":"(2018 개정 전 기준) 출제 당시 일시적 강연료(기타소득)의 필요경비 의제율은 80%였다.\n금융소득 33,000,000원(이자 10,000,000+비상장법인 주식배당 20,000,000+원천징수 안 된 외국법인 배당 3,000,000)이 2,000만원을 넘어 종합과세된다. 2,000만원은 이자와 외국법인 배당 13,000,000원이 먼저 채우고 Gross-up 대상 주식배당 중 7,000,000원이 들어간다. 나머지 13,000,000원×11%=1,430,000원 가산 → 금융소득금액 34,430,000원.\n사업소득금액=100,000,000-70,000,000=30,000,000원.\n기타소득금액=특강료 20,000,000×(1-80%)=4,000,000원(300만원 초과라 종합과세).\n종합소득금액=34,430,000+30,000,000+4,000,000=68,430,000원.\n현행은 필요경비 60%라 기타소득금액이 8,000,000원, 종합소득금액은 72,430,000원이 된다."},"공인회2016_51-27":{"w":"(2024 개정 전 기준) 출제 당시 출산·보육수당 비과세 한도는 월 10만원이었다.\n총급여=급여 24,000,000\n+인정상여 6,000,000(근로를 제공한 2016년 귀속)\n+자가운전보조금 중 월 20만원 초과분 100,000×12=1,200,000\n+자녀학비보조금 2,000,000\n+배우자 출산수당 중 월 10만원 초과분 100,000\n+식사대 1,200,000(현물식사를 따로 받아 비과세 아님)\n+주택구입자금 무상대여 이익 5,000,000(중소기업 종업원이 아니어서 과세)\n=39,500,000원.\n현행은 출산·보육수당 비과세가 월 20만원이라 출산수당이 전액 비과세되어 39,400,000원이 된다.","c":"상","v":1,"old":1,"ow":"(2024 개정 전 기준) 출제 당시 출산·보육수당 비과세 한도는 월 10만원이었다.\n총급여=급여 24,000,000\n+인정상여 6,000,000(근로를 제공한 2016년 귀속)\n+자가운전보조금 중 월 20만원 초과분 100,000×12=1,200,000\n+자녀학비보조금 2,000,000\n+배우자 출산수당 중 월 10만원 초과분 100,000\n+식사대 1,200,000(현물식사를 따로 받아 비과세 아님)\n+주택구입자금 무상대여 이익 5,000,000(중소기업 종업원이 아니어서 과세)\n=39,500,000원.\n현행은 출산·보육수당 비과세가 월 20만원이라 출산수당이 전액 비과세되어 39,400,000원이 된다."},"공인회2016_51-29":{"w":"부담부증여로 채무 300,000,000원은 양도로 본다. 양도가액을 증여 당시 기준시가(600,000,000원)로 보므로 양도가액=채무액 300,000,000원, 취득가액도 기준시가 방식으로 계산한다.\n취득가액=취득 당시 기준시가 500,000,000×(300,000,000/600,000,000)=250,000,000원. 개산공제=500,000,000×3%×1/2=7,500,000원.\n양도차익=300,000,000-250,000,000-7,500,000=42,500,000원.","c":"상","v":1},"공인회2016_51-30":{"w":"(2017 개정 전 기준) 출제 당시에는 자기가 적립해 준 마일리지로 결제받은 금액도 공급가액에 포함했다.\n(1) 상품 매출 100,000,000원(에누리·할인·환입은 이미 빠져 있다).\n(2) 마일리지 결제분 4,000,000원 포함.\n(3) 용역 매출 5,000,000원+임원에 대한 저가 용역의 시가 차액 500,000원. 주주에게 무상 제공한 운송용역은 용역의 무상공급이라 과세하지 않는다.\n(4) 사용하던 기계 처분가액 3,500,000원.\n(5) 비품 기부(사업상 증여): 2,000,000×(1-25%×경과 과세기간 1)=1,500,000원.\n합계=100,000,000+4,000,000+5,500,000+3,500,000+1,500,000=114,500,000원.\n2017.2.7 이후 공급분부터 자기적립 마일리지 결제액은 공급가액에서 빠지므로 현행이면 110,500,000원이 된다.","c":"상","v":1,"old":1,"ow":"(2017 개정 전 기준) 출제 당시에는 자기가 적립해 준 마일리지로 결제받은 금액도 공급가액에 포함했다.\n(1) 상품 매출 100,000,000원(에누리·할인·환입은 이미 빠져 있다).\n(2) 마일리지 결제분 4,000,000원 포함.\n(3) 용역 매출 5,000,000원+임원에 대한 저가 용역의 시가 차액 500,000원. 주주에게 무상 제공한 운송용역은 용역의 무상공급이라 과세하지 않는다.\n(4) 사용하던 기계 처분가액 3,500,000원.\n(5) 비품 기부(사업상 증여): 2,000,000×(1-25%×경과 과세기간 1)=1,500,000원.\n합계=100,000,000+4,000,000+5,500,000+3,500,000+1,500,000=114,500,000원.\n2017.2.7 이후 공급분부터 자기적립 마일리지 결제액은 공급가액에서 빠지므로 현행이면 110,500,000원이 된다."},"공인회2016_51-31":{"w":"5) 대가를 받지 않고 상대방으로부터 인도받은 재화를 가공만 해 주는 것은 용역의 무상공급이고, 특수관계인에게 부동산 임대용역을 무상으로 주는 경우 외에는 과세하지 않는다. 과세대상이 아니다.\n1), 2) 매입세액을 공제받은 재화를 매입세액 불공제 용도(개별소비세 과세 소형승용차)로 사용·전용하면 재화의 공급으로 본다.\n3) 폐업 시 잔존재화는 재화의 공급으로 본다.\n4) 사용인(특수관계인)에게 대가 없이 임대용역을 제공하면 과세한다.","c":"중","v":1},"공인회2016_51-32":{"w":"1) 상품 10,000,000원: 대금을 9개월간 나눠 받아 장기할부 요건(1년 이상)에 해당하지 않으므로 인도일(1월 30일)에 전액 공급. 10,000,000원.\n2) 주문생산 중간지급조건부: 대가를 받기로 한 때가 공급시기. 계약시 10% 1,000,000원+완성도 30% 도달 시 40% 4,000,000원=5,000,000원(70% 완성분은 미도래).\n3) 부동산 양도는 6월 20일 인도 시 공급시기. 이 기간에 포함되지 않는다.\n4) 계약금 200,000원은 세금계산서를 발급했으므로 발급한 부분이 공급시기.\n합계=10,000,000+5,000,000+200,000=15,200,000원.","c":"상","v":1},"공인회2016_51-34":{"w":"겸용주택에서 주택 면적(40㎡)이 주택 외 면적(80㎡)보다 작으므로 주택 부분만 면세이고 나머지는 과세한다.\n건물가액·토지가액 구분이 불분명하면 양도일이 속하는 과세기간의 직전 과세기간 개시일(2015.7.1) 이후 감정평가업자의 감정평가액으로 안분한다(2015.9.9 감정평가 사용 가능).\n건물분=200,000,000×54/180=60,000,000원. 과세 부분(상가·사무실 80㎡/120㎡)=60,000,000×80/120=40,000,000원.","c":"상","v":1},"공인회2016_51-36":{"w":"공통사용 건물과 트럭의 공통매입세액은 예정신고 기간의 공급가액 비율(과세 60,000,000/100,000,000=60%)로 안분하고, 공통사용재화(트럭) 매각 공급가액은 직전 과세기간 비율(과세 49.5/90=55%)을 적용한다.\n매입세액: 과세 상품 40,000,000×10%=4,000,000, 건물 6,000,000×60%=3,600,000, 트럭 1,000,000×60%=600,000 → 8,200,000원.\n매출세액: 과세 상품 60,000,000×10%=6,000,000, 트럭 매각 3,000,000×55%×10%=165,000 → 6,165,000원.\n납부세액=6,165,000-8,200,000=-2,035,000 → 환급세액 2,035,000원.","c":"중","v":1},"공인회2016_51-37":{"w":"(2024 개정 전 기준) 출제 당시 타인 명의 사업자등록 가산세는 공급가액의 1%였고 가공 세금계산서 수취 가산세는 2%였다.\n2) 타인 명의로 등록해 사업한 경우 가산세는 1%이므로 2%라는 설명이 옳지 않다.\n1) 미등록 가산세: 사업개시일부터 등록신청 직전일까지 공급가액의 1%. O\n3), 4) 실제 공급자·공급받는 자가 아닌 자의 명의로 세금계산서를 발급·수취한 경우 2%. O\n5) 재화를 공급받지 않고 세금계산서를 받은 경우 당시 2%. O\n현행은 타인 명의 등록 가산세가 2%, 가공 세금계산서 발급·수취 가산세가 3%라 옳지 않은 것은 5)가 된다.","c":"상","v":1,"old":1,"ow":"(2024 개정 전 기준) 출제 당시 타인 명의 사업자등록 가산세는 공급가액의 1%였고 가공 세금계산서 수취 가산세는 2%였다.\n2) 타인 명의로 등록해 사업한 경우 가산세는 1%이므로 2%라는 설명이 옳지 않다.\n1) 미등록 가산세: 사업개시일부터 등록신청 직전일까지 공급가액의 1%. O\n3), 4) 실제 공급자·공급받는 자가 아닌 자의 명의로 세금계산서를 발급·수취한 경우 2%. O\n5) 재화를 공급받지 않고 세금계산서를 받은 경우 당시 2%. O\n현행은 타인 명의 등록 가산세가 2%, 가공 세금계산서 발급·수취 가산세가 3%라 옳지 않은 것은 5)가 된다."},"공인회2016_51-39":{"w":"추정상속재산: 상속개시 전 1년 이내에 재산을 처분하고 받은 금액 500,000,000원(2억원 이상) 중 용도 불분명 300,000,000원에서 처분금액의 20%(100,000,000원)와 2억원 중 적은 금액을 뺀 200,000,000원을 상속재산으로 추정한다.\n증여재산 가산: 상속인 외의 자에게 상속개시 전 5년 이내(2011.7.1 증여) 증여한 재산은 증여 당시 가액 200,000,000원을 가산한다.\n장례비용 공제: 일반 장례비 10,000,000원(한도)+봉안시설 사용비용 5,000,000원=15,000,000원.\n과세가액=1,000,000,000+200,000,000+200,000,000-15,000,000=1,385,000,000원.","c":"중","v":1},"공인회2016_51-40":{"w":"ㄱ: 재산세 과세대상은 토지, 건축물, 주택, 선박, 항공기. O\nㄴ: 공부상 등재 현황과 사실상 현황이 다르면 사실상 현황에 따른다. O\nㄷ: 과세기준일은 매년 6월 1일이다. X\nㄹ: 재산세는 보통징수 방법으로 징수한다. X","c":"상","v":1},"공인회2017_52-01":{"w":"(2019 개정 전 기준) 출제 당시 국세기본법 제3조제1항은 세법이 특례를 둘 수 있는 규정을 열거했다. 제2장제1절(국세부과의 원칙), 제3장제3절(연대납세의무), 제45조의2(경정 등의 청구), 제51조·제52조(국세환급금의 충당과 환급) 등이 들어 있었고, 제26조의2(국세부과의 제척기간)는 빠져 있었다. 그래서 답은 ②이다.\n2019.12.31 개정으로 제3조제1항은 「세법에 별도의 규정이 있는 경우를 제외하고는 이 법에서 정하는 바에 따른다」로 바뀌어 열거 목록 자체가 없어졌다.","c":"상","v":1,"old":1,"ow":"(2019 개정 전 기준) 출제 당시 국세기본법 제3조제1항은 세법이 특례를 둘 수 있는 규정을 열거했다. 제2장제1절(국세부과의 원칙), 제3장제3절(연대납세의무), 제45조의2(경정 등의 청구), 제51조·제52조(국세환급금의 충당과 환급) 등이 들어 있었고, 제26조의2(국세부과의 제척기간)는 빠져 있었다. 그래서 답은 ②이다.\n2019.12.31 개정으로 제3조제1항은 「세법에 별도의 규정이 있는 경우를 제외하고는 이 법에서 정하는 바에 따른다」로 바뀌어 열거 목록 자체가 없어졌다."},"공인회2017_52-03":{"w":"ㄱ: 「조세범 처벌절차법」에 따른 통고처분은 국세기본법 제55조에 따른 불복 대상에서 빠진다. O\nㄴ: 재결청은 결정기간 안에 결정하지 못하면 결정기간이 지난 날부터 행정소송을 제기할 수 있다는 내용을 청구인에게 서면으로 지체 없이 알려야 한다. O\nㄷ: 불복 청구는 처분의 집행에 효력을 미치지 않는 것이 원칙이고 재결청이 필요하다고 인정하면 집행을 중지하게 하거나 중지할 수 있다(출제 당시 제57조). O\nㄹ: 조세심판관회의는 담당 조세심판관 3분의 2 이상 출석으로 개의하고 출석 과반수 찬성으로 의결한다(제72조제3항). 과반수 출석이 아니다. X","c":"상","v":1},"공인회2017_52-06":{"w":"2) 「보험업법」에 따른 고정자산 재평가는 법인세법상 평가증이 인정되므로 재평가이익은 익금이고 자산 증액도 세법이 인정한다. 장부에서 자본항목으로 처리했으므로 익금산입 3,000,000원(기타)만 한다. 유보로 처리하고 다시 익금불산입하는 것은 평가증이 인정되지 않는 임의평가의 조정이다. 옳지 않다.\n1) 자기주식처분이익은 익금이고 이미 수익으로 계상했으니 조정이 없다. O\n3) 특수관계 개인에게서 유가증권을 시가보다 싸게 산 차액 300,000원을 익금산입(유보)하고, 기타포괄손익으로 처리한 평가손실 100,000원은 세법이 인정하지 않으므로 유보 100,000원을 더하고 같은 금액을 기타로 빼 준다. 합계 익금산입 400,000원(유보), 익금불산입 100,000원(기타). O\n4) 전기에 비용 처리한 취득세는 전기에 손금불산입(유보)되어 토지원가에 들어가 있으므로 환급액은 익금불산입(△유보), 환급금 이자도 익금불산입(기타). O\n5) 특수관계인 임원에게서 고가 매입한 시가초과액 4,000,000원은 자산에서 빼는 손금산입(△유보)과 손금불산입(상여)을 함께 한다. O","c":"상","v":1},"공인회2017_52-08":{"w":"수입금액(기업회계기준 매출액): 일반매출 23,000,000,000원에서 영업외비용으로 처리한 매출할인·에누리 140,000,000원을 빼고, 전기 귀속 위탁매출 500,000,000원을 빼고, 부산물 매각대금 140,000,000원을 더하면 22,500,000,000원. 특수관계인 매출 12,000,000,000원.\n한도: 중소기업 기본 24,000,000원+일반 20,000,000+(225억-100억)×0.1%=32,500,000원+특수관계인분 120억×0.1%×10%=1,200,000원=57,700,000원.\n해당액: 장부 75,000,000원+미계상 접대분 5,000,000원=80,000,000원. 증빙 누락 2,000,000원은 먼저 손금불산입(대표자 상여), 개인명의 신용카드 사용분 4,000,000원은 손금불산입(기타사외유출). 남은 74,000,000원-57,700,000원=한도초과 16,300,000원(기타사외유출).\n기타사외유출 합계=4,000,000+16,300,000=20,300,000원.","c":"상","v":1},"공인회2017_52-09":{"w":"(2018 개정 전 기준) 출제 당시 법인세법 시행령 제20조제1항제4호는 사전 서면약정에 따라 근로자(임원 제외)에게 잉여금처분으로 지급한 성과배분상여금을 손금에 넣도록 했다.\n가. 자산수증이익 과소계상 1,000,000원: 익금산입(유보) +1,000,000\n나. 부가가치세 매출세액 500,000원: 익금불산입(△유보) -500,000\n다. 미수 배당금 2,000,000원: 익금산입(유보) +2,000,000, 수입배당금 익금불산입 2,000,000×30%=600,000원(기타) -600,000\n라. 사용인 성과배분상여금 3,000,000원: 손금산입(기타) -3,000,000. 임원분 5,000,000원은 장부에 비용이 아니므로 조정 없음\n마. 기부금 한도초과액은 소득금액조정합계표가 아닌 과세표준 계산 단계에서 더한다\n바. 전기에 자본적지출로 처리한 재산세는 전기에 손금산입(△유보)되었고, 당기 환급액은 익금이므로 수익 처리에 조정이 없다\n소득금액조정합계표 순액=1,000,000-500,000+2,000,000-600,000-3,000,000=-1,100,000원, 유보 순증=1,000,000-500,000+2,000,000=2,500,000원. 답 ③.\n현행 시행령에는 잉여금처분 성과배분상여금 손금 규정이 없고 제43조제1항에 따라 직원에게 이익처분으로 지급한 상여금도 손금불산입이다. 라의 조정이 없어져 소득금액조정합계표 순액이 +1,900,000원이 된다.","c":"상","v":1,"old":1,"ow":"(2018 개정 전 기준) 출제 당시 법인세법 시행령 제20조제1항제4호는 사전 서면약정에 따라 근로자(임원 제외)에게 잉여금처분으로 지급한 성과배분상여금을 손금에 넣도록 했다.\n가. 자산수증이익 과소계상 1,000,000원: 익금산입(유보) +1,000,000\n나. 부가가치세 매출세액 500,000원: 익금불산입(△유보) -500,000\n다. 미수 배당금 2,000,000원: 익금산입(유보) +2,000,000, 수입배당금 익금불산입 2,000,000×30%=600,000원(기타) -600,000\n라. 사용인 성과배분상여금 3,000,000원: 손금산입(기타) -3,000,000. 임원분 5,000,000원은 장부에 비용이 아니므로 조정 없음\n마. 기부금 한도초과액은 소득금액조정합계표가 아닌 과세표준 계산 단계에서 더한다\n바. 전기에 자본적지출로 처리한 재산세는 전기에 손금산입(△유보)되었고, 당기 환급액은 익금이므로 수익 처리에 조정이 없다\n소득금액조정합계표 순액=1,000,000-500,000+2,000,000-600,000-3,000,000=-1,100,000원, 유보 순증=1,000,000-500,000+2,000,000=2,500,000원. 답 ③.\n현행 시행령에는 잉여금처분 성과배분상여금 손금 규정이 없고 제43조제1항에 따라 직원에게 이익처분으로 지급한 상여금도 손금불산입이다. 라의 조정이 없어져 소득금액조정합계표 순액이 +1,900,000원이 된다."},"공인회2017_52-10":{"w":"특례기부금: 이재민 구호물품(현물은 장부가액) 6,000,000원+사립학교 시설비 2,000,000원=8,000,000원, 제14기 한도초과 이월액 9,000,000원. 일반기부금: 장학금 5,000,000원. 영업자 단체의 특별회비 20,000,000원은 비지정기부금으로 손금불산입(일반회비 3,000,000원은 손금).\n기준소득금액=100,000,000+20,000,000+13,000,000=133,000,000원. 이월결손금 90,000,000원을 차감한 43,000,000원.\n특례기부금 한도=43,000,000×50%=21,500,000원 → 이월분 9,000,000+당기 8,000,000=17,000,000원 전액 손금산입.\n일반기부금 한도=(43,000,000-17,000,000)×10%=2,600,000원 → 한도초과 2,400,000원.\n각 사업연도 소득금액=100,000,000+20,000,000+2,400,000-9,000,000(이월 특례기부금 손금산입)=113,400,000원.","c":"중","v":1},"공인회2017_52-12":{"w":"㈜A: 정당한 사유 없이 특수관계인 외의 자로부터 시가 10,000,000원인 주식을 15,000,000원에 매입했다. 시가의 130%(13,000,000원)를 넘는 부분만 기부금으로 보므로 취득가액은 13,000,000원이다. 평가이익은 인정하지 않는다.\n㈜B: 이익준비금 자본전입 무상주는 의제배당이고, 액면가액 5,000×200주=1,000,000원을 취득가액에 가산해 6,000,000원.\n㈜C: 파산 주식의 평가손실은 결산에 반영하지 않으면 손금산입할 수 없으므로 장부가액 1,250,000원.","c":"중","v":1},"공인회2017_52-13":{"w":"건물은 신고를 하지 않았으므로 정액법(상각률 0.1)을 적용한다. 취득세 2,500,000원은 취득원가에 가산하고 유보한다.\n제16기(4월 2일 취득, 9개월): 상각범위액=(1,000,000,000+2,500,000)×0.1×9/12=75,187,500원, 회사 계상 100,000,000원 → 한도초과 24,812,500원.\n제17기: 자본적 지출 50,000,000원은 즉시상각의제. 상각범위액=(1,002,500,000+50,000,000)×0.1=105,250,000원, 회사 계상 100,000,000+50,000,000=150,000,000원 → 한도초과 44,750,000원.\n유보 잔액=취득세 2,500,000+24,812,500+44,750,000=72,062,500원.","c":"중","v":1},"공인회2017_52-14":{"w":"① 소멸시효 완성 외상매출금 50,000,000원: 신고조정 대손사유 → 손금산입 50,000,000원(△유보).\n② 당기상계액 7,000,000원: 부도 6개월 경과 외상매출금은 중소기업만 대손 처리할 수 있다. ㈜A는 중소기업이 아니므로 손금불산입 7,000,000원(유보).\n③ 상각채권 추심 2,000,000원: 전기에 대손부인된 미수금이 회수되었으므로 그 유보를 없앤다 → 손금산입 2,000,000원(△유보). 회수액은 장부상 대손충당금 기말잔액에 들어가 한도초과 계산에 반영된다.\n④ 전기 대손충당금 한도초과액 1,500,000원 손금산입(추인).\n⑤ 한도: 설정대상 채권=1,000,000,000-50,000,000+7,000,000=957,000,000원, 1%(실적률 0.8%보다 큼) → 9,570,000원. 한도초과=20,000,000-9,570,000=10,430,000원 손금불산입.\n순영향=-50,000,000+7,000,000-2,000,000-1,500,000+10,430,000=-36,070,000원.","c":"상","v":1},"공인회2017_52-17":{"w":"이월결손금 공제: 중소기업이 아니므로 소득의 80% 한도. 이월결손금 90,000,000원 중 채무면제이익에 충당된 5,000,000원을 뺀 85,000,000원이나 한도 80,000,000원만 공제 → 과세표준 20,000,000원.\n산출세액=20,000,000×10%=2,000,000원.\n최저한세=과세표준 20,000,000×10%=2,000,000원이어서 연구·인력개발비 세액공제 100,000원은 최저한세 한도로 배제된다.\n외국납부세액공제 200,000원(최저한세 적용 제외)과 중간예납세액 50,000원을 차감: 2,000,000-200,000-50,000=1,750,000원.","c":"상","v":1},"공인회2017_52-20":{"w":"의제배당: ㈜A 자기주식처분이익 자본전입 무상주는 처분 시기와 관계없이 의제배당 10,000주×500원=5,000,000원. ㈜B 주식발행초과금 전입분은 의제배당이 아니다. ㈜C 자기주식소각이익은 소각 당시 시가가 취득가액 이하이지만 소각일(2015.8.30)부터 2년 안(2017.6.10)에 자본전입했으므로 의제배당 5,000주×500원=2,500,000원.\n금융소득=상장법인 현금배당 8,000,000+장기채권 이자 3,000,000(분리과세 미신청)+비영업대금 이자 6,000,000+의제배당 7,500,000=24,500,000원.\n2,000만원은 이자 9,000,000원이 먼저 채우고 나머지 11,000,000원은 Gross-up 대상 배당이 채운다. 초과분 4,500,000원(Gross-up 대상)×11%=495,000원 가산.\n합산 금액=24,500,000+495,000=24,995,000원.","c":"상","v":1},"공인회2017_52-21":{"w":"총수입금액: 월임대료 1,000,000×12=12,000,000원.\n간주임대료: (보증금 300,000,000-건물 취득가액 100,000,000)×3%=6,000,000원에서 보증금 운용수익 중 이자 2,000,000원·배당 1,000,000원을 차감 → 3,000,000원(유가증권처분이익은 차감 대상 아님).\n관리비수입 6,000,000원 중 전기·수도요금 징수대행분 2,000,000원 제외 → 4,000,000원.\n부속토지 사용 대가 5,000,000원은 24개월분이므로 2017년분 5,000,000×12/24=2,500,000원.\n합계=12,000,000+3,000,000+4,000,000+2,500,000=21,500,000원.","c":"중","v":1},"공인회2017_52-22":{"w":"(2023 개정 전 기준) 출제 당시 식사대와 6세 이하 보육수당의 비과세 한도는 각각 월 10만원이었다(현행 각 월 20만원).\n총급여=기본급 48,000,000\n+식사대 중 월 10만원 초과분 50,000×12=600,000\n+자가운전보조금 중 월 20만원 초과분 100,000×12=1,200,000\n+잉여금처분 성과배분상여금 중 결의일이 2017년인 5,000,000(2017 사업연도분은 결의일 2018.2.19라 2018년 귀속)\n+보육수당 중 월 10만원 초과분 100,000×12=1,200,000\n+연장·야간근로수당 3,000,000(생산직이 아니어서 과세)\n사택 무상 제공 이익은 비출자 직원이라 비과세.\n합계=59,000,000원.","c":"상","v":1,"old":1,"ow":"(2023 개정 전 기준) 출제 당시 식사대와 6세 이하 보육수당의 비과세 한도는 각각 월 10만원이었다(현행 각 월 20만원).\n총급여=기본급 48,000,000\n+식사대 중 월 10만원 초과분 50,000×12=600,000\n+자가운전보조금 중 월 20만원 초과분 100,000×12=1,200,000\n+잉여금처분 성과배분상여금 중 결의일이 2017년인 5,000,000(2017 사업연도분은 결의일 2018.2.19라 2018년 귀속)\n+보육수당 중 월 10만원 초과분 100,000×12=1,200,000\n+연장·야간근로수당 3,000,000(생산직이 아니어서 과세)\n사택 무상 제공 이익은 비출자 직원이라 비과세.\n합계=59,000,000원."},"공인회2017_52-23":{"w":"2002.1.1 이후 납입분에 대응하는 연금=18,000,000×900/(600+900)=10,800,000원.\n소득공제를 받지 못한 연금보험료(75,000,000-70,000,000=5,000,000원)는 과세제외기여금으로 연금수령액에서 차감한다.\n과세대상 연금액=10,800,000-5,000,000=5,800,000원.","c":"중","v":1},"공인회2017_52-24":{"w":"ㄱ: 출자공동사업자의 배당소득·사업소득·기타소득·양도소득에는 부당행위계산 부인 규정이 적용된다. O\nㄴ: 결손금이 발생한 과세기간과 이월결손금이 있는 경우에는 해당 과세기간의 결손금을 먼저 공제하고 이월결손금은 그 다음에 공제한다. X\nㄷ: 공동사업장의 소득과 그 외 소득을 구분한 계산서를 제출해야 한다. O\nㄹ: 특수관계인은 합산과세되는 소득금액 중 자기의 소득금액 해당분에 대해서만 연대납세의무를 진다. 전체에 대해서가 아니다. X","c":"중","v":1},"공인회2017_52-25":{"w":"교육비 세액공제 대상액: 본인 대학 등록금 4,000,000원(한도 없음). 배우자의 대학원 등록금은 본인 것만 공제되므로 제외.\n장녀(중학생): 교과서 대금 200,000+방과후학교 수업료·특별활동비 1,900,000+교복구입비 500,000(한도 50만원)=2,600,000원(초·중·고 1인당 한도 300만원 이내). 사설 학원비는 제외.\n장남(5세, 취학 전): 유치원 교육비 2,500,000+주 2회 이상 체육시설 수강료 1,200,000=3,700,000원이나 취학 전 1인당 한도 3,000,000원.\n공제 대상 합계=4,000,000+2,600,000+3,000,000=9,600,000원. 세액공제=9,600,000×15%=1,440,000원.","c":"중","v":1},"공인회2017_52-26":{"w":"1) 이혼 위자료를 지급하기 위해 비상장주식을 이전하는 것은 유상 양도로 본다. 양도소득세 과세. O\n2) 사업용 기계장치 처분은 양도소득세 과세대상이 아니다.\n3) 양도담보 제공은 양도로 보지 않는다.\n4) 건설업자가 주택을 신축·판매하면 사업소득이다.\n5) 자녀에게 무상으로 이전하면 증여세 과세대상이다.","c":"상","v":1},"공인회2017_52-27":{"w":"(2021 개정 전 기준) 출제 당시 1세대 1주택 고가주택 기준은 양도가액 9억원이었다(2021.12.8 이후 양도분부터 12억원).\n취득 실지거래가액을 모르므로 환산취득가액=1,000,000,000×450,000,000/900,000,000=500,000,000원.\n필요경비는 (환산취득가액+개산공제 13,500,000원)=513,500,000원과 (자본적지출 40,000,000+양도비 10,000,000)=50,000,000원 중 큰 금액 → 513,500,000원.\n양도차익=486,500,000원, 9억원 초과분 해당액=486,500,000×(10억-9억)/10억=48,650,000원.\n양도소득금액=48,650,000×(1-40%)=29,190,000원.\n현행 기준(12억원)이면 양도가액 10억원 주택은 전액 비과세다.","c":"상","v":1,"old":1,"ow":"(2021 개정 전 기준) 출제 당시 1세대 1주택 고가주택 기준은 양도가액 9억원이었다(2021.12.8 이후 양도분부터 12억원).\n취득 실지거래가액을 모르므로 환산취득가액=1,000,000,000×450,000,000/900,000,000=500,000,000원.\n필요경비는 (환산취득가액+개산공제 13,500,000원)=513,500,000원과 (자본적지출 40,000,000+양도비 10,000,000)=50,000,000원 중 큰 금액 → 513,500,000원.\n양도차익=486,500,000원, 9억원 초과분 해당액=486,500,000×(10억-9억)/10억=48,650,000원.\n양도소득금액=48,650,000×(1-40%)=29,190,000원.\n현행 기준(12억원)이면 양도가액 10억원 주택은 전액 비과세다."},"공인회2017_52-30":{"w":"미용 시술은 과세, 질병 치료는 면세. 매출세액=192,000,000×10%=19,200,000원.\n매입세액: 미용기계 25,000,000원은 과세 전용이라 2,500,000원 전액 공제. 의약품(질병치료용)과 승용차(개별소비세 과세대상)는 불공제.\n공통사용 상가건물 10,000,000원과 비품 500,000원은 공급가액 비율로 안분: 과세 192/200=96% → 10,500,000×96%=10,080,000원.\n공제 매입세액=2,500,000+10,080,000=12,580,000원.\n납부세액=19,200,000-12,580,000=6,620,000원.","c":"상","v":1},"공인회2017_52-34":{"w":"매출에누리·환입 20,000,000원을 뺀 공급가액 450,000,000원.\n① 하치장 반출은 재화의 공급이 아니다. 0.\n② 개별소비세 과세대상 승용차(업무용) 수리에 재고자산을 사용한 것은 간주공급: 시가 5,000,000원.\n③ 자기주식 양도는 주식 양도라 과세 제외.\n④ 사업상 증여: 취득가액 12,000,000원에서 경과된 과세기간 2개(2016년 제2기, 2017년 제1기)×25% 감가한 12,000,000×(1-0.5)=6,000,000원.\n⑤ 신제품 무상 제공은 사업상 증여: 시가 7,000,000원.\n합계=450,000,000+5,000,000+6,000,000+7,000,000=468,000,000원.","c":"상","v":1},"공인회2017_52-36":{"w":"(1) 원단 350,000,000×10%=35,000,000원 공제.\n(2) 사업과 관련 없는 지출의 매입세액은 불공제.\n(3) 출자임원 사택(소액주주 아님)의 유지비용은 업무무관 지출로 불공제.\n(4) 접대 목적으로 구입한 재화는 접대비 관련 매입세액으로 불공제.\n(5) 생산직 직원 작업복 구입 4,000,000×10%=400,000원 공제.\n합계=35,400,000원.","c":"상","v":1},"공인회2017_52-39":{"w":"증여세는 증여자별로 따로 계산하고, 동일인(직계존속은 그 배우자 포함)으로부터 10년 안에 받은 증여만 합산한다. 어머니와 친조부는 동일인이 아니다.\n같은 날 직계존속 둘에게서 받았으므로 직계존속 증여재산공제 5천만원을 증여재산가액 비율로 나눈다. 어머니 60/150 → 2천만원, 친조부 90/150 → 3천만원.\n어머니: (60,000,000-20,000,000)×10%=4,000,000원.\n친조부: (90,000,000-30,000,000)×10%=6,000,000원, 세대생략 할증 30% → 7,800,000원.\n친형: 2016년분 10,000,000원과 합산 35,000,000원-기타친족 공제 10,000,000원=25,000,000원×10%=2,500,000원(2016년분은 공제로 세액이 없었으므로 뺄 기납부세액 없음).\n2017년 귀속 산출세액 합계=4,000,000+7,800,000+2,500,000=14,300,000원.","c":"상","v":1},"공인회2017_52-40":{"w":"(2021 개정 전 기준) 출제 당시 개인의 유상취득 과세표준은 신고가액이되 신고가액이 시가표준액보다 적으면 시가표준액으로 했다.\n5) 신고가액이 시가표준액보다 적으면 시가표준액이 과세표준이므로 옳지 않다.\n1) 외국정부·주한국제기구의 취득은 비과세이고 상호주의에 따라 대한민국 정부기관 취득에 과세하는 외국정부는 과세. O\n2) 입목 취득세 납세지는 입목 소재지. O\n3) 등기·등록을 하지 않아도 사실상 취득하면 납세의무가 있고, 주문 건조 선박은 승계취득만 해당. O\n4) 지목 변경·종류 변경으로 가액이 늘면 취득으로 본다. O\n2023.1.1 시행 개정으로 유상승계취득의 과세표준은 사실상의 취득가격이 되고 시가표준액 하한 규정이 없어졌다.","c":"상","v":1,"old":1,"ow":"(2021 개정 전 기준) 출제 당시 개인의 유상취득 과세표준은 신고가액이되 신고가액이 시가표준액보다 적으면 시가표준액으로 했다.\n5) 신고가액이 시가표준액보다 적으면 시가표준액이 과세표준이므로 옳지 않다.\n1) 외국정부·주한국제기구의 취득은 비과세이고 상호주의에 따라 대한민국 정부기관 취득에 과세하는 외국정부는 과세. O\n2) 입목 취득세 납세지는 입목 소재지. O\n3) 등기·등록을 하지 않아도 사실상 취득하면 납세의무가 있고, 주문 건조 선박은 승계취득만 해당. O\n4) 지목 변경·종류 변경으로 가액이 늘면 취득으로 본다. O\n2023.1.1 시행 개정으로 유상승계취득의 과세표준은 사실상의 취득가격이 되고 시가표준액 하한 규정이 없어졌다."},"공인회2018_53-04":{"w":"매각대금 180,000,000원에서 강제징수비 10,000,000원을 뺀 170,000,000원을 배분한다.\n① 최종 3개월분 임금 10,000,000원(최우선).\n② 증여세 50,000,000원: 당해 재산에 부과된 당해세로 저당권보다 우선.\n③ 저당권 담보채권 60,000,000원: 설정일(2018.7.5)이 부가가치세 법정기일(신고일 2018.7.15)보다 앞서므로 부가가치세보다 우선.\n④ 그 밖의 임금채권 20,000,000원: 저당권에는 뒤지지만 조세보다 우선.\n⑤ 부가가치세: 남은 금액 170,000,000-10,000,000-50,000,000-60,000,000-20,000,000=30,000,000원.","c":"중","v":1},"공인회2018_53-06":{"w":"재평가세율 3%가 적용되는 건물 재평가적립금의 자본전입으로 받은 무상주 3,000주는 의제배당이 아니다. 자기주식처분이익 자본전입분 1,000주는 의제배당이다.\n의제배당이 아닌 무상주를 받은 날부터 2년 안에 감자하면 그 무상주를 먼저 소각한 것으로 보고 취득가액은 0으로 한다(법인세법 시행령 제14조제3항). 2017.7.1 무상주 수령 후 2018.2.1 감자이므로 반환한 2,000주는 이 무상주다.\n의제배당=감자대가 2,000주×20,000원-취득가액 0=40,000,000원.","c":"상","v":1},"공인회2018_53-07":{"w":"2016년 이후 취득한 업무용승용차는 정액법·내용연수 5년으로 상각해야 한다. 상각범위 120,000,000 ÷ 5 = 24,000,000원에 회사 계상 20,000,000원이 못 미쳐 4,000,000원을 손금산입(△유보)한다.\n관련비용은 24,000,000 + 4,000,000 = 28,000,000원이고 업무사용비율이 90%라 업무 외 사용분 2,800,000원은 손금불산입(상여)이다.\n업무사용 감가상각비 24,000,000 × 90% = 21,600,000원 중 연 8,000,000원을 넘는 13,600,000원은 손금불산입(유보)한다.\n유보 잔액 = −4,000,000 + 13,600,000 = 9,600,000원(2번).","c":"중","v":1},"공인회2018_53-09":{"w":"㈜갑(지분율 60%)과 ㈜을(70%)은 모두 50% 초과이므로 익금불산입률 50%. 두 법인 모두 배당기준일(2017.12.31) 3개월 전 이전에 취득했으므로 제외 주식이 아니다.\n차감할 지급이자는 회사채 이자 12,000,000원만 해당한다. 연지급수입 이자와 건설 중 특정차입금 이자는 차감 대상이 아니다.\n㈜갑: 10,000,000×50%=5,000,000원 - 12,000,000×(주식 적수 3,650억/자산 적수 36,500억)×50%=600,000원 → 4,400,000원.\n㈜을: 1,000,000×50%=500,000원 - 12,000,000×(7,300억/36,500억)×50%=1,200,000원 → 음수이므로 0.\n익금불산입액=4,400,000원.","c":"중","v":1},"공인회2018_53-13":{"w":"기준소득금액=당기순이익 100,000,000+법인세비용 10,000,000+기부금 합계(결산 계상 17,000,000+고가매입 의제 20,000,000)-의제분 손금산입 20,000,000=127,000,000원.\n고가매입: 정상가액은 시가 100,000,000원의 130%인 130,000,000원이므로 초과분 20,000,000원이 기부금(지방자치단체 → 특례기부금).\n특례기부금: 이월 10,000,000+국방헌금 5,000,000+고가매입 20,000,000=35,000,000원. 한도=(127,000,000-7,000,000)×50%=60,000,000원이므로 전액 손금산입.\n일반기부금 한도=(127,000,000-7,000,000-35,000,000)×10%=8,500,000원. 일반기부금 12,000,000원 → 한도초과 3,500,000원.","c":"중","v":1},"공인회2018_53-14":{"w":"신고하지 않은 기계장치는 정률법(상각률 0.7)을 적용한다.\n제18기초 미상각잔액=장부가액(302,000,000-280,000,000=22,000,000)+전기 상각부인액 5,600,000=27,600,000원.\n정률법에서 상각 후 잔액이 취득가액의 5%(15,100,000원) 이하가 되는 사업연도에는 비망가액 1,000원을 남기고 전부 상각할 수 있다. 상각범위액=27,600,000-1,000=27,599,000원.\n회사 계상액 22,000,000원은 범위 안이고 시인부족액 5,599,000원이 생기므로 전기 상각부인액 5,600,000원 중 5,599,000원을 손금추인한다. 부인액 잔액은 1,000원.\n법인세법상 장부가액=회사 장부가액 0+상각부인액 잔액 1,000=1,000원.","c":"중","v":1},"공인회2018_53-16":{"w":"부도어음 2매는 각각 비망가액 1,000원을 남기고 대손금이 되므로 비망가액 합계 2,000원은 채권에 남는다.\n설정대상 채권=매출채권 500,000,000+미수금 100,000,000+전기 대손부인 채권 중 소멸시효가 완성되지 않은 2,000,000+부도어음 비망가액 2,000=602,002,000원.\n한도액=602,002,000×1%=6,020,020원.\n기말잔액=한도 6,020,020+한도초과액 4,667,000=10,687,020원.","c":"중","v":1},"공인회2018_53-17":{"w":"임대료 시가가 불분명하면 (사택 시가×50%-보증금)×정기예금이자율로 본다.\nB씨: (200,000,000×50%-40,000,000)×5%=3,000,000원. 수령 임대료 200,000×12=2,400,000원. 차액 600,000원은 시가의 20%로 5% 이상이어서 부인 → 익금산입 600,000원.\nC씨: (120,000,000×50%)×5%=3,000,000원. 수령 240,000×12=2,880,000원. 차액 120,000원은 시가의 4%로 5% 미만이어서 부인 대상이 아니다.\n순영향=+600,000원.","c":"상","v":1},"공인회2018_53-19":{"w":"「사회복지사업법」에 따른 사회복지법인은 조세특례제한법 제74조제1항제2호에 따라 수익사업에서 생긴 소득 전액을 고유목적사업준비금으로 손금산입할 수 있다(법인세법 제29조의 50% 한도 대신).\n이자소득 80,000,000원+배당소득 20,000,000원=100,000,000원.\n부동산임대 사업소득 90,000,000원-이월결손금 10,000,000원=80,000,000원, 100% 적용.\n최대 손금산입 범위액=100,000,000+80,000,000=180,000,000원.","c":"상","v":1},"공인회2018_53-20":{"w":"(1) 저축성보험 만기보험금 100,000,000-납입보험료 88,000,000=12,000,000원은 보험차익으로 이자소득(10년 미만 유지).\n(2) 계약금이 배상금으로 대체된 25,000,000원은 기타소득.\n(3) 채권 중도 매도의 매매차익 중 보유기간 이자상당액 10,000,000원만 이자소득.\n(4) 공익신탁 이자는 비과세.\n(5) 비영업대금: 회수금액 42,000,000원은 원금 40,000,000원에 먼저 충당하므로 이자소득은 2,000,000원.\n합계=12,000,000+10,000,000+2,000,000=24,000,000원.","c":"상","v":1},"공인회2018_53-21":{"w":"1) 저작자 본인이 저작권의 양도·사용 대가로 받는 금품은 사업소득이다. 저작자가 아닌 자가 받으면 기타소득이다.\n2)~5)는 기타소득에 해당한다.","c":"상","v":1},"공인회2018_53-22":{"w":"당기순이익 124,500,000원에서 조정한다.\n가산: 소득세비용 15,000,000원, 대표자 갑의 급여 20,000,000원(필요경비 불산입), 기업업무추진비 한도초과액.\n기업업무추진비 한도(2018년 중소기업): 기본 24,000,000원+600,000,000×0.2%=1,200,000원=25,200,000원 → 한도초과 40,000,000-25,200,000=14,800,000원.\n차감: 배당금수익 6,000,000원(배당소득).\n대표자 본인의 국민건강보험료, 경리로 일하는 아들의 급여와 그 사용자 부담 보험료는 필요경비라 조정하지 않는다.\n사업소득금액=124,500,000+15,000,000+20,000,000+14,800,000-6,000,000=168,300,000원.","c":"상","v":1},"공인회2018_53-23":{"w":"(2024 개정 전 기준) 출제 당시 6세 이하 자녀 보육수당 비과세 한도는 월 10만원이었다.\n연장근로수당 1,500,000원: 생산직이고 직전 연도 총급여 2,400만원이 당시 기준(2,500만원 이하)에 들며 월정액급여 요건도 충족해 연 240만원 한도로 비과세.\n작업복 150,000원: 비과세.\n자가운전보조금: 월 20만원 초과분 50,000×12=600,000원 과세.\n식사대: 중식을 따로 제공받으므로 1,200,000원 전액 과세.\n보육수당: 월 10만원 초과분 200,000×12=2,400,000원 과세.\n총급여=12,000,000+4,000,000+600,000+1,200,000+2,400,000=20,200,000원.\n현행(보육수당 월 20만원 비과세)이면 보육수당 과세분이 1,200,000원이 되어 총급여는 19,000,000원(①)이다.","c":"상","v":1,"old":1,"ow":"(2024 개정 전 기준) 출제 당시 6세 이하 자녀 보육수당 비과세 한도는 월 10만원이었다.\n연장근로수당 1,500,000원: 생산직이고 직전 연도 총급여 2,400만원이 당시 기준(2,500만원 이하)에 들며 월정액급여 요건도 충족해 연 240만원 한도로 비과세.\n작업복 150,000원: 비과세.\n자가운전보조금: 월 20만원 초과분 50,000×12=600,000원 과세.\n식사대: 중식을 따로 제공받으므로 1,200,000원 전액 과세.\n보육수당: 월 10만원 초과분 200,000×12=2,400,000원 과세.\n총급여=12,000,000+4,000,000+600,000+1,200,000+2,400,000=20,200,000원.\n현행(보육수당 월 20만원 비과세)이면 보육수당 과세분이 1,200,000원이 되어 총급여는 19,000,000원(①)이다."},"공인회2018_53-26":{"w":"금융소득 40,000,000원(배당 15,000,000+이자 15,000,000+비영업대금 10,000,000)이 2,000만원을 넘어 종합과세된다. Gross-up 비대상 25,000,000원이 2,000만원을 먼저 채우므로 배당 15,000,000원 전부가 초과분 → 1,650,000원 가산, 금융소득금액 41,650,000원.\n종합소득과세표준=41,650,000+20,000,000-5,000,000=56,650,000원.\n① 일반산출세액=20,000,000×14%+기본세율(36,650,000원)=2,800,000+(720,000+24,650,000×15%)=7,217,500원.\n② 비교산출세액=원천징수세율 적용분(이자 15,000,000×14%+비영업대금 10,000,000×25%+배당 15,000,000×14%=6,700,000원)+기본세율(56,650,000-41,650,000=15,000,000원)=6,700,000+1,170,000=7,870,000원.\n산출세액=max(①, ②)=7,870,000원.","c":"상","v":1},"공인회2018_53-28":{"w":"기본공제 150만원: 본인, 부친(사망일 전날 기준), 남편(총급여 500만원 이하), 아들, 동생(장애인은 연령 요건 없음) → 5명=7,500,000원. 모친은 기타소득금액 4,000,000원(300만원 초과)이어서 소득금액 100만원 초과로 제외.\n추가공제: 경로우대(70세 이상 부친) 1,000,000원, 장애인(동생) 2,000,000원, 부녀자공제(종합소득금액 3,000만원 이하의 배우자 있는 여성) 500,000원.\n합계=7,500,000+1,000,000+2,000,000+500,000=11,000,000원.","c":"상","v":1},"공인회2018_53-29":{"w":"부담부증여로 채무 300,000,000원은 양도로 본다. 증여 시가 1,500,000,000원 중 양도 비율은 300,000,000/1,500,000,000=20%.\n양도가액=300,000,000원, 취득가액=800,000,000×20%=160,000,000원, 자본적지출=24,000,000×20%=4,800,000원.\n양도차익=300,000,000-160,000,000-4,800,000=135,200,000원.\n장기보유특별공제(3년 이상 10%)=13,520,000원.\n양도소득금액=135,200,000-13,520,000=121,680,000원.","c":"상","v":1},"공인회2018_53-30":{"w":"3) 거치 후 반환하지 않는 골프장 입회금은 용역의 대가로서 부가가치세 과세대상이다.\n1) 물납은 재화의 공급이 아니다. 2) 보세구역 반입만으로 수입이 아니다. 4) 조출료는 손해배상금 성격으로 과세 제외. 5) 망실 변상금도 손해배상금으로 과세 제외.","c":"상","v":1},"공인회2018_53-31":{"w":"주택 면적(50㎡)이 상가 면적(40㎡)보다 커서 건물 전체를 주택 임대로 보아 면세한다. 부수토지는 건물 정착면적 90㎡의 5배(도시지역) 450㎡까지 주택 부수토지로 면세, 나머지 300㎡는 과세되는 토지 임대다.\n1기 확정신고기간(4.1~6.30, 91일) 임대료 등: 월임대료·관리비 1,800,000×3=5,400,000원+간주임대료 91,250,000×1.8%×91/365=409,500원=5,809,500원.\n토지분=5,809,500×토지 기준시가 400,000,000/500,000,000=4,647,600원.\n과세 토지분=4,647,600×300/750=1,859,040원.","c":"상","v":1},"공인회2018_53-33":{"w":"(1) 상품권으로 받은 대금도 재화 인도 시점에 공급가액 2,000,000원.\n(2) 매입세액을 공제받지 못한 승용차는 간주공급 대상이 아니다. 0.\n(3) 수출: 공급시기(선적일) 전에 환가한 30,000달러는 환가 환율 950원 → 28,500,000원. 나머지 20,000달러는 선적일 환율 1,000원 → 20,000,000원.\n(4) 제품 판매 17,000,000원.\n(5) 판매목적 타 사업장 반출은 공급 간주: 취득가액에 일정액을 가산한 반출가액 6,000,000원.\n(6) 지방자치단체에 무상으로 제공한 제품은 과세 제외.\n합계=2,000,000+28,500,000+20,000,000+17,000,000+6,000,000=73,500,000원.","c":"중","v":1},"공인회2018_53-36":{"w":"2018 제1기 확정신고(4~6월)의 과세표준은 과세 60,000,000원이므로 매출세액 6,000,000원.\n매입세액: 과세 매입 4,000,000원 공제(면세 매입 3,000,000원은 불공제).\n비품(B) 공통매입세액 1,000,000원: 제1기 전체 공급가액 비율(과세 90/180=50%)로 정산 → 500,000원 공제.\n비품(A) 공통매입세액 3,000,000원: 감가상각자산이므로 면세비율 증감(취득 과세기간 제2기 면세비율 62.5% → 2018년 제1기 50%, 12.5%p 감소 ≥ 5%p)에 따라 재계산. 3,000,000×(1-25%×1)×12.5%=281,250원은 추가 공제(환급).\n납부세액=6,000,000-4,000,000-500,000-281,250=1,218,750원.","c":"중","v":1},"공인회2018_53-39":{"w":"(2019 개정 전 기준) 출제 당시 동거주택상속공제는 주택가액의 80%, 한도 5억원이었다(2020년부터 100%, 한도 6억원).\n과세가액=2,000,000,000-장례비 5,000,000=1,995,000,000원.\n기초공제 2억원+인적공제(자녀 2명 1억원, 장녀 미성년자 (19-9)×1천만원=1억원, 모친 연로자 5천만원, 모친 장애인 기대여명 20년×1천만원=2억원) 4억5천만원=6억5천만원으로 일괄공제 5억원보다 크다.\n동거주택상속공제=min(2,000,000,000×80%, 5억원)=5억원.\n과세표준=1,995,000,000-650,000,000-500,000,000=845,000,000원.\n현행 기준이면 동거주택상속공제가 6억원이 되어 745,000,000원이다.","c":"상","v":1,"old":1,"ow":"(2019 개정 전 기준) 출제 당시 동거주택상속공제는 주택가액의 80%, 한도 5억원이었다(2020년부터 100%, 한도 6억원).\n과세가액=2,000,000,000-장례비 5,000,000=1,995,000,000원.\n기초공제 2억원+인적공제(자녀 2명 1억원, 장녀 미성년자 (19-9)×1천만원=1억원, 모친 연로자 5천만원, 모친 장애인 기대여명 20년×1천만원=2억원) 4억5천만원=6억5천만원으로 일괄공제 5억원보다 크다.\n동거주택상속공제=min(2,000,000,000×80%, 5억원)=5억원.\n과세표준=1,995,000,000-650,000,000-500,000,000=845,000,000원.\n현행 기준이면 동거주택상속공제가 6억원이 되어 745,000,000원이다."},"공인회2018_53-40":{"w":"5) 재산세는 보통징수 방법으로 징수하고 고지서 1매당 세액이 2,000원 미만이면 징수하지 않는다. O\n1) 취득세 납세지는 부동산 소재지이다. 2) 지방소비세는 부가가치세를 과세표준으로 한다. 3) 일정 요건이 있으면 재산세 물납을 허가할 수 있다. 4) 토지 재산세 납기는 9월 16일~9월 30일이다.","c":"상","v":1},"공인회2019_54-07":{"w":"소득금액조정합계표 가산조정: 기업업무추진비 한도초과 300,000+교통사고벌과금 400,000+자기주식처분이익(자본조정 처리분) 익금산입 2,000,000=2,700,000원. 공정가치측정 금융자산 평가이익은 익금산입 1,800,000원과 손금산입(△유보) 1,800,000원이 서로 상쇄된다.\n차감조정: 재산세환급금이자 50,000원(익금불산입). 전기 납부 재산세 환급액은 손금으로 인정되었으므로 익금에 해당해 조정이 없다.\n기부금 한도초과액은 소득금액조정합계표 항목으로 보지 않는다.\n가산 2,700,000+1,800,000=4,500,000원, 차감 50,000+1,800,000=1,850,000원. 차이=2,650,000원.","c":"중","v":1},"공인회2019_54-08":{"w":"3) 이익처분으로 지급한 상여금은 처음부터 비용이 아니라 이익처분 항목이므로 세무조정이 없다. 손금산입(기타)으로 조정한다는 설명이 옳지 않다.\n1) 상업적 실질이 없는 교환은 공정가치로 자산을 평가해 200,000원 익금산입(유보). O\n2) 선급비용 중 당기 귀속분의 조정. O\n4) 임의평가이익은 인정하지 않는다. O\n5) 징벌적 손해배상금 중 실제 손해액을 초과하는 부분은 손금불산입(기타사외유출). O","c":"상","v":1},"공인회2019_54-09":{"w":"수입금액: 일반매출 7,000,000,000원에서 간주공급 300,000,000원(기업회계상 매출 아님)을 빼면 6,700,000,000원, 특수관계인 매출 8,000,000,000원. 매출할인은 이미 차감되어 있다.\n일반 한도: 중소기업 기본 24,000,000원+일반분 67억×0.2%=13,400,000원+특수관계인분 [(100억-67억)×0.2%+(147억-100억)×0.1%]×10%=(6,600,000+4,700,000)×10%=1,130,000원=38,530,000원.\n해당액: 판관비 50,000,000원-전기 귀속분 4,000,000원+직원이 조직한 법인인 단체에 낸 복리시설비 6,000,000원=52,000,000원.\n문화기업업무추진비 추가한도=min(10,000,000원, 38,530,000×20%=7,706,000원)=7,706,000원. 총한도 46,236,000원.\n한도초과액=52,000,000-46,236,000=5,764,000원.","c":"상","v":1},"공인회2019_54-10":{"w":"고가매입: 국가로부터 시가 50,000,000원인 토지를 70,000,000원에 샀으므로 정상가액(시가의 130%=65,000,000원) 초과분 5,000,000원이 기부금(특례기부금)이다. 자산에서 5,000,000원을 감액해 손금산입(△유보)한다.\n비지정기부금: 대표이사 대학동창회 기부금 2,000,000원은 손금불산입(+2,000,000).\n특례기부금 해당액=국립대학병원 연구비 3,000,000+고가매입 의제 5,000,000=8,000,000원.\n차가감소득금액=20,000,000+12,000,000-15,000,000+2,000,000-5,000,000=14,000,000원. 기준소득금액=14,000,000+8,000,000=22,000,000원.\n특례기부금 한도=(22,000,000-이월결손금 10,000,000)×50%=6,000,000원 → 한도초과 2,000,000원(손금불산입).\n영향=+2,000,000-5,000,000+2,000,000=-1,000,000원.","c":"중","v":1},"공인회2019_54-12":{"w":"감가상각방법을 변경하면 새 방법(정액법)의 상각범위액은 미상각잔액에 정액법 상각률을 곱해 계산한다.\n미상각잔액=100,000,000-55,000,000+전기 상각부인액 2,196,880=47,196,880원.\n상각범위액=47,196,880×0.125=5,899,610원.","c":"중","v":1},"공인회2019_54-13":{"w":"사용수익기부자산은 기부금으로 보되 시가가 아니라 장부가액 80,000,000원(특례기부금)을 사용기간(10년)에 걸쳐 균등하게 손금산입한다.\n유형자산처분이익 20,000,000원은 세법상 이익이 아니므로 익금불산입(-20,000,000).\n감가상각비 인정액=80,000,000/10년×6/12=4,000,000원. 회사 계상 10,000,000원 중 6,000,000원은 손금불산입(+6,000,000).\n순영향=-20,000,000+6,000,000=-14,000,000원.","c":"중","v":1},"공인회2019_54-14":{"w":"한도액=min[추계액(일시퇴직기준·보험수리기준 중 큰 금액 120,000,000원)-세무상 기말 퇴직급여충당금 잔액, 퇴직연금운용자산 잔액 110,000,000원].\n세무상 기말 퇴직급여충당금=장부 기말 20,000,000-손금부인 누계 잔액 5,000,000(기초 부인액 15,000,000에서 당기 퇴직금 지급 10,000,000이 먼저 감소)=15,000,000원 → 120,000,000-15,000,000=105,000,000원 (운용자산 110,000,000원보다 작다).\n세무상 기초 잔액 99,000,000원에서 당기 지급 10,000,000원을 뺀 89,000,000원에 한도까지 손금산입(16,000,000원)해 기말 잔액은 105,000,000원.","c":"중","v":1},"공인회2019_54-15":{"w":"1) 「채무자 회생 및 파산에 관한 법률」에 따른 회생계획인가 결정으로 회수불능이 확정된 채권은 신고조정 대손사유다(소멸시효 완성 채권, 법원 면책결정 채권 등과 함께 법인세법 시행령 제19조의2제3항제1호).\n2) 중소벤처기업부장관이 인정한 창업투자회사의 창업자 채권, 3) 채무자의 사업 폐지로 회수할 수 없는 채권, 4) 부도 6개월 경과 중소기업 외상매출금, 5) 금융감독원장 승인 금융회사 채권은 결산에 대손금으로 계상해야 손금이 되는 결산조정 사유다.","c":"상","v":1},"공인회2019_54-17":{"w":"지분율 40%(25% 이상, 6개월 이상 보유)라 간접외국납부세액공제 대상이다.\n간접외국납부세액=500,000×1,000,000/(3,000,000-500,000)=200,000원 → 익금산입. 직접 원천징수세액 100,000원은 장부에서 빠져 있으므로 익금산입(세액공제 선택).\n과세표준=100,000,000+100,000+200,000=100,300,000원, 산출세액=100,300,000×10%=10,030,000원.\n공제 한도=10,030,000×국외원천소득(1,000,000+200,000)/100,300,000=120,000원.\n외국납부세액 합계 300,000원 중 한도 120,000원만 공제한다.","c":"상","v":1},"공인회2019_54-18":{"w":"중소기업의 최저한세율은 7%. 연구·인력개발비 세액공제 2,000,000원은 중소기업의 경우 최저한세 적용 대상이 아니다.\n경정 시 배제순서는 손금산입 등 소득 관련 특례가 먼저이므로 신고조정 손금산입 5,000,000원을 배제하면 소득금액은 203,000,000원이다. 산출세액=200,000,000×10%+3,000,000×20%=20,600,000원.\n최저한세=203,000,000×7%=14,210,000원.\n근로소득증대 세액공제 7,800,000원은 20,600,000-14,210,000=6,390,000원까지만 공제 가능.\n공제액=6,390,000+2,000,000=8,390,000원.","c":"중","v":1},"공인회2019_54-21":{"w":"원천징수세액: 정기예금이자 10,000,000×14%=1,400,000, 비영업대금 이익 5,000,000×25%=1,250,000, 내국법인 배당 7,000,000×14%=980,000, 집합투자기구 이익 3,000,000×14%=420,000. 합계 4,050,000원(원천징수되지 않은 무조건 종합과세 소득 제외).\n금융소득 합계=15,000,000+5,000,000+7,000,000+3,000,000+6,000,000=36,000,000원 → 2,000만원 초과분은 모두 배당 쪽이어서 배당가산(Gross-up) 대상 배당 7,000,000원에 11%를 곱한 770,000원을 더한다.\n금융소득금액=36,770,000원.","c":"중","v":1},"공인회2019_54-22":{"w":"소득세비용차감전순이익 51,000,000원에서 조정한다.\n① 위탁매출: 수탁자가 2020년에 판매했으므로 2019년 매출 2,000,000원 차감(원가는 회계처리하지 않아 조정 없음).\n② 판매장건물 처분이익 5,000,000원: 복식부기의무자가 아니므로 사업소득이 아니다. 차감.\n③ 건물 감가상각비 상각부인액 200,000원 가산. 처분된 건물의 유보(500,000+200,000원)는 처분손익이 사업소득에서 빠지므로 사업소득 계산에서 추인하지 않는다.\n④ 시설개체로 폐기한 생산설비의 폐기손실은 필요경비로 인정된다. 감가상각비 부인액 200,000원 가산, 폐기로 전기 부인액 300,000원과 당기 부인액 200,000원 합계 500,000원을 손금(필요경비) 추인해 차감.\n사업소득금액=51,000,000-2,000,000-5,000,000+200,000+200,000-500,000=43,900,000원.","c":"상","v":1},"공인회2019_54-23":{"w":"㈜A: 급여 12,000,000+상여금 2,000,000. 성과배분상여금 5,000,000원은 결의일(2018.12.20)이 2018년이어서 제외. 식대 월 10만원, 숙직비 실비는 비과세.\n㈜B: 급여 15,000,000+식대 900,000(식사를 제공받아 비과세 불가)+건강검진보조금 500,000+추석명절격려금 3,000,000+자녀학비보조금 3,000,000. 자가운전보조금 월 20만원은 비과세.\n총급여=14,000,000+22,400,000=36,400,000원.\n근로소득공제=7,500,000+(36,400,000-15,000,000)×15%=10,710,000원. 근로소득금액=25,690,000원.","c":"상","v":1},"공인회2019_54-24":{"w":"1) 임원에게 부당행위계산 부인으로 상여 처분된 7억원은 근로소득으로 과세되므로 양도소득의 양도가액에서 뺀다. 양도가액은 15억-7억=8억원이다. 15억원이라는 설명이 옳지 않다.\n2) 고가 양도로 증여세가 과세된 증여재산가액 4억원은 양도가액에서 제외: 15억-4억=11억원. O\n3) 상여 처분된 4억원은 취득가액에 가산: 6억+4억=10억원. O\n4) 저가 취득으로 증여세가 과세된 1억원은 취득가액에 가산: 6억+1억=7억원. O\n5) 4촌은 특수관계인(친족)이므로 저가 양도에는 시가 10억원을 양도가액으로 본다. O","c":"중","v":1},"공인회2019_54-25":{"w":"(1) 공익사업 관련 지역권 설정 대가: 필요경비는 실제 1,000,000원과 60% 의제 1,200,000원 중 큰 금액 → 소득금액 800,000원.\n(2) 대학에 한 학기 고용되어 받은 시간강사료는 근로소득이다.\n(3) 원고료 500,000원: 60% 의제 → 200,000원.\n(4) 산업재산권 양도: 실제 1,500,000원과 의제 2,100,000원 중 큰 금액 → 1,400,000원.\n(5) 퇴직 후 받은 직무발명보상금 4,000,000원: 2019년 비과세 한도 연 500만원 이내라 과세소득 없음.\n(6) 공익법인 주최 발명경진대회 상금: 80% 의제 → 600,000원.\n(7) 법인세법상 기타소득 처분 1,000,000원.\n기타소득금액 합계=4,000,000원. 300만원을 넘어 분리과세를 선택할 수 없으므로 종합소득에 합산된다.","c":"상","v":1},"공인회2019_54-27":{"w":"기본공제 150만원: 본인, 배우자(육아휴직 급여는 비과세), 모친(67세, 수도권 밖 읍·면 전통주 제조소득 연 1,200만원 이하는 비과세), 장남(기숙사 별거는 동거로 본다), 장녀 → 5명=7,500,000원. 부친은 일시적 강연 기타소득금액 8,000,000×40%=3,200,000원(300만원 초과, 종합과세)이어서 소득요건 초과로 제외.\n추가공제: 장애인(장녀) 2,000,000원. 부녀자공제는 종합소득금액 3,000만원 초과라 해당 없음.\n연금보험료공제 1,500,000원, 건강·장기요양보험료공제 600,000원.\n합계=7,500,000+2,000,000+1,500,000+600,000=11,600,000원.","c":"상","v":1},"공인회2019_54-28":{"w":"모친의 이자소득 3,000,000원은 분리과세라 기본공제대상자이고 의료비 공제 대상이다. 총급여 3%=1,500,000원.\n일반 의료비(한도 700만원): 모친(64세) 한약비 1,000,000원.\n한도 없는 의료비: 본인 안경 500,000원(1인당 50만원 한도), 부친 장애인 보장구 1,500,000원 → 2,000,000원.\n난임시술비: 4,000,000원(공제율 20%).\n3% 기준액은 일반 의료비에서 먼저 빼고 모자라는 500,000원을 한도 없는 의료비에서 뺀다. (2,000,000-500,000)×15%=225,000원.\n난임시술비 4,000,000×20%=800,000원.\n의료비 세액공제=1,025,000원.","c":"상","v":1},"공인회2019_54-30":{"w":"(1) 재화 공급 49,000,000원(매출할인 제외)+판매장려금품으로 준 상품 시가 2,000,000원(사업상 증여).\n(2) 사무실 임대 6개월분 선불 6,000,000원: 2 과세기간에 걸친 부동산 임대용역의 선불 대가는 월수로 안분해 예정신고기간 종료일 등을 공급시기로 한다. 계약기간 2.16~8.15는 6개월(개시월 1개월로 산입, 종료월 미산입), 예정신고기간분은 2·3월 2개월 → 6,000,000×2/6=2,000,000원.\n(3) 현금 6,000,000원+Y통신사 마일리지 결제분 중 보전받은 2,000,000원=8,000,000원. 자기적립 마일리지 1,000,000원은 공급가액에서 제외.\n(4) 특수관계인에게 무상 제공한 공기정화기 임대용역은 부동산 임대용역이 아니라 과세하지 않는다.\n(5) 건물을 재화와 교환했으므로 건물 시가 40,000,000원(토지는 면세).\n합계=49,000,000+2,000,000+2,000,000+8,000,000+40,000,000=101,000,000원.","c":"상","v":1},"공인회2019_54-34":{"w":"과세 사업분 매입세액은 전액 공제, 면세 사업분은 불공제.\n공통 매입세액은 2019년 제1기 공급가액 비율(과세 70%)로 안분: 원자재 40,000,000×70%=28,000,000, 비품 10,000,000×70%=7,000,000.\n공제 합계=60,000,000+30,000,000+28,000,000+7,000,000=125,000,000원.\n면세사업용 기계(2018.7.7 구입, 매입세액 70,000,000원)를 과세사업으로 전용하면 경과된 과세기간 수(1)를 감안해 70,000,000×(1-25%×1)=52,500,000원을 공제한다.\n총 매입세액공제=177,500,000원.","c":"중","v":1},"공인회2019_54-35":{"w":"부수토지가 있는 건물을 양도할 때 가액 구분이 불분명하면 양도일 이전 6개월 이내 감정평가액으로 안분한다(2019.2.2 평가, 사용 가능). 건물분=100,000,000×40/100=40,000,000원.\n건물은 1층(100㎡)만 과세 임대에 사용하고 나머지는 면세사업(생닭 판매)에 사용했으며 매입세액을 사용면적 비율로 공제했다. 과세되는 공급가액=40,000,000×100/500=8,000,000원. 토지는 면세.","c":"중","v":1},"공인회2019_54-36":{"w":"(2020 개정 전 기준) 2019년 간이과세자 납부세액과 매입세액공제는 모두 업종별 부가가치율을 곱해 계산했다.\n공급대가=양복 60,000,000+재봉틀 매각 1,000,000=61,000,000원. 납부세액=61,000,000×20%×10%=1,220,000원.\n매입세액공제=세금계산서·신용카드 수취분 매입세액(2,000,000+1,000,000+재봉틀 200,000)×부가가치율 20%=640,000원.\n신용카드매출전표·현금영수증 발행세액공제=(12,000,000+10,000,000)×1.3%=286,000원.\n차가감납부세액=1,220,000-640,000-286,000=294,000원.\n2021.7.1 이후 간이과세자의 매입세액공제는 매입 공급대가의 0.5%로 바뀌어 같은 자료로 계산하면 결과가 달라진다.","c":"상","v":1,"old":1,"ow":"(2020 개정 전 기준) 2019년 간이과세자 납부세액과 매입세액공제는 모두 업종별 부가가치율을 곱해 계산했다.\n공급대가=양복 60,000,000+재봉틀 매각 1,000,000=61,000,000원. 납부세액=61,000,000×20%×10%=1,220,000원.\n매입세액공제=세금계산서·신용카드 수취분 매입세액(2,000,000+1,000,000+재봉틀 200,000)×부가가치율 20%=640,000원.\n신용카드매출전표·현금영수증 발행세액공제=(12,000,000+10,000,000)×1.3%=286,000원.\n차가감납부세액=1,220,000-640,000-286,000=294,000원.\n2021.7.1 이후 간이과세자의 매입세액공제는 매입 공급대가의 0.5%로 바뀌어 같은 자료로 계산하면 결과가 달라진다."},"공인회2019_54-39":{"w":"대출금: 법정이자율 4.6%로 계산한 이자 450,000,000×4.6%=20,700,000원에서 실제 지급이자 4,500,000원을 뺀 16,200,000원이 증여이익(1,000만원 이상이므로 과세).\n토지: 증여세 신고기한(증여받은 달의 말일부터 3개월) 이내에 반환한 50,000,000원과 40,000,000원은 처음부터 증여가 없었던 것으로 본다. 신고기한이 지난 뒤 반환한 25,000,000원은 증여가 유지된다.\n토지 증여세 과세가액=250,000,000-50,000,000-40,000,000=160,000,000원.","c":"상","v":1},"공인회2019_54-40":{"w":"5) 대한민국 정부기관의 재산에 대하여 과세하는 외국정부의 재산에는 재산세를 부과한다(상호주의). 부과하지 않는다는 설명이 옳지 않다.\n1) 상속이 개시된 자동차는 상속지분이 가장 높은 자가 납세의무자. O  2) 소싸움 사업자는 레저세 납세의무. O  3) 원자력 발전은 지역자원시설세. O  4) 국가·지자체 자기를 위한 등록은 등록면허세 비과세. O","c":"상","v":1},"공인회2020_55-08":{"w":"자본금과 적립금조정명세서(을) 기말잔액=기초 500,000원+당기 증감.\n(3) 대주주 유류비: 손금불산입 → 사외유출(배당·상여), 유보 아님.\n(4) 공장 재산세: 정상 비용, 조정 없음.\n(5) 공정가치측정 금융자산 평가손실 비용 200,000원: 손금불산입(+유보 200,000).\n(6) 증빙 미수취 기업업무추진비: 손금불산입(기타사외유출).\n(7) 회계처리 누락 외상매출금 200,000원: 익금산입(+유보 200,000).\n(8) 자기주식처분이익: 익금산입(기타).\n(9) 기타포괄손익 평가이익 200,000원: 익금산입(기타)과 손금산입(△유보 200,000).\n당기 증감=+200,000+200,000-200,000=+200,000. 기말잔액=500,000+200,000=700,000원.","c":"중","v":1},"공인회2020_55-10":{"w":"㈜C의 주식은 2019.11.15 취득으로 배당기준일(2019.12.31) 전 3개월 이내 취득분이므로 익금불산입 대상에서 제외한다.\n㈜B(60%, 50%): 6,000,000×50%=3,000,000원. ㈜D(40%, 30%): 3,000,000×30%=900,000원.\n차입금 이자 차감: 채권자 불분명 사채이자 15,000,000원을 뺀 15,000,000원이 대상.\n㈜B 차감=15,000,000×(300,000,000/5,000,000,000)×50%=450,000원. ㈜D 차감=15,000,000×(600,000,000/5,000,000,000)×30%=540,000원.\n익금불산입액=(3,000,000-450,000)+(900,000-540,000)=2,910,000원.","c":"상","v":1},"공인회2020_55-11":{"w":"수입금액 한도: 일반 8,000,000,000×0.3%=24,000,000원, 특수관계인분 [80억~100억 구간 20억×0.3%+100억~120억 구간 20억×0.2%]×10%=(6,000,000+4,000,000)×10%=1,000,000원.\n한도=중소기업 기본 36,000,000+24,000,000+1,000,000=61,000,000원.\n해당액: 판관비 54,000,000원+접대 목적 증정 제품 11,000,000원(시가 10,000,000원과 장부가액 중 큰 금액에 매출세액 1,000,000원을 더한 금액)=65,000,000원. 법인이 아닌 직원 단체에 낸 복리시설비는 회사 경리의 일부로 보아 기업업무추진비가 아니다.\n한도초과액=65,000,000-61,000,000=4,000,000원.","c":"상","v":1},"공인회2020_55-12":{"w":"신고하지 않았으므로 건물은 정액법(0.05), 기계장치는 정률법(0.259)을 적용한다.\n건물: 기초 장부가액=900,000,000-(435,000,000-30,000,000)=495,000,000원. 자본적 지출 24,000,000원은 전기말 장부가액의 5%(24,750,000원) 미만이라 손금으로 인정되어 즉시상각의제가 아니다. 상각범위액=900,000,000×0.05=45,000,000원, 회사 계상 30,000,000원 → 시인부족 15,000,000원, 전기 부인액 4,000,000원 범위에서 손금산입 4,000,000원.\n기계장치: 기초 장부가액=400,000,000-(280,000,000-25,000,000)=145,000,000원. 자본적 지출 10,000,000원은 145,000,000원의 5%(7,250,000원) 이상이고 600만원 이상이므로 즉시상각의제. 상각범위액=(145,000,000+20,000,000+10,000,000)×0.259=45,325,000원, 회사 계상 25,000,000+10,000,000=35,000,000원 → 시인부족 10,325,000원, 전기 부인액 20,000,000원 범위에서 손금산입 10,325,000원.","c":"상","v":1},"공인회2020_55-14":{"w":"채권자 불분명 사채이자 3,000,000원은 손금불산입한다. 원천징수세액 1,260,000원은 기타사외유출, 나머지 1,740,000원은 대표자상여.\n업무무관 자산·업무무관 가지급금 관련 지급이자는 은행차입금 이자 10,000,000원에 대해 계산한다.\n업무무관 자산 적수=20,000,000×366=7,320,000,000원, 업무무관 대여금 적수 1,830,000,000원 → 합계 9,150,000,000원.\n손금불산입=10,000,000×9,150,000,000/36,600,000,000=2,500,000원(기타사외유출).\n기타사외유출 합계=1,260,000+2,500,000=3,760,000원.","c":"중","v":1},"공인회2020_55-15":{"w":"대손금 부인: 법령상 요건을 충족하지 못한 상계액 2,000,000원 → 손금불산입(+2,000,000).\n전기 유보 추인: 대손충당금 한도초과액 3,000,000원 → 손금산입(-3,000,000). 외상매출금 대손부인액 7,000,000원은 소멸시효 완성 → 손금산입(-7,000,000).\n한도액: 설정대상 채권=대여금 50,000,000+미수금 300,000,000+매출채권 500,000,000+남은 대손부인 채권(대여금 10,000,000+당기 부인 외상매출금 2,000,000)=862,000,000원. 한도=862,000,000×1.5%=12,930,000원.\n한도초과액=기말잔액 30,000,000-12,930,000=17,070,000원.\n순영향=+2,000,000+17,070,000-3,000,000-7,000,000=+9,070,000원.","c":"중","v":1},"공인회2020_55-17":{"w":"결손금 소급공제 환급세액: 제19기 과세표준 350,000,000원에서 소급공제 결손금을 뺀 과세표준에 대한 산출세액을 직전 산출세액 50,000,000원에서 뺀다. 한도는 직전 사업연도 법인세액(산출세액 50,000,000-공제·감면 30,000,000=20,000,000원).\n당초 환급: 80,000,000원 소급 → 과세표준 270,000,000원, 산출세액 20,000,000+70,000,000×20%=34,000,000원. 환급세액=50,000,000-34,000,000=16,000,000원(한도 이내).\n결손금이 70,000,000원으로 줄었으므로 소급공제 가능 결손금은 70,000,000원. 과세표준 280,000,000원, 산출세액 36,000,000원. 환급세액=50,000,000-36,000,000=14,000,000원.\n징수액=16,000,000-14,000,000=2,000,000원.","c":"상","v":1},"공인회2020_55-18":{"w":"재해상실비율=재해상실자산가액/상실 전 자산총액(토지 제외): (250,000,000+50,000,000)/(250,000,000+150,000,000)=75%.\n공제 대상 세액=법인세 산출세액 150,000,000-공제·감면세액 25,000,000+가산세 5,000,000+재해발생일 현재 미납 법인세액 200,000,000=330,000,000원.\n공제액=330,000,000×75%=247,500,000원. 재해상실가액 300,000,000원 한도 이내.","c":"중","v":1},"공인회2020_55-22":{"w":"(1) 파생결합사채 이익 10,000,000원은 배당소득.\n(2) 개인종합자산관리계좌(ISA) 배당 5,000,000원은 비과세·분리과세 대상이라 종합소득에 합산하지 않는다.\n(3) 자기주식처분이익 자본전입 무상주: 20,000주×1,000원=20,000,000원은 의제배당(Gross-up 대상).\n(4) 코넥스 상장법인 현금배당 3,000,000원.\n합계 33,000,000원이 2,000만원을 초과하는 13,000,000원은 모두 배당가산 대상이어서 11%를 곱한 1,430,000원을 더한다.\n배당소득금액=34,430,000원.","c":"중","v":1},"공인회2020_55-23":{"w":"총수입금액: 임대료 2,000,000×12=24,000,000원, 관리비 500,000×12=6,000,000원.\n간주임대료: (보증금 500,000,000-건물 취득가액 300,000,000)×2%=4,000,000원에서 보증금 운용수익 중 수입이자 300,000원과 수입배당금 500,000원을 뺀 3,200,000원(신주인수권처분이익은 차감 대상이 아님).\n합계=24,000,000+6,000,000+3,200,000=33,200,000원.","c":"중","v":1},"공인회2020_55-24":{"w":"(2023 개정 전 기준) 출제 당시 식사대 비과세 한도는 월 10만원이었다(현행 월 20만원).\n총급여=급여 24,000,000+상여금 10,000,000\n+식사대 중 월 10만원 초과분 50,000×12=600,000\n+단체환급부보장성보험료 중 연 70만원 초과분 500,000\n+주식매수선택권 행사이익 20,000,000(벤처기업 비과세 특례 대상 아님, 재직 중 행사라 근로소득)\n보육수당(6세) 월 10만원과 중소기업 종업원의 사택 무상 제공 이익은 비과세.\n합계=55,100,000원.\n현행이면 식사대가 전액 비과세되어 54,500,000원이 된다.","c":"상","v":1,"old":1,"ow":"(2023 개정 전 기준) 출제 당시 식사대 비과세 한도는 월 10만원이었다(현행 월 20만원).\n총급여=급여 24,000,000+상여금 10,000,000\n+식사대 중 월 10만원 초과분 50,000×12=600,000\n+단체환급부보장성보험료 중 연 70만원 초과분 500,000\n+주식매수선택권 행사이익 20,000,000(벤처기업 비과세 특례 대상 아님, 재직 중 행사라 근로소득)\n보육수당(6세) 월 10만원과 중소기업 종업원의 사택 무상 제공 이익은 비과세.\n합계=55,100,000원.\n현행이면 식사대가 전액 비과세되어 54,500,000원이 된다."},"공인회2020_55-26":{"w":"(2023 개정 전 기준) 2020년 자녀세액공제는 기본공제대상 자녀 중 7세 이상이 대상이고 2명이면 1명당 150,000원이었다.\n자녀세액공제: 8세·10세 2명 → 300,000원(6세는 제외).\n연금계좌세액공제: 총급여 5,500만원 이하라 공제율 15%. 연금저축 3,000,000원(한도 400만원 이내)+퇴직연금 2,000,000원=5,000,000원(합산 한도 700만원 이내) → 750,000원.\n합계=1,050,000원.\n현행 소득세법 제59조의2 제1항(2026.4.21 개정)은 대상 나이를 13세 이상으로 정하고 2026년 과세기간분은 부칙 제2조에 따라 9세 이상이다. 2명 공제액도 55만원으로 늘어 현행 기준으로는 선지와 맞지 않는다.","c":"상","v":1,"old":1,"ow":"(2023 개정 전 기준) 2020년 자녀세액공제는 기본공제대상 자녀 중 7세 이상이 대상이고 2명이면 1명당 150,000원이었다.\n자녀세액공제: 8세·10세 2명 → 300,000원(6세는 제외).\n연금계좌세액공제: 총급여 5,500만원 이하라 공제율 15%. 연금저축 3,000,000원(한도 400만원 이내)+퇴직연금 2,000,000원=5,000,000원(합산 한도 700만원 이내) → 750,000원.\n합계=1,050,000원.\n현행 소득세법 제59조의2 제1항(2026.4.21 개정)은 대상 나이를 13세 이상으로 정하고 2026년 과세기간분은 부칙 제2조에 따라 9세 이상이다. 2명 공제액도 55만원으로 늘어 현행 기준으로는 선지와 맞지 않는다."},"공인회2020_55-28":{"w":"퇴직소득=퇴직급여 30,000,000+퇴직공로금 5,000,000=35,000,000원. 근속연수 4년 3개월은 5년으로 올림한다.\n근속연수공제=300,000×5=1,500,000원. 환산급여=(35,000,000-1,500,000)×12/5=80,400,000원.\n환산급여공제=45,200,000+(80,400,000-70,000,000)×55%=50,920,000원. 환산과세표준=80,400,000-50,920,000=29,480,000원.\n환산산출세액=720,000+(29,480,000-12,000,000)×15%=3,342,000원. 퇴직소득산출세액=3,342,000×5/12=1,392,500원.","c":"상","v":1},"공인회2020_55-29":{"w":"(2021 개정 전 기준) 출제 당시 고가주택 기준은 양도가액 9억원이었다.\n양도차익=1,200,000,000-660,000,000-자본적지출 40,000,000-중개수수료 5,000,000=495,000,000원.\n9억원 초과분 해당 양도차익=495,000,000×(12억-9억)/12억=123,750,000원.\n2021.12.8 이후 양도분은 고가주택 기준이 12억원이라 양도가액 12억원 주택은 전액 비과세가 된다.","c":"상","v":1,"old":1,"ow":"(2021 개정 전 기준) 출제 당시 고가주택 기준은 양도가액 9억원이었다.\n양도차익=1,200,000,000-660,000,000-자본적지출 40,000,000-중개수수료 5,000,000=495,000,000원.\n9억원 초과분 해당 양도차익=495,000,000×(12억-9억)/12억=123,750,000원.\n2021.12.8 이후 양도분은 고가주택 기준이 12억원이라 양도가액 12억원 주택은 전액 비과세가 된다."},"공인회2020_55-31":{"w":"주택 부분 200㎡와 상가 부분 200㎡가 같으므로 상가 부분은 과세한다.\n임대료를 기준시가로 건물분과 토지분으로 안분: 건물 1,500,000원, 토지 1,500,000원(9월 한 달분 3,000,000원).\n건물: 상가 부분 1,500,000×200/400=750,000원.\n토지: 건물 정착면적(400㎡)의 5배(도시지역 주거지역) 2,000㎡ 안에서 상가 부분 해당 1,000㎡와, 5배를 넘는 500㎡는 건물과 별개로 과세 → 1,500㎡. 1,500,000×1,500/2,500=900,000원.\n과세표준=750,000+900,000=1,650,000원.","c":"중","v":1},"공인회2020_55-32":{"w":"폐업 시 잔존재화의 과세표준:\n제품: 폐업일의 시가 9,000,000원.\n건물: 취득가액 100,000,000원(장기미지급금 명목가액)에서 5%×경과된 과세기간 수(4)를 뺀다: 100,000,000×(1-0.2)=80,000,000원.\n소형승용차: 취득 시 매입세액을 공제받지 못했으므로 재화의 공급으로 보지 않는다.\n합계=9,000,000+80,000,000=89,000,000원.","c":"중","v":1},"공인회2020_55-35":{"w":"2020년 제2기(7~12월) 공급가액: 과세 100,000,000원, 면세 100,000,000원 → 과세비율 50%.\n10~12월 확정분: 매출세액 51,000,000×10%=5,100,000원, 과세 매입세액 3,500,000원(면세 매입 불공제).\n트럭 공통매입세액 1,000,000원: 예정신고 때 7~9월 비율(49%)로 490,000원 공제했으므로 제2기 전체 비율 50%로 정산하면 500,000원 → 10,000원 추가 공제.\n기계장치(감가상각자산) 재계산: 취득한 제1기 면세비율 60%에서 제2기 50%로 10%p 감소(5%p 이상). 2,000,000×(1-25%×1)×10%=150,000원 추가 공제.\n납부세액=5,100,000-3,500,000-10,000-150,000=1,440,000원.","c":"중","v":1},"공인회2020_55-36":{"w":"(1) 착오로 공급가액을 잘못 적었더라도 기재 사항으로 거래사실이 확인되면 실제 공급가액 9,000,000원의 매입세액 900,000원을 공제한다.\n(2) 업무용 소형승용차 임차료의 매입세액은 불공제.\n(3) 간이과세자로부터 받은 신용카드매출전표(영수증 발급 대상)의 매입세액은 공제하지 않는다.\n(4) 직원 사택 수리비 4,000,000원의 매입세액 400,000원은 공제.\n(5) 수입 시 부가가치세=(과세가격 10,000,000+관세 800,000)×10%=1,080,000원 공제.\n합계=900,000+400,000+1,080,000=2,380,000원.","c":"상","v":1},"공인회2020_55-37":{"w":"매출세액=450,000,000×10%=45,000,000원.\n매입세액: 세금계산서 10,000,000원 중 기업업무추진비 관련 500,000원 불공제 → 9,500,000원. 의제매입세액 2,000,000원.\n대손세액공제: 받을어음 부도발생일 6개월 경과(2020.12.1) → 2,200,000×10/110=200,000원.\n납부세액=45,000,000-9,500,000-2,000,000-200,000=33,300,000원.\n신용카드매출전표 발행세액공제=385,000,000×1.3%=5,005,000원(연 한도 1,000만원, 제1기 4,500,000원을 빼면 5,500,000원 이내). 전자신고세액공제 10,000원.\n차가감납부세액=33,300,000-5,005,000-10,000=28,285,000원.","c":"중","v":1},"공인회2020_55-39":{"w":"특수관계인(어머니) 간 저가 양수: 시가 500,000,000원과 대가 300,000,000원의 차이 200,000,000원이 시가의 30% 이상. 증여재산가액=200,000,000-min(시가의 30% 150,000,000원, 3억원)=50,000,000원.\n비특수관계인 간 저가 양수: 시가 700,000,000원과 대가 500,000,000원의 차이 200,000,000원은 시가의 28.6%로 30% 미만이어서 증여로 보지 않는다. 0.\n특수관계인(할아버지)에게 고가 양도: 대가 400,000,000원과 시가 200,000,000원의 차이 200,000,000원은 시가의 100%. 증여재산가액=200,000,000-min(시가의 30% 60,000,000원, 3억원)=140,000,000원.\n합계=50,000,000+0+140,000,000=190,000,000원.","c":"중","v":1},"공인회2020_55-40":{"w":"2) 주문을 받아 건조하는 선박을 제조사가 원시취득하는 경우는 등록 전에 취득세 납세의무가 생기지 않는다(승계취득의 경우에만 사실상 취득으로 과세). 옳지 않다.\n1) 대여시설 이용자에게 대여하기 위해 수입하는 자가 납세의무자. O  3) 주택조합이 조합원용으로 취득하는 부동산은 조합원이 납세의무자. O  4) 배우자 간 교환은 유상취득. O  5) 부담부증여의 채무액 부분은 유상취득. O","c":"상","v":1},"공인회2021_56-01":{"w":"1) 납세조합이 징수하는 소득세의 납세의무 성립시기는 과세기간이 끝나는 때가 아니라 납세조합이 소득세를 징수하는 때이다. 옳지 않다.\n2) 수입물품 개별소비세는 수입신고하는 때. O  3) 청산소득 법인세는 해산하는 때. O  4) 무신고가산세는 법정신고기한이 경과하는 때. O  5) 수시부과 국세는 사유가 발생한 때. O","c":"상","v":1},"공인회2021_56-05":{"w":"5) 성실도 분석 결과 불성실 혐의가 있다는 이유만으로는 같은 세목·같은 과세기간에 대한 재조사를 할 수 없다.\n1)~4)는 국세기본법이 정한 재조사 사유다(조세탈루 혐의가 있는 명백한 자료, 환급결정을 위한 확인조사, 2개 이상 과세기간 관련 잘못, 다른 기관의 제공 자료 처리 등).","c":"상","v":1},"공인회2021_56-08":{"w":"(2024 개정 전 기준) 출제 당시 직무발명보상금 비과세 한도는 연 500만원이었다(현행 연 700만원).\n비과세: 직무발명보상금 5,000,000원+중소기업 종업원의 주택취득자금 무상제공 이익 5,000,000원+단체순수보장성보험료 700,000원+자가운전보조금(월 20만원 이내) 2,000,000원=12,700,000원.\n과세: 급여 40,000,000+식사를 제공받으면서 받은 식대 1,200,000+직무발명보상금 초과분 5,000,000+보험료 초과분 300,000+영업사원 시간외 근무수당 2,000,000=48,500,000원.\n현행 한도(700만원)를 적용하면 비과세 14,700,000원, 총급여 46,500,000원이 되어 선지에 없다.","c":"상","v":1,"old":1,"ow":"(2024 개정 전 기준) 출제 당시 직무발명보상금 비과세 한도는 연 500만원이었다(현행 연 700만원).\n비과세: 직무발명보상금 5,000,000원+중소기업 종업원의 주택취득자금 무상제공 이익 5,000,000원+단체순수보장성보험료 700,000원+자가운전보조금(월 20만원 이내) 2,000,000원=12,700,000원.\n과세: 급여 40,000,000+식사를 제공받으면서 받은 식대 1,200,000+직무발명보상금 초과분 5,000,000+보험료 초과분 300,000+영업사원 시간외 근무수당 2,000,000=48,500,000원.\n현행 한도(700만원)를 적용하면 비과세 14,700,000원, 총급여 46,500,000원이 되어 선지에 없다."},"공인회2021_56-10":{"w":"기본공제(150만원): 본인, 부친(공무원연금은 소득공제를 받지 않은 불입분에 대응해 과세 소득이 없음), 모친, 아들 → 4명=6,000,000원. 이혼한 배우자는 과세기간 종료일 현재 배우자가 아니므로 제외.\n추가공제: 경로우대(70세 이상) 부친·모친 2,000,000원, 장애인(모친) 2,000,000원, 한부모공제(배우자 없는 자로서 직계비속이 있음) 1,000,000원.\n합계=6,000,000+2,000,000+2,000,000+1,000,000=11,000,000원.","c":"중","v":1},"공인회2021_56-11":{"w":"사업소득금액=300,000,000-(390,000,000-대표자 인건비 30,000,000)=-60,000,000원(딸 인건비는 필요경비 인정). 결손금 60,000,000원.\n사업소득 결손금은 근로소득금액 → 연금소득금액 → 기타소득금액 → 이자소득금액 → 배당소득금액 순서로 공제한다.\n근로소득금액 40,000,000원에서 먼저 40,000,000원을 공제하고 남은 20,000,000원을 기타소득금액 30,000,000원에서 공제하면 10,000,000원이 남는다.\n종합소득금액=10,000,000원.","c":"상","v":1},"공인회2021_56-13":{"w":"(1) 직장공제회 초과반환금 10,000,000원은 무조건 분리과세이므로 합산하지 않는다.\n(2) 전용계좌의 특정사회기반시설 집합투자기구 배당은 분리과세.\n(3) 출자공동사업자 배당 5,000,000원: 무조건 종합과세.\n(4) 국내은행 정기예금이자 10,000,000원.\n(5) 외국법인 현금배당 15,000,000원(원천징수되지 않아 무조건 종합과세, Gross-up 대상 아님).\n(6) 주권상장법인 현금배당 20,000,000원(Gross-up 대상).\n합산 금융소득=5,000,000+10,000,000+15,000,000+20,000,000=50,000,000원. 2,000만원까지는 Gross-up 대상이 아닌 소득 30,000,000원이 먼저 채우므로 상장법인 배당 20,000,000원은 모두 초과분에 들어가 11%를 곱한 2,200,000원을 가산한다.\n합산 금융소득금액=52,200,000원.","c":"상","v":1},"공인회2021_56-14":{"w":"본인 대학원 등록금 4,000,000원(한도 없음).\n아들(22세) 대학 등록금: 1인당 한도 9,000,000원. 회사에서 받은 학자금 2,000,000원은 근로소득에 포함되어 있으므로 교육비에서 차감하지 않는다.\n딸(16세): 교과서 대금 100,000원과 교복구입비 300,000원 → 400,000원.\n모친(직계존속)의 교육비는 공제 대상이 아니다.\n대상 합계=4,000,000+9,000,000+400,000=13,400,000원. 세액공제=13,400,000×15%=2,010,000원.","c":"중","v":1},"공인회2021_56-15":{"w":"(2021 개정 전 기준) 2021년 4월 양도 당시 고가주택 기준은 9억원이었다(현행 12억원이면 전액 비과세).\n필요경비=취득가액 500,000,000+취득 중개수수료 2,000,000+취득세 5,000,000+양도 중개수수료 3,000,000=510,000,000원(보유 중 재산세 제외).\n양도차익=490,000,000원, 9억원 초과분 해당액=490,000,000×(10억-9억)/10억=49,000,000원.\n장기보유특별공제: 보유기간 2014.5.5~2021.4.4 6년(24%)+거주기간 2016.6.6~2021.4.4 4년(16%)=40%.\n양도소득금액=49,000,000×60%=29,400,000원.","c":"상","v":1,"old":1,"ow":"(2021 개정 전 기준) 2021년 4월 양도 당시 고가주택 기준은 9억원이었다(현행 12억원이면 전액 비과세).\n필요경비=취득가액 500,000,000+취득 중개수수료 2,000,000+취득세 5,000,000+양도 중개수수료 3,000,000=510,000,000원(보유 중 재산세 제외).\n양도차익=490,000,000원, 9억원 초과분 해당액=490,000,000×(10억-9억)/10억=49,000,000원.\n장기보유특별공제: 보유기간 2014.5.5~2021.4.4 6년(24%)+거주기간 2016.6.6~2021.4.4 4년(16%)=40%.\n양도소득금액=49,000,000×60%=29,400,000원."},"공인회2021_56-18":{"w":"각 사업연도소득금액=당기순이익 1,500,000원\n+업무무관자산 관리비 700,000원(손금불산입)\n-전기 납부분 법인세환급액 500,000원(익금불산입)\n-법인세환급금이자 10,000원(익금불산입)\n-기부금 한도초과이월액 중 당기 손금산입액 100,000원\n연지급수입이자는 손금으로 인정하고, 고가매입 토지의 시가초과 상당액은 손금불산입과 자산 감액이 상쇄되어 소득금액에 영향이 없다. 이월결손금은 과세표준 계산 단계에서 공제한다.\n=1,590,000원.","c":"상","v":1},"공인회2021_56-19":{"w":"㈜B의 무상주 중 10%를 수령했다. 의제배당 대상과 제외 항목을 가른다.\n자기주식처분이익 2,200,000원 전입분: 의제배당 대상 → 220,000원.\n주식의 포괄적 교환차익 2,000,000원: 자본전입해도 의제배당이 아니다.\n재평가적립금: 전입액 1,500,000원은 토지분(재평가세 1%, 4,000,000원의 30%=1,200,000원)과 건물분(3% 적용, 1,000,000원의 30%=300,000원)으로 구성. 의제배당은 토지분 1,200,000원 × 10% = 120,000원.\n의제배당=220,000+120,000=340,000원 → 익금산입 340,000원. 수입배당금 익금불산입 30%=102,000원.\n순영향=340,000-102,000=238,000원.","c":"중","v":1},"공인회2021_56-21":{"w":"분류: 이재민 구호금품 3,000,000원은 특례기부금. 무료 아동복지시설 기부금 2,000,000원은 일반기부금.\n공익법인에 저가 양도한 토지: 정상가액(시가의 70%=56,000,000원)과 양도가액 50,000,000원의 차액 6,000,000원이 일반기부금.\n기준소득금액=차가감소득금액(5,000,000+10,000,000-12,000,000=3,000,000)+기부금 합계(3,000,000+2,000,000+6,000,000)=14,000,000원.\n이월결손금은 소득의 60% 한도 8,400,000원만 공제할 수 있다.\n특례기부금 한도=(14,000,000-8,400,000)×50%=2,800,000원 → 3,000,000원 중 200,000원 초과.\n일반기부금 한도=(14,000,000-8,400,000-2,800,000)×10%=280,000원. 일반기부금 해당액 8,000,000원 → 한도초과 7,720,000원.","c":"중","v":1},"공인회2021_56-23":{"w":"(1) 제품: 평가방법을 변경신고 없이 바꾼 경우 신고한 방법(선입선출법)과 실제 평가액 중 큰 금액으로 본다. 3,200,000-3,000,000=200,000원 익금산입(유보).\n(2) 재공품: 신고된 방법으로 평가했으나 계산착오로 과소계상한 300,000원을 익금산입(유보).\n(3) 원재료: 무신고이므로 선입선출법(4,500,000원)으로 평가. 4,500,000-4,250,000=250,000원 익금산입(유보). 전기 평가감 유보 100,000원은 추인(손금산입).\n순영향=200,000+300,000+250,000-100,000=650,000원.","c":"중","v":1},"공인회2021_56-25":{"w":"세무상 퇴직급여충당금 기말잔액: 기초 50,000,000-부인액 48,000,000=2,000,000원, 합병 승계분 30,000,000-부인액 29,000,000=1,000,000원 → 3,000,000원. 퇴직연금운용자산에서 지급한 20,000,000원은 세무상 퇴직연금충당금에서 먼저 줄어들므로 장부의 퇴직급여충당금 감소분은 손금산입(부인액 추인) 20,000,000원, 퇴직연금충당금 감소분은 손금불산입 20,000,000원으로 서로 상쇄된다.\n퇴직연금충당금 한도=min[추계액 66,000,000-세무상 퇴직급여충당금 3,000,000=63,000,000원, 운용자산 잔액 60,000,000원]=60,000,000원.\n세무상 퇴직연금충당금: 기초 30,000,000-지급 20,000,000=10,000,000원 → 한도까지 손금산입 50,000,000원(△유보).\n순영향=-50,000,000원.","c":"상","v":1},"공인회2021_56-26":{"w":"건물: 영업외수익으로 처리한 국고보조금 50,000,000원만큼 일시상각충당금 손금산입(△유보) 50,000,000원. 당기 감가상각비 10,000,000원×50,000,000/100,000,000=5,000,000원 환입 → 익금산입 5,000,000원.\n기계장치: 장부에서 보조금 20,000,000원을 자산에서 차감했으므로 세무상으로는 국고보조금 익금산입 20,000,000원(유보)과 일시상각충당금 손금산입 20,000,000원(△유보)이 같이 생긴다. 감가상각비와 상계한 보조금 상당액 20,000,000/5×9/12=3,000,000원은 국고보조금 유보 감소(손금산입)와 일시상각충당금 환입(익금산입)으로 다시 상쇄되어 순영향은 0이다.\n순영향=-50,000,000+5,000,000=-45,000,000원.","c":"상","v":1},"공인회2021_56-27":{"w":"토지: 특수관계인으로부터 고가로 취득한 부분(10,000,000원)은 취득 연도(전기)에 이미 조정했으므로 당기 영향이 없다.\n가지급금: 업무와 무관한 특수관계인 대여금 20,000,000원에 인정이자를 익금산입한다. 금전대차거래의 시가를 신고하지 않았으므로 가중평균차입이자율을 적용: (10,000,000+30,000,000)/(200,000,000+300,000,000)=8%.\n인정이자=20,000,000×8%=1,600,000원(익금산입, 당좌대출이자율 9%는 선택 신고 때만 적용).\n순영향=+1,600,000원.","c":"중","v":1},"공인회2021_56-29":{"w":"산출세액=20,000,000+(260,000,000-200,000,000)×20%=32,000,000원.\n외국납부세액(직접 262,500원+간접 500,000원=762,500원)은 한도까지 공제. 한도=산출세액×국외원천소득/과세표준=32,000,000×(배당 2,000,000+262,500+500,000=2,762,500)/260,000,000≈340,000원.\n최저한세=(260,000,000+20,000,000)×7%=19,600,000원이므로 산출세액 32,000,000원이 더 커서 영향이 없다.\n차감납부세액=32,000,000-340,000=31,660,000원.","c":"상","v":1},"공인회2021_56-31":{"w":"㈜A: 과세·면세 공통사용 재화의 공급가액은 직전 과세기간(2020년 제2기) 과세공급가액 비율 50%로 안분한다. 차량 20,000,000×50%=10,000,000원. 비품은 공급가액이 50만원 미만이라 안분하지 않고 400,000원 전액이 과세표준(부가가치세법 시행령 제63조).\n㈜B: 실지거래가액으로 구분한 건물가액 200,000,000원은 기준시가로 안분한 건물가액 500,000,000×240,000,000/400,000,000=300,000,000원과 30% 이상 차이가 나므로 기준시가 안분액 300,000,000원을 건물 공급가액으로 한다. 토지는 면세.\n합계=10,000,000+400,000+300,000,000=310,400,000원.","c":"상","v":1},"공인회2021_56-32":{"w":"1) 자기적립 마일리지가 아닌 제3자 마일리지로 결제받고 그 부분을 보전받지 않은 채 자기생산·취득재화를 공급하면 공급가액은 그 재화의 시가다(부가가치세법 시행령 제61조제2항제10호가목). 재화A의 공급가액은 1,000,000원이므로 700,000원이라는 설명이 옳지 않다.\n2) 금전 외의 대가를 받으면 자기가 공급한 재화의 시가 1,000,000원. O\n3) 공급시기 후에 외화를 받으면 공급시기의 기준환율 1,100원×1,000달러=1,100,000원. O\n4) 판매장려금은 공급가액에서 빼지 않는다. O\n5) 매출에누리는 공급가액에 포함하지 않으므로 900,000원. O","c":"상","v":1},"공인회2021_56-33":{"w":"㈜A의 받을어음은 부도발생일(2021.1.20)부터 6개월이 지난 2021.7.20이 대손확정일이다. 이 날이 속하는 2021년 제2기 확정신고에서 대손세액 1,000,000원을 공제하므로 1)(제1기)과 2)(예정신고)는 틀리다.\n회수한 5,500,000원(부가가치세 포함)은 매출세액에 500,000원(5,500,000×10/110)을 가산한다. 과세표준에 5,000,000원을 더한다는 3)은 표현이 틀리다.\n㈜B는 대손처분받은 세액을 매입세액에서 빼는 시기가 2021년 제2기 확정신고이므로 4)는 틀리다.\n㈜B가 변제한 5,500,000원 중 500,000원(5,500,000×10/110)은 변제한 날(2022.3.10)이 속하는 2022년 제1기 확정신고에서 매입세액에 더한다. 5) O","c":"상","v":1},"공인회2021_56-34":{"w":"과세사업분 매입세액 50,000,000+10,000,000=60,000,000원 공제, 면세사업분 불공제.\n비품(공통): 같은 과세기간에 사서 그 과세기간에 매각했으므로 매입세액도 직전 과세기간(2020년 제2기) 공급가액 비율 70%로 안분 → 2,000,000×70%=1,400,000원.\n기계장치(공통): 2021년 제1기 비율 80% → 10,000,000×80%=8,000,000원.\n트럭(면세→과세·면세 공통 전환): 매입세액 4,000,000원×(1-25%×경과 과세기간 3)×2021년 제1기 과세비율 80%=800,000원.\n합계=60,000,000+1,400,000+8,000,000+800,000=70,200,000원.","c":"상","v":1},"공인회2021_56-35":{"w":"의제매입세액 공제 대상 매입가액:\n돼지고기(면세 축산물): 26,000,000×(제조에 사용 60%+재고 10%)=18,200,000원. 그대로 판매한 30%는 제외.\n밀가루(수입 면세): 관세 과세가격 20,800,000원만 대상(관세 제외).\n소금: 매입운임 520,000원을 뺀 10,400,000원.\n치즈(가공식품, 과세 재화)와 김치(제조에 사용하지 않음)는 제외.\n합계=18,200,000+20,800,000+10,400,000=49,400,000원. 공제액=49,400,000×4/104=1,900,000원.","c":"상","v":1},"공인회2021_56-39":{"w":"회사채(상장 채권): 상속개시일 이전 2개월 최종시세가액 평균 1,300,000,000원과 최근일 최종시세가액 1,200,000,000원 중 큰 1,300,000,000원. 상속재산=1,300,000,000+2,500,000,000=3,800,000,000원.\n장례비용: 증빙 없는 일반 장례비는 최소 5,000,000원, 봉안시설 사용료 9,000,000원은 한도 5,000,000원 → 10,000,000원. 과세가액=3,790,000,000원.\n공제: 일괄공제 5억원(기초공제 2억원+자녀공제 5천만원보다 크다), 배우자상속공제 5억원(분할신고가 없어 최소액), 동거주택상속공제 min(2,500,000,000×100%, 6억원)=6억원, 금융재산상속공제 min(1,300,000,000×20%, 2억원)=2억원 → 18억원.\n과세표준=3,790,000,000-1,800,000,000=1,990,000,000원.","c":"상","v":1},"공인회2021_56-40":{"w":"1) 자동차의 취득세 납세지는 자동차관리법상 등록지가 아니라 사용본거지다. 등록지가 납세지라는 설명이 옳지 않다.\n2) 선박 등기 등록면허세는 선적항 소재지. O  3) 수입판매업자가 반출한 담배소비세는 판매된 소매인의 영업장 소재지. O  4) 주민세 사업소분은 사업소 소재지. O  5) 주택 재산세는 주택 소재지. O","c":"상","v":1},"공인회2022_57-08":{"w":"(1) 환매조건부채권 매매차익 5,000,000원: 이자소득.\n(2) 저축성보험(계약기간 4년, 10년 미만): 보험차익=(보험금 10,000,000+계약 중 받은 배당금 1,000,000)-납입보험료 8,000,000=3,000,000원.\n(3) 비영업대금의 이익 2,000,000원: 이자소득.\n(4) 위약에 따른 손해배상금 법정이자 500,000원은 기타소득.\n(5) 공익신탁의 이익은 비과세.\n합계=5,000,000+3,000,000+2,000,000=10,000,000원.","c":"중","v":1},"공인회2022_57-09":{"w":"원천징수 대상 기타소득만 고른다.\n(1) 계약금이 위약금으로 대체된 위약금은 원천징수 대상에서 제외된다(소득세법 제127조제1항제6호나목).\n(2) 일시적 강연료 3,000,000원: 필요경비 60% 의제 → 1,200,000원.\n(3) 배임수재 금품은 원천징수하지 않는다.\n(4) 상표권 대여 대가 1,000,000원: 60% 의제 → 400,000원.\n(5) 주택입주 지체상금 2,000,000원: 80% 의제 → 400,000원.\n(6) 슬롯머신 당첨금품 1,500,000원: 건당 200만원 이하라 과세최저한으로 과세하지 않는다.\n합계=1,200,000+400,000+400,000=2,000,000원.","c":"상","v":1},"공인회2022_57-10":{"w":"총급여=기본급·상여 65,000,000원+회사가 대신 부담한 국민연금보험료 3,000,000원=68,000,000원(여비 실비는 비과세).\n근로소득공제=12,000,000+(68,000,000-45,000,000)×5%=13,150,000원 → 근로소득금액 54,850,000원.\n인적공제: 본인, 배우자(예금이자 10,000,000원은 분리과세되어 소득금액 0), 아들(장애인) → 기본공제 4,500,000원+장애인공제 2,000,000원=6,500,000원.\n보험료공제: 국민연금 3,000,000+건강보험 4,000,000=7,000,000원.\n과세표준=54,850,000-6,500,000-7,000,000=41,350,000원.","c":"상","v":1},"공인회2022_57-12":{"w":"2002.1.1 이후 납입분에 대응하는 과세 연금=45,000,000×380,000,000/(100,000,000+380,000,000)=35,625,000원. 이후 납입분은 전액 소득공제를 받았으므로 과세제외기여금은 없다.\n연금소득공제=6,300,000+(35,625,000-14,000,000)×10%=8,462,500원.\n연금소득금액=35,625,000-8,462,500=27,162,500원.","c":"상","v":1},"공인회2022_57-13":{"w":"총급여 120,000,000원의 3% = 3,600,000원.\n의료비: 본인 안경 600,000원은 1인당 연 500,000원 한도 → 500,000원. 부친(70세) 수술·입원비 9,000,000-보험금 5,000,000=4,000,000원. 한도 없는 대상 합계 4,500,000원.\n그 밖의 부양가족(한도 700만원): 배우자 건강진단비 2,000,000원, 모친 보청기 1,500,000원(건강증진용 보약은 제외) → 3,500,000원.\n난임시술비 10,000,000원은 30% 공제율.\n일반 의료비 합계 8,000,000원에서 3,600,000원을 빼면 4,400,000원×15%=660,000원. 난임시술비 10,000,000원×30%=3,000,000원.\n의료비 세액공제=3,660,000원.","c":"중","v":1},"공인회2022_57-15":{"w":"취득가액·매매사례가액·감정가액을 모르므로 환산취득가액=500,000,000×100,000,000/400,000,000=125,000,000원.\n환산취득가액을 쓰면 필요경비는 ① 환산취득가액+개산공제(100,000,000×3%=3,000,000원)=128,000,000원과 ② 자본적지출 120,000,000+양도비 10,000,000=130,000,000원 중 큰 금액을 적용한다(소득세법 제97조제2항). → 130,000,000원.\n양도차익=500,000,000-130,000,000=370,000,000원.","c":"상","v":1},"공인회2022_57-17":{"w":"4) 추계로 과세표준을 결정하면서 대표자 상여로 처분되어 발생한 소득세를 법인이 대납한 금액을 비용으로 계상한 경우, 손금불산입하고 기타사외유출로 처분한다. 소득의 귀속자(대표자)에게 추가 납세의무가 생기지 않는다.\n1) 임원 퇴직금 초과분은 상여, 2) 채권자 불분명 사채이자(원천징수분 제외)는 대표자 상여, 3) 개인주주의 건물 임차료는 배당, 5) 임원 상여금 한도초과액은 상여로 처분되어 귀속자에게 소득세가 과세된다.","c":"상","v":1},"공인회2022_57-18":{"w":"보유 주식: 유상취득 10,000주(1주 14,000원, 140,000,000원), 주식발행초과금 전입 무상주 6,000주(의제배당 아님, 취득가액 0), 자기주식소각이익 전입 무상주 2,000주(소각 당시 시가가 취득가액을 넘었으므로 의제배당, 취득가액은 액면 5,000원씩 10,000,000원).\n의제배당이 아닌 무상주 6,000주는 감자일(2022.9.1) 전 2년 안에 받았으므로 먼저 소각한 것으로 보고 취득가액은 0이다(법인세법 시행령 제14조제3항).\n나머지 4,000주는 남은 12,000주의 평균단가 (140,000,000+10,000,000)/12,000=12,500원 → 50,000,000원.\n의제배당=10,000주×18,000원-50,000,000원=130,000,000원.","c":"상","v":1},"공인회2022_57-19":{"w":"㈜C(45%)는 주식 취득일(2021.11.30)이 배당기준일(2021.12.31) 전 3개월 이내라 익금불산입 대상에서 제외한다.\n㈜B(70%, 익금불산입률 90%): 35,000,000×90%=31,500,000원.\n차입금 이자 차감: 50,000,000×(350,000,000/5,000,000,000)×90%=3,150,000원.\n익금불산입액=31,500,000-3,150,000=28,350,000원.","c":"중","v":1},"공인회2022_57-20":{"w":"신고한 평가방법(매매기준율)에 따라 외화자산·부채를 평가하고 결산서에 반영하지 않은 부분은 세무조정으로 반영한다.\n외화차입금 $10,000: 제21기말 평가손실=(1,300-1,250)×10,000=500,000원은 제21기에 손금산입(△유보). 제22기 상환 시 세무상 상환 손익을 다시 계산하면 외환차익이 회사 계상 500,000원보다 500,000원 더 커서 제22기에 유보를 추인(익금산입 +500,000).\n외화예금 $20,000: 기말 평가이익=(1,320-1,280)×20,000=800,000원 익금산입(+800,000, 유보).\n순영향=500,000+800,000=1,300,000원.","c":"중","v":1},"공인회2022_57-21":{"w":"창업중소기업 세액감면을 받는 법인은 감가상각의제 규정에 따라 상각범위액만큼 감가상각한 것으로 본다(결산에 덜 계상하면 신고조정으로 손금산입). 신고하지 않았으므로 기계장치는 정률법 0.259.\n제2기(2021.7.1~12.31, 6개월): 상각범위액 500,000,000×0.259×6/12=64,750,000원. 장부 감가상각비는 75,000,000-50,000,000=25,000,000원이므로 39,750,000원 손금산입. 기말 세무상 미상각잔액 435,250,000원.\n제3기 자본적 지출 22,000,000원은 전기말 장부가액 475,000,000원의 5%(23,750,000원) 미만이라 즉시상각의제가 아니고 수선비로 손금 인정된다.\n제3기 상각범위액=435,250,000×0.259=112,729,750원(장부 50,000,000원, 나머지 62,729,750원 손금산입).\n제3기말 세무상 미상각잔액=435,250,000-112,729,750=322,520,250원.","c":"상","v":1},"공인회2022_57-23":{"w":"수입금액 한도: 일반 12,000,000,000원: 30,000,000+2,000,000,000×0.2%=34,000,000원. 특수관계인 3,000,000,000원: (120억~150억 구간 3,000,000,000×0.2%=6,000,000원)의 10%=600,000원. 기본한도 36,000,000원. 일반 한도=36,000,000+34,000,000+600,000=70,600,000원.\n문화기업업무추진비(체육활동 관람 입장권 20,000,000원)는 일반 한도의 20%(14,120,000원) 안에서 별도 한도로 인정. 총 한도=70,600,000+14,120,000=84,720,000원.\n해당액: 90,000,000원에서 전기 귀속 접대분 5,000,000원을 빼고, 접대 목적 증정 제품의 시가·부가세 합계 11,000,000원에서 이미 계상한 9,000,000원을 뺀 2,000,000원을 더하면 87,000,000원(직원이 조직한 법인 단체에 낸 복리시설비 4,000,000원도 기업업무추진비 해당액으로 포함).\n한도초과액=87,000,000-84,720,000=2,280,000원.","c":"중","v":1},"공인회2022_57-24":{"w":"대손금 부인: 대여금(업무무관가지급금) 8,000,000원 → 손금불산입. 외상매출금 중 요건 불충족 20,000,000원 → 손금불산입. 합계 +28,000,000원.\n전기 유보 추인: 대손충당금 한도초과액 6,000,000원 손금산입, 소멸시효가 완성된 외상매출금 10,000,000원 손금산입 → -16,000,000원.\n한도: 대손실적률=(당기 인정 대손금 20,000,000+소멸시효 완성 10,000,000)/전기말 채권 2,000,000,000=1.5%. 한도=2,500,000,000×1.5%=37,500,000원. 한도초과=50,000,000-37,500,000=12,500,000원.\n순영향=28,000,000-16,000,000+12,500,000=24,500,000원.","c":"중","v":1},"공인회2022_57-25":{"w":"사택 임대: 임대료 시가 불분명 시 (사택 시가×50%-보증금)×정기예금이자율=(400,000,000×50%-100,000,000)×3%=3,000,000원. 수령 2,000,000원과의 차액 1,000,000원이 시가의 5% 이상(33%)이므로 부당행위로 부인 → 익금산입 +1,000,000원.\n건설용역: 시가가 불분명하면 유사용역 매출액/매출원가 비율로 시가를 구한다. 시가=200,000,000×500,000,000/400,000,000=250,000,000원. 받은 대가 240,000,000원과의 차이 10,000,000원은 시가의 4%로 5% 미만이므로 부인하지 않는다.\n순영향=+1,000,000원.","c":"중","v":1},"공인회2022_57-26":{"w":"간접외국납부세액: 지분율 40%(25% 이상)이고 6개월 이상 보유했으므로 대상. 외국자회사 법인세액 20,000,000×배당 100,000,000/(소득금액 270,000,000-법인세 20,000,000)=8,000,000원. 직접외국납부세액 10,000,000원. 합계 18,000,000원.\n국외원천소득=배당 100,000,000+간접외국납부세액 8,000,000=108,000,000원. 과세표준=국내 292,000,000+108,000,000=400,000,000원. 산출세액=20,000,000+200,000,000×20%=60,000,000원.\n공제한도=60,000,000×108,000,000/400,000,000=16,200,000원 (외국납부세액 18,000,000원보다 작다).\n공제액=16,200,000원.","c":"상","v":1},"공인회2022_57-32":{"w":"(1) 대금을 8개월에 나눠 받는 약정이라 장기할부(인도일 다음 날부터 최종 지급기일까지 1년 이상)가 아니다. 인도일(1.5) 전액 50,000,000원이 공급가액.\n(2) 판매목적 직매장 반출은 재화의 공급으로 본다. 취득가액에 일정액을 가산하는 규정이 없으면 취득가액이나 문제에서는 반출가액 12,000,000원으로 계산.\n(3) 인도(4.8) 전이라도 세금계산서를 발급한 날(3.27)부터 7일 이내에 대금을 받았으므로 발급일(3.27)이 공급시기: 3,000,000원.\n합계=50,000,000+12,000,000+3,000,000=65,000,000원.","c":"중","v":1},"공인회2022_57-34":{"w":"건물 주택 면적(30㎡)이 상가 면적(30㎡)보다 크지 않으므로 주택 부분만 면세다. 부수토지 750㎡는 건물 면적 비율로 나누어 주택분 375㎡, 상가분 375㎡. 주택 부수토지 면세 한도는 주택 정착면적 30㎡×5배(도시지역)=150㎡라 갑 임대분 토지 중 225㎡는 과세된다.\n확정신고기간(4.1~6.30, 91일) 임차인별 임대료 등:\n을(상가) 2,000,000×3+간주임대료 43,800,000×1.5%×91/365=6,163,800원 → 건물·토지 모두 과세.\n갑(주택) 1,000,000×3+21,900,000×1.5%×91/365=3,081,900원 → 기준시가 비율로 토지분 4/5=2,465,520원, 그중 과세 토지 225/375=1,479,312원.\n과세표준=6,163,800+1,479,312=7,643,112원.","c":"상","v":1},"공인회2022_57-35":{"w":"감가상각자산(건물)을 공통으로 사용하는 경우 면세비율이 5%p 이상 증감하면 납부세액을 재계산한다.\n취득한 2021년 제1기 면세비율 40%에서 2022년 제1기 50%로 10%p 증가(제2기 44%는 4%p라 대상이 아님).\n재계산 세액=매입세액 30,000,000×(1-5%×경과된 과세기간 수 2)×10%=2,700,000원을 납부세액에 가산한다.","c":"상","v":1},"공인회2022_57-36":{"w":"㉠ 간이과세자(2021.7.1 이후 제도): 납부세액=공급대가 63,800,000×부가가치율 15%×10%=957,000원.\n공제: 세금계산서 수취분 매입세액공제=매입 공급대가(11,000,000+41,800,000)×0.5%=264,000원, 신용카드매출전표 발행세액공제=55,000,000×1.3%=715,000원. 간이과세자는 의제매입세액공제를 받을 수 없다.\n공제 합계 979,000원이 납부세액을 넘지만 간이과세자는 환급이 없으므로 차가감납부세액 0원.\n㉡ 일반과세자: 매출세액=63,800,000×10/110=5,800,000원, 매입세액=(11,000,000+41,800,000)×10/110=4,800,000원, 의제매입세액=5,450,000×9/109=450,000원.\n납부세액=5,800,000-4,800,000-450,000=550,000원.","c":"상","v":1},"공인회2022_57-39":{"w":"생명보험금 505,000,000원: 피상속인이 계약자로서 보험료를 모두 냈으므로 상속재산으로 본다.\n국민연금 반환일시금 100,000,000원은 상속재산에서 제외.\n상속인에게 10년 이내 증여한 토지는 증여 당시 가액 300,000,000원을 가산.\n장례비용 증빙이 없으면 최소 5,000,000원 공제.\n상속세 과세가액=1,500,000,000+505,000,000+300,000,000-5,000,000=2,300,000,000원.","c":"상","v":1},"공인회2022_57-40":{"w":"4) 지방자치단체의 장은 조례로 취득세 세율을 표준세율의 100분의 50 범위에서 가감 조정할 수 있다. 조정할 수 없다는 설명이 옳지 않다.\n1) 지목 변경으로 가액이 증가하면 취득으로 본다. O  2) 외국정부 취득 비과세(상호주의 예외). O  3) 과세표준은 취득 당시의 가액, 연부취득은 연부금액. O  5) 유상취득은 취득한 날부터 60일 이내 신고·납부. O","c":"상","v":1},"공인회2023_58-02":{"w":"ㄱ: 청산인은 분배·인도한 재산가액을 한도로, 그 가액은 분배·인도한 날 현재의 시가. O\nㄴ: 합명회사 재산으로 부족하면 납세의무 성립일 현재 사원이 제2차 납세의무. O\nㄷ: 과점주주의 조세에 대한 법인의 제2차 납세의무는 법인 순자산가액×과점주주 지분비율 한도. O\nㄹ: 사업양수인의 요건(미수금·미지급금 제외 포괄 승계, 양도인과 특수관계 또는 조세회피 목적). O\n모두 옳다.","c":"상","v":1},"공인회2023_58-06":{"w":"ㄱ: 매출할인은 약정에 의한 지급기일(정한 날이 없으면 지급한 날)이 속하는 사업연도의 매출액에서 뺀다. O\nㄴ: 기간경과분 미지급이자를 결산에 손비로 계상하면 그 사업연도 손금이 되지만, 차입일부터 이자지급일이 1년을 넘는 특수관계인과의 거래에서 생긴 이자는 제외된다. 문장은 바로 이 제외 대상을 손금이라고 했다. X\nㄷ: 인도기준으로 회계처리한 장기할부판매를 회수기준으로 신고조정할 수 있는 것은 중소기업뿐이다. X\nㄹ: 장기할부 취득 자산의 현재가치할인차금은 취득가액에 포함하지 않는다. X","c":"상","v":1},"공인회2023_58-07":{"w":"법인세차감전순이익 210,000원에서 조정:\n+누락 매출 300,000원-누락 매출원가 220,000원=+80,000원.\n+선급비용 25,000원(손익귀속시기 미도래, 손금불산입).\n+자기주식처분이익 10,000원(자본잉여금 처리분 익금산입).\n출자전환 채무면제이익 150,000원은 경영정상화계획 이행 약정을 체결한 법인이므로 익금불산입(과세이연).\n각 사업연도 소득금액=210,000+80,000+25,000+10,000-150,000=175,000원.","c":"중","v":1},"공인회2023_58-08":{"w":"한도: 기본한도 12,000,000원+수입금액 150억원 기준 30,000,000+(150억-100억)×0.2%=40,000,000원 → 52,000,000원.\n해당액: 영수증 수취분 중 건당 3만원 초과 500,000원은 증빙 불비로 손금불산입. 나머지: 적격증빙 68,000,000원+3만원 이하 영수증 1,500,000원+복리후생비 중 적격증빙 접대 해당액 5,000,000-사적 사용 1,000,000=4,000,000원 → 73,500,000원.\n한도초과액=73,500,000-52,000,000=21,500,000원.\n손금불산입 합계=증빙 불비 500,000+한도초과 21,500,000+대표이사 사적 사용 1,000,000=23,000,000원.","c":"중","v":1},"공인회2023_58-09":{"w":"신고하지 않았으므로 정률법(0.300).\n제22기: 미상각잔액=장부가액 40,000,000+상각부인누계 5,000,000=45,000,000원, 상각범위 13,500,000원. 회사 계상 12,500,000원 → 시인부족 1,000,000원 추인, 부인누계 4,000,000원.\n제23기: 장부가액=100,000,000-(60,000,000+12,500,000)=27,500,000원, 미상각잔액 27,500,000+4,000,000=31,500,000원, 상각범위 31,500,000×0.3=9,450,000원.\n자본적 지출 1,000,000원은 600만원 미만이라 수선비로 손금 인정되고 즉시상각의제가 아니다.\n손금불산입=15,000,000-9,450,000=5,550,000원.","c":"상","v":1},"공인회2023_58-11":{"w":"보유 5,000주: 구주 2,000주(취득가 9,500원), 이익준비금 전입 무상주 2,500주(의제배당 대상, 액면 5,000원), 주식발행초과금 전입 무상주 500주(의제배당 아님, 취득가액 0).\n소각 주식 수=5,000×20%=1,000주, 대가=1,000×20,000=20,000,000원.\n소각 주식 취득가액: 의제배당이 아닌 무상주 500주(0원)를 먼저 소각한 것으로 보고, 나머지 500주는 구주·이익준비금 무상주의 평균단가 7,000원[(2,000×9,500+2,500×5,000)/4,500]으로 3,500,000원.\n의제배당=20,000,000-3,500,000=16,500,000원.","c":"중","v":1},"공인회2023_58-13":{"w":"변경신고는 변경할 평가방법을 적용하려는 사업연도 종료일 이전 3개월이 되는 날(제23기는 2023.9.30)까지 해야 한다.\n원재료: 10월 20일 신고는 기한을 넘겨 제23기에는 효력이 없으므로 후입선출법 평가는 임의변경이다. 선입선출법 250,000원과 당초 신고한 총평균법 200,000원 중 큰 250,000원으로 평가한다. 장부 150,000원 → 익금산입 100,000원(유보).\n재공품: 변경신고 없이 후입선출법으로 평가한 임의변경이다. 선입선출법 370,000원과 총평균법 360,000원 중 큰 370,000원. 장부 350,000원 → 익금산입 20,000원(유보).\n제품: 신고한 총평균법으로 평가했으나 계산착오로 과대계상한 경우는 신고방법 평가액 200,000원으로 고친다. 장부 250,000원 → 손금산입 50,000원(△유보).\n익금산입 합계 120,000원(유보), 손금산입 50,000원(△유보).","c":"상","v":1},"공인회2023_58-14":{"w":"인정이자: 시가를 신고하지 않았으므로 가중평균차입이자율을 적용한다. (48,000,000+90,000,000)/(600,000,000+900,000,000)=9.2%.\n갑(무이자) 30,000,000×9.2%=2,760,000원 익금산입. 을은 시가 40,000,000×9.2%=3,680,000원과 약정 이자 3,200,000원의 차액 480,000원이 시가의 5% 이상이므로 익금산입. 인정이자 합계 3,240,000원.\n지급이자 손금불산입: 업무무관가지급금 70,000,000원. 기업구매자금대출 이자는 제외하고, 운영자금대출(차입금 900,000,000원) 이자 90,000,000원 기준: 90,000,000×70,000,000/900,000,000=7,000,000원.\n순영향=3,240,000+7,000,000=10,240,000원.","c":"중","v":1},"공인회2023_58-15":{"w":"세무상 퇴직급여충당금 기초잔액=50,000,000-부인액 20,000,000=30,000,000원.\n갑 퇴직금 30,000,000원(현금 지급, 퇴직급여충당금 상계): 세무상 충당금 30,000,000원과 상계되어 조정 없음. 세무상 기말잔액 0, 장부 기말잔액 10,000,000원은 전액 부인액으로 남는다.\n을 퇴직금 10,000,000원(퇴직연금운용자산에서 지급): 세무상으로는 퇴직연금충당금에서 줄어든다. 장부의 퇴직급여충당금 감소분 손금산입 10,000,000원(부인액 20,000,000원 → 10,000,000원)과 퇴직연금충당금 감소분 손금불산입 10,000,000원(세무상 잔액 40,000,000원 → 30,000,000원)이 상쇄된다.\n퇴직연금충당금 한도=min[추계액 max(90,000,000, 95,000,000)-세무상 퇴직급여충당금 0=95,000,000원, 운용자산 97,000,000원]=95,000,000원.\n손금산입=95,000,000-30,000,000=65,000,000원. 순영향 -65,000,000원.","c":"상","v":1},"공인회2023_58-18":{"w":"재해상실비율=(공장건물 100,000,000+차량 40,000,000+변상책임 있는 타인 자산 100,000,000)/(사업용자산 500,000,000+타인 자산 100,000,000)=240,000,000/600,000,000=40%.\n공제 대상 법인세=산출세액 300,000,000-연구·인력개발비 세액공제 30,000,000+원천징수 등 납부지연가산세 6,000,000=276,000,000원(법인세법 시행령 제95조제3항: 국세기본법 제47조의2~제47조의5 가산세 포함).\n재해손실세액공제=276,000,000×40%=110,400,000원. 한도는 상실된 자산가액 240,000,000원이고 보험금은 한도 계산에 영향이 없다.\n사실과 다른 회계처리로 인한 경정 세액공제: 과다납부세액 40,000,000원의 20%=8,000,000원을 해당 사업연도에 공제하고 남은 금액은 다음 사업연도로 넘긴다.\n합계=110,400,000+8,000,000=118,400,000원.","c":"상","v":1},"공인회2023_58-20":{"w":"직장공제회 초과반환금 1,000,000원과 법원보증금 이자 2,000,000원은 무조건 분리과세라 빠진다.\n출자공동사업자 배당 6,000,000원은 무조건 종합과세지만 2,000만원 기준 판정과 Gross-up에서 제외된다.\n기준 판정 대상: 이익준비금 자본전입 무상주 10,000,000원+상장법인 현금배당 7,000,000원+법인으로 보는 단체의 배당 8,000,000원=25,000,000원 > 20,000,000원 → 종합과세.\n2,000만원은 Gross-up 대상이 아닌 소득부터 채우고 남은 부분을 Gross-up 대상 배당이 채운다. 어느 순서로 채워도 2,000만원 초과분 5,000,000원은 Gross-up 대상 배당이므로 5,000,000×11%=550,000원 가산.\n종합과세 금융소득금액=25,000,000+6,000,000+550,000=31,550,000원.","c":"상","v":1},"공인회2023_58-22":{"w":"총급여=급여 21,600,000원\n+식사대 3,000,000원(식사를 따로 제공받아 비과세 아님)\n+주택구입자금 무상대여 이익 2,400,000원(중소기업 종업원이 아니어서 과세)\n+휴일근로수당 2,000,000원(생산직이 아니어서 과세)\n+학자금 8,000,000원(자녀 학자금은 과세)\n잉여금처분 상여금은 결의일(2022.11.25)이 속하는 2022년 귀속이고, 직무발명보상금 2,000,000원은 2023년 비과세 한도(연 500만원) 이내다.\n합계=37,000,000원.","c":"상","v":1},"공인회2023_58-24":{"w":"취득가액을 알 수 없고 매매사례가액·감정가액도 없어 환산취득가액을 쓴다. 환산취득가액=800,000,000×420,000,000/600,000,000=560,000,000원.\n필요경비 개산공제=취득 당시 기준시가 420,000,000×3%=12,600,000원. 양도차익=800,000,000-560,000,000-12,600,000=227,400,000원.\n장기보유특별공제(12%)=27,288,000원. 양도소득금액=227,400,000×88%=200,112,000원.","c":"하","v":1},"공인회2023_58-25":{"w":"기본공제 150만원: 본인, 배우자(예금이자 2,000,000원은 분리과세되어 소득금액 0), 모친(농어촌 전통주 제조소득은 연 1,200만원 이하 비과세), 아들(20세), 딸 → 5명=7,500,000원.\n추가공제: 경로우대(모친 78세) 1,000,000원, 장애인(딸) 2,000,000원 → 인적공제 합계 10,500,000원.\n특별소득공제: 건강·노인장기요양·고용보험료 2,500,000원, 주택임차차입금 원리금 상환액 5,000,000×40%=2,000,000원 → 4,500,000원.\n합계=10,500,000+4,500,000=15,000,000원.","c":"상","v":1},"공인회2023_58-28":{"w":"공익사업과 관련 없는 지역권 대여 대가는 사업소득(부동산임대업)이다.\n복권당첨금은 무조건 분리과세다.\n상속받은 저작권의 양도 대가: 저작자 외의 자가 받는 대가라 기타소득. 실제 필요경비 8,000,000원 → 2,000,000원.\n공익법인 시상 상금 4,000,000원: 80% 의제 → 800,000원.\n퇴직 후 받은 직무발명보상금 3,000,000원: 2023년 비과세 한도(연 500만원) 이내.\n일시적 외부특강료 2,000,000원: 60% 의제 → 800,000원.\n합계 3,600,000원으로 300만원을 넘으므로 분리과세를 선택할 수 없고 전액 종합과세된다.","c":"상","v":1},"공인회2023_58-29":{"w":"2022년: 금융소득(이자 5,000,000+배당 3,000,000)은 2,000만원 이하라 분리과세되어 종합소득에 없다. 부동산임대업 이외 사업 결손금 30,000,000원을 근로 15,000,000 → 연금 6,000,000 → 기타 4,000,000원 순으로 공제하고 5,000,000원이 이월된다. 부동산임대업 결손금 10,000,000원은 부동산임대업 소득에서만 공제할 수 있어 이월된다.\n2023년: 금융소득 41,500,000원은 종합과세. 당기 결손금을 먼저 공제한다. 부동산임대업 이외 결손금 35,000,000원 → 부동산임대업 소득 15,000,000원과 통산(-20,000,000원) → 근로 5,000,000 → 연금 6,000,000 → 이자 9,000,000원 공제, 이자소득금액 16,000,000원 남음.\n이월결손금: 일반 사업 이월결손금 5,000,000원을 이자소득금액에서 공제 → 11,000,000원. 부동산임대업 이월결손금은 공제할 부동산임대업 소득이 남지 않아 다시 이월된다.\n종합소득금액=이자 11,000,000+배당 16,500,000=27,500,000원.","c":"상","v":1},"공인회2023_58-32":{"w":"ㄱ: 상시주거용(사업을 위한 주거용 제외) 건물의 임대용역은 면세. O\nㄴ: 도서·신문·잡지·관보·뉴스통신·방송은 면세지만 광고는 면세 대상에서 빠진다. X\nㄷ: 은행업 관련 전산시스템과 소프트웨어의 판매·대여는 금융용역이 아니어서 과세. X\nㄹ: 공익사업을 위해 주무관청의 승인을 받아 금품을 모집하는 단체에 무상으로 공급하는 재화·용역만 면세. 유상 공급은 과세. X\nㅁ: 수입신고 수리 전에 변질된 물품은 관세가 경감되는 비율만큼 부가가치세를 면제한다. O","c":"상","v":1},"공인회2023_58-33":{"w":"원재료: 착오로 공급가액을 10,000만원 초과 기재했어도 기재 사항으로 거래사실이 확인되면 실제 공급가액 100,000,000원의 매입세액 10,000,000원 공제.\n접대용 물품 1,000,000원은 불공제. 생산직 작업복 매입세액 2,000,000원 공제.\n토지와 건물을 함께 구입한 뒤 토지만 사용하려고 건물을 철거한 경우 건물 구입비와 철거비용의 매입세액(50,000,000원, 3,000,000원)은 토지 관련이므로 불공제.\n신규 사업 간이과세자는 영수증 발급 대상이라 신용카드 수취분(2,200,000원) 매입세액은 공제하지 않는다.\n공제액=10,000,000+2,000,000=12,000,000원.","c":"상","v":1},"공인회2023_58-34":{"w":"매출세액=600,000,000×10%=60,000,000원. 2022년 제1기에 대손세액공제를 받은 외상매출금의 회수분 4,400,000원은 매출세액에 4,400,000×10/110=400,000원 가산(대여금 3,300,000원은 공급대가가 아니라 대손세액공제 대상이 아님).\n매입세액: 과세재화 200,000,000×10%=20,000,000원. 의제매입세액 54,000,000×8/108=4,000,000원.\n신용카드 발행세액공제는 직전연도 공급가액 합계(500,000,000+700,000,000=12억원)가 10억원을 넘어 적용하지 않는다. 전자신고세액공제 10,000원.\n납부세액=60,000,000+400,000-20,000,000-4,000,000=36,400,000원. 차가감납부세액=36,400,000-10,000-예정고지세액 10,000,000=26,390,000원.","c":"상","v":1},"공인회2023_58-36":{"w":"건물 신축 관련 공통매입세액은 사용면적 비율로 안분한다.\n2023년 제2기 매입세액 20,000,000원: 실제 사용면적 비율(과세 53%)로 20,000,000×53%=10,600,000원 공제.\n2023년 제1기 매입세액 10,000,000원은 예정 사용면적 비율(과세 50%)로 5,000,000원을 공제했으나 실제 비율 53%로 정산하면 5,300,000원이어서 300,000원 추가 공제.\n합계=10,600,000+300,000=10,900,000원.","c":"중","v":1},"공인회2023_58-37":{"w":"간이과세자가 일반과세자로 바뀌면 그날 현재 재고품과 감가상각자산(건물은 취득 후 10년, 그 밖의 자산은 2년 이내)에 대해 재고매입세액을 공제한다. 금액은 장부나 세금계산서로 확인되는 취득가액(공급대가)이고, 간이과세 기간의 체감률은 과세기간(1년)마다 건물 10%, 그 밖의 자산 50%다.\n상품(2023.6.1 취득): 1,100,000×10/110×(1-0.5%×110/10)=94,500원.\n기계장치: 취득가액이 확인되지 않아 대상이 아니다.\n화물자동차(2022.9.1): 경과 과세기간 2(2022·2023년) → 22,000,000×(1-50%×2)=0원.\n건물(2021.3.1, 2021.6.30 이전 취득분이라 종전 산식): 110,000,000×(1-10%×3)×10/110×(1-업종별 부가가치율 20%)=5,600,000원.\n재고매입세액 합계=94,500+5,600,000=5,694,500원.","c":"상","v":1},"공인회2023_58-38":{"w":"증여재산은 평가기간(증여일 전 6개월~후 3개월) 안의 해당 재산 매매·감정·수용 가액 등을 시가로 본다. 유사재산의 매매가액은 해당 재산 자체의 가액이 없을 때만 쓰므로, 토지X 자체의 감정가액 200,000,000원(8.1)이 시가다.\n저당권이 설정된 재산은 시가와 그 저당권으로 담보된 채권액(180,000,000원) 중 큰 금액으로 평가한다(상속세 및 증여세법 제66조). 담보 채권액은 채권최고액 234,000,000원이 아니라 실제 차입금 180,000,000원이다.\n증여재산가액=max(200,000,000, 180,000,000)=200,000,000원.","c":"상","v":1},"공인회2023_58-40":{"w":"(2023 개정 전 기준) 출제 당시 재산세 분할납부 기간은 납부기한이 지난 날부터 2개월 이내였다(2023.12.29 개정으로 3개월).\n4) 지방자치단체가 1년 이상 공용·공공용으로 쓰더라도 소유권의 유상이전을 약정하고 취득 전에 미리 사용하는 재산은 재산세를 부과한다. 옳지 않다.\n1) 지적공부 등록대상 토지와 사실상의 토지가 과세대상. O\n2) 소유권 귀속이 불분명해 사실상 소유자를 확인할 수 없으면 사용자가 납세의무자. O\n3) 1세대 1주택 판단 시 신탁된 주택은 위탁자의 주택 수에 넣는다. O\n5) 납부세액 250만원 초과 시 2개월 이내 분할납부(당시). O\n현행으로는 5)의 2개월도 틀린 문장이 되어 옳지 않은 것이 둘이다.","c":"상","v":1,"old":1,"ow":"(2023 개정 전 기준) 출제 당시 재산세 분할납부 기간은 납부기한이 지난 날부터 2개월 이내였다(2023.12.29 개정으로 3개월).\n4) 지방자치단체가 1년 이상 공용·공공용으로 쓰더라도 소유권의 유상이전을 약정하고 취득 전에 미리 사용하는 재산은 재산세를 부과한다. 옳지 않다.\n1) 지적공부 등록대상 토지와 사실상의 토지가 과세대상. O\n2) 소유권 귀속이 불분명해 사실상 소유자를 확인할 수 없으면 사용자가 납세의무자. O\n3) 1세대 1주택 판단 시 신탁된 주택은 위탁자의 주택 수에 넣는다. O\n5) 납부세액 250만원 초과 시 2개월 이내 분할납부(당시). O\n현행으로는 5)의 2개월도 틀린 문장이 되어 옳지 않은 것이 둘이다."},"공인회2024_59-06":{"w":"간주익금=(임대보증금-임대용 건물 건설비 상당액)×정기예금이자율-보증금 운용수익. 주택(부수토지 포함)의 보증금은 제외하고 토지 가액은 건설비 상당액에 넣지 않는다.\n사무실 보증금 50,000,000원, 건설비 상당액=사무실 건물 100,000,000원×임대면적 20%=20,000,000원.\n(50,000,000-20,000,000)×5%=1,500,000원, 사무실 보증금 이자수익 100,000원을 빼면 1,400,000원.\n주택 보증금 200,000,000원과 그 이자수익 200,000원은 계산에서 빠진다.","c":"상","v":1},"공인회2024_59-07":{"w":"㈜B 주식은 2023.10.1에 취득한 10,000주가 배당기준일(2023.12.31) 전 3개월 이내 취득분이어서 제외한다. 처분 5,000주는 먼저 취득한 35,000주에서 처분한 것으로 보아 대상 주식은 30,000주, 출자비율 30%(익금불산입률 80%).\n대상 배당금=20,000,000×30,000/40,000=15,000,000원 → 15,000,000×80%=12,000,000원.\n차입금 이자 차감: (30,000,000-현재가치할인차금 상각액 10,000,000)×(대상 주식 장부가액 600,000,000/자산총액 2,000,000,000)×80%=4,800,000원.\n익금불산입액=12,000,000-4,800,000=7,200,000원.","c":"상","v":1},"공인회2024_59-08":{"w":"ㄱ: 특수관계 유무와 관계없이 파산한 법인의 주식은 사업연도 종료일의 시가(1,000원 이하이면 1,000원)로 감액할 수 있다. 감액할 수 없다는 설명이 옳지 않다. X\nㄴ: 국·공채 매입가액과 현재가치의 차액을 유형자산 취득가액으로 계상하면 취득가액에 포함. O\nㄷ: 「보험업법」에 따라 장부가액을 증액한 평가증은 인정되며 평가일이 속하는 사업연도의 익금. O\nㄹ: 파손·부패한 재고자산은 처분가능한 시가로 감액할 수 있다. O","c":"상","v":1},"공인회2024_59-10":{"w":"ㄱ: 사회복지법인은 이자소득금액(비영업대금 이익 제외)의 100%를 고유목적사업준비금으로 손금산입할 수 있다. O\nㄴ: 보험금을 받은 사업연도에 사용하지 못하고 다음 사업연도 개시일부터 2년 이내에 취득할 계획이면 일시상각충당금을 설정할 수 있다. O\nㄷ: 공사손실충당부채는 법인세법상 손금에 산입하지 않는다. X\nㄹ: 회생계획인가 결정으로 확정된 채권은 그 사유가 발생한 날이 속하는 사업연도의 손금(신고조정). O","c":"상","v":1},"공인회2024_59-11":{"w":"고가매입: 국가로부터 시가 60,000,000원인 토지를 90,000,000원에 샀으므로 정상가액(시가의 130%=78,000,000원) 초과분 12,000,000원이 특례기부금. 자산을 12,000,000원 감액해 손금산입(△유보).\n기준소득금액=차가감소득금액(100,000,000+20,000,000-10,000,000=110,000,000)+기부금 합계(일반 5,000,000+특례 12,000,000)-손금산입 12,000,000=115,000,000원.\n이월결손금: 소득의 80% 한도 92,000,000원 공제.\n특례기부금 한도=(115,000,000-92,000,000)×50%=11,500,000원 → 12,000,000원 중 500,000원 초과.\n일반기부금 한도=(115,000,000-92,000,000-11,500,000)×10%=1,150,000원. 일반기부금 해당액=당기 5,000,000+전기 이월 1,000,000=6,000,000원 → 한도초과 4,850,000원.","c":"중","v":1},"공인회2024_59-14":{"w":"채권자 불분명 사채이자 4,000,000원 손금불산입: 원천징수세액 1,000,000원은 기타사외유출, 나머지 3,000,000원은 대표자상여.\n업무무관 가지급금: 대표이사 대여금(소득세 대납액)은 제외. 직원 갑은 지배주주이므로 주택구입자금 대여액 5,000,000원이 해당. 직원 을(전세자금)과 병(학자금)은 제외 대상.\n운영자금대출 이자 5,000,000원(적수 36,600,000,000원, 평균 차입금 100,000,000원) 중 업무무관 가지급금 5,000,000원 비율: 5,000,000×5,000,000/100,000,000=250,000원(기타사외유출).\n기타사외유출=1,000,000+250,000=1,250,000원.","c":"상","v":1},"공인회2024_59-16":{"w":"토지: 특수관계인으로부터 매입한 토지의 시가가 불분명하면 감정평가액(둘 이상의 평균 (270,000,000+330,000,000)/2=300,000,000원)을 쓴다. 매입가 450,000,000원과의 차이 150,000,000원이 시가의 5% 이상이므로 손금불산입(귀속자 소득처분) 150,000,000원, 토지 감액 손금산입(△유보) 150,000,000원.\n가지급금 인정이자: 대표이사 사업자금 대여 70,000,000원은 갑이 별도 약정 없이 빌려준 10,000,000원과 상계한 60,000,000원 기준: 60,000,000×4.6%=2,760,000원, 수령 2,700,000원, 차이 2%로 5% 미만이라 부인하지 않는다. 전무이사 별장자금 30,000,000원: 1,380,000-700,000=680,000원 익금산입. 회계부장 주택전세자금은 지배주주가 아니라 제외.\n익금산입 합계=150,000,000+680,000=150,680,000원, 손금산입 합계=150,000,000원.","c":"중","v":1},"공인회2024_59-17":{"w":"감가상각비는 정액법·내용연수 5년으로 강제상각한다. 승용차X 50,000,000/5=10,000,000원(회사 계상과 같음), 승용차Y 100,000,000/5=20,000,000원(회사 계상 18,000,000원 → 손금산입 2,000,000원, △유보).\n운행기록이 없으면 승용차별 관련비용 중 15,000,000원까지만 업무사용금액으로 본다.\n승용차X: 관련비용 14,000,000원 전액 업무사용. 업무사용 감가상각비 10,000,000원 중 8,000,000원 초과 2,000,000원 손금불산입(유보).\n승용차Y: 관련비용 20,000,000+5,000,000=25,000,000원, 업무사용비율 15,000,000/25,000,000=60%. 업무 외 10,000,000원 손금불산입(상여). 업무사용 감가상각비 20,000,000×60%=12,000,000원 중 8,000,000원 초과 4,000,000원 손금불산입(유보).\n순영향=-2,000,000+2,000,000+10,000,000+4,000,000=+14,000,000원.","c":"상","v":1},"공인회2024_59-18":{"w":"지분율 30%, 6개월 이상 보유라 간접외국납부세액공제 대상이다.\n수령액 4,500,000원은 10% 원천징수 후 금액이므로 배당금 총액은 5,000,000원, 직접외국납부세액 500,000원(익금산입).\n간접외국납부세액=2,000,000×5,000,000/(10,000,000-2,000,000)=1,250,000원(익금산입).\n국외원천소득=5,000,000+1,250,000=6,250,000원. 과세표준=120,000,000+500,000+1,250,000=121,750,000원, 산출세액=121,750,000×9%=10,957,500원(2024년 2억원 이하 세율 9%).\n한도=10,957,500×6,250,000/121,750,000=562,500원. 외국납부세액 합계 1,750,000원 중 562,500원을 공제한다.","c":"상","v":1},"공인회2024_59-19":{"w":"법인세 부담을 최소화하려면 기준내용연수 20년의 하한(25% 단축)인 15년을 신고한다. 건물은 정액법만 쓸 수 있으므로 상각률 1/15.\n취득가액=350,000,000+취득세 10,000,000=360,000,000원. 사용개시일 2024.9.1부터 4개월 상각.\n상각범위액=360,000,000×1/15×4/12=8,000,000원.\n회사 계상 감가상각비: 감가상각비는 계상하지 않았지만 비용 처리한 취득세 10,000,000원이 즉시상각의제로 감가상각비가 된다.\n상각부인액=10,000,000-8,000,000=2,000,000원 → 익금산입(손금불산입) 2,000,000원(유보).","c":"상","v":1},"공인회2024_59-21":{"w":"(1) 비영업대금: 회수액 35,000,000원은 원금 30,000,000원에 먼저 충당하므로 이자소득은 5,000,000원(원천징수되지 않아 무조건 종합과세).\n(2) 법원 보증금 이자 3,000,000원: 무조건 분리과세. (5) 공익신탁 이익: 비과세.\n(3) 출자공동사업자 배당 9,000,000원: 무조건 종합과세, 2,000만원 판정·Gross-up 대상에서 제외.\n2,000만원 판정 대상: 5,000,000+정기예금 3,000,000+환매조건부 매매차익 7,000,000+비상장법인 배당 12,000,000=27,000,000원 → 종합과세.\nGross-up 대상이 아닌 15,000,000원이 먼저 채우고 비상장법인 배당 중 5,000,000원이 2,000만원까지 들어간다. 초과분 7,000,000원×10%=700,000원 가산.\n금융소득금액=27,000,000+9,000,000+700,000=36,700,000원.","c":"상","v":1},"공인회2024_59-23":{"w":"공동사업장 사업소득금액: 당기순이익 500,000,000원-이자수익 50,000,000원(이자소득으로 따로 분배)-사업용 건물 처분익 10,000,000원(건물은 복식부기의무자라도 양도소득)+갑의 급여 80,000,000원(공동사업자 급여는 필요경비 불산입)=520,000,000원.\n갑의 배우자는 조세회피 목적의 특수관계인 공동사업자라 배우자 몫을 손익분배비율이 큰 갑의 소득금액으로 본다. 갑의 사업소득금액=520,000,000×(50%+30%)=416,000,000원. 동생 몫 20%는 동생에게 귀속된다.\n공동사업장의 이자수익은 손익분배비율대로 각자의 이자소득이 된다. 갑 몫 25,000,000원으로 2,000만원을 넘어 종합과세된다. 이자소득은 부당행위계산 부인 대상 소득이 아니어서 적정이자와의 차이는 조정하지 않는다.\n종합소득금액=416,000,000+25,000,000=441,000,000원.","c":"중","v":1},"공인회2024_59-24":{"w":"직전연도 수입금액이 35,000,000원이지만 당해연도 수입금액이 매출 170,000,000원+국가 보조금 20,000,000원=190,000,000원(기계장치 처분가액 10,000,000원은 복식부기의무자가 아니라 제외)으로 간편장부대상자 기준 150,000,000원을 넘으므로 단순경비율 대상이 아니다.\n기준경비율 방식: 수입금액 190,000,000-주요경비(원재료 30,000,000+임차료 10,000,000+종업원 급여 40,000,000=80,000,000)-수입금액×기준경비율 20%(38,000,000)=72,000,000원. (기계장치 구입비와 보험료는 주요경비가 아니다.)\n단순경비율 방식(배율 2.8): [190,000,000-190,000,000×60%]×2.8=212,800,000원.\n두 금액 중 적은 금액 72,000,000원.","c":"중","v":1},"공인회2024_59-26":{"w":"미등기 양도자산은 장기보유특별공제와 기본공제를 받을 수 없고 세율도 70%로 별도이다. 부동산 그룹 안에서 양도차손(토지 C -100,000,000원)은 동일 세율 자산(40%: 상가 B 62,000,000원)에서 먼저 공제하고 남는 차손 38,000,000원은 다른 세율 자산의 양도소득금액에서 안분해 공제한다.\nD(토지 5년 6개월): 50,000,000-장기보유특별공제 10%=45,000,000원.\n공제 대상 소득금액 합계: 창고건물 A 50,000,000원+D 45,000,000원=95,000,000원. 차손 38,000,000원을 비율로 안분: A는 38,000,000×50/95=20,000,000원 공제 → 30,000,000원.\n창고건물은 미등기라 기본공제를 받을 수 없으므로 과세표준 30,000,000원.","c":"중","v":1},"공인회2024_59-28":{"w":"연금수령연차: 2013.3.1 전에 가입한 연금계좌는 연금수령 개시 연도를 6년차로 보므로 2023년이 6년차, 2024년이 7년차.\n연금수령한도=100,000,000/(11-7)×120%=30,000,000원. 수령액 45,000,000원 중 15,000,000원은 연금외수령이다.\n연금계좌 인출 순서: 과세제외기여금(공제받지 못한 납입액) 3,000,000원 → 이연퇴직소득 10,000,000원 → 공제받은 납입액과 운용수익.\n한도 30,000,000원 안의 연금수령분: 과세제외기여금 3,000,000원(과세 안 함), 이연퇴직소득 10,000,000원(연금소득이지만 분리과세), 나머지 17,000,000원(사적연금소득).\n사적연금 17,000,000원은 1,500만원을 넘어 종합과세와 15% 분리과세 중 선택할 수 있고, 종합과세를 택하면 총연금액은 17,000,000원이다.","c":"상","v":1},"공인회2024_59-29":{"w":"(1) 주택입주 지체상금 3,000,000원: 80% 의제 → 600,000원(원천징수됨).\n(2) 복권당첨금: 무조건 분리과세.\n(3) 일시적 강연료 100,000원: 소득금액 40,000원이 건당 5만원 이하라 과세하지 않는다.\n(4) 계약금이 대체된 위약금 1,000,000원: 원천징수되지 않지만 분리과세기타소득 범위에 포함된다(소득세법 제14조제3항제8호가목 괄호).\n(5) 배임수재 금품 4,000,000원: 분리과세 대상이 아니라 무조건 종합과세.\n분리과세 선택 가능 기타소득금액=600,000+1,000,000=1,600,000원(300만원 이하). 한계세율 24%가 분리과세 세율 20%보다 높으므로 분리과세를 택한다.\n종합과세되는 기타소득금액=4,000,000원.","c":"상","v":1},"공인회2024_59-32":{"w":"ㄱ: 저가항공기 국내 여객운송은 면세 대상(시내버스 등)이 아니라 과세. X\nㄴ: 미가공 다이아몬드 원석은 면세 재화가 아니다. X\nㄷ: 안마사가 제공하는 용역은 의료보건용역으로 면세. O\nㄹ: 기업합병 중개용역은 금융·보험용역에서 제외되어 과세. X\nㅁ: 산후조리원에서 분만 직후 임산부에게 제공하는 급식 용역은 면세. O\nㅂ: 주무관청에 등록된 학원의 교육용역은 면세. O","c":"상","v":1},"공인회2024_59-34":{"w":"면세사업에도 쓰기 시작한 감가상각 재화(건물·기계장치)는 공급으로 의제하되 토지는 제외한다. 과세표준=취득가액×(1-체감률×경과된 과세기간 수)×면세공급가액 비율. 면세공급가액 비율은 해당 과세기간(2024년 제2기) 60,000,000/240,000,000=25%.\n건물: 40,000,000×(1-5%×4)×25%=8,000,000원 (2022년 제2기 취득 후 4개 과세기간 경과).\n기계장치: 10,000,000×(1-25%×2)×25%=1,250,000원.\n합계=9,250,000원.","c":"상","v":1},"공인회2024_59-35":{"w":"미가공 냉동명태(면세농산물) 130,000,000×4/104=5,000,000원 의제매입세액.\n승용차(개별소비세 과세대상)는 불공제.\n포장용기 700,000원의 세금계산서를 같은 과세기간 안에 발급받았으므로 매입세액 70,000원 공제.\n작업복 330,000원(공급대가)의 신용카드매출전표 매입세액 30,000원 공제.\n판매촉진 목적으로 구입해 제공한 물품 500,000원은 접대비 성격으로 보아 불공제.\n공장 임차료 4,000,000원(공급가액)의 매입세액 400,000원 공제.\n합계=5,000,000+70,000+30,000+400,000=5,500,000원.","c":"중","v":1},"공인회2024_59-36":{"w":"건물의 상가 부분(60㎡)이 주택 부분(30㎡)보다 크므로 상가 부분만 과세하고 주택 부분은 면세. 토지는 건물 정착면적(90㎡)의 5배 이내인 300㎡ 전부가 건물 부수토지이고, 과세 비율은 건물과 같은 2/3이다.\n1~3월 임대료 5,000,000×3=15,000,000원의 2/3=10,000,000원. 청소관리비 300,000×3=900,000원(상가분이라 전액).\n간주임대료: 임대보증금 500,000,000×(2/3)×91/366×2.9%≈2,403,460원(부가가치세법상 간주임대료는 이자수익을 차감하지 않는다).\n과세표준=10,000,000+900,000+2,403,460=13,303,460원.","c":"중","v":1},"공인회2024_59-37":{"w":"과세표준: 국내 현금매출 503,000,000(운임 등 부대비용 포함)+외상매출 100,000,000+대표이사 배우자에게 사용하게 한 포장용기 시가 4,000,000+수출 $5,000×선적일 기준환율 1,200원=6,000,000 = 613,000,000원.\n대손세액공제 4,400,000×10/110=400,000원.\n매출세액=(503,000,000+100,000,000+4,000,000)×10%=60,700,000원(수출은 영세율).\n매입세액: 수입 면세농수산물 의제매입 260,000,000(관세 과세가격)×4/104=10,000,000원, 원재료 56,000,000×10%=5,600,000원, 기계장치 100,000,000×10%=10,000,000원 → 25,600,000원.\n납부세액=60,700,000-400,000-25,600,000=34,700,000원.","c":"상","v":1},"공인회2024_59-39":{"w":"순손익가치: 최근 3년 가중평균 1주당 순손익액=(3,200×3+3,000×2+2,400×1)/6=3,000원 → 3,000/10%=30,000원.\n순자산가치=(자산 3,600,000,000-부채 400,000,000)/100,000주=32,000원.\n평가액=(순손익가치×3+순자산가치×2)/5=(90,000+64,000)/5=30,800원 (순자산가치의 80%인 25,600원보다 큼).\n1,000주=30,800,000원.","c":"상","v":1},"공인회2024_59-40":{"w":"4) 법인 설립 시 발행하는 주식을 취득해 과점주주가 된 경우는 간주취득세 대상에서 제외한다. 설립 때 과점주주가 되어도 부동산을 취득한 것으로 보지 않는다. 옳지 않다.\n1) 취득세 과세대상. O  2) 종류 변경·지목 변경으로 가액이 증가하면 취득으로 본다. O  3) 사실상 취득하면 등기·등록하지 않아도 취득으로 본다. O  5) 영업용 차량의 실질 취득자 규정. O","c":"상","v":1},"공인회2025_60-05":{"w":"저당권이 설정된 뒤 재산이 양도된 경우라서 국세기본법 제35조제1항제3호의2가 적용된다. 저당권 채권은 양수인 을의 국세보다 우선하되, 직전 보유자 갑이 저당권 설정 당시 체납하고 있던 국세(설정일보다 법정기일이 빠른 것) 금액의 범위에서는 을의 국세 중 법정기일이 설정일보다 빠른 것을 먼저 징수한다.\n① 종합부동산세 11,500,000원: 그 재산에 부과된 종합부동산세는 제3호의2 채권보다도 우선한다(제35조제3항). 남은 금액 68,500,000원.\n② 을의 소득세: 법정기일(2024.3.10)이 설정일(2024.4.4)보다 빠르지만 우선 징수는 갑의 체납액 35,000,000원(법정기일 2024.1.25, 설정일보다 빠름) 한도까지다. 35,000,000원 징수, 남은 금액 33,500,000원.\n③ A은행 대출금 50,000,000원 중 33,500,000원 회수.\n답 ④ 33,500,000원. 을의 소득세 40,000,000원을 전부 저당권보다 앞세우면 28,500,000원(③)이 나오지만 양도된 재산에는 직전 보유자 체납액 한도가 적용된다.","c":"상","v":1},"공인회2025_60-07":{"w":"의제배당 대상 재원(10% 수령):\n주식발행초과금 중 이익잉여금으로 상환된 상환주식 발행초과금 8,000,000원 → 대상 (나머지 16,000,000원은 제외).\n자기주식처분이익 14,000,000원 → 대상.\n자기주식소각이익 10,000,000원: 소각 당시 시가가 취득가액을 초과하지 않았으므로 2년 이내 자본전입분(60%)=6,000,000원이 대상(2년 경과분은 제외).\n주식의 포괄적 이전차익 5,000,000원 → 제외.\n이익준비금 15,000,000원 → 대상.\n합계=8,000,000+14,000,000+6,000,000+15,000,000=43,000,000원. 10% 수령분=4,300,000원.","c":"상","v":1},"공인회2025_60-08":{"w":"잔여재산가액=환가 금액(재고 60,000,000+건물 150,000,000+토지 300,000,000=510,000,000원)-차입금 상환 150,000,000=360,000,000원.\n자기자본총액: 자본금 100,000,000원 중 2024년 자본잉여금 전입분 20,000,000원은 잉여금으로 보고(납입자본금 80,000,000원), 잉여금=자본잉여금 70,000,000+전입분 20,000,000+이익잉여금 80,000,000=170,000,000원. 세무상 이월결손금 180,000,000원으로 잉여금 전액을 보전하면 잉여금은 0이고 남는 10,000,000원은 자본금과 상계하지 않는다. 자기자본총액=80,000,000원.\n청산소득금액=360,000,000-80,000,000=280,000,000원.","c":"중","v":1},"공인회2025_60-09":{"w":"재해상실비율(토지 제외): 상실가액=재고자산 40,000,000+차량운반구 50,000,000+건물 100,000,000+변상책임 있는 타인 기계장치 30,000,000=220,000,000원, 상실 전 자산총액=50,000,000+120,000,000+200,000,000+30,000,000=400,000,000원 → 55%.\n공제 대상 법인세: 재해발생일 현재 미납 법인세 11,000,000원(장부 기록·보관 불성실 가산세 포함, 시행령 제95조제3항)+당기 산출세액 20,000,000원-다른 법률(조세특례제한법) 세액공제 2,000,000원=29,000,000원. 외국납부세액공제는 법인세법상 공제라 먼저 빼지 않는다.\n공제액=29,000,000×55%=15,950,000원(한도: 상실된 자산가액 220,000,000원).","c":"상","v":1},"공인회2025_60-10":{"w":"수입금액 18,000,000,000원(중단사업 매출 포함) 중 일반 16,000,000,000원, 특수관계인 2,000,000,000원.\n한도: 기본 36,000,000+일반 [10,000,000,000×0.3%=30,000,000+6,000,000,000×0.2%=12,000,000]=42,000,000+특수관계인 (2,000,000,000×0.2%=4,000,000)의 10%=400,000 → 78,400,000원.\n일반 기업업무추진비 해당액=120,000,000-임직원 단합대회 행사비 10,000,000(복리후생)-문화기업업무추진비 6,000,000-전통시장 접대비 9,000,000=95,000,000원 → 한도초과 16,600,000원.\n문화기업업무추진비는 일반 한도의 20%(15,680,000원) 내에서 6,000,000원 전액 인정. 전통시장 접대비는 일반 한도의 10%(7,840,000원) 내에서만 인정되어 1,160,000원 초과.\n한도초과액=16,600,000+1,160,000=17,760,000원.","c":"중","v":1},"공인회2025_60-15":{"w":"차가감소득금액=당기순이익 100,000,000\n+법인세비용 8,000,000(손금불산입)\n+자기주식처분이익 9,000,000(익금산입, 자본잉여금 처리분)\n+대표이사 종친회 비지정기부금 5,000,000(손금불산입)\n-국세 과오납금 환급금이자 2,000,000(익금불산입)\n-정기예금 미수이자 4,000,000(원천징수 대상 이자는 지급받는 날에 익금)\n사업용 공장 재산세는 정상 비용이고, 특례기부금 한도초과액은 차가감소득금액에는 반영하지 않고 별도로 계산한다.\n=116,000,000원.","c":"중","v":1},"공인회2025_60-17":{"w":"(1) 유상증자 액면초과분을 자본금으로 처리한 것은 자본거래 내 계정 구분의 문제로 소득에 영향이 없다. 세무조정 없음.\n(2) 특수관계가 없는 자로부터 무상으로 받은 토지의 자산수증이익 15,000,000원 → 익금산입(유보) +15,000,000.\n(3) 제24기에 익금산입(유보)한 외상매출금 7,000,000원을 제25기에 회수해 수익으로 계상 → 익금불산입(△유보) -7,000,000.\n(4) 재평가이익을 기타포괄손익으로 처리한 것은 소득에 포함되지 않는다.\n순액=15,000,000-7,000,000=+8,000,000원.","c":"상","v":1},"공인회2025_60-18":{"w":"멸실된 기계장치X의 세무상 장부가액=취득가액 100,000,000-(감가상각누계 60,000,000-상각부인액 10,000,000)=50,000,000원.\n보험금 80,000,000원 중 70,000,000원으로 기계장치Y를 취득했으므로 일시상각충당금 설정액=보험금 사용액 70,000,000-멸실 자산 세무상 장부가액 50,000,000=20,000,000원(신고조정 손금산입).\n기계장치Y의 감가상각범위액=70,000,000×0.200×6/12=7,000,000원. 일시상각충당금 환입=20,000,000×7,000,000/70,000,000=2,000,000원(익금산입).\n기말 △유보 잔액=20,000,000-2,000,000=18,000,000원.","c":"중","v":1},"공인회2025_60-19":{"w":"건물: 내용연수를 10년으로 변경한 정액법. 상각범위액=취득가액 300,000,000×0.100=30,000,000원. 회사 계상 37,500,000원 → 한도초과 7,500,000원(손금불산입, +).\n차량운반구: 정률법에서 정액법으로 변경하면 미상각잔액(200,000,000-90,200,000=109,800,000원)에 정액법 상각률 0.200을 곱한 21,960,000원이 범위액. 회사 계상 27,450,000원 → 한도초과 5,490,000원(+).\n합계=7,500,000+5,490,000=12,990,000원.","c":"중","v":1},"공인회2025_60-21":{"w":"금융소득: 비영업대금 이익 3,000,000원(무조건 종합과세)+환매조건부채권 매매차익 4,000,000원+이익잉여금 자본전입 무상주 액면 5,000,000원(의제배당, Gross-up 대상)+상장법인 현금배당 1,000,000원(Gross-up 대상)+집합투자기구 이익 중 배당 15,000,000원(상장주식 매매차익 3,000,000원은 제외, Gross-up 비대상)=28,000,000원. 2,000만원을 넘어 종합과세.\n출자공동사업자 배당 11,000,000원은 무조건 종합과세하되 2,000만원 판정과 Gross-up에서 빠진다.\nGross-up 비대상 22,000,000원이 2,000만원을 먼저 채우므로 Gross-up 대상 6,000,000원은 전부 초과분 → 600,000원 가산.\n금융소득금액=28,000,000+11,000,000+600,000=39,600,000원.","c":"상","v":1},"공인회2025_60-24":{"w":"인적공제: 본인, 부친(72세, 예금이자 7,000,000원은 분리과세되어 소득금액 0), 모친, 동생(20세, 총급여 3,000,000원) → 4명×1,500,000=6,000,000원+경로우대(부친) 1,000,000원=7,000,000원.\n신용카드 등 소득공제: 형제자매의 사용액(동생 직불카드)은 제외. 해외 사용액과 자동차세 결제액도 제외. 총급여의 25%=12,500,000원을 넘는 사용액부터 공제.\n신용카드 사용액: 백화점 10,000,000+부친 병원비 3,000,000=13,000,000원 → (13,000,000-12,500,000)×15%=75,000원.\n영화상영관 입장료(문화체육) 1,000,000×30%=300,000원, 전통시장 4,000,000×40%=1,600,000원, 대중교통 1,500,000×40%=600,000원 → 2,500,000원.\n소득공제 합계=75,000+2,500,000=2,575,000원.\n총합계=7,000,000+2,575,000=9,575,000원.","c":"상","v":1},"공인회2025_60-25":{"w":"총급여=기본급 100,000,000원\n+인정상여 5,000,000원(근로를 제공한 2025년 귀속)\n+운전보조금 2,400,000원(자가운전이 아니어서 비과세 아님)\n+업무와 무관한 여비 4,000,000원\n+직무발명보상금 7,000,000원(2024년부터 지배주주등과 그 특수관계인이 받는 보상금은 비과세에서 제외)\n+사택 제공이익 20,000,000원(지배주주인 출자임원이라 비과세 아님)\n직장 건강보험료 회사 부담분은 비과세.\n합계=138,400,000원.","c":"상","v":1},"공인회2025_60-26":{"w":"업무와 관련된 사내 원고료와 연구활동비는 근로소득이다.\n산업재산권 양도 대가는 대금청산일·인도일·사용수익일 중 빠른 날(양수인 사용일 2024.11.25)이 수입시기라 2025년 기타소득이 아니다.\n승마투표권 환급금: 지급받은 날(2025.1.5) 귀속. 단위투표금액의 100배를 넘으므로 과세최저한이 적용되지 않고, 필요경비(적중 투표금액)를 뺀 소득금액 2,000,000원×20%=400,000원.\n계약금이 대체된 위약금은 원천징수 대상이 아니다.\n주택입주 지체상금 1,500,000원: 80% 의제 → 300,000원×20%=60,000원.\n원천징수세액=400,000+60,000=460,000원.","c":"상","v":1},"공인회2025_60-28":{"w":"보험료 세액공제: 일반 보장성보험(배우자) 500,000×12%=60,000원, 장애인전용 보장성보험(딸) 1,000,000(한도)×15%=150,000원.\n의료비 세액공제: 본인 안경 800,000원은 1인당 500,000원 한도, 딸 장애인 보장구 2,000,000원 → 2,500,000원-총급여 60,000,000원의 3% 1,800,000원=700,000원×15%=105,000원.\n교육비 세액공제(지원금 차감): 본인 직업능력개발훈련비 1,200,000-1,000,000=200,000원, 딸 장애인특수교육비 5,000,000-3,000,000=2,000,000원 → 2,200,000×15%=330,000원.\n합계=60,000+150,000+105,000+330,000=645,000원.","c":"상","v":1},"공인회2025_60-29":{"w":"부담부증여로 채무 200,000,000원은 양도로 본다. 증여 당시 시가가 없어 개별공시지가 500,000,000원으로 평가하므로 양도가액=채무액 200,000,000원이고, 취득가액도 기준시가 방식으로 계산한다.\n취득가액=취득 당시 기준시가 300,000,000×(200,000,000/500,000,000)=120,000,000원. 필요경비 개산공제=300,000,000×3%×40%=3,600,000원.\n양도차익=200,000,000-120,000,000-3,600,000=76,400,000원.\n장기보유특별공제 20%=15,280,000원. 양도소득금액=76,400,000-15,280,000=61,120,000원.","c":"상","v":1},"공인회2025_60-31":{"w":"ㄱ: 고속철도 여객운송용역은 과세(영세율·면세 아님). X\nㄴ: 사회기반시설 민간투자법에 따른 사업시행자에게 직접 공급하는 도시철도건설용역은 조세특례제한법 제105조에 따른 영세율. O\nㄷ: 외국 항행 항공기에 공급하는 재화는 영세율이지만, 부가가치세를 별도로 적은 세금계산서를 발급한 경우는 제외한다(부가가치세법 시행령 제33조제2항제5호 단서). X\nㄹ: 학술 연구단체가 면세를 포기하면 10% 과세가 되는 것이지 영세율이 아니다. X\nㅁ: 개별소비세법에 따라 지정받은 외국인전용판매장 경영자가 국내에서 재화를 공급하고 외화를 받아 외국환은행에서 원화로 바꾸면 영세율. O","c":"상","v":1},"공인회2025_60-33":{"w":"승용자동차 X(판매용으로 취득해 매입세액 공제): 1대 판매 25,000,000원 + 1대는 업무용으로 전용했으므로 간주공급(시가 25,000,000원).\n승용자동차 Y(출장 등 업무용으로 구입해 매입세액 불공제): 1대 판매 20,000,000원은 일반 공급. 나머지 1대의 거래처 증여는 매입세액을 공제받지 못한 재화이므로 간주공급 대상이 아니다.\n합계=25,000,000+25,000,000+20,000,000=70,000,000원.","c":"중","v":1},"공인회2025_60-35":{"w":"(1) 토지의 형질변경 관련 매입세액은 토지 관련 지출이라 불공제.\n(2) 기계장치를 장기할부로 매입하고 세금계산서를 받았으면 할부금 지급일이 도래하지 않았어도 공급시기가 도래한 것이므로 20,000,000×10%=2,000,000원 공제.\n(3) 유류비 880,000원(공급대가) 중 개별소비세 과세 승용자동차분 220,000원의 매입세액 20,000원은 불공제, 제품 운반용 트럭 분 660,000원의 매입세액 60,000원 공제.\n(4) 거래처 증정 물품(접대 목적)의 매입세액 150,000원은 불공제.\n(5) 종업원 선물(복리후생) 3,300,000원의 매입세액 300,000원 공제.\n합계=2,000,000+60,000+300,000=2,360,000원.","c":"상","v":1},"공인회2025_60-36":{"w":"매출세액: 10~12월 과세 공급가액 60,000,000×10%=6,000,000원.\n과세사업 매입세액 1,800,000원에서 기업업무추진비 관련 200,000원 불공제 → 1,600,000원 공제.\n트럭(제2기 취득) 공통매입세액 2,000,000×제2기 과세비율 65%(130/200)=1,300,000원 공제.\n기계장치(제2기 취득) 공통매입세액 20,000,000원: 예정신고 때 7~9월 비율 70%로 14,000,000원 공제했으므로 제2기 비율 65%로 정산하면 13,000,000원 → 1,000,000원 추가 납부.\n비품(제1기 취득, 공통매입세액 5,000,000원) 재계산: 취득 과세기간 면세비율 45%(제1기)에서 제2기 35%로 10%p 감소(5%p 이상). 5,000,000×(1-25%×1)×10%=375,000원 추가 공제.\n납부세액=6,000,000-1,600,000-1,300,000+1,000,000-375,000=3,725,000원.","c":"중","v":1},"공인회2025_60-38":{"w":"증여재산가액=아파트 시가 500,000,000원-인수한 채무 200,000,000원=300,000,000원.\n증여재산 공제: 직계존속 증여재산공제 50,000,000원+혼인·출산 증여재산공제 100,000,000원(혼인신고일부터 2년, 출생일부터 2년 이내이며 혼인·출산 합쳐 1억원 한도) = 150,000,000원.\n감정평가수수료는 500만원까지 공제: 5,000,000원.\n증여세 과세표준=300,000,000-150,000,000-5,000,000=145,000,000원.","c":"상","v":1},"공인회2025_60-39":{"w":"5) 장례비용은 증빙이 없어도 최소 500만원은 공제된다. 증빙서류가 없으면 인정되지 않는다는 설명이 옳지 않다.\n1) 상속개시 전 1년 내 채무 부담 2억원 이상(2년 내 5억원 이상)이고 용도 불분명한 경우 상속 추정. O\n2) 공익신탁으로 공익법인 등에 출연한 재산은 과세가액 불산입. O\n3) 10년 이내 상속인 증여재산 가산액은 증여일 현재 가액(시가). O\n4) 금융재산상속공제: 20% 또는 2천만원 중 큰 금액, 한도 2억원. O","c":"상","v":1},"공인회2025_60-40":{"w":"3) 등록면허세의 등록에는 취득세 과세대상 취득을 원인으로 하는 등기·등록은 포함하지 않는다. 포함한다는 설명이 옳지 않다.\n1) 유상승계취득은 잔금지급일, 상속은 상속개시일. O  2) 부담부 증여는 취득일이 속한 달의 말일부터 3개월 이내 신고납부. O  4) 취득세 신고납부, 재산세 보통징수. O  5) 토지 재산세 납세의무자. O","c":"상","v":1},"공인회2026_61-02":{"w":"재조사 사유는 국세기본법 제81조의4제2항과 시행령 제63조의2에 열거된 경우뿐이다.\nㄱ: 무자료거래 등 거래 내용이 사실과 다른 혐의는 수시 세무조사 대상 선정 사유(제81조의6제3항)이다. 재조사 사유로 열거된 것은 부동산투기·매점매석·무자료거래 등 경제질서 교란을 통한 탈루 혐의자에 대한 일제조사(시행령 제63조의2제1호)이다. X\nㄴ: 거래상대방에 대한 조사가 필요한 경우(제2호). O\nㄷ: 세무공무원에게 직무 관련 금품을 제공하거나 알선한 경우(제5호). O\nㄹ: 무작위추출방식 표본조사는 정기선정 사유(제81조의6제2항제3호)이다. X\nㅁ: 국세환급금 결정을 위한 확인조사(시행령 제63조의2제3호). O","c":"상","v":1},"공인회2026_61-07":{"w":"세무상 퇴직급여충당금 기초=5,000,000-부인액 2,000,000=3,000,000원.\n퇴직금 15,000,000원 중 퇴직연금운용자산에서 10,000,000원, 현금으로 5,000,000원을 지급했다. 세무상으로는 운용자산 지급분 10,000,000원이 퇴직연금충당금(80,000,000원)에서 줄고, 현금 지급분은 퇴직급여충당금 3,000,000원과 상계한 뒤 2,000,000원만 비용이 된다.\n장부 비용 11,000,000원과 세무상 비용 2,000,000원의 차이: 퇴직연금충당금 감소분 손금불산입 10,000,000원(△유보 감소), 퇴직급여충당금 부인액 추인 손금산입 1,000,000원(장부 기말 1,000,000원, 세무상 기말 0).\n퇴직연금충당금 한도: 운용자산 기말=90,000,000+77,000,000-10,000,000=157,000,000원, 추계액 135,000,000-세무상 퇴직급여충당금 0=135,000,000원 → 한도 135,000,000원. 세무상 잔액 70,000,000원 → 손금산입 65,000,000원.\n순영향=+10,000,000-1,000,000-65,000,000=-56,000,000원.","c":"상","v":1},"공인회2026_61-08":{"w":"차입금적수가 자기자본적수의 2배를 넘고 임대사업 자산 비율이 50% 이상이므로 추계가 아닌 경우에도 간주익금을 계산한다.\n건설비 상당액=건물 200,000,000원×임대면적 40%=80,000,000원(토지 제외).\n(200,000,000-80,000,000)×5%=6,000,000원.\n운용수익: 은행이자 1,000,000원+신주인수권처분이익 2,000,000원+유가증권처분이익(처분이익 500,000원-처분손실 700,000원이 음수이므로 0)=3,000,000원.\n간주익금=6,000,000-3,000,000=3,000,000원.","c":"상","v":1},"공인회2026_61-09":{"w":"㈜C 주식은 2025.12.1 취득이므로 배당기준일(2025.12.31) 전 3개월 이내 취득분으로 제외한다.\n㈜B(40%, 80%): 10,000,000×80%=8,000,000원. ㈜D(80%, 100%): 4,000,000원.\n차감 이자: 채권자 불분명 사채이자와 연지급수입의 지급이자는 차감 대상이 아니므로 회사채 이자 10,000,000원만 대상.\n㈜B 차감=10,000,000×(200,000,000/1,000,000,000)×80%=1,600,000원. ㈜D 차감=10,000,000×(100,000,000/1,000,000,000)×100%=1,000,000원.\n익금불산입액=(8,000,000-1,600,000)+(4,000,000-1,000,000)=9,400,000원.","c":"상","v":1},"공인회2026_61-10":{"w":"각 사업연도 소득금액=당기순이익 80,000,000+법인세비용 30,000,000-익금불산입 10,000,000=100,000,000원.\n이월결손금: 중소기업이 아니므로 소득의 80% 한도(80,000,000원). 이월결손금 62,000,000원 중 자산수증이익으로 충당된 2,000,000원을 뺀 60,000,000원 공제 → 과세표준 40,000,000원.\n산출세액=40,000,000×10%=4,000,000원. 최저한세=(40,000,000+10,000,000)×10%=5,000,000원이므로 연구·인력개발비 세액공제 1,000,000원은 배제되고 부담세액은 5,000,000원.\n외국납부세액공제 500,000원(최저한세 대상 아님)과 중간예납세액 300,000원을 차감: 5,000,000-500,000-300,000=4,200,000원.","c":"상","v":1},"공인회2026_61-11":{"w":"제품: 신고한 총평균법 860,000원으로 평가했다. 입고 후 6개월 지나 진부화된 제품의 평가손실 100,000원은 법정 감액 사유가 아니므로 손금불산입(+100,000, 유보).\n재공품: 평가방법을 2026.11.1에 신고했으나 신고기한(사업연도 종료일 전 3개월)이 지나 신고 효력이 없으므로 무신고로 보아 선입선출법으로 평가한 것이 인정된다. 전기 평가감 유보 20,000원은 추인(손금산입, -20,000).\n원재료: 신고한 선입선출법으로 평가했으나 계산 착오로 30,000원 과대평가 → 손금산입(-30,000, △유보).\n손금산입·익금불산입 합계=20,000+30,000=50,000원.","c":"중","v":1},"공인회2026_61-12":{"w":"기계장치는 신고하지 않았으므로 정률법(0.300). 제26기 수선비 5,000,000원은 소액수선비(개별 자산 600만원 미만)로 즉시 비용 인정되어 별도 조정이 없다.\n제26기초 미상각잔액=장부가액(100,000,000-80,000,000=20,000,000)+전기 상각부인액 3,000,000=23,000,000원. 상각범위액=23,000,000×0.3=6,900,000원.\n회사 계상 감가상각비 5,000,000원 → 시인부족액 1,900,000원이 생겨 전기 상각부인액 3,000,000원 중 1,900,000원을 추인(손금산입).\n기말 유보 잔액=3,000,000-1,900,000=1,100,000원.","c":"중","v":1},"공인회2026_61-13":{"w":"건물 저가 양도: 특수관계인 갑에게 시가 500,000,000원인 건물을 300,000,000원에 양도했으므로 시가와의 차액 200,000,000원을 익금산입(부당행위계산 부인).\n사택 임대료의 시가=(사택 시가 400,000,000×50%-보증금 100,000,000)×5%=5,000,000원. 받은 임대료 200,000×12=2,400,000원과의 차이 2,600,000원이 시가의 5% 이상이므로 익금산입.\n순영향=200,000,000+2,600,000=202,600,000원.","c":"상","v":1},"공인회2026_61-19":{"w":"감가상각비는 회사가 계상하지 않아도 정액법 5년으로 강제상각한다. 60,000,000/5=12,000,000원 손금산입(△유보). 취득가액이 8,000만원 미만이라 전용번호판을 달지 않아도 손금 요건에 문제가 없다.\n관련비용=12,000,000+3,000,000=15,000,000원, 업무사용비율=8,000/10,000=80%.\n업무 외 사용금액 15,000,000×20%=3,000,000원 손금불산입(상여).\n업무사용 감가상각비 12,000,000×80%=9,600,000원 중 8,000,000원 초과 1,600,000원 손금불산입(유보).\n순영향=-12,000,000+3,000,000+1,600,000=-7,400,000원.","c":"상","v":1},"공인회2026_61-21":{"w":"A상가: 임대료 5,000,000×12=60,000,000원. 간주임대료=(보증금 500,000,000-건물 취득가액 300,000,000)×5%=10,000,000원에서 보증금 운용수익 중 수입이자 2,500,000+수입배당금 1,500,000(유가증권처분이익은 제외)을 뺀 6,000,000원.\nB상가: 영화촬영 목적 대여 10,000,000원, 2026.10.1~2027.9.30분 임대료 중 2026년 귀속분 36,000,000×3/12=9,000,000원.\n공익사업과 관련된 지상권 대여 대가는 기타소득이라 제외.\n총수입금액=60,000,000+6,000,000+10,000,000+9,000,000=85,000,000원. 필요경비 35,000,000원.\n사업소득금액=50,000,000원.","c":"상","v":1},"공인회2026_61-22":{"w":"(1) 회사 업무와 관련된 사내 강의료는 근로소득.\n(2) 상속받은 음원 저작권의 양도 대가 6,000,000원: 저작자 외의 자가 받는 기타소득(소득세법 제21조제1항제5호)이고 필요경비 의제(60%·80%) 대상이 아니다. 실제 필요경비가 확인되지 않으므로 6,000,000원.\n(3) 공익법인 시상 상금 20,000,000원: 80% 의제 → 4,000,000원.\n(4) 이혼에 따른 정신적 피해 손해배상금은 과세 대상 소득이 아니다.\n(5) 서화 양도 소득은 무조건 분리과세라 합산하지 않는다.\n(6) 복권당첨금은 무조건 분리과세.\n(7) 재직 중 회사로부터 받은 직무발명보상금은 근로소득.\n(8) 사외 잡지 원고료 5,000,000원: 60% 의제 → 2,000,000원.\n합계 12,000,000원(300만원 초과라 종합과세).","c":"상","v":1},"공인회2026_61-23":{"w":"금융소득 40,500,000원이 2,000만원을 넘어 종합과세되며, 결손금은 기본세율이 적용되는 금융소득 범위에서 공제할 수 있다.\n당기 결손금: 부동산임대업 외 사업 결손금 35,000,000원을 부동산임대업 소득 10,000,000원과 먼저 통산(-25,000,000원) → 근로 5,000,000 → 연금 4,000,000 → 기타 6,000,000 → 이자 10,000,000원 공제, 이자소득금액 6,500,000원 남음.\n이월결손금: 2019년 발생 일반 사업 결손금 8,000,000원(10년 이내)을 이자 6,500,000원, 배당 1,500,000원에서 공제. 부동산임대업 이월결손금 15,000,000원은 부동산임대업 소득이 남지 않아 공제하지 못하고 이월된다.\n종합소득금액=24,000,000-1,500,000=22,500,000원.","c":"상","v":1},"공인회2026_61-24":{"w":"(1) 법원 보증금·경락대금 이자 3,000,000원: 무조건 분리과세, 제외.\n(2) 장기채권 이자 분리과세 신청 특례는 2017.12.31 이전 발행 채권에만 적용되므로 2020.12.31 발행분 5,000,000원은 일반 이자소득.\n(3) 비영업대금의 이익 7,000,000원: 원천징수되지 않아 무조건 종합과세.\n(4) 자기주식처분이익 자본전입 무상주 10,000주×1,000원=10,000,000원: 의제배당(Gross-up 대상).\n(5) 외국법인 현금배당 8,000,000원: 무조건 종합과세, Gross-up 비대상.\n(6) 인정배당은 결산확정일이 속하는 연도 귀속: 2025 사업연도분 4,000,000원은 2026년 귀속(Gross-up 대상), 2026 사업연도분은 2027년 귀속.\n합계=5,000,000+7,000,000+10,000,000+8,000,000+4,000,000=34,000,000원. Gross-up 비대상 20,000,000원이 2,000만원을 채우므로 Gross-up 대상 14,000,000원×10%=1,400,000원 가산.\n금융소득금액=35,400,000원.","c":"상","v":1},"공인회2026_61-28":{"w":"본인 직업능력개발훈련 수강료 4,500,000원(한도 없음). 배우자의 대학원 수업료는 본인만 대상이므로 제외.\n자녀A(대학생): 대학입학전형료 500,000+입학금·수업료 8,900,000=9,400,000원이나 1인당 한도 9,000,000원.\n자녀B(중학생): 교복구입비 600,000원은 50만원 한도 → 500,000원, 방과후 특별활동비 700,000원, 현장체험학습비 500,000원은 30만원 한도 → 300,000원, 사설학원은 제외 → 1,500,000원.\n자녀C(미취학): 보육시설 2,350,000+체육시설 수강료 850,000=3,200,000원이나 한도 3,000,000원.\n공제 대상 합계=4,500,000+9,000,000+1,500,000+3,000,000=18,000,000원. 세액공제=18,000,000×15%=2,700,000원.","c":"상","v":1},"공인회2026_61-29":{"w":"총급여=기본급 30,000,000원\n+자가운전보조금 중 월 20만원 초과분 100,000×12=1,200,000원\n+식사대 2,400,000원(구내식당에서 식사를 제공받아 비과세 불가)\n+종업원 할인금액 6,000,000원 중 비과세 한도(시가 20,000,000원의 20% 4,000,000원과 연 240만원 중 큰 금액)를 넘는 2,000,000원\n주택 임차자금 무상대여 이익은 중소기업 종업원(지배주주 아님)에게 비과세이고, 출산지원금은 출생일부터 2년 이내 2회 이내 전액 비과세이다.\n합계=35,600,000원.","c":"상","v":1},"공인회2026_61-30":{"w":"매출세액=185,000,000×10%=18,500,000원.\n대손세액공제: 받을어음 부도발생일(2025.8.10)부터 6개월이 지난 뒤 확정신고 기간이므로 5,500,000×10/110=500,000원 공제.\n매입세액: 일반과세자 매입분 93,000,000원의 세금계산서 매입세액 9,300,000원 공제. 면세사업자로부터 매입한 중고자동차 55,000,000원은 중고자동차 의제매입세액 55,000,000×10/110=5,000,000원 공제.\n전자세금계산서 발급·전송 세액공제 건당 200원×50건=10,000원.\n차가감납부세액=18,500,000-500,000-9,300,000-5,000,000-10,000=3,690,000원.","c":"상","v":1},"공인회2026_61-31":{"w":"예정신고기간 과세공급가액 비율=201,600,000/210,000,000=96%. 면세공급가액 비율이 4%로 5% 미만이지만 공통매입세액 합계가 500만원 이상이라 안분을 생략할 수 없다.\n과세사업용 원재료 매입세액 12,000,000원 공제, 면세사업용 원재료는 불공제.\n공통매입세액: 기계장치 5,000,000×96%=4,800,000원, 공장 임차료 720,000×96%=691,200원, 작업모(과세·면세 공통 생산 인력용) 45,000×96%=43,200원.\n직원 명절 선물과 거래처 선물로 산 사과는 면세 재화라 매입세액이 없다.\n합계=12,000,000+4,800,000+691,200+43,200=17,534,400원.","c":"상","v":1},"공인회2026_61-32":{"w":"ㄱ: 매입세액을 공제받은 승용차를 개인적 용도로 사용하면 개인적 공급으로 재화의 공급이다. O\nㄴ: 건설업자가 건설자재를 부담하는 것은 용역의 공급이다. X\nㄷ: 부동산 매매업자의 부동산 판매는 재화의 공급이다. O\nㄹ: 사업장별 신고·납부 사업자가 판매 목적으로 다른 사업장에 반출하는 것은 재화의 공급(간주공급)이다. O\nㅁ: 자기적립마일리지로만 결제받은 경우는 재화의 공급으로 보지 않는다. X","c":"상","v":1},"공인회2026_61-33":{"w":"감정평가(7.10)는 공급시기(6.15)가 속하는 과세기간이 끝난 뒤라 안분 기준으로 쓸 수 없다. 기준시가가 토지·건물에만 있고 기계장치에는 없으므로 먼저 장부가액으로 나누고, 기준시가가 있는 토지·건물은 그 합계액을 다시 기준시가로 나눈다(부가가치세법 시행령 제64조).\n1차(장부가액 125,000,000원): 기계장치 160,000,000×15/125=19,200,000원, 토지·건물 160,000,000×110/125=140,800,000원.\n2차(기준시가): 건물 140,800,000×45,000,000/120,000,000=52,800,000원, 토지 88,000,000원(면세).\n과세 공급가액=19,200,000+52,800,000=72,000,000원.","c":"상","v":1},"공인회2026_61-36":{"w":"일반과세자에서 간이과세자로 바뀔 때 재고납부세액=재고금액(감가상각자산은 취득가액×(1-체감률×경과된 과세기간 수))×10%×(1-0.5%×110/10).\n상품: 15,000,000×10%×0.945=1,417,500원.\n건물: 취득 2023.1.5부터 2026.7.1까지 과세기간 7개가 경과. 100,000,000×(1-5%×7)=65,000,000원 → 65,000,000×10%×0.945=6,142,500원.\n2026.7~12월 간이과세 납부세액: 공급대가 56,900,000×15%×10%=853,500원. 공제: 신용카드 발행세액공제 56,900,000×1.3%=739,700원, 세금계산서 수취 매입세액공제 18,500,000×0.5%=92,500원.\n납부세액=1,417,500+6,142,500+853,500-739,700-92,500=7,581,300원.","c":"중","v":1},"공인회2026_61-38":{"w":"상속재산: 주택 550,000,000원, 퇴직금 200,000,000원(피상속인의 사망으로 인하여 지급된 금액). 산업재해보상보험법상 유족보상금 150,000,000원은 상속재산에서 제외.\n추정상속재산: 1년 내 처분금액 250,000,000원(2억원 이상) 중 용도 불분명 150,000,000원-min(처분금액의 20% 50,000,000원, 2억원)=100,000,000원.\n채무 200,000,000원 공제. 장례비용: 일반 장례비 7,000,000원+봉안시설 비용 한도 5,000,000원=12,000,000원.\n상속세 과세가액=550,000,000+200,000,000+100,000,000-200,000,000-12,000,000=638,000,000원.","c":"상","v":1},"공인회2026_61-39":{"w":"4) 출산 증여재산공제는 직계존속으로부터 자녀의 출생일 또는 입양일부터 2년 이내에 받은 증여가 대상이다(혼인은 혼인신고일 전후 2년). 출생일 전후 2년이라는 설명이 옳지 않다.\n1) 미성년자 2천만원. O  2) 혼인 증여공제 후 약혼자 사망 등으로 3개월 이내 반환 시 처음부터 없던 것으로 봄. O  3) 둘 이상 증여가 동시에 있으면 안분 공제. O  5) 혼인·출산 공제 합계 1억원 한도. O","c":"상","v":1},"공인회2026_61-40":{"w":"1) 토지 재산세 과세대상은 종합합산·별도합산·분리과세대상으로 구분한다. O\n2) 국가의 보호·지원 또는 중과가 필요한 토지는 분리과세대상이다. X\n3) 1동의 건물이 주거와 주거 외 용도로 함께 쓰이면 주거용 부분만 주택으로 본다. 주거용 면적이 50% 이상이면 전부를 주택으로 보는 것은 1구의 건물이다. X\n4) 주택 부속토지의 경계가 명백하지 않으면 주택 바닥면적의 10배 토지를 부속토지로 본다. X\n5) 허가 없이 공부상 등재현황과 달리 이용해 재산세 부담이 낮아지면 공부상 등재현황에 따라 부과한다. X","c":"상","v":1},"공인회2016_51-01-1":{"w":"국세기본법 제21조 제2항 제1호는 소득세·법인세의 납세의무 성립시기를 과세기간이 끝나는 때로 정한다. 청산소득 법인세만 해산하는 때에 성립한다.","c":"상","v":1},"공인회2016_51-01-2":{"w":"국세기본법 제21조 제2항 제3호는 증여세 납세의무가 증여에 의하여 재산을 취득하는 때 성립한다고 정한다. 상속세는 상속이 개시되는 때 성립한다(같은 항 제2호).","c":"상","v":1},"공인회2016_51-01-3":{"w":"소득세는 신고로 확정되는 세목이지만 신고를 하지 않으면 정부가 과세표준과 세액을 결정하는 때 그 결정에 따라 확정된다(국세기본법 제22조 제2항 단서).","c":"상","v":1},"공인회2016_51-01-5":{"w":"신고로 세액은 이미 확정됐으므로 납부하지 않은 세액은 따로 결정할 필요 없이 국세징수법에 따른 납부고지·독촉과 강제징수 절차로 거둔다(국세징수법 제6조·제10조).","c":"중","v":1},"공인회2016_51-03-1":{"w":"국세기본법 제41조 제1항은 사업양수인의 제2차 납세의무를 양수한 재산의 가액을 한도로 정한다. 지금은 양도인과 특수관계인이거나 조세회피 목적으로 양수한 자만 이 의무를 진다(같은 법 시행령 제22조).","c":"상","v":1},"공인회2016_51-03-2":{"w":"국세기본법 제39조 제1호의 무한책임사원(합명회사 사원, 합자회사 무한책임사원)은 법인 재산으로 부족한 금액 전부에 제2차 납세의무를 진다. 지분비율 한도는 같은 조 단서의 과점주주·과점조합원에게만 있다.","c":"상","v":1},"공인회2016_51-03-3":{"w":"국세기본법 제39조 단서는 과점주주의 제2차 납세의무를 부족액에 그 과점주주가 실질적으로 권리를 행사하는 주식 수를 의결권 없는 주식을 뺀 발행주식 총수로 나눈 비율을 곱한 금액으로 제한한다.","c":"상","v":1},"공인회2016_51-03-4":{"w":"국세기본법 제40조 제2항은 법인의 제2차 납세의무 한도를 (자산총액-부채총액)×출자자의 소유주식 금액 또는 출자액÷발행주식 총액 또는 출자총액으로 정한다. 순자산에 출자지분비율을 곱한 금액이다.","c":"상","v":1},"공인회2016_51-05-1":{"w":"법정신고기한까지 신고한 자의 수정신고는 당초 신고로 확정된 과세표준과 세액을 증액해 확정하는 효력이 있다(국세기본법 제22조의2 제1항). 소득세는 신고로 확정되는 세목이므로 300만원으로 확정된다.","c":"상","v":1},"공인회2016_51-05-3":{"w":"경정청구는 세무서장에게 감액을 요구하는 절차일 뿐이다. 세무서장이 청구를 받은 날부터 2개월 안에 결정·경정해야 세액이 줄어든다(국세기본법 제45조의2 제3항).","c":"상","v":1},"공인회2016_51-05-5":{"w":"2015년 귀속 소득세의 법정신고기한은 2016년 5월 31일이고 경정청구는 법정신고기한이 지난 후 5년 이내에 할 수 있으므로 2021년 5월 31일까지다(국세기본법 제45조의2 제1항, 소득세법 제70조 제1항).","c":"상","v":1},"공인회2017_52-02-2":{"w":"종합부동산세는 정부가 결정하는 때 확정되는 것이 원칙이지만 납세의무자가 종합부동산세법 제16조 제3항에 따라 신고하면 신고하는 때 확정된다(국세기본법 제22조 제2항 제9호·제3항).","c":"상","v":1},"공인회2017_52-02-3":{"w":"국세기본법 제26조의2 제4항 후단은 부담부증여로 증여세와 함께 과세되는 양도소득세의 부과제척기간을 증여세와 같게 정한다. 상호합의 절차가 진행 중이면 같은 조 제8항에 따라 국제조세조정에 관한 법률이 적용된다.","c":"상","v":1},"공인회2017_52-02-4":{"w":"국세기본법 제22조의3 제2항은 당초 확정된 세액을 감소시키는 경정이 그 경정으로 감소되는 세액 외의 세액에 관한 권리·의무관계에 영향을 미치지 않는다고 정한다.","c":"상","v":1},"공인회2017_52-02-5":{"w":"국세기본법 제27조 제1항은 가산세를 뺀 금액이 5억원 이상인 국세의 징수권 소멸시효를 10년, 그 밖의 국세는 5년으로 정한다.","c":"상","v":1},"공인회2017_52-04-2":{"w":"같은 세목·같은 과세기간의 재조사는 원칙적으로 금지되지만 국세기본법 제81조의4 제2항 제2호가 거래상대방에 대한 조사가 필요한 경우를 예외로 둔다.","c":"상","v":1},"공인회2017_52-04-3":{"w":"국세기본법 제81조의11 제1항이 통합조사를 원칙으로 정하고 같은 조 제2항이 세목 특성·탈루 혐의 등으로 특정 세목만 조사할 필요가 있는 경우를 예외로 둔다.","c":"상","v":1},"공인회2017_52-04-4":{"w":"국세기본법 제81조의9 제2항은 세무조사 범위를 확대하는 경우 그 사유와 범위를 납세자에게 문서로 통지하도록 한다.","c":"상","v":1},"공인회2017_52-04-5":{"w":"국세기본법 제81조의2 제2항 제3호는 사업자등록증을 발급하는 경우 납세자권리헌장 문서를 내주도록 정한다. 세무조사를 하는 경우도 같다(같은 항 제1호).","c":"상","v":1},"공인회2018_53-01-5":{"w":"국세기본법 제22조의3 제1항은 확정된 세액을 증가시키는 경정이 당초 확정된 세액에 관한 권리·의무관계에 영향을 미치지 않는다고 정한다. 당초분에 대한 불복기간·징수 효력 등은 그대로 남는다.","c":"상","v":1},"공인회2018_53-02-1":{"w":"국세기본법 제23조는 합병 후 존속하거나 합병으로 설립된 법인이 소멸법인에 부과되거나 소멸법인이 납부할 국세와 강제징수비를 납부할 의무를 진다고 정한다. 가산금은 2020년부터 납부지연가산세에 통합됐다.","c":"상","v":1},"공인회2018_53-02-2":{"w":"국세기본법 제24조 제6항은 피상속인에게 한 처분 또는 절차가 납세의무를 승계하는 상속인이나 상속재산관리인에게도 효력이 있다고 정한다.","c":"상","v":1},"공인회2018_53-02-4":{"w":"납세담보 규정은 2021년 국세징수법으로 옮겨졌다. 국세징수법 제22조 제1항은 금전을 납세담보로 제공한 자가 그 금전으로 담보한 국세와 강제징수비를 납부할 수 있다고 정한다.","c":"상","v":1},"공인회2018_53-02-5":{"w":"국세기본법 제41조 제1항은 양도일 이전에 양도인의 납세의무가 확정된 국세만 사업양수인의 제2차 납세의무 대상으로 한다. 성립했으나 확정되지 않은 국세는 대상이 아니다.","c":"상","v":1},"공인회2018_53-03-1":{"w":"국세기본법 제43조 제1항은 신고 당시 납세지 관할 세무서장에게 제출하도록 하지만 같은 조 제2항은 다른 세무서장에게 제출해도 신고의 효력에 영향이 없다고 정한다.","c":"상","v":1},"공인회2018_53-03-2":{"w":"국세기본법 제51조 제2항 단서는 납부고지로 납부하는 국세와 세법에 따라 자진납부하는 국세에 충당하는 경우 납세자가 동의해야만 하도록 정한다. 체납된 국세에는 동의 없이 충당한다.","c":"상","v":1},"공인회2018_53-03-3":{"w":"국세기본법 제45조의2 제3항은 경정청구를 받은 세무서장이 청구일부터 2개월 이내에 결정·경정하거나 그 이유가 없다는 뜻을 통지하도록 정한다.","c":"상","v":1},"공인회2018_53-03-5":{"w":"국세기본법 제54조 제1항은 국세환급금과 국세환급가산금에 관한 권리의 소멸시효를 행사할 수 있는 때부터 5년으로 정한다.","c":"상","v":1},"공인회2018_53-05-1":{"w":"국세기본법 제61조 제3항은 청구기한까지 우편으로 발송(통신날짜도장 날짜 기준)한 심사청구서가 기간이 지나 도달해도 기간 만료일에 적법하게 청구한 것으로 본다.","c":"상","v":1},"공인회2018_53-05-2":{"w":"국세기본법 제57조 제1항 본문이 불복청구의 집행부정지를 원칙으로 정하고 단서가 중대한 손해 예방이 긴급하다고 재결청이 인정하면 집행정지를 할 수 있게 한다.","c":"상","v":1},"공인회2018_53-05-3":{"w":"국세기본법 제79조 제1항(불고불리)은 조세심판관회의가 심판청구를 한 처분 외의 처분을 취소·변경하거나 새로운 처분을 결정하지 못한다고 정한다.","c":"상","v":1},"공인회2018_53-05-4":{"w":"국세기본법 제75조는 담당 조세심판관이 필요하다고 인정하면 심판사항을 병합하거나 병합된 사항을 분리할 수 있다고 정한다.","c":"상","v":1},"공인회2019_54-01-2":{"w":"국세기본법 제20조는 세법에 특별한 규정이 없으면 납세의무자가 계속 적용하는 기업회계 기준·관행으로서 일반적으로 공정·타당하다고 인정되는 것을 존중하도록 정한다.","c":"상","v":1},"공인회2019_54-01-3":{"w":"국세기본법 제18조 제1항의 세법 해석 기준이다. 과세의 형평과 해당 조항의 합목적성에 비추어 납세자의 재산권이 부당하게 침해되지 않도록 해석해야 한다.","c":"상","v":1},"공인회2019_54-01-4":{"w":"국세기본법 제16조 제1항(근거과세)은 장부를 갖추어 기록하는 납세의무자의 과세표준 조사·결정을 장부와 관계 증거자료에 의하도록 정한다.","c":"상","v":1},"공인회2019_54-01-5":{"w":"국세기본법 제19조(세무공무원의 재량의 한계)의 내용이다. 재량은 과세의 형평과 세법의 목적에 비추어 일반적으로 적당하다고 인정되는 한계 안에서 행사해야 한다.","c":"상","v":1},"공인회2019_54-02-1":{"w":"원천징수하는 소득세·법인세는 소득금액 또는 수입금액을 지급하는 때 성립하고(국세기본법 제21조 제3항 제1호) 성립하는 때 특별한 절차 없이 확정된다(같은 법 제22조 제4항 제2호).","c":"상","v":1},"공인회2019_54-02-2":{"w":"국세기본법 제22조의3 제1항은 증액경정이 당초 확정된 세액에 관한 권리·의무관계에 영향을 미치지 않는다고 정한다.","c":"상","v":1},"공인회2019_54-02-4":{"w":"국세기본법 제27조 제1항 제1호는 5억원 이상 국세(가산세 제외)의 징수권 소멸시효를 10년으로 정한다.","c":"상","v":1},"공인회2019_54-02-5":{"w":"국세기본법 제28조 제1항은 납부고지·독촉·교부청구·압류를 소멸시효 중단 사유로 정한다. 납부최고는 그 뒤 개정으로 조문에서 빠지고 독촉만 남았다.","c":"상","v":1},"공인회2019_54-03-2":{"w":"국세기본법 제37조는 납세담보물을 매각한 경우 압류 우선(제36조)에도 불구하고 그 국세와 강제징수비를 매각대금에서 다른 국세·강제징수비와 지방세보다 먼저 징수하도록 정한다.","c":"상","v":1},"공인회2019_54-03-3":{"w":"국세기본법 제35조 제1항 제3호 나목은 법정기일 전에 주택임대차보호법상 대항요건과 확정일자를 갖춘 임차권의 보증금반환채권을 국세보다 우선시킨다. 다만 그 재산에 부과된 상속세·증여세·종합부동산세는 예외다(같은 조 제3항).","c":"상","v":1},"공인회2019_54-03-4":{"w":"국세기본법 제35조 제1항 제5호는 근로기준법 제38조 등에 따라 국세에 우선하여 변제되는 임금채권을 국세보다 먼저 변제하도록 한다. 최종 3개월분 임금은 근로기준법 제38조 제2항에 따라 법정기일과 관계없이 최우선이다.","c":"상","v":1},"공인회2019_54-03-5":{"w":"국세기본법 제35조 제6항은 납세자가 제3자와 짜고 거짓으로 저당권 설정계약을 하고 등기해 국세 징수가 곤란하다고 인정되면 세무서장이 법원에 그 행위의 취소를 청구할 수 있게 한다.","c":"상","v":1},"공인회2019_54-04-3":{"w":"국세기본법 제51조 제3항은 체납 국세에 충당하면 체납 국세의 법정납부기한과 국세환급금 발생일 중 늦은 때로 소급해 대등액이 소멸한 것으로 본다.","c":"상","v":1},"공인회2019_54-04-4":{"w":"국세기본법 제51조 제6항은 충당하고 남은 국세환급금을 결정한 날부터 30일 내에 납세자에게 지급하도록 정한다.","c":"상","v":1},"공인회2019_54-04-5":{"w":"물납한 상속세의 환급은 물납재산으로 하는 것이 원칙이지만 국세기본법 제51조의2 제2항과 같은 법 시행령 제43조의2 제2항 제1호는 성질상 분할하여 환급하기 곤란한 경우 금전으로 환급하도록 정한다.","c":"상","v":1},"공인회2019_54-05-1":{"w":"국세기본법 제81조의15 제1항 제2호는 세무조사에서 확인된 조사대상자 외의 자에 대한 과세자료와 현지 확인조사에 따라 과세하는 경우 과세예고통지를 하도록 정한다.","c":"상","v":1},"공인회2019_54-05-2":{"w":"국세기본법 제81조의15 제2항 단서와 같은 법 시행령 제63조의15 제1항 제1호는 법령과 관련해 국세청장의 유권해석을 변경해야 하거나 새로운 해석이 필요한 경우 국세청장에게 청구하도록 정한다.","c":"상","v":1},"공인회2019_54-05-3":{"w":"국세기본법 제81조의15 제3항 제3호는 결과통지·과세예고통지일부터 부과제척기간 만료일까지 3개월 이하인 경우 과세전적부심사를 청구할 수 없다고 정한다.","c":"상","v":1},"공인회2019_54-05-4":{"w":"국세기본법 제81조의15 제4항은 과세전적부심사 청구를 받은 세무서장 등이 국세심사위원회 심사를 거쳐 결정하고 청구일부터 30일 이내에 결과를 통지하도록 정한다.","c":"상","v":1},"공인회2020_55-01-2":{"w":"국세기본법 제2조 제11호의 제2차 납세의무자 정의다. 주된 납세자가 납세의무를 이행할 수 없을 때 보충적으로 납세의무를 진다.","c":"상","v":1},"공인회2020_55-01-3":{"w":"국세기본법 제8조 제2항은 연대납세의무자에게 서류를 송달할 때 대표자를 명의인으로 하되 납부고지와 독촉에 관한 서류는 연대납세의무자 모두에게 각각 송달하도록 정한다.","c":"상","v":1},"공인회2020_55-01-4":{"w":"국세기본법 제20조는 기업회계 기준·관행 존중을 정하면서 세법에 특별한 규정이 있는 경우를 제외한다.","c":"상","v":1},"공인회2020_55-01-5":{"w":"국세기본법 제55조 제2항 제1호는 제2차 납세의무자로서 납부고지서를 받은 자를 이해관계인으로 보아 주된 납세자의 처분에 불복할 수 있게 한다.","c":"상","v":1},"공인회2020_55-02-3":{"w":"국세기본법 제36조 제1항은 국세 강제징수로 압류한 경우 압류와 관계되는 국세와 강제징수비를 교부청구된 다른 국세나 지방세보다 먼저 징수하도록 정한다(압류선착주의).","c":"상","v":1},"공인회2020_55-03-5":{"w":"국세기본법 제48조 제1항 제3호와 같은 법 시행령 제28조 제1항 제1호는 세법해석 질의·회신 등에 따라 신고·납부했으나 이후 다른 과세처분을 하는 경우 가산세를 부과하지 않도록 정한다.","c":"상","v":1},"공인회2020_55-04-1":{"w":"국세기본법 제55조 제1항 제1호는 조세범 처벌절차법에 따른 통고처분을 불복 대상에서 뺀다.","c":"상","v":1},"공인회2020_55-04-2":{"w":"국세기본법 제55조 제3항은 국세청장이 조사·결정 또는 처리하거나 하였어야 할 처분을 이의신청 대상에서 제외한다. 이 경우 바로 심사청구나 심판청구를 한다.","c":"상","v":1},"공인회2020_55-04-4":{"w":"국세기본법 제56조 제2항 단서는 심사청구·심판청구의 재조사 결정에 따른 처분청의 처분에 대한 행정소송은 다시 심사·심판을 거치지 않고 제기할 수 있다고 정한다.","c":"상","v":1},"공인회2020_55-04-5":{"w":"국세기본법 제59조의2 제1항은 이의신청인·심사청구인·심판청구인과 함께 과세전적부심사 청구인도 요건을 갖추면 국선대리인 선정을 신청할 수 있게 한다.","c":"상","v":1},"공인회2020_55-05-1":{"w":"국세기본법 제81조의4 제1항은 세무조사를 필요한 최소한의 범위에서 하도록 하고 괄호에서 조세범 처벌절차법에 따른 조세범칙조사를 세무조사에 포함한다.","c":"상","v":1},"공인회2020_55-05-2":{"w":"국세기본법 제81조의4 제2항 제7호와 같은 법 시행령 제63조의2 제3호는 국세환급금 결정을 위한 확인조사를 재조사 허용 사유로 정한다.","c":"상","v":1},"공인회2020_55-05-3":{"w":"국세기본법 제81조의8 제5항은 세무조사 중지기간에는 과세표준과 세액을 결정·경정하기 위한 질문이나 장부 등의 검사·조사·제출 요구를 할 수 없다고 정한다.","c":"상","v":1},"공인회2020_55-05-4":{"w":"국세기본법 제81조의11 제1항의 통합조사 원칙이다. 사업과 관련해 신고·납부의무가 있는 세목을 통합하여 조사한다.","c":"상","v":1},"공인회2021_56-02-1":{"w":"국세기본법 제35조 제1항 제2호는 강제집행·경매·파산 절차로 재산을 매각할 때 그 절차에 든 비용을 국세와 강제징수비보다 먼저 변제하도록 정한다.","c":"상","v":1},"공인회2021_56-02-2":{"w":"국세기본법 제35조 제1항 제3호 가목은 법정기일 전에 전세권이 설정된 재산을 매각할 때 그 전세금 채권을 국세보다 우선시킨다. 다만 그 재산에 부과된 상속세·증여세·종합부동산세는 예외다(같은 조 제3항).","c":"상","v":1},"공인회2021_56-02-3":{"w":"국세기본법 제35조 제6항 제1호는 짜고 한 거짓 저당권 설정계약과 등기로 국세 징수가 곤란한 경우 세무서장이 법원에 취소를 청구할 수 있게 한다. 법정기일 전 1년 내 특수관계인과 한 계약은 거짓으로 추정한다.","c":"상","v":1},"공인회2021_56-02-5":{"w":"국세기본법 제37조는 납세담보물 매각대금에서 그 담보된 국세와 강제징수비를 지방세보다 먼저 징수하도록 정한다. 제36조(압류에 의한 우선)에 앞서 적용되므로 지방세 압류가 있어도 같다.","c":"상","v":1},"공인회2021_56-03-2":{"w":"국세기본법 제51조 제11항은 명의대여자 과세를 취소하고 실질귀속자에게 과세할 때 실질귀속자가 명의대여자 대신 낸 것으로 확인된 금액을 실질귀속자의 기납부세액으로 먼저 공제하고 남으면 실질귀속자에게 환급하도록 정한다.","c":"상","v":1},"공인회2021_56-03-3":{"w":"국세기본법 시행령 제43조의2 제2항 제2호는 물납재산이 임대 중이거나 다른 행정용도로 사용되는 경우 금전으로 환급하도록 정한다(국세기본법 제51조의2 제2항).","c":"상","v":1},"공인회2021_56-03-4":{"w":"국세기본법 제53조 제2항은 국세환급금 권리 양도 요구가 있으면 양도인 또는 양수인이 낼 국세와 강제징수비에 먼저 충당하고 남은 금액은 지체 없이 양도 요구에 따르도록 정한다.","c":"상","v":1},"공인회2021_56-03-5":{"w":"국세기본법 시행령 제31조 제2항은 체납된 국세와 강제징수비에 먼저 충당하되 납세자가 납부고지로 납부하는 국세에 충당하는 데 동의하거나 신청하면 그 국세에 먼저 충당하도록 정한다.","c":"상","v":1},"공인회2021_56-04-2":{"w":"국세기본법 제59조의2 제2항은 재결청이 요건을 갖춘 신청을 받으면 지체 없이 국선대리인을 선정하고 신청일부터 5일 이내에 신청인과 국선대리인에게 각각 통지하도록 정한다.","c":"상","v":1},"공인회2021_56-04-3":{"w":"국세기본법 제64조 제2항은 국세청장이 국세심사위원회 의결이 법령에 명백히 위반된다고 판단하면 구체적 사유를 적은 서면으로 한 차례에 한정하여 다시 심의를 요청할 수 있게 한다.","c":"상","v":1},"공인회2021_56-04-4":{"w":"국세기본법 제65조 제1항 제1호 가목은 심판청구를 제기한 후 심사청구를 제기한 경우(같은 날 제기한 경우 포함) 심사청구를 각하하도록 정한다. 같은 처분에 심사청구와 심판청구를 중복해 낼 수 없기 때문이다(같은 법 제55조 제9항).","c":"상","v":1},"공인회2021_56-04-5":{"w":"국세기본법 제61조 제1항이 심사청구 기간을 처분이 있음을 안 날(통지를 받은 날)부터 90일 이내로 정하고 제65조 제2항이 결정 기간을 심사청구를 받은 날부터 90일 이내로 정한다.","c":"상","v":1},"공인회2022_57-01-5":{"w":"국세기본법 제18조 제3항의 소급과세 금지 원칙이다. 일반적으로 받아들여진 해석·관행에 따른 행위나 계산은 정당한 것으로 보고 새로운 해석·관행으로 소급과세하지 않는다.","c":"상","v":1},"공인회2022_57-02-1":{"w":"국세기본법 제24조 제1항은 상속인(수유자 포함)이나 상속재산관리인이 피상속인의 국세와 강제징수비를 상속으로 받은 재산의 한도에서 납부하도록 정한다.","c":"상","v":1},"공인회2022_57-02-3":{"w":"국세기본법 제25조 제3항은 분할법인이 분할 후 소멸하면 분할신설법인과 분할합병의 상대방 법인이 분할법인의 국세와 강제징수비를 분할로 승계된 재산가액을 한도로 연대하여 납부하도록 정한다.","c":"상","v":1},"공인회2022_57-02-4":{"w":"국세기본법 제25조 제1항은 공유물, 공동사업 또는 그 공동사업에 속하는 재산과 관계되는 국세와 강제징수비를 공유자나 공동사업자가 연대하여 납부하도록 정한다.","c":"상","v":1},"공인회2022_57-02-5":{"w":"국세기본법 제25조 제4항은 법인이 채무자 회생 및 파산에 관한 법률 제215조에 따라 신회사를 설립하면 기존 법인에 부과되거나 납세의무가 성립한 국세와 강제징수비를 신회사가 연대하여 납부하도록 정한다.","c":"상","v":1},"공인회2022_57-03-2":{"w":"국세기본법 제35조 제1항 제2호는 강제집행·경매·파산 절차로 재산을 매각할 때 그 절차에 든 비용을 국세와 강제징수비보다 먼저 변제하도록 정한다.","c":"상","v":1},"공인회2022_57-03-3":{"w":"국세기본법 제35조 제1항 제3호 가목은 법정기일 전에 설정된 전세권·질권·저당권으로 담보된 채권을 국세보다 먼저 변제하도록 정한다. 그 재산에 부과된 상속세·증여세·종합부동산세는 예외다(같은 조 제3항).","c":"상","v":1},"공인회2022_57-03-4":{"w":"국세기본법 제36조 제1항은 강제징수로 압류한 국세와 강제징수비를 교부청구된 다른 국세·강제징수비나 지방세보다 먼저 징수하도록 정한다(압류선착주의).","c":"상","v":1},"공인회2022_57-03-5":{"w":"국세기본법 제37조는 납세담보물을 매각하면 그 담보된 국세와 강제징수비를 매각대금에서 다른 국세·강제징수비와 지방세보다 먼저 징수하도록 정한다. 압류에 의한 우선(제36조)보다 앞선다.","c":"상","v":1},"공인회2022_57-04-1":{"w":"국세기본법 제21조 제2항 제1호는 법인세가 과세기간이 끝나는 때 성립하고 청산소득에 대한 법인세는 법인이 해산하는 때 성립한다고 정한다.","c":"상","v":1},"공인회2022_57-04-2":{"w":"국세기본법 제22조 제2항 단서는 신고납세 세목이라도 신고를 하지 않으면 정부가 과세표준과 세액을 결정하는 때 그 결정에 따라 확정된다고 정한다.","c":"상","v":1},"공인회2022_57-04-3":{"w":"국세기본법 제22조의2 제2항은 수정신고가 당초 신고로 확정된 세액에 관한 권리·의무관계에 영향을 미치지 않는다고 정한다. 수정신고는 증액분만 추가로 확정한다(같은 조 제1항).","c":"상","v":1},"공인회2022_57-04-5":{"w":"국세기본법 제26조 제2호는 부과제척기간에 국세가 부과되지 않고 그 기간이 끝난 때 납부의무가 소멸한다고 정한다.","c":"상","v":1},"공인회2022_57-05-1":{"w":"국세기본법 제2조 제4호의 가산세 정의다. 의무의 성실한 이행을 확보하려고 세법에 따라 산출한 세액에 가산하여 징수하는 금액이다.","c":"상","v":1},"공인회2022_57-05-2":{"w":"국세기본법 제47조 제3항은 가산세를 납부할 세액에 가산하거나 환급받을 세액에서 공제한다고 정한다.","c":"상","v":1},"공인회2022_57-05-3":{"w":"국세기본법 제47조 제2항은 가산세를 의무가 규정된 세법의 해당 국세 세목으로 하고 해당 국세를 감면하더라도 가산세는 감면 대상에 넣지 않는다고 정한다.","c":"상","v":1},"공인회2022_57-05-4":{"w":"국세기본법 제48조 제1항 제2호는 납세자가 의무를 이행하지 않은 데 정당한 사유가 있으면 해당 가산세를 부과하지 않도록 정한다.","c":"상","v":1},"공인회2023_58-01-4":{"w":"국세기본법 제26조의2 제6항 제1호의2는 불복 결정이나 판결이 확정되어 연동된 다른 세목(같은 과세기간)의 과세표준 조정이 필요하면 확정된 날부터 1년이 지나기 전까지 경정 등을 할 수 있게 한다.","c":"상","v":1},"공인회2023_58-03-1":{"w":"국세기본법 제43조 제2항은 과세표준신고서를 관할 세무서장 외의 세무서장에게 제출해도 신고의 효력에 영향이 없다고 정한다.","c":"상","v":1},"공인회2023_58-03-2":{"w":"국세기본법 제45조 제1항 제1호는 신고한 과세표준·세액이 신고해야 할 금액에 미치지 못하면 관할 세무서장이 결정·경정하여 통지하기 전으로서 부과제척기간이 끝나기 전까지 수정신고를 할 수 있게 한다.","c":"상","v":1},"공인회2023_58-03-3":{"w":"국세기본법 제45조의2 제2항 제2호는 소득이나 과세물건의 귀속을 제3자에게로 변경시키는 결정·경정이 있으면 그 사유가 발생한 것을 안 날부터 3개월 이내에 경정청구를 할 수 있게 한다(후발적 경정청구).","c":"상","v":1},"공인회2023_58-03-5":{"w":"국세기본법 제45조의2 제3항은 경정청구를 받은 세무서장이 청구일부터 2개월 이내에 경정하거나 경정할 이유가 없다는 뜻을 통지하도록 정한다.","c":"상","v":1},"공인회2023_58-04-2":{"w":"국세기본법 제56조 제3항 단서는 결정기간에 결정 통지를 받지 못하면 통지 전이라도 결정기간이 지난 날부터 행정소송을 제기할 수 있게 한다.","c":"상","v":1},"공인회2023_58-04-3":{"w":"국세기본법 제74조 제1항은 담당 조세심판관에게 공정한 심판을 기대하기 어려운 사정이 있으면 심판청구인이 기피를 신청할 수 있게 하고 같은 조 제2항은 그 신청을 조세심판원장에게 하도록 정한다.","c":"상","v":1},"공인회2023_58-04-4":{"w":"국세기본법 제79조 제1항(불고불리)은 조세심판관회의가 심판청구를 한 처분 외의 처분을 취소·변경하거나 새로운 처분을 결정하지 못한다고 정한다.","c":"상","v":1},"공인회2023_58-04-5":{"w":"국세기본법 제80조의2는 심판청구에 제63조(청구서의 보정)를 준용하면서 20일 이내의 기간을 상당한 기간으로 바꿔 읽게 한다. 그래서 조세심판원장은 상당한 기간을 정해 보정을 요구할 수 있다.","c":"상","v":1},"공인회2023_58-05-1":{"w":"국세기본법 제81조의2 제2항 제1호는 세무조사(조세범칙조사 포함)를 하는 경우 납세자권리헌장 문서를 내주도록 정한다.","c":"상","v":1},"공인회2023_58-05-2":{"w":"국세기본법 제81조의4 제2항 제2호는 거래상대방에 대한 조사가 필요한 경우를 같은 세목·같은 과세기간 재조사 금지의 예외로 둔다.","c":"상","v":1},"공인회2023_58-05-4":{"w":"국세기본법 제81조의9 제1항과 같은 법 시행령 제63조의10 제2호는 조사대상 과세기간 특정 항목의 세법 적용 착오가 다른 과세기간에도 있을 것으로 의심되어 그 항목을 조사할 필요가 있으면 조사 범위를 확대할 수 있게 한다.","c":"상","v":1},"공인회2023_58-05-5":{"w":"국세기본법 제81조의19 제1항은 납세자가 세무조사 기간이 끝나는 날까지 세무서장 또는 지방국세청장에게 제81조의18 제2항 제4호 사항(위법·부당한 세무조사와 세무공무원의 위법·부당한 행위에 대한 세무조사 일시중지·중지 요청)의 심의를 요청할 수 있게 한다.","c":"상","v":1},"공인회2024_59-01-1":{"w":"국세기본법 제10조 제3항은 교부송달을 송달할 장소에서 하도록 하되 송달받을 자가 거부하지 않으면 다른 장소에서 교부할 수 있다고 정한다.","c":"상","v":1},"공인회2024_59-01-3":{"w":"국세기본법 제10조 제4항 후단은 송달받을 자나 사리를 판별할 수 있는 사용인·종업원·동거인이 정당한 사유 없이 수령을 거부하면 송달할 장소에 서류를 둘 수 있다고 정한다(유치송달).","c":"상","v":1},"공인회2024_59-01-5":{"w":"국세기본법 제11조 제2항 후단은 국세정보통신망으로 공시송달을 할 때 세무서 게시판·관보 등 다른 공시송달 방법과 함께 하도록 정한다.","c":"상","v":1},"공인회2024_59-02-1":{"w":"국세기본법 제37조는 납세담보물을 매각하면 그 담보된 국세와 강제징수비를 매각대금에서 다른 국세·강제징수비와 지방세보다 먼저 징수하도록 정한다.","c":"상","v":1},"공인회2024_59-03-3":{"w":"국세기본법 제51조 제6항은 충당하고 남은 국세환급금을 국세환급금 결정일부터 30일 내에 납세자에게 지급하도록 정한다.","c":"상","v":1},"공인회2024_59-04-1":{"w":"국세기본법 제23조는 합병 후 존속하거나 합병으로 설립된 법인이 소멸법인의 국세와 강제징수비를 납부할 의무를 진다고 정한다. 상속과 달리 승계 한도가 없다.","c":"상","v":1},"공인회2024_59-04-2":{"w":"국세기본법 제25조 제3항은 분할법인이 소멸하면 분할신설법인과 분할합병의 상대방 법인이 분할로 승계된 재산가액을 한도로 연대납부의무를 진다고 정한다.","c":"상","v":1},"공인회2024_59-04-3":{"w":"국세기본법 제26조의2 제7항 제1호는 불복 결정이나 판결로 명의대여 사실이 확인되면 당초 처분을 취소하고 확정된 날부터 1년 이내에 실제로 사업을 경영한 자에게 경정 등을 할 수 있게 한다.","c":"상","v":1},"공인회2024_59-04-5":{"w":"국세기본법 제28조 제4항은 사해행위 취소소송이나 채권자대위 소송 제기로 인한 시효정지의 효력이 소송이 각하·기각 또는 취하되면 없어진다고 정한다.","c":"상","v":1},"공인회2024_59-05-1":{"w":"국세기본법 제55조 제1항 제1호는 조세범 처벌절차법에 따른 통고처분을 불복 대상에서 제외한다.","c":"상","v":1},"공인회2024_59-05-3":{"w":"국세기본법 제56조 제3항은 행정소송을 결정 통지를 받은 날부터 90일 이내에 제기하도록 하고 단서에서 결정기간에 통지를 받지 못하면 결정기간이 지난 날부터 제기할 수 있게 한다.","c":"상","v":1},"공인회2024_59-05-4":{"w":"국세기본법 제65조의2 제1항은 심사청구 결정에 잘못된 기재나 계산착오 등 명백한 잘못이 있으면 국세청장이 직권으로 또는 심사청구인의 신청으로 경정할 수 있다고 정한다.","c":"상","v":1},"공인회2024_59-05-5":{"w":"국세기본법 제79조 제1항(불고불리)은 조세심판관회의가 심판청구를 한 처분 외의 처분을 취소·변경하거나 새로운 처분을 결정하지 못한다고 정한다.","c":"상","v":1},"공인회2025_60-01-1":{"w":"국세기본법 제61조 제3항은 청구기한까지 우편으로 발송한 심사청구서가 기간이 지나 도달해도 그 기간의 만료일에 적법하게 청구한 것으로 본다.","c":"상","v":1},"공인회2025_60-01-2":{"w":"장부·서류의 압수·영치는 기한연장 사유이고(국세기본법 시행령 제2조 제5호) 같은 영 제2조의2 제2항은 신고와 관련된 기한연장을 9개월을 넘지 않는 범위에서 관할 세무서장이 할 수 있게 한다.","c":"상","v":1},"공인회2025_60-01-3":{"w":"국세기본법 제5조의2 제1항은 우편으로 낸 과세표준신고서가 우편날짜도장이 찍힌 날에 신고된 것으로 보는 발신주의를 따른다. 반면 같은 법 제12조는 송달 서류가 송달받을 자에게 도달한 때부터 효력이 생기는 도달주의를 따른다.","c":"상","v":1},"공인회2025_60-01-4":{"w":"국세기본법 제13조 제1항 제2호는 공익 목적으로 출연된 기본재산이 있는 재단으로서 등기되지 않고 수익을 구성원에게 분배하지 않는 단체를 신청·승인 없이 법인으로 본다. 독립적 소유·관리 요건은 승인을 받아 법인으로 보는 단체(같은 조 제2항)에만 있다.","c":"상","v":1},"공인회2025_60-02-1":{"w":"국세기본법 제24조 제1항은 상속인이나 상속재산관리인이 피상속인의 국세와 강제징수비를 상속으로 받은 재산의 한도에서 납부하도록 정한다.","c":"상","v":1},"공인회2025_60-02-3":{"w":"국세기본법 제25조 제4항은 채무자 회생 및 파산에 관한 법률 제215조에 따라 설립된 신회사가 기존 법인의 국세와 강제징수비를 연대하여 납부하도록 정한다.","c":"상","v":1},"공인회2025_60-02-4":{"w":"국세기본법 제25조 제3항은 분할법인이 소멸하면 분할신설법인과 분할합병의 상대방 법인이 분할로 승계된 재산가액을 한도로 연대납부의무를 진다고 정한다.","c":"상","v":1},"공인회2025_60-02-5":{"w":"국세기본법 제41조 제1항과 같은 법 시행령 제22조는 양도인과 특수관계인이거나 조세회피 목적으로 사업을 포괄 양수한 자에게 양도일 이전에 확정된 국세에 대해 양수한 재산가액을 한도로 제2차 납세의무를 지운다.","c":"상","v":1},"공인회2025_60-03-2":{"w":"증권거래세는 매매거래가 확정되는 때 성립하고(국세기본법 제21조 제2항 제7호) 신고하는 때 확정되는 세목이다(같은 법 제22조 제2항 제6호).","c":"상","v":1},"공인회2025_60-03-3":{"w":"상속세는 상속이 개시되는 때 성립하고(국세기본법 제21조 제2항 제2호) 신고납세 세목(제22조 제2항)에 들지 않으므로 정부가 결정하는 때 확정된다(같은 조 제3항).","c":"상","v":1},"공인회2025_60-03-4":{"w":"국세기본법 제28조는 징수권 소멸시효에 중단·정지 사유를 두지만 제26조의2의 부과제척기간에는 그런 규정이 없다. 제척기간은 정해진 기간이 지나면 부과권이 그대로 소멸한다.","c":"상","v":1},"공인회2025_60-03-5":{"w":"부과제척기간은 과세표준신고기한의 다음 날부터 기산하고(국세기본법 시행령 제12조의3 제1항 제1호) 신고한 세액의 징수권 소멸시효는 법정 신고납부기한의 다음 날부터 기산한다(국세기본법 제27조 제3항 제1호).","c":"상","v":1},"공인회2025_60-04-2":{"w":"국세기본법 제22조의2 제1항은 신고납세 세목에서 법정신고기한까지 신고한 자의 수정신고에만 증액 확정 효력을 준다. 경정청구는 세무서장의 경정이 있어야 하고(제45조의2 제3항) 기한후신고는 세무서장이 결정·통지해야 확정된다(제45조의3 제3항).","c":"상","v":1},"공인회2025_60-04-3":{"w":"국세기본법 제45조 제1항은 관할 세무서장이 결정·경정하여 통지하기 전으로서 부과제척기간이 끝나기 전까지 수정신고를 할 수 있게 한다.","c":"상","v":1},"공인회2025_60-04-4":{"w":"국세기본법 제45조의3 제1항은 법정신고기한까지 신고하지 않은 자가 관할 세무서장이 결정하여 통지하기 전까지 기한후과세표준신고서를 제출할 수 있게 한다.","c":"상","v":1},"공인회2025_60-04-5":{"w":"국세기본법 제45조의2 제2항 제2호는 과세물건의 귀속을 제3자에게로 변경시키는 결정·경정이 있으면 그 사유가 발생한 것을 안 날부터 3개월 이내에 경정청구를 할 수 있게 한다.","c":"상","v":1},"공인회2026_61-01-1":{"w":"국세기본법 제14조 제3항은 제3자를 통한 간접적인 방법이나 둘 이상의 거래를 거쳐 세법 혜택을 부당하게 받으려는 것으로 인정되면 경제적 실질에 따라 당사자가 직접 거래한 것으로 보아 과세한다고 정한다.","c":"상","v":1},"공인회2026_61-01-3":{"w":"국세기본법 제17조 제1항(조세감면의 사후관리)은 감면 취지를 이루거나 국가정책 수행에 필요하면 감면세액에 상당하는 자금·자산의 운용 범위를 정할 수 있게 한다. 그 범위를 벗어나면 감면을 취소하고 징수할 수 있다(같은 조 제2항).","c":"상","v":1},"공인회2026_61-01-4":{"w":"국세기본법 제18조 제3항은 일반적으로 받아들여진 국세행정 관행에 따른 행위·계산을 정당한 것으로 보고 새로운 관행으로 소급과세하지 않는다고 정한다.","c":"상","v":1},"공인회2026_61-01-5":{"w":"국세기본법 제19조는 세무공무원이 재량을 행사할 때 과세의 형평과 세법의 목적에 비추어 일반적으로 적당하다고 인정되는 한계를 엄수하도록 정한다.","c":"상","v":1},"공인회2026_61-03-1":{"w":"국세기본법 제81조의15 제1항 제3호는 납부고지하려는 세액이 100만원 이상인 경우에만 과세예고통지를 하도록 한다. 과세전적부심사는 세무조사 결과통지나 과세예고통지를 받은 자가 청구하므로(같은 조 제2항) 통지가 없으면 청구할 수 없다.","c":"상","v":1},"공인회2026_61-03-2":{"w":"국세기본법 제81조의15 제3항 제2호는 조세범 처벌법 위반으로 고발·통고처분하는 경우 과세전적부심사를 배제하되 단서에서 고발·통고처분과 관련 없는 세목이나 세액은 청구할 수 있게 한다.","c":"상","v":1},"공인회2026_61-03-3":{"w":"국세기본법 제81조의15 제3항 제3호는 세무조사 결과통지·과세예고통지일부터 부과제척기간 만료일까지 3개월 이하이면 과세전적부심사를 청구할 수 없다고 정한다.","c":"상","v":1},"공인회2026_61-03-4":{"w":"국세기본법 제81조의15 제8항은 통지를 받은 자가 과세전적부심사를 청구하지 않고 통지한 세무서장이나 지방국세청장에게 조기 결정·경정결정을 신청할 수 있게 하고 신청받은 내용대로 즉시 결정하도록 한다.","c":"상","v":1},"공인회2026_61-04-4":{"w":"국세기본법 제45조의2 제6항은 과세기준일이 속한 연도에 종합부동산세를 부과·고지받은 자에게 경정청구 규정(제1항부터 제4항)을 준용한다. 그래서 같은 조 제2항 제2호의 귀속 변경 결정이 있으면 안 날부터 3개월 이내에 청구할 수 있다.","c":"상","v":1},"공인회2026_61-05-3":{"w":"국세기본법 제65조 제1항 제1호 가목은 심판청구를 제기한 후 심사청구를 제기한 경우(같은 날 제기한 경우 포함) 그 심사청구를 각하하도록 정한다.","c":"상","v":1},"공인회2016_51-07-1":{"w":"법인세법 시행령 제13조 제1호는 잉여금의 자본전입으로 인한 의제배당의 귀속시기를 주주총회·사원총회 또는 이사회에서 자본전입을 결의한 날로 정한다.","c":"상","v":1},"공인회2016_51-07-2":{"w":"법인세법 제16조 제1항 제3호는 자기주식을 보유한 상태에서 과세되지 않는 잉여금(같은 항 제2호 각 목)을 자본에 전입해 다른 주주의 지분비율이 늘면 늘어난 지분비율에 상당하는 주식가액을 배당으로 본다.","c":"상","v":1},"공인회2016_51-07-4":{"w":"법인세법 시행령 제12조 제1항 제2호는 자기주식소각이익을 과세되지 않는 자본잉여금에서 빼고 소각 당시 시가가 취득가액을 넘지 않고 소각일부터 2년이 지난 후 전입하는 경우만 다시 제외한다. 시가가 취득가액을 초과했다면 전입 시기와 관계없이 의제배당이다.","c":"상","v":1},"공인회2016_51-07-5":{"w":"법인세법 제16조 제1항 제4호는 해산한 법인의 주주가 잔여재산 분배로 받은 금전 등의 가액이 그 주식의 취득가액을 초과하는 금액을 배당으로 본다.","c":"상","v":1},"공인회2017_52-05-1":{"w":"법인세법 제6조 제2항은 법령이나 정관에 사업연도 규정이 없는 내국법인이 따로 사업연도를 정해 법인 설립신고나 사업자등록과 함께 관할 세무서장에게 신고하도록 정한다. 신고하지 않으면 1월 1일부터 12월 31일까지가 사업연도다(같은 조 제5항).","c":"상","v":1},"공인회2017_52-05-2":{"w":"법인세법 제7조 제2항 단서는 법령에 따라 사업연도가 정해지는 법인이 그 법령 개정으로 사업연도가 바뀌면 변경신고를 하지 않아도 개정 내용대로 변경된 것으로 본다.","c":"상","v":1},"공인회2017_52-05-4":{"w":"법인세법 제8조 제5항은 사업연도 중에 연결납세방식을 적용받으면 그 사업연도 개시일부터 연결사업연도 개시일 전날까지를 1사업연도로 본다.","c":"상","v":1},"공인회2017_52-05-5":{"w":"법인세법 시행령 제8조 제3항은 납세지 지정통지를 그 법인의 해당 사업연도 종료일부터 45일 이내에 하도록 정한다. 기한 내에 통지하지 않으면 종전 납세지가 그대로 납세지다(같은 조 제4항).","c":"상","v":1},"공인회2019_54-06-1":{"w":"법인세법 제8조 제3항은 사업연도 중에 제78조 각 호에 따른 조직변경(상법상 조직변경 등)을 하면 조직변경 전의 사업연도가 계속되는 것으로 본다. 해산 의제에서도 조직변경은 빠진다(같은 조 제1항).","c":"상","v":1},"공인회2019_54-06-2":{"w":"법인세법 제8조 제5항은 사업연도 중에 연결납세방식을 적용받으면 사업연도 개시일부터 연결사업연도 개시일 전날까지를 1사업연도로 본다.","c":"상","v":1},"공인회2019_54-06-3":{"w":"법인세법 제7조 제1항은 사업연도를 변경하려는 법인이 직전 사업연도 종료일부터 3개월 이내에 관할 세무서장에게 신고하도록 정한다.","c":"상","v":1},"공인회2019_54-06-4":{"w":"법인세법 제9조 제3항은 둘 이상의 국내사업장이 있는 외국법인의 납세지를 주된 사업장의 소재지로 정한다. 주된 사업장은 직전 사업연도 사업수입금액이 가장 많은 사업장이다(같은 법 시행령 제7조 제2항·제3항).","c":"상","v":1},"공인회2020_55-06-1":{"w":"법인세법 시행령 제2조 제2항은 본점·주사무소가 외국에 있고 실질적 관리장소가 국내에 없는 단체 중 구성원이 유한책임사원으로만 구성된 단체를 외국법인으로 본다.","c":"상","v":1},"공인회2020_55-06-2":{"w":"법인세법 제3조 제2항은 국가와 지방자치단체(지방자치단체조합 포함)에 법인세 납부의무가 없다고 정한다. 그래서 비사업용 토지를 양도해도 토지등 양도소득에 대한 법인세를 내지 않는다.","c":"상","v":1},"공인회2020_55-06-3":{"w":"법인세법 제4조 제3항은 비영리내국법인의 각 사업연도 소득을 같은 항 각 호의 수익사업이나 수입에서 생기는 소득으로 한정한다.","c":"상","v":1},"공인회2020_55-06-5":{"w":"법인세법 제76조의8 제1항은 완전모법인과 완전자법인이 연결납세방식을 적용받으려면 완전모법인의 납세지 관할 지방국세청장의 승인을 받도록 정한다.","c":"상","v":1},"공인회2020_55-07-1":{"w":"법인세법 시행령 제106조 제1항 제1호 라목은 사외유출된 금액의 귀속자가 주주·임직원·법인·사업자(배당·상여·기타사외유출 대상) 외의 자이면 그 귀속자에 대한 기타소득으로 처분한다.","c":"상","v":1},"공인회2020_55-07-2":{"w":"법인세법 시행령 제106조 제1항 제2호는 익금산입액이 사외로 유출되지 않았으면 사내유보로 처분하도록 정한다. 순자산에 영향이 없는 경우는 실무상 기타로 처분한다.","c":"상","v":1},"공인회2020_55-07-3":{"w":"법인세법 시행령 제106조 제1항 제3호 아목은 귀속불분명으로 대표자 상여 처분한 소득세 등을 법인이 대납하고 손비로 계상해 익금산입한 금액을 기타사외유출로 처분한다.","c":"상","v":1},"공인회2020_55-07-4":{"w":"추계결정한 과세표준과 당기순이익의 차액(법인세상당액을 빼지 않은 금액)은 대표자 상여가 원칙이지만 천재지변 등으로 장부가 멸실된 법인세법 제68조 단서의 경우는 기타사외유출로 처분한다(같은 법 시행령 제106조 제2항).","c":"상","v":1},"공인회2020_55-09-2":{"w":"법인세법 제15조 제2항 제1호는 특수관계인인 개인으로부터 유가증권을 시가보다 낮은 가액으로 매입한 경우 시가와 매입가액의 차액을 익금으로 본다.","c":"상","v":1},"공인회2020_55-09-3":{"w":"법인세법 시행령 제11조 제1호는 사업수입금액을 익금으로 하되 기업회계기준에 따른 매출에누리와 매출할인은 빼도록 정한다.","c":"상","v":1},"공인회2020_55-09-4":{"w":"자기주식소각이익을 소각일부터 2년 이내에 자본에 전입하면 과세되지 않는 잉여금에서 제외되므로(법인세법 시행령 제12조 제1항 제2호) 주주가 받는 무상주는 법인세법 제16조 제1항 제2호의 의제배당으로 익금에 산입한다.","c":"상","v":1},"공인회2020_55-09-5":{"w":"법인세는 손금불산입 항목이므로 환급금은 법인세법 제18조 제3호로, 국세 과오납금 환급금에 대한 이자는 같은 조 제4호로 익금에 산입하지 않는다.","c":"상","v":1},"공인회2021_56-16-1":{"w":"법인세법 제75조의12 제4항은 법인과세 신탁재산의 법인세 납세지를 그 법인과세 수탁자의 납세지로 정한다.","c":"상","v":1},"공인회2021_56-16-2":{"w":"법인세법 제75조의13 제1항은 둘 이상의 수탁자가 있으면 신탁사무를 주로 처리하는 수탁자로 신고한 대표수탁자가 법인세를 납부하도록 정한다. 다른 수탁자는 연대납부의무를 진다(같은 조 제2항).","c":"상","v":1},"공인회2021_56-16-4":{"w":"법인세법 제18조의2 제2항 제5호는 제75조의14에 따라 배당 소득공제를 받는 법인과세 신탁재산으로부터 받은 수입배당금에 익금불산입을 적용하지 않는다. 신탁재산 단계에서 이미 과세되지 않았기 때문이다.","c":"상","v":1},"공인회2021_56-16-5":{"w":"법인세법 제109조 제1항은 내국법인이 설립등기일(법인과세 신탁재산은 설립일)부터 2개월 이내에 법인설립신고를 하도록 정한다. 법인과세 신탁재산은 신탁이 설정된 날 설립된 것으로 본다(같은 법 제75조의12 제1항).","c":"상","v":1},"공인회2021_56-17-1":{"w":"자기주식 소각으로 생긴 감자차익은 자본거래로 생긴 이익이어서 법인세법 제17조 제1항 제4호에 따라 익금불산입한다. 회사 순자산에 변동이 없으므로 소득처분은 기타다.","c":"상","v":1},"공인회2021_56-17-2":{"w":"법률에 따르지 않은 임의 재평가이익은 법인세법 제18조 제1호의 평가이익이라 익금이 아니다. 기타포괄손익으로 자본에 계상된 금액을 익금산입(기타)하고 자산 증가분을 익금불산입(△유보)해 상계한다.","c":"상","v":1},"공인회2021_56-17-3":{"w":"공정가치측정 금융자산 평가이익은 법인세법 제42조가 인정하는 평가가 아니어서 익금이 아니다(같은 법 제18조 제1호). 기타포괄손익 계상분을 익금산입(기타)하고 자산 증가분을 익금불산입(△유보)한다.","c":"상","v":1},"공인회2021_56-17-4":{"w":"이익잉여금의 자본전입으로 받은 무상주는 법인세법 제16조 제1항 제2호의 의제배당이다. 장부에 없으므로 1,500,000원을 익금산입(유보)하고 수입배당금 익금불산입액 450,000원은 같은 법 제18조의2에 따라 익금불산입(기타)한다.","c":"상","v":1},"공인회2022_57-16-1":{"w":"법인세법 제7조 제1항은 사업연도 변경신고를 직전 사업연도 종료일부터 3개월 이내에 하도록 정한다.","c":"상","v":1},"공인회2022_57-16-2":{"w":"법인세법 제6조 제4항은 국내사업장이 없는 외국법인으로서 국내원천 부동산소득(제93조 제3호)이나 부동산등양도소득(제7호)이 있는 법인이 그 소득이 최초로 발생한 날부터 1개월 이내에 사업연도를 신고하도록 정한다.","c":"상","v":1},"공인회2022_57-16-4":{"w":"법인세법 제9조 제4항과 같은 법 시행령 제7조 제6항 제1호는 원천징수의무자가 개인이면 소득세법 제7조 제1항 제1호·제2호의 소재지를 납세지로 한다. 거주자는 주된 사업장, 사업장이 없으면 주소지 또는 거소지다.","c":"상","v":1},"공인회2022_57-16-5":{"w":"법인세법 제11조 제1항은 납세지가 변경되면 변경된 날부터 15일 이내에 변경 후의 납세지 관할 세무서장에게 신고하도록 정한다.","c":"상","v":1},"공인회2022_57-29-1":{"w":"법인세법 제83조는 청산소득에 대한 법인세를 청산소득 과세표준에 제55조 제1항의 각 사업연도 소득 세율을 적용해 계산하도록 정한다.","c":"상","v":1},"공인회2024_59-12-1":{"w":"신고를 하지 않으면 매년 1월 1일부터 12월 31일까지가 사업연도이고(법인세법 제6조 제5항) 외국법인의 최초사업연도 개시일은 국내사업장을 가지게 된 날이다(같은 법 시행령 제4조 제1항 제2호).","c":"상","v":1},"공인회2024_59-12-2":{"w":"직전 사업연도 종료일(2023년 12월 31일)부터 3개월이 지난 뒤 신고했으므로 2024 사업연도는 변경되지 않는다(법인세법 제7조 제2항). 변경은 2025년부터 적용되어 종전 개시일인 2025년 1월 1일부터 변경 사업연도 개시 전날인 6월 30일까지가 1사업연도다(같은 조 제3항).","c":"상","v":1},"공인회2024_59-12-3":{"w":"법인세법 시행령 제4조 제2항은 최초사업연도 개시일 전에 생긴 손익을 사실상 법인에 귀속시킨 경우 조세포탈 우려가 없으면 최초사업연도가 1년을 넘지 않는 범위에서 최초사업연도 손익에 산입할 수 있게 한다.","c":"상","v":1},"공인회2024_59-12-4":{"w":"법인세법 제7조 제3항은 사업연도가 변경되면 종전 사업연도 개시일부터 변경된 사업연도 개시일 전날까지를 1사업연도로 하고 그 기간이 1개월 미만이면 변경된 사업연도에 포함한다고 정한다.","c":"상","v":1},"공인회2024_59-13-2":{"w":"법인세법 제62조의2 제1항은 수익사업(사업소득)을 하지 않는 비영리내국법인이 토지·건물·주식 등을 양도한 소득에 대해 과세표준 신고를 하지 않고 소득세법을 준용해 계산한 세액을 법인세로 낼 수 있게 한다(같은 조 제2항).","c":"상","v":1},"공인회2024_59-13-3":{"w":"법인세법 제2조 제4호는 비영리외국법인을 외국법인 중 외국의 정부·지방자치단체와 영리를 목적으로 하지 않는 법인(법인으로 보는 단체 포함)으로 정의한다.","c":"상","v":1},"공인회2024_59-13-4":{"w":"법인세법 제4조 제3항 제5호는 유형자산·무형자산 처분 수입을 비영리내국법인의 수익사업 수입에 넣되 고유목적사업에 직접 사용한 자산의 처분 수입을 빼고 같은 법 시행령 제3조 제2항은 그 기준을 처분일 현재 3년 이상 계속 직접 사용한 경우로 정한다.","c":"상","v":1},"공인회2024_59-13-5":{"w":"법인세법 제4조 제1항 단서는 비영리내국법인의 과세소득을 각 사업연도 소득과 토지등 양도소득으로 한정한다. 청산소득은 과세 대상이 아니다.","c":"상","v":1},"공인회2025_60-16-1":{"w":"법인세법 제6조 제4항은 국내사업장이 없는 외국법인으로서 국내원천 부동산소득이나 부동산등양도소득이 있는 법인이 소득이 최초로 발생한 날부터 1개월 이내에 사업연도를 신고하도록 정한다.","c":"상","v":1},"공인회2025_60-16-3":{"w":"법인세법 제7조 제1항은 사업연도 변경신고를 직전 사업연도 종료일부터 3개월 이내에 하도록 정한다.","c":"상","v":1},"공인회2025_60-16-4":{"w":"법인세법 제8조 제7항은 국내사업장이 없는 외국법인에 국내원천 부동산소득이나 부동산등양도소득이 더 이상 발생하지 않게 되어 그 사실을 신고하면 사업연도 개시일부터 신고일까지를 1사업연도로 본다.","c":"상","v":1},"공인회2025_60-16-5":{"w":"법인세법 제10조 제1항은 관할지방국세청장이나 국세청장이 납세지가 적당하지 않다고 인정되는 경우로서 시행령 제8조 제1항의 사유가 있으면 납세지를 지정할 수 있게 한다.","c":"상","v":1},"공인회2026_61-16-1":{"w":"법인세법 시행령 제106조 제1항 각 호 외의 부분 후단은 소득처분 규정을 비영리내국법인과 비영리외국법인에도 똑같이 적용한다고 정한다.","c":"상","v":1},"공인회2026_61-16-2":{"w":"법인세법 시행령 제106조 제1항 제1호 다목은 귀속자가 법인이거나 사업을 하는 개인이고 그 이익이 거주자의 사업소득 등을 구성하면 기타사외유출로 처분한다.","c":"상","v":1},"공인회2026_61-16-3":{"w":"법인세법 시행령 제106조 제1항 제3호 가목은 특례기부금(법인세법 제24조 제2항 제1호)과 일반기부금의 손금산입한도 초과액을 기타사외유출로 처분한다.","c":"상","v":1},"공인회2026_61-16-4":{"w":"법인세법 시행령 제106조 제1항 제1호 라목은 사외유출 귀속자가 주주·임직원·법인·사업자 외의 자이면 그 귀속자에 대한 기타소득으로 처분한다.","c":"상","v":1},"공인회2016_51-08-4":{"w":"급여지급기준 초과 상여금의 손금불산입은 임원에게만 적용된다(법인세법 시행령 제43조 제2항). 직원에게 지급한 상여금은 이익처분에 의한 것이 아니면 기준을 넘어도 손금이다.","c":"상","v":1},"공인회2018_53-11-4":{"w":"법인세법 시행령 제22조 제1항 제3호와 같은 법 시행규칙 제11조 제1호는 부가가치세법 제36조의 영수증을 받은 거래분에 포함된 매입세액으로서 공제대상이 아닌 금액을 손금에 산입하도록 정한다.","c":"상","v":1},"공인회2021_56-20-1":{"w":"법인세법 시행령 제19조 제18호는 특정인에게 기증한 광고선전 물품(개당 3만원 이하 물품 제외)의 구입비용을 연간 5만원 이내에서 손비로 인정한다.","c":"상","v":1},"공인회2021_56-20-2":{"w":"법인세법 시행령 제48조 제1항 제1호는 출자로 특정사업을 공동 영위하는 경우 출자총액 중 해당 법인 출자비율에 따른 분담금액을 초과하는 공동경비를 손금에 산입하지 않는다.","c":"상","v":1},"공인회2021_56-20-4":{"w":"개별소비세 과세대상 승용자동차의 유지 관련 매입세액은 부가가치세법 제39조 제1항 제5호로 공제받지 못하지만 법인세법 시행령 제22조 제1항 제1호가 이를 손금으로 인정한다.","c":"상","v":1},"공인회2021_56-20-5":{"w":"법인세법 시행령 제50조 제1항 제5호는 노동조합 및 노동관계조정법 제24조 제2항·제4항을 위반하여 지급하는 급여를 업무와 관련 없는 지출로 보아 손금에 산입하지 않는다(법인세법 제27조).","c":"상","v":1},"공인회2025_60-06-3":{"w":"지분법손실은 기업회계상 평가손실이고 법인세법 제42조가 인정하는 평가가 아니므로 손금이 아니다(법인세법 제22조). 비용처리한 2,000만원을 손금불산입(유보)하는 세무조정이 필요하다.","c":"상","v":1},"공인회2026_61-17-1":{"w":"법인세법 시행령 제48조 제1항 제1호는 출자로 특정사업을 공동 영위하는 경우 출자총액 중 해당 법인 출자비율에 따른 분담금액을 초과하는 공동경비를 손금에 산입하지 않는다.","c":"상","v":1},"공인회2026_61-17-2":{"w":"법인세법 시행령 제19조 제1호의2는 판매한 상품·제품의 보관료·포장비·운반비·판매장려금·판매수당 등 판매 부대비용을 손비로 정하고 판매장려금·판매수당은 사전약정이 없어도 인정한다.","c":"상","v":1},"공인회2026_61-17-3":{"w":"법인세법 시행령 제19조 제3호의2는 임원 또는 직원의 출산·양육 지원을 위해 공통적으로 적용되는 지급기준에 따라 지급하는 금액을 손비로 정한다.","c":"상","v":1},"공인회2026_61-17-4":{"w":"법인세법 시행령 제19조 제17호는 여러 사람이 볼 수 있는 공간에 항상 전시하는 미술품을 취득한 사업연도에 손비로 계상하면 거래단위별 취득가액 1천만원 이하인 것에 한해 손금으로 인정한다.","c":"상","v":1},"공인회2016_51-11-1":{"w":"법인이 받는 이자는 결산 때 경과분을 수익으로 계상하면 그 사업연도 익금이 되지만 원천징수되는 이자는 이 특례에서 빠진다(법인세법 시행령 제70조 제1항 제1호 단서). 정기예금 미수이자는 원천징수 대상이므로 익금불산입(△유보)한다.","c":"상","v":1},"공인회2016_51-11-2":{"w":"법인세법 시행령 제70조 제1항 제2호 단서는 결산 때 이미 경과한 기간에 대응하는 지급이자를 비용으로 계상하면 그 사업연도 손금으로 인정한다(차입일부터 이자지급일이 1년을 넘는 특수관계인 거래는 제외).","c":"상","v":1},"공인회2016_51-11-3":{"w":"파산한 법인의 주식은 장부가액을 감액할 수 있으나(법인세법 제42조 제3항 제3호 라목) 발행법인별 시가 총액이 1천원 이하이면 1천원을 시가로 본다(같은 법 시행령 제78조 제3항 제3호). 시가 0원이라도 1,000원은 손금불산입한다.","c":"상","v":1},"공인회2016_51-11-4":{"w":"법인세법 시행령 제68조 제6항은 장기할부 판매채권을 기업회계기준에 따라 현재가치로 평가해 현재가치할인차금을 계상하면 그 할인차금 상당액을 채권 회수기간에 걸쳐 익금에 산입하도록 인정한다. 회계처리를 그대로 따르므로 세무조정이 없다.","c":"상","v":1},"공인회2016_51-13-2":{"w":"주식배당으로 받은 주식은 법인세법 시행령 제14조 제1항 제1호 다목에 따라 발행금액으로 평가한다. 1,000주×발행가액 10,000원=1천만원이 배당금액이자 취득가액이다.","c":"상","v":1},"공인회2016_51-13-3":{"w":"장기할부 취득 채무를 현재가치로 평가해 현재가치할인차금을 계상한 경우에만 그 할인차금을 취득가액에서 뺀다(법인세법 시행령 제72조 제4항 제1호). 명목가액 3천만원으로 계상했으므로 세무상 취득가액도 3천만원이다.","c":"상","v":1},"공인회2016_51-13-4":{"w":"특수관계인인 개인으로부터 저가매입한 차액을 익금으로 보는 규정은 유가증권에만 적용된다(법인세법 제15조 제2항 제1호). 토지는 매입가액 10억원이 취득가액이다(같은 법 시행령 제72조 제2항 제1호).","c":"상","v":1},"공인회2016_51-13-5":{"w":"사업용 유형자산의 건설·매입에 든 특정차입금 이자(건설자금이자)는 손금에 산입하지 않고(법인세법 제28조 제1항 제3호) 자산 취득가액에 포함한다(같은 법 시행령 제72조 제3항 제2호). 토지 취득가액은 10억 1천만원이다.","c":"상","v":1},"공인회2017_52-07-1":{"w":"법인세법 시행령 제72조 제2항 제8호는 매입·제조·합병 등 각 호에 해당하지 않는 방법으로 취득한 자산의 취득가액을 취득 당시의 시가로 정한다. 교환으로 취득한 자산이 여기에 해당한다.","c":"상","v":1},"공인회2017_52-07-2":{"w":"법인세법 시행령 제72조 제3항 제3호는 유형자산과 함께 매입한 국·공채의 매입가액과 현재가치 차액을 기업회계기준에 따라 유형자산 취득가액으로 계상한 금액을 취득가액에 포함한다.","c":"상","v":1},"공인회2017_52-07-4":{"w":"법인세법 시행령 제74조 제4항은 신고한 평가방법 외의 방법으로 평가하면 선입선출법으로 평가하되 신고방법으로 평가한 가액이 더 크면 그 가액으로 평가하도록 한다. 결국 둘 중 큰 금액이다.","c":"상","v":1},"공인회2017_52-07-5":{"w":"법인세법 시행령 제72조 제4항 제1호는 장기할부 취득 채무를 기업회계기준에 따라 현재가치로 평가해 계상한 현재가치할인차금을 취득가액에 포함하지 않는다고 정한다.","c":"상","v":1},"공인회2017_52-11-1":{"w":"법인세법 시행령 제68조 제1항 제5호는 증권시장에서 보통거래방식으로 한 유가증권 매매의 손익 귀속시기를 매매계약을 체결한 날로 정한다.","c":"상","v":1},"공인회2018_53-08-2":{"w":"채무를 출자전환하면서 발행가액이 시가를 넘는 부분은 주식발행액면초과액에서 빠지고(법인세법 제17조 제1항 제1호 단서) 채무면제이익이 된다. 1억원-시가 7천만원=3천만원을 익금산입하는 세무조정이 필요하다.","c":"상","v":1},"공인회2018_53-08-4":{"w":"발행주식 1%를 가진 임원은 소액주주등(1% 미만)이 아니다. 이런 출자임원이 업무와 무관하게 쓰는 사택의 유지관리비는 업무무관비용으로 손금불산입(상여)한다(법인세법 제27조, 같은 법 시행령 제50조 제1항 제1호).","c":"상","v":1},"공인회2018_53-08-5":{"w":"단기금융자산의 세무상 취득가액은 매입가액뿐이다(법인세법 시행령 제72조 제2항 제5호의2). 취득가액에 넣은 거래원가 1천만원을 손금산입(△유보)하는 세무조정이 필요하다.","c":"상","v":1},"공인회2018_53-12-3":{"w":"법인세법 시행령 제29조의2 제1항은 기준내용연수의 50% 이상 지난 중고자산을 다른 법인 등에서 취득하면 기준내용연수의 50%에 상당하는 연수(1년 미만 버림)와 기준내용연수 사이에서 신고한 연수를 내용연수로 할 수 있게 한다. 기준내용연수 5년이면 2년부터 5년까지다.","c":"상","v":1},"공인회2019_54-11-1":{"w":"법인세법 시행령 제71조 제3항은 상환할 사채금액에서 사채발행가액을 뺀 사채할인발행차금을 기업회계기준의 상각방법에 따라 손금에 산입하도록 정한다.","c":"상","v":1},"공인회2019_54-11-2":{"w":"법인세법 시행령 제68조 제2항 단서는 중소기업이 장기할부조건으로 판매·양도한 경우 결산 처리와 관계없이 회수하였거나 회수할 금액과 대응 비용을 각 사업연도 익금·손금에 산입할 수 있게 한다.","c":"상","v":1},"공인회2019_54-11-3":{"w":"법인세법 제42조 제3항 제3호 가목과 같은 법 시행령 제78조 제2항 제1호 가목은 주권상장법인 주식의 발행법인이 부도나면 장부가액을 감액할 수 있게 한다. 시가는 발행법인별 총액이 1천원 이하면 1천원으로 한다(같은 조 제3항 제3호).","c":"상","v":1},"공인회2019_54-11-5":{"w":"법인세법 시행령 제72조 제4항 제1호는 장기할부 취득 채무를 현재가치로 평가해 계상한 현재가치할인차금을 취득가액에 포함하지 않는다고 정한다.","c":"상","v":1},"공인회2020_55-13-2":{"w":"건설 등 용역 손익은 작업진행률 기준이 원칙이지만 법인세법 시행령 제69조 제1항 제1호는 중소기업의 계약기간 1년 미만 건설 등은 인도일이 속하는 사업연도 익금으로 할 수 있게 한다.","c":"상","v":1},"공인회2020_55-13-3":{"w":"법인세법 시행령 제71조 제2항은 영수증을 발급할 수 있는 업종의 법인이 금전등록기를 설치·사용하면 물품대금과 용역대가의 귀속을 실제로 수입된 사업연도로 할 수 있게 한다.","c":"상","v":1},"공인회2020_55-13-4":{"w":"법인세법 시행령 제68조 제2항 단서는 중소기업의 장기할부 판매·양도에 대해 결산상 회계처리와 관계없이 회수기일도래기준으로 익금과 손금을 산입할 수 있게 한다.","c":"상","v":1},"공인회2020_55-13-5":{"w":"법인세법 시행령 제71조 제1항 단서는 결산 때 이미 경과한 기간에 대응하는 임대료와 비용을 수익·손비로 계상하면 그 사업연도 익금·손금으로 인정한다.","c":"상","v":1},"공인회2022_57-22-1":{"w":"법인세법 시행령 제69조 제1항 제1호는 중소기업이 수행하는 계약기간 1년 미만 건설 등의 수익을 목적물 인도일이 속하는 사업연도 익금으로 할 수 있게 한다.","c":"상","v":1},"공인회2022_57-22-2":{"w":"법인세법 시행령 제68조 제2항 단서는 중소기업이 장기할부조건으로 자산을 판매·양도하면 각 사업연도에 회수하였거나 회수할 금액을 그 사업연도 익금에 산입할 수 있게 한다.","c":"상","v":1},"공인회2022_57-22-4":{"w":"법인세법 시행령 제71조 제3항은 사채할인발행차금(상환할 사채금액-발행가액)을 기업회계기준의 상각방법에 따라 손금에 산입하도록 정한다.","c":"상","v":1},"공인회2022_57-22-5":{"w":"금융보험업 법인의 보험료는 실제로 수입된 날이 귀속시기지만 법인세법 시행령 제70조 제3항 단서는 결산 때 이미 경과한 기간에 대응하는 보험료를 수익으로 계상하면 그 사업연도 익금으로 한다.","c":"상","v":1},"공인회2023_58-12-1":{"w":"법인세법 제44조의3 제1항은 적격합병을 한 합병법인이 피합병법인 자산을 장부가액으로 양도받은 것으로 하고 장부가액과 시가의 차액을 자산별로 계상하도록 정한다(자산조정계정).","c":"상","v":1},"공인회2023_58-12-3":{"w":"법인세법 시행령 제31조 제7항 제1호는 시설 개체나 기술 낙후로 생산설비 일부를 폐기하면 장부가액에서 1천원을 뺀 금액을 폐기일이 속하는 사업연도 손금에 산입할 수 있게 한다.","c":"상","v":1},"공인회2023_58-12-4":{"w":"법인세법 시행령 제75조 제1항은 유가증권을 총평균법·이동평균법 중 신고한 방법으로 평가하고 채권은 개별법도 선택할 수 있게 한다.","c":"상","v":1},"공인회2023_58-12-5":{"w":"특수관계인인 개인에게서 유가증권을 저가매입한 차액은 익금이고(법인세법 제15조 제2항 제1호) 이 금액은 취득가액에 포함한다(같은 법 시행령 제72조 제3항 제1호). 나중에 처분할 때 이중과세를 막기 위해서다.","c":"상","v":1},"공인회2024_59-09-1":{"w":"법인세법 시행령 제69조 제2항과 같은 법 시행규칙 제34조는 장부가 없어 총공사비누적액을 확인할 수 없는 등 작업진행률을 계산할 수 없는 경우 목적물 인도일이 속하는 사업연도의 익금과 손금에 산입하도록 정한다.","c":"상","v":1},"공인회2024_59-09-3":{"w":"법인세법 시행령 제71조 제1항 단서는 임대료 지급기간이 1년을 넘으면 지급일과 관계없이 이미 경과한 기간에 대응하는 임대료와 비용을 그 사업연도 익금·손금으로 정한다.","c":"상","v":1},"공인회2024_59-09-4":{"w":"법인세법 시행령 제68조 제2항 단서는 중소기업의 장기할부 판매·양도에 대해 회수하였거나 회수할 금액과 대응 비용을 각 사업연도 익금·손금에 산입할 수 있게 한다.","c":"상","v":1},"공인회2024_59-09-5":{"w":"법인세법 시행령 제71조 제6항은 목적물을 인도하지 않고 가액변동 차액을 금전으로 정산하는 파생상품 손익의 귀속시기를 그 거래에서 정한 대금결제일로 정한다.","c":"상","v":1},"공인회2025_60-11-1":{"w":"법인세법 시행령 제72조 제2항 제4호 가목은 현물출자로 피출자법인을 새로 설립하면서 그 대가로 주식등만 받는 경우 출자법인이 취득한 주식의 취득가액을 현물출자한 순자산의 시가로 정한다.","c":"상","v":1},"공인회2025_60-11-2":{"w":"법인세법 시행령 제72조 제2항 제7호는 대기관리권역법에 따라 정부로부터 무상으로 할당받은 배출허용총량의 취득가액을 영(0)원으로 정한다.","c":"상","v":1},"공인회2025_60-11-4":{"w":"법인세법 시행령 제68조 제7항은 프로젝트금융투자회사가 택지개발사업 등 토지개발사업을 완료하기 전에 대상 토지 일부를 양도하면 그 양도대금을 작업진행률에 따라 각 사업연도 익금에 산입할 수 있게 한다.","c":"상","v":1},"공인회2025_60-11-5":{"w":"법인세법 시행령 제68조 제1항 제5호는 증권시장에서 보통거래방식으로 한 유가증권 매매의 손익 귀속시기를 매매계약을 체결한 날로 정한다.","c":"상","v":1},"공인회2026_61-18-1":{"w":"결산 때 계상한 경과이자라도 원천징수되는 이자는 계상한 사업연도 익금이 될 수 없다(법인세법 시행령 제70조 제1항 제1호 단서). 보통예금 미수이자는 원천징수 대상이므로 익금불산입(△유보)한다.","c":"상","v":1},"공인회2026_61-18-2":{"w":"임대료 지급일이 정해져 있고 지급기간이 1년을 넘지 않으면 지급일이 속하는 사업연도가 귀속시기다(법인세법 시행령 제71조 제1항 제1호). 10월분은 11월 5일, 11월분은 12월 5일에 받기로 했으므로 2026년 귀속은 두 달분이고 12월분은 2027년 1월 5일 귀속이다.","c":"상","v":1},"공인회2026_61-18-3":{"w":"중소기업은 결산상 회계처리와 관계없이 장기할부 판매대금을 회수기일도래기준으로 익금에 산입할 수 있다(법인세법 시행령 제68조 제2항 단서). 제26기 회수기일분 100만원만 익금이므로 나머지 200만원을 익금불산입(△유보)한다.","c":"중","v":1},"공인회2026_61-18-5":{"w":"법인이 받는 배당금은 소득세법 시행령 제46조의 수입시기, 곧 잉여금처분결의일이 속하는 사업연도의 익금이다(법인세법 시행령 제70조 제2항). 결의일이 2026년 2월 20일이므로 제26기 수익 계상이 맞아 세무조정이 없다.","c":"상","v":1},"공인회2016_51-15-5":{"w":"법인세법 제36조 제1항은 국고보조금을 받은 날이 속하는 사업연도 종료일까지 사업용자산 취득·개량에 사용하면 그 금액을 일시상각충당금이나 압축기장충당금으로 손금에 산입할 수 있게 한다.","c":"상","v":1},"공인회2016_51-19-1":{"w":"법인세법 제4조 제3항은 비영리내국법인의 수익사업에 소득세법상 이자소득(제2호)과 주식·출자지분 양도 수입(제4호)을 포함한다.","c":"상","v":1},"공인회2016_51-19-2":{"w":"법인세법 제29조 제5항 제4호는 손금에 산입한 사업연도 종료일 이후 5년이 되는 날까지 고유목적사업 등에 사용하지 않은 고유목적사업준비금 잔액을 익금에 산입하도록 정한다.","c":"상","v":1},"공인회2016_51-19-3":{"w":"법인세법 제29조 제3항은 고유목적사업 등에 지출한 금액을 먼저 계상한 준비금부터 차례로 상계하고 직전 사업연도 종료일 현재 준비금 잔액을 초과해 지출한 금액은 그 사업연도에 계상할 준비금에서 지출한 것으로 본다.","c":"상","v":1},"공인회2016_51-19-5":{"w":"법인세법 제62조의2 제1항·제2항은 수익사업(사업소득)을 하지 않는 비영리내국법인이 토지·건물 등의 양도소득에 대해 과세표준 신고를 하지 않고 소득세법을 준용해 계산한 세액을 법인세로 낼 수 있게 한다.","c":"상","v":1},"공인회2021_56-24-1":{"w":"법인세법 제29조 제4항은 준비금을 손금산입한 비영리내국법인이 모든 권리·의무를 다른 비영리내국법인에 포괄 양도하고 해산하면 해산등기일 현재 준비금 잔액을 그 법인이 승계할 수 있게 한다.","c":"상","v":1},"공인회2023_58-16-1":{"w":"민법상 소멸시효가 완성된 대여금·선급금은 법인세법 시행령 제19조의2 제1항 제4호의 대손사유이고 같은 조 제3항에 따라 결산 계상 여부와 관계없이 그 사유가 발생한 날이 속하는 사업연도 손금이 된다(신고조정).","c":"상","v":1},"공인회2023_58-16-2":{"w":"채무자 파산으로 회수할 수 없는 채권은 손비로 계상해야 손금이 되는 결산조정 대손이지만 법인세법 시행령 제19조의2 제4항은 합병·분할 시 합병등기일 등이 속하는 사업연도까지 계상하지 않은 이런 대손금을 그 사업연도의 손비로 하도록 정한다.","c":"상","v":1},"공인회2023_58-16-4":{"w":"법인세법 제34조 제3항은 대손금을 대손충당금과 먼저 상계하고 상계 후 남은 대손충당금은 다음 사업연도 소득금액 계산 때 익금에 산입하도록 정한다.","c":"상","v":1},"공인회2023_58-16-5":{"w":"동일인에 대한 매출채권과 매입채무가 함께 있어도 상계하지 않고 매출채권 전액에 대손충당금을 설정할 수 있고 당사자 약정으로 상계하기로 한 경우만 예외라는 것이 법인세법 기본통칙(34-61…)의 해석이다.","c":"중","v":1},"공인회2017_52-16-1":{"w":"법인세법 시행령 제88조 제1항 제3호 단서는 같은 영 제19조 제19호의2의 주식매수선택권(상법 등에 따라 발행주식총수 10% 범위에서 부여)의 행사로 주식을 저가 양도하는 경우를 부당행위계산에서 제외한다.","c":"상","v":1},"공인회2018_53-10-4":{"w":"천재지변 이재민을 위한 구호금품은 특례기부금이고(법인세법 제24조 제2항 제1호 라목) 특례기부금으로 제공한 현물은 장부가액으로 평가하므로(같은 법 시행령 제36조 제1항 제1호) 3억원이다.","c":"상","v":1},"공인회2018_53-15-1":{"w":"법인세법 시행규칙 제44조 제6호는 직원에 대한 월정급여액 범위의 일시적인 급료 가불금을 인정이자 계산 대상 가지급금에서 뺀다.","c":"상","v":1},"공인회2018_53-15-2":{"w":"인정이자는 가중평균차입이자율이 원칙이지만 특수관계인이 아닌 자로부터 차입한 금액이 없는 등 가중평균차입이자율을 적용할 수 없으면 당좌대출이자율을 시가로 한다(법인세법 시행령 제89조 제3항 제1호).","c":"상","v":1},"공인회2018_53-15-3":{"w":"법인세법 시행규칙 제44조 제5호는 귀속불분명으로 대표자 상여처분한 금액의 소득세를 법인이 내고 가지급금으로 계상한 금액(특수관계 소멸 시까지 기간분)을 인정이자 계산 대상에서 뺀다.","c":"상","v":1},"공인회2018_53-15-5":{"w":"법인세법 시행규칙 제44조 제2호는 국외투자법인 종사자의 여비·급료 등을 내국법인이 대신 부담하고 가지급금으로 계상한 금액(실제로 환부받을 때까지 기간분)을 인정이자 계산 대상에서 뺀다.","c":"상","v":1},"공인회2020_55-16-1":{"w":"법인세법 시행령 제89조 제2항 제1호는 시가가 불분명하면 감정평가법인등의 감정가액을 적용하고 감정가액이 둘 이상이면 평균액으로 하되 주식등과 가상자산은 제외한다.","c":"상","v":1},"공인회2020_55-16-2":{"w":"법인세법 시행령 제89조 제3항 제2호는 법인세 신고와 함께 당좌대출이자율을 시가로 선택하면 그 사업연도와 이후 2개 사업연도에 당좌대출이자율을 시가로 한다.","c":"상","v":1},"공인회2020_55-16-4":{"w":"법인세법 시행령 제88조 제2항은 부당행위계산 부인을 그 행위 당시를 기준으로 법인과 특수관계인 간 거래에 적용하도록 정한다. 출연금 대신 부담(같은 조 제1항 제5호)도 여기에 해당한다.","c":"상","v":1},"공인회2020_55-16-5":{"w":"법인세법 시행령 제88조 제3항은 고가매입·저가양도 등은 시가와 거래가액의 차액이 3억원 이상이거나 시가의 5% 이상인 경우에만 부당행위계산 부인을 적용한다.","c":"상","v":1},"공인회2021_56-22-1":{"w":"채권자의 능력과 자산상태로 보아 금전을 대여한 것으로 인정할 수 없는 차입금은 채권자가 불분명한 사채로 보아 그 이자를 손금에 산입하지 않는다(법인세법 제28조 제1항 제1호, 같은 법 시행령 제51조 제1항 제2호).","c":"상","v":1},"공인회2021_56-22-2":{"w":"법인세법 시행령 제52조 제2항은 특정차입금 이자를 건설 준공일까지 자본적 지출로 원본에 가산하되 특정차입금의 일시예금에서 생긴 수입이자는 차감하도록 정한다.","c":"상","v":1},"공인회2021_56-22-3":{"w":"업무무관자산의 가액은 취득가액으로 하며 특수관계인으로부터 시가를 초과해 취득한 경우 그 시가초과액을 포함한다(법인세법 시행령 제53조 제3항).","c":"상","v":1},"공인회2021_56-22-4":{"w":"법인세법 시행규칙 제44조 제7호의2는 중소기업 직원(지배주주등 제외)에 대한 주택구입·전세자금 대여액을 업무무관 가지급금에서 뺀다.","c":"상","v":1},"공인회2023_58-10-1":{"w":"법인세법 시행령 제35조 제1호는 특수관계인 외의 자에게 정당한 사유 없이 정상가액(시가±30%)보다 낮은 가액으로 양도한 경우 그 차액을 기부금으로 본다(법인세법 제24조 제1항).","c":"상","v":1},"공인회2023_58-10-3":{"w":"법인세법 제24조 제2항 제1호 라목은 천재지변(특별재난지역 선포 사유가 된 재난 포함)으로 생기는 이재민을 위한 구호금품을 특례기부금으로 정한다.","c":"상","v":1},"공인회2023_58-10-4":{"w":"법인세법 제24조 제5항은 일반기부금 한도초과액을 다음 사업연도 개시일부터 10년 이내 끝나는 사업연도로 이월해 한도 범위에서 손금에 산입하게 한다.","c":"상","v":1},"공인회2023_58-10-5":{"w":"기부금은 현금주의로 귀속시킨다. 법인세법 시행령 제36조 제3항은 지출한 기부금을 이연계상하면 지출한 사업연도의 기부금으로 하고 그 후 사업연도에는 기부금으로 보지 않는다.","c":"상","v":1},"공인회2023_58-17-1":{"w":"법인세법 시행령 제2조 제8항 제7호는 공정거래법상 기업집단에 속하는 법인이면 그 기업집단에 소속된 다른 계열회사와 그 임원을 특수관계인으로 정한다.","c":"상","v":1},"공인회2025_60-12-2":{"w":"법인세법 시행령 제51조 제2항은 채권자가 불분명한 사채이자에 알선수수료·사례금 등 명목에 관계없이 사채를 차입하고 지급하는 금품을 포함한다.","c":"상","v":1},"공인회2025_60-12-3":{"w":"법인세법 시행규칙 제28조 제2항은 동일인에 대한 가지급금과 가수금은 상계해 적수를 계산하되 발생 시 각각 상환기간·이자율 약정이 있어 상계할 수 없으면 상계하지 않도록 정한다.","c":"상","v":1},"공인회2025_60-12-4":{"w":"법인세법 시행령 제72조 제6항은 장기할부 취득 채무의 현재가치할인차금 상각액에 지급이자 손금불산입(법인세법 제28조)과 원천징수 규정을 적용하지 않도록 정한다.","c":"상","v":1},"공인회2025_60-12-5":{"w":"법인세법 시행령 제52조 제4항은 특정차입금의 연체로 생긴 이자를 원본에 가산하면 그 금액을 해당 사업연도의 자본적 지출로 하고 그 원본가산액에 대한 지급이자는 손금으로 하도록 정한다.","c":"상","v":1},"공인회2026_61-06-1":{"w":"법인세법 제25조 제1항은 기업업무추진비를 접대·교제·사례 등 명목과 관계없이 직접 또는 간접적으로 업무와 관련 있는 자와 업무를 원활하게 진행하려고 지출한 금액으로 정의한다.","c":"상","v":1},"공인회2026_61-06-2":{"w":"법인세법 시행령 제40조 제2항은 직원이 조직한 조합·단체에 복리시설비를 지출한 경우 그 조합·단체가 법인이면 기업업무추진비로 보고 법인이 아니면 법인의 경리 일부로 본다.","c":"상","v":1},"공인회2026_61-06-3":{"w":"법인세법 시행령 제42조 제6항은 기업업무추진비를 금전 외 자산으로 제공하면 제공한 때의 시가와 장부가액 중 큰 금액으로 평가하도록 정한다.","c":"상","v":1},"공인회2026_61-06-4":{"w":"법인세법 시행령 제35조 제2호는 특수관계인 외의 자로부터 정당한 사유 없이 정상가액보다 높은 가액으로 매입한 경우 그 차액을 실질적 증여로 보아 기부금으로 정한다.","c":"상","v":1},"공인회2016_51-18-2":{"w":"법인세법 제72조 제1항은 중소기업 결손금 소급공제 환급액을 직전 사업연도 법인세액(토지등 양도소득에 대한 법인세 제외) 한도로 정한다.","c":"상","v":1},"공인회2016_51-18-3":{"w":"법인세법 제58조 제1항은 천재지변 등 재해로 토지를 뺀 사업용자산 총액의 20% 이상을 상실해 납세가 곤란하면 재해손실세액공제를 하도록 정한다.","c":"상","v":1},"공인회2017_52-18-1":{"w":"법인세법 제64조 제2항은 납부할 세액이 1천만원을 초과하면 납부기한이 지난 날부터 1개월(중소기업은 2개월) 이내에 분납할 수 있게 한다.","c":"상","v":1},"공인회2017_52-18-3":{"w":"미환류소득에 대한 법인세(조세특례제한법 제100조의32 제1항)는 지금 상호출자제한기업집단에 속하는 내국법인에만 적용된다. 중소기업은 자기자본 규모와 관계없이 과세대상이 아니다.","c":"상","v":1},"공인회2017_52-18-4":{"w":"법인세법 제60조 제5항은 재무상태표·포괄손익계산서·이익잉여금처분계산서(결손금처리계산서)와 세무조정계산서를 첨부하지 않으면 신고로 보지 않는다고 정한다(수익사업이 없는 비영리법인 제외).","c":"상","v":1},"공인회2017_52-18-5":{"w":"법인세법 제72조 제1항은 결손금 소급공제 환급을 중소기업에만 허용한다. 중소기업이 아닌 법인은 이월공제만 받는다.","c":"상","v":1},"공인회2019_54-16-2":{"w":"추계결정 때는 이월결손금 공제를 적용하지 않지만 법인세법 제68조 단서는 천재지변 등으로 장부가 멸실되어 추계하는 경우를 예외로 둔다.","c":"상","v":1},"공인회2020_55-19-1":{"w":"법인세법 제60조 제1항은 사업연도 종료일이 속하는 달의 말일부터 3개월 이내 신고를 원칙으로 하되 성실신고확인서를 제출하는 법인은 4개월 이내에 신고하도록 정한다.","c":"상","v":1},"공인회2020_55-19-3":{"w":"외부조정대상법인은 세무조정계산서를 조정반 소속 세무사 등이 작성해야 하고(법인세법 제60조 제9항) 세무조정계산서를 첨부하지 않은 신고는 신고로 보지 않으므로(같은 조 제5항) 무신고가산세 대상이다.","c":"상","v":1},"공인회2020_55-19-4":{"w":"법인세법 제69조 제1항은 신고를 하지 않고 본점 등을 이전하는 등 법인세를 포탈할 우려가 있다고 인정되면 관할 세무서장이 수시로 법인세를 부과할 수 있게 한다.","c":"상","v":1},"공인회2020_55-19-5":{"w":"추계결정 때는 외국납부세액공제(법인세법 제57조)를 적용하지 않지만 같은 법 제68조 단서가 천재지변 등으로 장부가 멸실된 경우를 예외로 둔다.","c":"상","v":1},"공인회2021_56-28-1":{"w":"법인세법 제51조는 공익신탁법에 따른 공익신탁 신탁재산에서 생기는 소득에 각 사업연도 소득에 대한 법인세를 과세하지 않는다고 정한다.","c":"상","v":1},"공인회2021_56-28-3":{"w":"법인세법 시행령 제95조 제5항은 재해손실세액공제를 받으려면 재해손실세액공제신청서를 정해진 기한까지 납세지 관할 세무서장에게 제출하도록 정한다.","c":"상","v":1},"공인회2021_56-28-4":{"w":"법인세법 시행령 제94조 제7항은 국외사업장이 둘 이상의 국가에 있으면 외국납부세액 공제한도를 국가별로 구분해 계산하도록 정한다.","c":"상","v":1},"공인회2021_56-28-5":{"w":"법인세법 시행령 제110조 제3항 단서는 결손금 일부만 소급공제받은 경우 결손금이 감소하면 소급공제받지 않은 결손금(이월공제분)이 먼저 감소된 것으로 본다.","c":"상","v":1},"공인회2022_57-27-5":{"w":"이월결손금 공제는 원칙적으로 각 사업연도 소득의 80% 한도지만 법인세법 제13조 제1항 단서와 같은 법 시행령 제10조 제1항 제1호는 법원이 인가한 회생계획을 이행 중인 법인에 100% 한도를 적용한다.","c":"상","v":1},"공인회2025_60-13-1":{"w":"법인세법 제63조 제4항은 중간예납세액이 1천만원을 초과하면 제64조 제2항을 준용해 분납할 수 있게 한다.","c":"상","v":1},"공인회2025_60-13-2":{"w":"법인세법 제63조 제1항 괄호는 합병·분할에 의하지 않고 새로 설립된 법인의 최초 사업연도를 중간예납 의무에서 뺀다.","c":"상","v":1},"공인회2025_60-13-3":{"w":"법인세법 제63조의2 제2항 제2호 다목은 분할신설법인과 분할합병 상대방 법인의 분할 후 최초 사업연도에는 해당 중간예납기간의 법인세액을 기준으로 하는 방법으로 계산하도록 정한다.","c":"상","v":1},"공인회2025_60-13-4":{"w":"법인세법 제63조의2 제5항은 중간예납기간 중 휴업 등으로 수입금액이 없는 법인은 그 사실이 확인되면 해당 중간예납기간 법인세를 징수하지 않도록 정한다.","c":"상","v":1},"공인회2026_61-14-3":{"w":"법인세법 제60조의2 제1항 단서는 주식회사 등의 외부감사에 관한 법률 제4조에 따라 감사인의 감사를 받은 내국법인은 성실신고확인서를 제출하지 않을 수 있게 한다.","c":"상","v":1},"공인회2017_52-15-2":{"w":"법인세법 제44조 제3항 제1호는 내국법인이 발행주식총수를 소유한 다른 법인을 합병하거나 그 법인에 합병되면 적격합병 요건을 갖추지 않아도 양도손익이 없는 것으로 할 수 있게 한다.","c":"상","v":1},"공인회2022_57-28-1":{"w":"법인세법 제44조 제2항 제1호는 합병등기일 현재 1년 이상 사업을 계속하던 내국법인 간의 합병을 적격합병 요건으로 정한다.","c":"상","v":1},"공인회2022_57-28-3":{"w":"법인세법 제44조 제2항 제3호는 합병법인이 합병등기일이 속하는 사업연도 종료일까지 피합병법인으로부터 승계받은 사업을 계속하는 것을 적격합병 요건으로 정한다.","c":"상","v":1},"공인회2022_57-28-4":{"w":"법인세법 제44조 제2항 각 호 외의 부분은 적격합병이면 피합병법인이 받은 양도가액을 합병등기일 현재 순자산 장부가액으로 보아 양도손익이 없는 것으로 할 수 있게 한다.","c":"상","v":1},"공인회2022_57-28-5":{"w":"법인세법 제44조의3 제1항은 적격합병을 한 합병법인이 피합병법인의 자산을 장부가액으로 양도받은 것으로 한다고 정한다.","c":"상","v":1},"공인회2023_58-19-1":{"w":"법인세법 제4조 제1항 단서는 비영리내국법인의 과세소득에서 청산소득을 빼고 같은 조 제4항은 외국법인의 과세소득을 국내원천소득과 토지등 양도소득으로 한정한다. 둘 다 청산소득 납세의무가 없다.","c":"상","v":1},"공인회2023_58-19-3":{"w":"법인세법 제79조 제6항은 청산기간에 생기는 각 사업연도의 소득금액을 청산소득이 아니라 그 법인의 각 사업연도 소득금액에 산입하도록 정한다.","c":"상","v":1},"공인회2023_58-19-4":{"w":"법인세법 제79조 제3항은 청산기간에 국세기본법에 따라 환급되는 법인세액이 있으면 해산등기일 현재 자기자본 총액에 가산하도록 정한다.","c":"상","v":1},"공인회2023_58-19-5":{"w":"법인세법 제78조는 특별법에 따라 설립된 법인이 그 특별법의 개정·폐지로 상법상 회사로 조직변경하는 경우 등에는 청산소득에 대한 법인세를 과세하지 않는다고 정한다.","c":"상","v":1},"공인회2024_59-15-2":{"w":"법인세법 제44조 제2항은 적격합병이면 피합병법인이 받은 양도가액을 합병등기일 현재 순자산 장부가액으로 보아 양도손익이 없는 것으로 할 수 있게 한다.","c":"상","v":1},"공인회2024_59-15-3":{"w":"법인세법 시행령 제80조 제2항은 피합병법인의 순자산 장부가액을 계산할 때 국세기본법에 따라 환급되는 법인세액을 더하도록 정한다.","c":"상","v":1},"공인회2024_59-15-4":{"w":"법인세법 제46조 제1항은 내국법인이 분할로 해산하면(물적분할 제외) 그 자산을 분할신설법인 등에 양도한 것으로 보아 양도손익을 분할등기일이 속하는 사업연도 소득에 산입하도록 정한다.","c":"상","v":1},"공인회2024_59-15-5":{"w":"법인세법 시행령 제80조의4 제1항은 적격합병 시 승계 자산·부채를 시가로 계상하되 시가가 장부가액보다 크면 차액을 익금산입하고 손금산입(자산조정계정)하며 작으면 차액을 손금산입하고 같은 금액을 자산조정계정으로 익금산입하도록 정한다.","c":"상","v":1},"공인회2025_60-14-4":{"w":"법인세법 시행령 제92조의2는 저당권 실행으로 취득하거나 채권변제 대신 취득한 주택으로서 취득일부터 3년이 지나지 않은 주택을 토지등 양도소득 과세대상 주택에서 뺀다. 2년 6개월 보유 후 양도했으므로 과세대상이 아니다.","c":"상","v":1},"공인회2026_61-15-2":{"w":"법인세법 제44조의3 제1항은 적격합병을 한 합병법인이 피합병법인의 자산을 장부가액으로 양도받은 것으로 한다고 정한다.","c":"상","v":1},"공인회2025_60-32-5":{"w":"국내 사업장에서 계약과 대가 수령이 이루어지고 국내에서 통관되지 않은 수출물품을 외국으로 인도하는 것도 수출에 해당하는 재화의 공급이다(부가가치세법 제21조 제2항 제2호, 같은 법 시행령 제31조 제1항). 영세율이 적용되지만 그 공급가액은 과세표준에 포함된다.","c":"중","v":1},"공인회2016_51-20-1":{"w":"국외에서 근무하는 공무원은 거소 기간과 관계없이 거주자로 본다(소득세법 시행령 제3조). 거주자는 국내외 모든 소득에 납세의무를 진다(소득세법 제3조 제1항).","c":"상","v":1},"공인회2016_51-20-2":{"w":"외국을 항행하는 선박 승무원은 생계를 같이하는 가족이 사는 장소가 국내에 있으면 주소가 국내에 있는 것으로 본다(소득세법 시행령 제2조 제5항). 그래서 거주자로서 국내외 원천소득에 납세의무를 진다.","c":"상","v":1},"공인회2016_51-20-4":{"w":"거주자가 된 날부터 국내외 모든 소득에, 그 전 비거주자 기간에는 국내원천소득에만 과세한다(소득세법 제3조, 같은 법 시행령 제2조의2 제1항). 한국 국적을 취득해 외국인 거주자 5년 특례도 적용되지 않는다.","c":"중","v":1},"공인회2016_51-20-5":{"w":"주한 외교관과 그 외교관과 같은 세대인 가족(대한민국 국민 제외)은 국내 주소 여부와 관계없이 비거주자로 본다는 것이 소득세법 기본통칙의 해석이다. 비거주자는 국내원천소득에만 과세된다(소득세법 제3조 제2항).","c":"중","v":1},"공인회2017_52-19-1":{"w":"소득세법 제3조 제1항 단서는 과세기간 종료일 10년 전부터 국내 주소·거소 기간 합계가 5년 이하인 외국인 거주자의 국외원천소득은 국내에서 지급되거나 국내로 송금된 것만 과세한다고 정한다.","c":"상","v":1},"공인회2017_52-19-2":{"w":"소득세법 시행령 제3조는 국외에서 근무하는 공무원을 거주자로 본다고 정한다.","c":"상","v":1},"공인회2017_52-19-3":{"w":"소득세법 제2조의2 제2항은 제44조에 따라 피상속인의 소득금액에 과세하는 경우 그 상속인이 납세의무를 진다고 정한다.","c":"상","v":1},"공인회2017_52-19-5":{"w":"소득세법 시행령 제4조 제3항 제2호는 거소 기간이 2과세기간에 걸쳐 계속하여 183일 이상이면 국내에 183일 이상 거소를 둔 것으로 본다.","c":"상","v":1},"공인회2019_54-20-1":{"w":"소득세법 제5조 제3항은 거주자가 주소 또는 거소를 국외로 이전해 비거주자가 되면 과세기간을 1월 1일부터 출국한 날까지로 정한다.","c":"상","v":1},"공인회2019_54-20-2":{"w":"소득세법 시행령 제2조 제3항 제1호는 계속하여 183일 이상 국내에 거주할 것을 통상 필요로 하는 직업을 가진 때 국내에 주소를 가진 것으로 본다.","c":"상","v":1},"공인회2019_54-20-4":{"w":"소득세법 제6조 제2항은 비거주자의 납세지를 국내사업장 소재지로 하되 둘 이상이면 주된 국내사업장, 국내사업장이 없으면 국내원천소득이 발생하는 장소로 정한다.","c":"상","v":1},"공인회2019_54-20-5":{"w":"소득세법 제10조는 납세지가 변경되면 변경된 날부터 15일 이내에 변경 후 납세지 관할 세무서장에게 신고하도록 정한다.","c":"상","v":1},"공인회2020_55-20-1":{"w":"소득세법 제2조 제2항 제2호는 비거주자도 이 법에 따라 원천징수한 소득세를 납부할 의무를 진다고 정한다.","c":"상","v":1},"공인회2020_55-20-2":{"w":"소득세법 제2조 제3항은 법인으로 보는 단체 외의 법인 아닌 단체를 국내에 주사무소가 있으면 1거주자로 보고 분배비율이 정해져 있거나 사실상 구성원별로 분배되는 경우에만 구성원별로 과세한다.","c":"상","v":1},"공인회2020_55-20-4":{"w":"소득세법 제2조의3 제1항은 신탁재산에 귀속되는 소득을 그 신탁의 수익자(사망하면 상속인)에게 귀속되는 것으로 본다.","c":"상","v":1},"공인회2020_55-20-5":{"w":"소득세법 제2조의2 제5항은 공동으로 소유한 자산의 양도소득금액을 계산할 때 공동 소유자인 각 거주자가 납세의무를 진다고 정한다.","c":"상","v":1},"공인회2020_55-21-1":{"w":"소득세법 제2조 제1항 제2호는 국내원천소득이 있는 비거주자에게 소득세 납부의무를 지운다.","c":"상","v":1},"공인회2020_55-21-2":{"w":"소득세법 시행령 제2조의2 제2항 제1호는 거주자가 주소·거소의 국외 이전을 위해 출국하는 날의 다음 날 비거주자가 된다고 정한다.","c":"상","v":1},"공인회2020_55-21-3":{"w":"소득세법 시행령 제3조는 거주자나 내국법인의 국외사업장 또는 100% 출자 해외현지법인 등에 파견된 임직원을 거주자로 본다.","c":"상","v":1},"공인회2020_55-21-4":{"w":"소득세법 제119조 제6호는 비거주자의 국내원천 퇴직소득을 국내에서 제공하는 근로의 대가로 받는 퇴직소득으로 정한다.","c":"상","v":1},"공인회2022_57-06-2":{"w":"소득세법 제2조의2 제5항은 공동 소유 자산의 양도소득금액을 계산할 때 각 공동소유자가 납세의무를 진다고 정한다.","c":"상","v":1},"공인회2022_57-06-4":{"w":"소득세법 제2조의2 제4항은 원천징수되는 소득 중 종합소득과세표준에 합산되지 않는 분리과세 소득이 있는 자가 그 원천징수 소득세에 대해 납세의무를 진다고 정한다.","c":"상","v":1},"공인회2024_59-20-1":{"w":"지상권은 부동산에 관한 권리여서 양도하면 양도소득이다(소득세법 제94조 제1항 제2호 나목). 공익사업 관련 지상권·지역권을 설정하거나 대여해 받는 대가만 기타소득이다(같은 법 제21조 제1항 제9호).","c":"상","v":1},"공인회2024_59-20-2":{"w":"소득세법 제21조 제1항 제8호의2는 통신판매중개자를 통해 물품이나 장소를 대여하고 받는 연간 수입금액 500만원 이하의 사용료를 기타소득으로 정한다.","c":"상","v":1},"공인회2024_59-20-4":{"w":"소득세법 제21조 제1항 제7호는 지하수의 개발·이용권을 양도하거나 대여하고 받는 금품을 기타소득으로 정한다. 지하수개발권은 양도소득 과세대상 자산(같은 법 제94조)에 없어 토지와 함께 양도해도 기타소득이다.","c":"상","v":1},"공인회2024_59-20-5":{"w":"소득세법 시행령 제51조 제3항 제4호의2 라목은 사업과 관련하여 사업용 자산의 손실로 취득하는 보험차익을 사업소득 총수입금액에 산입한다.","c":"상","v":1},"공인회2024_59-25-1":{"w":"2024년 3월 4일부터 10월 1일까지 거소 기간이 183일을 넘어 거주자가 되었다(소득세법 시행령 제4조 제1항). 국내 거주 기간이 5년 이하인 외국인 거주자이므로 국외원천소득은 국내에서 지급되거나 국내로 송금된 것만 과세한다(소득세법 제3조 제1항 단서).","c":"상","v":1},"공인회2024_59-25-2":{"w":"국내에 주소가 있으므로 거주자이고 해외 공연으로 6개월 남짓 출국했어도 주소를 국외로 옮긴 것이 아니어서 거주자 지위가 유지된다(소득세법 제1조의2 제1항 제1호). 거주자는 국내외 원천소득 모두에 납세의무를 진다(같은 법 제3조 제1항).","c":"상","v":1},"공인회2024_59-25-3":{"w":"국외에서 근무하는 공무원은 거주자로 보므로(소득세법 시행령 제3조) 일본에 1년 내내 거소를 두었어도 국내외 원천소득에 납세의무를 진다.","c":"상","v":1},"공인회2024_59-25-5":{"w":"입국 다음 날인 4월 5일부터 9월 19일까지 거소 기간이 183일에 못 미치므로(소득세법 시행령 제4조 제1항·제3항) 비거주자다. 비거주자는 국내원천소득에만 과세된다(소득세법 제3조 제2항).","c":"상","v":1},"공인회2025_60-20-5":{"w":"소득세법 시행령 제6조 제3항은 국세청장 등이 납세지를 지정하면 과세표준확정신고 또는 납부기간 개시일 전에 서면 통지하되 중간예납이나 수시부과 사유가 있으면 납기개시 15일 전에 통지하도록 정한다.","c":"상","v":1},"공인회2026_61-25-1":{"w":"소득세법 제2조 제3항은 법인으로 보는 단체 외의 법인 아닌 단체가 분배비율이 정해져 있지 않고 사실상 구성원별로 분배되지도 않으면 그 단체를 1거주자(국내에 주사무소 등이 없으면 1비거주자)로 본다.","c":"상","v":1},"공인회2026_61-25-3":{"w":"소득세법 제44조 제1항은 피상속인의 소득에 대한 소득세와 상속인의 소득에 대한 소득세를 구분하여 계산하도록 하고 같은 법 제2조의2 제2항은 피상속인 소득분의 납세의무를 상속인에게 지운다.","c":"상","v":1},"공인회2026_61-25-4":{"w":"소득세법 제2조의2 제4항은 원천징수되는 소득으로서 종합소득과세표준에 합산되지 않는 소득이 있는 자가 그 원천징수 소득세에 대해 납세의무를 진다고 정한다.","c":"상","v":1},"공인회2026_61-25-5":{"w":"소득세법 제2조의3 제2항과 같은 법 시행령 제4조의2 제4항 제1호는 위탁자가 신탁 해지권·수익자 지정·변경권 등을 보유해 신탁재산을 실질적으로 통제하는 신탁의 소득을 위탁자에게 귀속시킨다.","c":"상","v":1},"공인회2018_53-24-5":{"w":"소득세법 제2조의2 제1항 단서는 공동사업 합산과세로 주된 공동사업자에게 합산되는 소득금액에 대해 특수관계인이 자기 손익분배비율에 해당하는 소득금액을 한도로 주된 공동사업자와 연대납세의무를 진다고 정한다.","c":"상","v":1},"공인회2020_55-25-1":{"w":"소득세법 제43조 제2항은 공동사업 소득금액을 각 거주자 간 약정된 손익분배비율(없으면 지분비율)에 따라 공동사업자별로 분배하도록 정한다.","c":"상","v":1},"공인회2021_56-07-1":{"w":"소득세법 제31조 제1항은 유형자산 멸실로 받은 보험금으로 같은 종류의 자산을 대체 취득하면 그 취득에 사용된 보험차익 상당액을 보험금을 받은 날이 속하는 과세기간의 필요경비에 산입할 수 있게 한다.","c":"상","v":1},"공인회2021_56-07-3":{"w":"소득세법 제33조 제1항은 반출했으나 판매하지 않은 제품의 개별소비세·주세 미납액을 필요경비에 넣지 않는다. 제품가격에 그 세액을 더한 경우만 예외다.","c":"상","v":1},"공인회2021_56-07-4":{"w":"서화·골동품 양도 기타소득은 받은 금액이 1억원 이하이면 90%를 필요경비로 하고 실제 필요경비가 더 크면 그 금액을 필요경비로 한다(소득세법 제37조 제2항, 같은 법 시행령 제87조 제2호).","c":"상","v":1},"공인회2021_56-07-5":{"w":"소득세법 제37조 제1항 제1호는 승마투표권 등의 구매자가 받는 환급금의 필요경비를 그 구매자가 구입한 적중 투표권의 단위투표금액으로 정한다.","c":"상","v":1},"공인회2022_57-07-1":{"w":"소득세법 시행령 제98조 제2항 제2호 단서는 직계존비속에게 주택을 무상으로 사용하게 하고 직계존비속이 실제 거주하는 경우를 부당행위계산 대상에서 뺀다.","c":"상","v":1},"공인회2022_57-07-3":{"w":"소득세법 제44조 제1항은 피상속인의 소득금액에 대한 소득세로서 상속인에게 과세할 것과 상속인 자신의 소득에 대한 소득세를 구분하여 계산하도록 정한다.","c":"상","v":1},"공인회2022_57-07-4":{"w":"소득세법 제45조 제2항은 부동산임대업(주거용 건물 임대업 제외)에서 생긴 결손금을 다른 종합소득에서 공제하지 않도록 정한다. 그 결손금은 이후 부동산임대업 소득에서만 공제한다(같은 조 제3항 제2호).","c":"상","v":1},"공인회2022_57-07-5":{"w":"소득세법 제46조의2는 확정신고 후 예금·신탁계약 중도 해지로 지난 과세기간 이자소득금액이 감액되면 중도 해지일이 속하는 과세기간 이자소득금액에서 그 감액분을 뺄 수 있게 한다.","c":"상","v":1},"공인회2023_58-21-1":{"w":"부가가치세가 면제되는 의료보건용역(부가가치세법 제26조 제1항 제5호, 수의사 용역 포함)에서 생기는 사업소득은 원천징수대상 사업소득이다(소득세법 제127조 제1항 제3호, 같은 법 시행령 제184조 제1항).","c":"상","v":1},"공인회2023_58-21-2":{"w":"소득세법 제144조의2 제1항은 간편장부대상자인 보험모집인 등에게 사업소득을 지급하는 원천징수의무자가 그 사업소득에 대해 연말정산을 하도록 정한다.","c":"상","v":1},"공인회2023_58-21-5":{"w":"소득세법 시행령 제26조 제5항은 건설업자가 자기가 생산한 물품을 자기가 도급받은 건설공사의 자재로 사용하면 그 부분을 총수입금액에 산입하지 않도록 정한다.","c":"상","v":1},"공인회2025_60-22-1":{"w":"소득세법 시행령 제201조의11 제1항은 연말정산 대상 사업소득의 원천징수의무자가 최초로 연말정산을 하려면 해당 과세기간 종료일까지 사업소득세액연말정산신청서를 사업장 관할 세무서장에게 제출하도록 정한다.","c":"상","v":1},"공인회2025_60-22-2":{"w":"소득세법 제127조 제1항 제8호와 같은 법 시행령 제184조의2는 음식·숙박용역 등을 공급하면서 받은 봉사료를 소득자에게 지급하는 사업자가 그 봉사료에 대한 소득세를 원천징수하도록 정한다.","c":"중","v":1},"공인회2025_60-22-3":{"w":"소득세법 제149조 제2호와 같은 법 시행령은 농·축·수산물 판매업자(복식부기의무자 제외) 등 대통령령으로 정하는 사업자가 납세조합을 조직할 수 있게 한다.","c":"중","v":1},"공인회2025_60-22-4":{"w":"부가가치세법 제26조 제1항 제15호의 면세 인적용역(저술가·작곡가 등이 직업상 제공)에서 생기는 소득은 원천징수대상 사업소득이다(소득세법 제127조 제1항 제3호, 같은 법 시행령 제184조 제1항).","c":"상","v":1},"공인회2025_60-23-1":{"w":"부당행위계산 부인은 출자공동사업자의 배당소득·사업소득·기타소득에만 적용된다(소득세법 제41조 제1항). 대금업자가 아닌 거주자의 대여 이자는 이자소득이라 무상 대여해도 부인 대상이 아니다.","c":"상","v":1},"공인회2025_60-23-2":{"w":"소득세법 제43조 제3항은 생계를 같이하는 특수관계인이 공동사업자에 포함되고 손익분배비율을 거짓으로 정하는 등의 사유가 있으면 그 특수관계인의 소득금액을 손익분배비율이 큰 주된 공동사업자의 소득금액으로 본다.","c":"상","v":1},"공인회2025_60-23-4":{"w":"소득세법 제45조 제6항은 해당 과세기간에 결손금이 발생하고 이월결손금도 있으면 그 과세기간의 결손금을 먼저 공제하도록 정한다.","c":"상","v":1},"공인회2025_60-23-5":{"w":"소득세법 제46조 제1항과 제133조의2 제1항은 거주자가 채권을 발행법인 등 법인에 매도하면 보유기간 이자 상당액을 이자소득으로 보고 그 채권을 매수하는 법인(여기서는 발행법인)을 원천징수의무자로 한다.","c":"상","v":1},"공인회2018_53-25-1":{"w":"소득세법 제22조 제1항 제1호는 공적연금 관련법에 따라 받는 일시금을 퇴직소득으로 정한다.","c":"상","v":1},"공인회2018_53-25-2":{"w":"소득세법 시행령 제43조 제1항 제1호는 종업원이 임원이 되었으나 퇴직급여를 실제로 받지 않은 경우 퇴직으로 보지 않을 수 있게 한다.","c":"상","v":1},"공인회2018_53-25-4":{"w":"소득세법 제21조 제1항 제21호는 연금계좌에서 세액공제받은 납입액과 운용수익을 연금외수령하면 그 소득의 성격과 관계없이 기타소득으로 정한다.","c":"상","v":1},"공인회2018_53-25-5":{"w":"연금소득은 원천징수 대상이고(소득세법 제127조 제1항 제5호) 원천징수한 세액은 징수일이 속하는 달의 다음 달 10일까지 납부한다(같은 법 제128조 제1항).","c":"상","v":1},"공인회2021_56-09-2":{"w":"소득세법 제21조 제1항 제9호는 공익사업과 관련한 지역권·지상권을 설정하거나 대여하고 받는 금품을 기타소득으로 정한다.","c":"상","v":1},"공인회2021_56-09-3":{"w":"소득세법 제12조 제5호 자목은 법령·조례에 따른 위원회 등의 보수를 받지 않는 위원(학술원·예술원 회원 포함)이 받는 수당을 비과세 기타소득으로 정한다.","c":"상","v":1},"공인회2021_56-09-4":{"w":"소득세법 제21조 제1항 제23호·제24호는 뇌물과 알선수재·배임수재로 받는 금품을 기타소득으로 정한다.","c":"상","v":1},"공인회2021_56-09-5":{"w":"소득세법 제21조 제1항 제22호는 퇴직 전에 부여받은 주식매수선택권을 퇴직 후 행사해 얻은 이익을 기타소득으로 정한다. 재직 중 행사하면 근로소득이다.","c":"상","v":1},"공인회2023_58-23-1":{"w":"소득세법 시행령 제40조 제4항은 공적연금소득을 지연 지급하면서 함께 주는 지연이자를 공적연금소득으로 본다.","c":"상","v":1},"공인회2023_58-23-2":{"w":"소득세법 시행령 제40조의4 제1항 제1호는 연금수령 개시 전 연금저축계좌와 퇴직연금계좌 상호 간 이체를 인출로 본다. 전액 이체 등 같은 조 제2항의 요건을 갖춘 경우만 예외다.","c":"상","v":1},"공인회2023_58-23-4":{"w":"소득세법 제14조 제3항 제9호는 이연퇴직소득을 연금수령하는 연금소득을 종합소득과세표준에 합산하지 않는 분리과세 소득으로 정한다.","c":"상","v":1},"공인회2023_58-23-5":{"w":"소득세법 제143조의2 제1항은 공적연금소득을 지급할 때 연금소득 간이세액표에 따라 원천징수하도록 정한다.","c":"상","v":1},"공인회2026_61-27-2":{"w":"소득세법 시행령 제40조 제4항은 공적연금소득을 지연 지급하면서 함께 주는 지연이자를 공적연금소득으로 본다.","c":"상","v":1},"공인회2026_61-27-3":{"w":"소득세법 시행령 제43조 제1항 제2호는 동일한 사업자가 경영하는 다른 사업장으로 전출되었으나 퇴직급여를 실제로 받지 않은 경우 퇴직으로 보지 않을 수 있게 한다.","c":"상","v":1},"공인회2026_61-27-4":{"w":"소득세법 제57조 제1항은 종합소득금액뿐 아니라 퇴직소득금액에 국외원천소득이 합산된 경우에도 외국소득세액을 공제한도 내에서 그 산출세액에서 공제할 수 있게 한다.","c":"상","v":1},"공인회2026_61-27-5":{"w":"소득세법 제146조 제2항은 퇴직일 현재 연금계좌에 있거나 연금계좌로 지급되는 퇴직소득에 대해 연금외수령하기 전까지 소득세를 원천징수하지 않도록 정한다(이연퇴직소득).","c":"상","v":1},"공인회2019_54-26-1":{"w":"소득세법 시행령 제150조 제6항은 공동사업자가 확정신고를 할 때 신고서와 함께 그 공동사업장에서 발생한 소득과 그 밖의 소득을 구분한 계산서를 제출하도록 정한다.","c":"상","v":1},"공인회2019_54-26-2":{"w":"소득세법 제87조 제1항은 공동사업장 소득금액에 대해 원천징수된 세액을 각 공동사업자의 손익분배비율에 따라 배분하도록 정한다.","c":"상","v":1},"공인회2019_54-26-4":{"w":"소득세법 제85조의2 제2항·제3항은 결손금 소급공제 환급을 과세표준확정신고기한까지 신청하도록 하고 신청을 받은 세무서장이 지체 없이 환급세액을 결정해 국세기본법에 따라 환급하도록 정한다.","c":"상","v":1},"공인회2019_54-26-5":{"w":"소득세법 제45조 제5항은 종합과세되는 금융소득 중 원천징수세율(14%)을 적용받는 부분은 결손금·이월결손금 공제대상에서 빼고 기본세율을 적용받는 부분은 사업자가 공제 여부와 금액을 정할 수 있게 한다.","c":"상","v":1},"공인회2021_56-12-1":{"w":"소득세법 제56조의2 제2항 제1호는 장부에 따라 신고해야 할 소득금액의 20% 이상을 누락한 경우 기장세액공제를 적용하지 않도록 정한다.","c":"상","v":1},"공인회2021_56-12-3":{"w":"소득세법 시행령 제117조 제1항 제2호는 개인 소득세와 유사한 세목으로 소득 외의 수입금액 등을 과세표준으로 과세된 세액도 공제대상 외국소득세액에 넣는다.","c":"상","v":1},"공인회2021_56-12-4":{"w":"소득세법 제58조 제1항은 사업자가 재해로 사업용 자산총액의 20% 이상을 상실해 납세가 곤란하면 재해손실세액공제를 적용하도록 정한다.","c":"상","v":1},"공인회2021_56-12-5":{"w":"소득세법 시행령 제118조 제2항은 재해발생 비율을 재해발생일 현재 장부가액으로 계산하되 장부가 소실·분실되어 알 수 없으면 관할 세무서장이 조사·확인한 재해발생일 현재 가액으로 계산하도록 정한다.","c":"하","v":1},"공인회2022_57-11-1":{"w":"소득세법 제59조의2 제3항 제1호는 해당 과세기간에 출산하거나 입양 신고한 공제대상자녀가 첫째이면 연 30만원을 자녀세액공제로 정한다(둘째 50만원, 셋째 이상 70만원).","c":"상","v":1},"공인회2022_57-11-2":{"w":"대학원 교육비는 본인을 위해 지출한 경우에만 교육비세액공제 대상이다(소득세법 제59조의4 제3항 제1호 다목·제2호). 기본공제대상자인 직계비속의 대학원 교육비는 공제받을 수 없다.","c":"상","v":1},"공인회2022_57-11-3":{"w":"조세특례제한법 제100조의30 제2항은 자녀장려금을 소득세법 제59조의2의 자녀세액공제와 중복하여 적용할 수 없다고 정한다.","c":"상","v":1},"공인회2022_57-11-5":{"w":"사업소득만 있는 거주자의 기부금은 사업소득 필요경비로 처리하고(소득세법 제34조) 기부금세액공제는 종합소득에서 사업소득만 있는 자를 제외한다(같은 법 제59조의4 제4항). 연말정산 대상 사업소득자만 예외다.","c":"상","v":1},"공인회2024_59-22-3":{"w":"소득세법 제57조 제2항 단서는 이월공제기간(10년) 내에 공제받지 못한 외국소득세액을 이월공제기간 종료일 다음 날이 속하는 과세기간의 필요경비에 산입할 수 있게 한다.","c":"상","v":1},"공인회2026_61-26-1":{"w":"소득세법 제53조 제3항은 거주자(배우자 포함)의 직계존속이 주거 형편에 따라 별거하고 있어도 생계를 같이하는 사람으로 본다.","c":"상","v":1},"공인회2026_61-26-2":{"w":"소득세법 제51조 제1항 단서는 부녀자공제(제3호)와 한부모공제(제6호)에 모두 해당하면 한부모공제를 적용하도록 정한다.","c":"상","v":1},"공인회2026_61-26-3":{"w":"소득세법 시행령 제106조 제3항은 과세기간 중 사망하거나 외국 영주를 위해 출국한 거주자의 공제대상가족이 상속인 등 다른 거주자의 공제대상가족에도 해당하면 피상속인 또는 출국한 거주자의 공제대상가족으로 한다.","c":"상","v":1},"공인회2026_61-26-4":{"w":"공제대상 판정은 과세기간 종료일 현재 상황에 따르지만(소득세법 제53조 제4항) 같은 조 제5항은 적용대상 나이가 정해진 경우 과세기간 중 해당 나이에 해당하는 날이 하루라도 있으면 공제대상자로 본다.","c":"상","v":1},"공인회2016_51-23-1":{"w":"소득세법 시행령 제43조 제1항 제3호는 법인의 상근임원이 비상근임원이 되었으나 퇴직급여를 실제로 받지 않은 경우 퇴직으로 보지 않을 수 있게 한다.","c":"상","v":1},"공인회2016_51-23-2":{"w":"소득세법 제22조 제3항은 임원의 2012년 1월 1일 이후 근무기간분 퇴직소득금액(공적연금 일시금 제외)이 한도액을 초과하면 그 초과액을 근로소득으로 본다.","c":"상","v":1},"공인회2016_51-23-3":{"w":"소득세법 제57조 제1항은 퇴직소득금액에 국외원천소득이 합산되어 외국소득세액을 납부한 경우 공제한도 내에서 퇴직소득 산출세액에서 외국납부세액을 공제할 수 있게 한다.","c":"상","v":1},"공인회2016_51-23-5":{"w":"소득세법 제48조 제2항은 퇴직소득금액이 근속연수공제액에 미달하면 그 퇴직소득금액을 공제액으로 한다고 정한다.","c":"상","v":1},"공인회2023_58-26-1":{"w":"소득세법 시행령 제43조 제1항 제2호는 직·간접 출자관계에 있는 법인으로 전출되었으나 퇴직급여를 실제로 받지 않은 경우 퇴직으로 보지 않을 수 있게 한다.","c":"상","v":1},"공인회2023_58-26-3":{"w":"소득세법 제22조 제1항 제2호는 사용자 부담금을 기초로 하여 현실적인 퇴직을 원인으로 지급받는 소득을 퇴직소득으로 정한다.","c":"상","v":1},"공인회2023_58-26-4":{"w":"소득세법 제57조 제1항은 종합소득금액 또는 퇴직소득금액에 국외원천소득이 합산된 경우 외국소득세액을 공제한도 내에서 그 산출세액에서 공제할 수 있게 한다.","c":"상","v":1},"공인회2023_58-26-5":{"w":"소득세법 시행령 제43조 제2항은 임원을 포함한 근로소득자가 근로자퇴직급여 보장법 시행령의 중간정산 사유로 퇴직급여를 미리 받으면 그 지급받은 날에 퇴직한 것으로 본다.","c":"상","v":1},"공인회2025_60-27-1":{"w":"소득세법 제57조 제2항은 외국소득세액 한도초과액의 10년 이월공제를 종합소득산출세액에서 공제하는 경우에만 허용한다. 퇴직소득분 한도초과액은 이월공제하지 못한다.","c":"상","v":1},"공인회2025_60-27-2":{"w":"소득세법 제146조 제2항 제2호는 퇴직하여 지급받은 날부터 60일 이내에 연금계좌에 입금하면 원천징수를 하지 않고 이미 원천징수된 세액은 환급을 신청할 수 있게 한다.","c":"상","v":1},"공인회2025_60-27-4":{"w":"소득세법 제22조 제1항 제1호와 같은 법 시행령은 공적연금 일시금 중 2002년 1월 1일 이후 납입된 기여금·사용자 부담금이나 그 이후 근로 제공을 기초로 받은 부분을 퇴직소득으로 정한다.","c":"중","v":1},"공인회2025_60-27-5":{"w":"소득세법 제127조 제1항 제7호 단서는 외국기관이나 우리나라 주둔 국제연합군(미군 제외)으로부터 받는 근로소득(같은 항 제4호 가목)이 있는 사람이 퇴직하여 받는 퇴직소득을 원천징수 대상에서 뺀다.","c":"상","v":1},"공인회2016_51-28-1":{"w":"소득세법 제133조의2 제1항은 거주자가 채권을 법인에 매도하면 보유기간 이자상당액을 이자소득으로 보고 그 채권을 매수하는 법인을 원천징수의무자로 정한다. 발행법인에 매도했으므로 발행법인이 원천징수한다.","c":"상","v":1},"공인회2016_51-28-2":{"w":"소득세법 제128조 제1항은 원천징수한 소득세를 징수일이 속하는 달의 다음 달 10일까지 납부하도록 정한다. 2월 26일 징수분은 3월 10일까지다.","c":"상","v":1},"공인회2016_51-28-4":{"w":"소득세법 제131조 제1항은 처분결정일부터 3개월이 되는 날까지 미지급한 배당은 그날 지급한 것으로 보되 단서에서 11월 1일부터 12월 31일 사이에 결정한 배당을 다음 연도 2월 말일까지 지급하지 않으면 2월 말일에 지급한 것으로 본다.","c":"상","v":1},"공인회2016_51-28-5":{"w":"소득세법 제143조의2 제1항과 제129조 제3항은 매월분 공적연금소득에 대해 연금소득 간이세액표에 따라 원천징수하도록 정한다.","c":"상","v":1},"공인회2017_52-28-1":{"w":"국세기본법 제47조의2 제6항은 무신고가산세와 소득세법 제81조의5의 장부 기록·보관 불성실가산세(무기장가산세)가 동시에 적용되면 그중 가산세액이 큰 것만 적용하고 같으면 무신고가산세를 적용하도록 정한다.","c":"상","v":1},"공인회2017_52-28-2":{"w":"소득세법 제65조 제1항 괄호는 과세기간 개시일 현재 사업자가 아니었다가 그 과세기간 중 신규로 사업을 시작한 자를 중간예납 대상에서 뺀다.","c":"상","v":1},"공인회2017_52-28-3":{"w":"소득세법 제80조 제1항은 확정신고를 해야 할 자가 신고하지 않으면 관할 세무서장 또는 지방국세청장이 과세표준과 세액을 결정하도록 정한다.","c":"상","v":1},"공인회2017_52-28-4":{"w":"소득세법 제82조 제1항 제2호는 조세를 포탈할 우려가 있다고 인정되는 상당한 이유가 있으면 관할 세무서장 또는 지방국세청장이 수시부과할 수 있게 한다.","c":"상","v":1},"공인회2018_53-27-1":{"w":"소득세법 제78조 제1항은 사업자에게 다음 연도 2월 10일까지 사업장 현황신고를 하도록 하고 부가가치세 신고를 한 과세사업자는 면제한다. 면세사업만 하는 사업자는 부가가치세 신고가 없으므로 사업장 현황신고를 해야 한다.","c":"상","v":1},"공인회2018_53-27-2":{"w":"소득세법 제74조 제4항은 확정신고를 해야 할 거주자가 출국하면 출국일이 속하는 과세기간의 과세표준을 출국일 전날까지 신고하도록 정한다.","c":"상","v":1},"공인회2018_53-27-3":{"w":"소득세법 제77조는 확정신고 등으로 납부할 세액이 1천만원을 초과하면 납부기한이 지난 후 2개월 이내에 일부를 분할납부할 수 있게 한다.","c":"상","v":1},"공인회2018_53-27-5":{"w":"소득세법 제69조 제1항은 부동산매매업자가 토지·건물의 매매차익과 세액을 매매일이 속하는 달의 말일부터 2개월이 되는 날까지 신고하도록 정한다.","c":"상","v":1},"공인회2019_54-29-1":{"w":"퇴직소득은 원천징수 대상이고(소득세법 제127조 제1항 제7호) 원천징수세액은 징수일이 속하는 달의 다음 달 10일까지 납부한다(같은 법 제128조 제1항).","c":"상","v":1},"공인회2019_54-29-2":{"w":"소득세법 제73조 제1항 제5호는 근로소득과 퇴직소득만 있는 자의 과세표준확정신고를 면제한다. 연말정산과 원천징수로 세액이 확정되기 때문이다.","c":"상","v":1},"공인회2019_54-29-4":{"w":"소득세법 제70조 제4항 후단은 복식부기의무자가 재무상태표·손익계산서와 그 부속서류, 합계잔액시산표, 조정계산서를 제출하지 않으면 확정신고를 하지 않은 것으로 본다.","c":"상","v":1},"공인회2019_54-29-5":{"w":"소득세법 제80조 제1항은 확정신고를 하지 않은 거주자의 과세표준과 세액을 관할 세무서장 또는 지방국세청장이 결정하도록 정한다.","c":"상","v":1},"공인회2020_55-27-1":{"w":"의료비·교육비 세액공제는 근로소득자 대상이 원칙이지만 조세특례제한법 제122조의3은 성실신고확인서를 제출한 성실신고확인대상사업자가 지출한 의료비·교육비를 세액공제하도록 정한다.","c":"상","v":1},"공인회2020_55-27-2":{"w":"소득세법 제70조의2 제2항은 성실신고확인서를 제출하는 사업자의 확정신고 기간을 다음 연도 5월 1일부터 6월 30일까지로 정한다.","c":"상","v":1},"공인회2020_55-27-3":{"w":"소득세법 시행령 제133조 제4항은 세무사가 성실신고확인대상사업자이면 자기 사업소득금액에 대한 성실신고확인서를 그 세무사가 작성·제출해서는 안 된다고 정한다.","c":"상","v":1},"공인회2020_55-27-4":{"w":"소득세법 제70조의2 제3항은 관할 세무서장이 성실신고확인서에 미비한 사항이나 오류가 있으면 보정을 요구할 수 있게 한다.","c":"상","v":1},"공인회2021_56-06-1":{"w":"소득세법 제127조 제5항은 외국법인이 발행한 채권·증권의 이자·배당소득을 거주자에게 지급할 때 국내에서 지급을 대리하거나 지급 권한을 위임·위탁받은 자가 원천징수하도록 정한다.","c":"상","v":1},"공인회2021_56-06-2":{"w":"주식 소각 의제배당의 수입시기는 주식의 소각을 결정한 날이고(소득세법 시행령 제46조 제4호) 원천징수도 그날 지급한 것으로 보아 한다.","c":"중","v":1},"공인회2021_56-06-3":{"w":"소득세법 제135조 제1항은 1월부터 11월까지의 근로소득을 12월 31일까지 지급하지 않으면 12월 31일에 지급한 것으로 보아 원천징수하도록 정한다.","c":"상","v":1},"공인회2021_56-06-4":{"w":"소득세법 제155조는 발생 후 지급되지 않아 원천징수되지 않은 소득이 종합소득에 합산되어 과세된 경우 나중에 지급할 때 원천징수하지 않도록 정한다. 이중과세를 막기 위해서다.","c":"상","v":1},"공인회2022_57-14-2":{"w":"소득세법 제65조 제1항 괄호와 같은 법 시행령 제123조 제3호의2는 분리과세 주택임대소득만 있는 자를 중간예납 대상에서 뺀다.","c":"상","v":1},"공인회2022_57-14-3":{"w":"소득세법 제65조 제3항은 중간예납추계액이 중간예납기준액의 30%에 미달하면 11월 1일부터 30일까지 중간예납추계액을 중간예납세액으로 신고할 수 있게 한다.","c":"상","v":1},"공인회2022_57-14-4":{"w":"소득세법 제86조 제4호는 제65조에 따른 중간예납세액이 50만원 미만이면 징수하지 않도록 정한다(소액 부징수).","c":"상","v":1},"공인회2022_57-14-5":{"w":"소득세법 제77조는 제65조의 중간예납세액이 1천만원을 초과하면 납부기한이 지난 후 2개월 이내에 일부를 분할납부할 수 있게 한다.","c":"상","v":1},"공인회2023_58-27-1":{"w":"소득세법 제82조 제1항 제1호는 사업부진 등으로 장기간 휴업·폐업 상태이고 소득세를 포탈할 우려가 있으면 수시부과할 수 있게 한다.","c":"상","v":1},"공인회2023_58-27-2":{"w":"소득세법 제65조 제3항은 중간예납기간 종료일까지의 소득세액(중간예납추계액)이 중간예납기준액의 30%에 미달하면 중간예납추계액을 중간예납세액으로 신고할 수 있게 한다.","c":"상","v":1},"공인회2023_58-27-3":{"w":"소득세법 제65조 제1항 괄호는 과세기간 개시일 현재 사업자가 아니었던 신규사업자를 중간예납 대상에서 뺀다.","c":"상","v":1},"공인회2023_58-27-4":{"w":"소득세법 제155조는 지급되지 않아 원천징수되지 않은 소득이 종합소득에 합산되어 과세되었다면 그 소득을 지급할 때 원천징수하지 않도록 정한다.","c":"상","v":1},"공인회2024_59-27-1":{"w":"반기별 납부 승인을 받은 원천징수의무자라도 법인세법 제67조에 따라 처분된 상여·배당·기타소득의 원천징수세액은 징수일이 속하는 달의 다음 달 10일까지 납부한다(소득세법 제128조 제2항 제1호).","c":"상","v":1},"공인회2024_59-27-3":{"w":"소득세법 제147조 제1항은 1월부터 11월 사이에 퇴직한 사람의 퇴직소득을 12월 31일까지 지급하지 않으면 12월 31일에 지급한 것으로 보아 원천징수하도록 정한다.","c":"상","v":1},"공인회2024_59-27-4":{"w":"소득세법 제129조 제1항 제8호는 대통령령으로 정하는 봉사료의 원천징수세율을 100분의 5로 정한다.","c":"상","v":1},"공인회2024_59-27-5":{"w":"소득세법 제129조 제1항 제6호 나목은 소기업·소상공인 공제부금 해지일시금(제21조 제1항 제18호)의 원천징수세율을 100분의 15로 정한다.","c":"상","v":1},"공인회2026_61-20-1":{"w":"소득세법 제65조 제1항은 1월 1일부터 6월 30일까지를 중간예납기간으로 하여 직전 과세기간 종합소득세액의 2분의 1을 중간예납세액으로 결정해 11월 30일까지 징수하도록 정한다.","c":"상","v":1},"공인회2026_61-20-2":{"w":"소득세법 제69조 제1항은 부동산매매업자가 매매일이 속하는 달의 말일부터 2개월이 되는 날까지 매매차익과 세액을 신고하도록 하고 매매차익이 없거나 매매차손이 생겨도 신고하도록 정한다. 산출세액은 같은 기한까지 납부한다(같은 조 제4항).","c":"상","v":1},"공인회2026_61-20-4":{"w":"소득세법 제78조 제1항 제2호 단서는 과세사업과 면세사업을 겸영하는 사업자가 부가가치세 신고와 함께 면세사업 수입금액을 신고하면 그 면세사업에 대해 사업장 현황신고를 한 것으로 본다.","c":"상","v":1},"공인회2026_61-20-5":{"w":"소득세법 제150조 제3항·제4항은 외국기관 등에서 근로소득을 받는 자(제149조 제1호)가 조직한 납세조합이 2027년 12월 31일 이전에 매월분 소득세를 징수할 때 세액의 3%를 연 100만원 한도로 공제하도록 정한다.","c":"상","v":1},"공인회2017_52-29-2":{"w":"부가가치세법 제10조 제4항은 매입세액공제를 받은 자기생산·취득재화를 사업과 직접 관계없이 개인적 목적으로 사용·소비하고 대가를 받지 않거나 시가보다 낮은 대가를 받으면 재화의 공급으로 본다(개인적 공급).","c":"상","v":1},"공인회2017_52-31-1":{"w":"부가가치세법 제52조 제1항은 국내사업장이 없는 외국법인 등으로부터 용역을 공급받는 자에게 대리납부 의무를 지우되 그 용역을 과세사업에 제공하는 경우(매입세액불공제 대상은 제외)를 뺀다. 공제대상 용역을 과세사업에 쓰면 대리납부 의무가 없다.","c":"상","v":1},"공인회2017_52-32-2":{"w":"부가가치세법 시행령 제33조 제2항 제1호 단서는 국내사업장이 없는 비거주자 등에게 공급하는 전문서비스업 용역에 대해 그 국가에서 우리나라 거주자·내국법인에게 동일하게 면세하는 경우에만 영세율을 적용한다.","c":"상","v":1},"공인회2017_52-32-3":{"w":"부가가치세법 제28조 제3항은 면세포기를 신고한 사업자가 신고한 날부터 3년간 부가가치세를 면제받지 못한다고 정한다.","c":"상","v":1},"공인회2017_52-32-4":{"w":"부가가치세법 제39조 제1항 제7호는 면세사업 등에 관련된 매입세액(면세사업 투자 관련 포함)을 매출세액에서 공제하지 않도록 정한다.","c":"상","v":1},"공인회2017_52-32-5":{"w":"두부는 부가가치세법 시행령 제34조 제2항 제1호의 단순 가공식료품으로 미가공식료품에 포함되어 면세된다(부가가치세법 제26조 제1항 제1호).","c":"상","v":1},"공인회2017_52-33-1":{"w":"부가가치세법 시행령 제28조 제2항은 반환조건부·동의조건부 등 조건부 판매와 기한부 판매의 공급시기를 조건이 성취되거나 기한이 지나 판매가 확정되는 때로 정한다.","c":"상","v":1},"공인회2017_52-33-2":{"w":"부가가치세법 시행령 제28조 제1항은 현금판매·외상판매·할부판매의 공급시기를 재화가 인도되거나 이용가능하게 되는 때로 정한다.","c":"상","v":1},"공인회2017_52-33-3":{"w":"부가가치세법 시행령 제28조 제5항은 무인판매기로 재화를 공급하면 사업자가 무인판매기에서 현금을 꺼내는 때를 공급시기로 본다.","c":"상","v":1},"공인회2017_52-33-4":{"w":"부가가치세법 시행령 제28조 제3항 제1호는 재정경제부령으로 정하는 장기할부판매의 공급시기를 대가의 각 부분을 받기로 한 때로 정한다.","c":"상","v":1},"공인회2018_53-32-5":{"w":"부가가치세법 시행령 제33조 제2항 제1호 사목은 국내사업장이 없는 외국법인에게 공급하는 상품 중개업 용역으로서 대금을 외국환은행에서 원화로 받는 것을 영세율 대상으로 정한다.","c":"상","v":1},"공인회2019_54-32-1":{"w":"여객운송용역은 면세가 원칙이지만 부가가치세법 시행령 제37조 제1호 나목 1)은 시외우등고속버스·시외고급고속버스를 사용하는 시외버스운송사업의 여객운송을 면세에서 뺀다. 시내버스는 면세다(부가가치세법 제26조 제1항 제7호).","c":"상","v":1},"공인회2019_54-32-3":{"w":"약사가 제공하는 의약품 조제용역은 면세 의료보건용역이지만(부가가치세법 시행령 제35조) 조제하지 않은 의약품의 단순 판매는 재화의 공급으로 과세된다.","c":"상","v":1},"공인회2019_54-32-4":{"w":"부가가치세법 제26조 제1항 제8호는 도서의 공급을 면세하되 도서에 게재되는 광고는 제외한다.","c":"상","v":1},"공인회2019_54-32-5":{"w":"부가가치세법 제28조 제1항 제1호는 영세율 적용 대상인 면세재화에 대해 면세포기를 할 수 있게 한다. 면세를 포기하고 과세사업자로 등록하면 영세율로 매입세액을 환급받는다.","c":"상","v":1},"공인회2020_55-30-2":{"w":"부가가치세법 제17조 제1항은 공급시기 전에 대가의 전부 또는 일부를 받고 그 받은 대가에 대해 세금계산서를 발급하면 발급하는 때를 공급시기로 본다.","c":"상","v":1},"공인회2020_55-30-3":{"w":"부가가치세법 시행령 제28조 제9항은 폐업 전에 공급한 재화의 공급시기가 폐업일 이후에 도래하면 폐업일을 공급시기로 본다.","c":"상","v":1},"공인회2020_55-30-4":{"w":"부가가치세법 제17조 제4항과 같은 법 시행령 제30조는 장기할부판매 등에서 공급시기 전에 세금계산서를 발급하면 대가를 받지 않았더라도 그 발급한 때를 공급시기로 본다.","c":"상","v":1},"공인회2020_55-30-5":{"w":"자기가 주요자재를 부담하는 가공계약은 재화의 공급이고(부가가치세법 시행령 제18조 제1항 제2호) 그 공급시기는 가공된 재화를 인도하는 때다(같은 영 제28조 제1항).","c":"상","v":1},"공인회2020_55-33-2":{"w":"영세율 규정(부가가치세법 제21조부터 제24조)은 과세사업자에게 적용되므로 간이과세자도 수출 등에 영세율을 적용받을 수 있다. 면세사업자만 영세율을 적용받지 못한다.","c":"중","v":1},"공인회2020_55-33-3":{"w":"부가가치세법 제23조 제2항과 같은 법 시행령 제32조 제1항 제4호는 외국항행사업자가 자기 승객만 전용하는 호텔에 투숙하게 하는 용역을 외국항행용역에 포함해 영세율을 적용한다.","c":"상","v":1},"공인회2020_55-33-4":{"w":"조세특례제한법 제105조 제1항 제3호 가목은 국가·지방자치단체에 직접 공급하는 도시철도건설용역에 영세율을 적용한다(2026년 12월 31일까지 공급분).","c":"상","v":1},"공인회2020_55-33-5":{"w":"부가가치세법 제25조 제1항은 사업자가 비거주자 또는 외국법인이면 그 국가에서 우리나라 거주자·내국법인에게 동일하게 면세하는 경우에만 영세율을 적용한다(상호주의).","c":"상","v":1},"공인회2021_56-30-1":{"w":"부가가치세법 제10조 제9항 제4호는 신탁 종료로 수탁자로부터 위탁자에게 신탁재산을 이전하는 경우 등 신탁재산의 소유권 이전을 재화의 공급으로 보지 않는다.","c":"상","v":1},"공인회2021_56-30-2":{"w":"대가를 받지 않는 용역의 공급은 과세대상이 아니다(부가가치세법 제12조 제2항). 특수관계인에게 사업용 부동산 임대용역을 무상으로 제공하는 경우만 예외이고 사용인 식사 제공은 이에 해당하지 않는다.","c":"상","v":1},"공인회2021_56-30-4":{"w":"부가가치세법 제10조 제3항 단서 제1호는 사업자 단위 과세 사업자가 판매 목적으로 자기의 다른 사업장에 반출하는 것을 재화의 공급으로 보지 않는다.","c":"상","v":1},"공인회2021_56-30-5":{"w":"부가가치세법 제10조 제1항은 매입세액공제를 받은 재화뿐 아니라 내국신용장 등으로 영세율을 적용받은 재화(같은 항 제3호)를 면세사업에 직접 사용·소비하는 경우도 재화의 공급(면세전용)으로 본다.","c":"상","v":1},"공인회2022_57-30-3":{"w":"사업상 증여는 재화의 공급이지만 부가가치세법 시행령 제20조 제2호는 재난 및 안전관리 기본법에 따라 특별재난지역에 공급하는 물품을 제외한다(부가가치세법 제10조 제5항 단서).","c":"상","v":1},"공인회2022_57-33-2":{"w":"내국신용장·구매확인서에 의한 재화 공급(금지금 제외)은 수출로 보아 영세율이 적용되고(부가가치세법 시행령 제31조 제2항 제1호) 사업자 간 거래여서 세금계산서 발급의무 면제 대상(같은 영 제71조 제1항)에 들지 않는다.","c":"상","v":1},"공인회2022_57-33-3":{"w":"내국물품을 외국으로 반출하는 수출은 영세율 대상이고(부가가치세법 제21조 제2항 제1호) 같은 법 시행령 제71조 제1항은 이런 수출 재화의 세금계산서 발급의무를 면제한다.","c":"상","v":1},"공인회2022_57-33-4":{"w":"부가가치세법 제22조는 사업자가 국외에서 공급하는 용역에 영세율을 적용한다. 대금을 어떻게 받는지는 요건이 아니다.","c":"상","v":1},"공인회2022_57-33-5":{"w":"부가가치세법 제23조 제1항·제2항은 항공기로 여객이나 화물을 국내에서 국외로 수송하는 외국항행용역에 영세율을 적용한다.","c":"상","v":1},"공인회2023_58-31-1":{"w":"부가가치세법 시행령 제31조 제1항 제6호는 관세법상 수입신고 수리 전 물품으로서 보세구역에 보관하는 물품을 외국으로 반출하는 것을 수출로 보아 영세율을 적용한다(부가가치세법 제21조 제2항 제2호).","c":"상","v":1},"공인회2023_58-31-2":{"w":"부가가치세법 시행령 제33조 제2항 제3호는 수출업자와 직접 도급계약에 의한 수출재화임가공용역에 영세율을 적용하되 부가가치세를 별도로 적은 세금계산서를 발급하면 제외한다.","c":"상","v":1},"공인회2023_58-31-3":{"w":"부가가치세법 시행령 제33조 제2항 제5호는 외국 항행 선박·항공기·원양어선에 공급하는 재화·용역에 영세율을 적용하되 부가가치세를 별도로 적은 세금계산서를 발급하면 제외한다.","c":"상","v":1},"공인회2023_58-31-4":{"w":"부가가치세법 시행령 제31조 제2항 제4호는 대한적십자사가 그 목적사업을 위해 외국에 무상 반출하는 재화를 공급하는 경우를 수출로 보아 영세율을 적용한다.","c":"상","v":1},"공인회2024_59-31-1":{"w":"부가가치세법 시행령 제33조 제2항 제5호는 외국을 항행하는 선박·항공기에 공급하는 재화에 영세율을 적용하고 부가가치세를 별도로 적은 세금계산서를 발급한 경우만 제외한다.","c":"상","v":1},"공인회2024_59-31-2":{"w":"부가가치세법 시행령 제33조 제2항 제1호 가목은 국내사업장이 없는 비거주자가 지정하는 국내사업자에게 인도되어 그 사업자의 과세사업에 쓰이는 재화로서 대금을 재정경제부령이 정하는 방법(비거주자에게 줄 금액에서 빼는 방법 등)으로 받는 것에 영세율을 적용한다.","c":"상","v":1},"공인회2024_59-31-3":{"w":"부가가치세법 시행령 제31조 제2항 제1호는 내국신용장 또는 구매확인서에 의해 공급하는 재화(금지금 제외)를 수출로 보아 영세율을 적용한다.","c":"상","v":1},"공인회2024_59-31-4":{"w":"부가가치세법 시행령 제31조 제1항 제5호는 원료를 대가 없이 국외 수탁가공 사업자에게 반출해 가공한 재화를 양도하는 경우 그 원료의 반출을 수출로 보아 영세율을 적용한다.","c":"상","v":1},"공인회2024_59-33-1":{"w":"부가가치세법 시행령 제28조 제2항은 반환조건부 판매의 공급시기를 조건이 성취되거나 기한이 지나 판매가 확정되는 때로 정한다.","c":"상","v":1},"공인회2024_59-33-2":{"w":"완성도기준지급조건부 공급은 대가의 각 부분을 받기로 한 때가 공급시기지만 부가가치세법 시행령 제28조 제3항 단서는 재화가 인도되거나 이용가능하게 된 날 이후에 받기로 한 대가는 인도일 등을 공급시기로 본다.","c":"상","v":1},"공인회2024_59-33-3":{"w":"부가가치세법 시행령 제28조 제3항 제4호는 전력 등 공급단위를 구획할 수 없는 재화를 계속 공급하는 경우 대가의 각 부분을 받기로 한 때를 공급시기로 본다.","c":"상","v":1},"공인회2024_59-33-4":{"w":"부가가치세법 시행령 제28조 제7항은 보세구역 안에서 보세구역 밖의 국내로 재화를 공급하는 것이 재화의 수입에 해당하면 수입신고 수리일을 공급시기로 본다.","c":"상","v":1},"공인회2025_60-30-1":{"w":"온라인 사설 경매사이트를 통한 판매는 일반 매매계약에 따른 재화의 공급이다. 부가가치세법 시행령 제18조 제3항 제2호는 민사집행법에 따른 경매로 재화를 인도·양도하는 것을 재화의 공급에서 뺀다.","c":"상","v":1},"공인회2025_60-30-2":{"w":"차입금을 건물로 갚는 대물변제는 계약상 원인에 따른 재화의 인도로 과세되지만(부가가치세법 시행령 제18조 제1항 제4호) 법률에 따른 조세 물납은 재화의 공급이 아니다(부가가치세법 제10조 제9항 제3호).","c":"상","v":1},"공인회2025_60-30-3":{"w":"현물출자는 계약상 원인에 따른 재화의 인도·양도로 과세되고(부가가치세법 시행령 제18조 제1항 제4호) 재화를 담보로 제공하는 것은 재화의 공급이 아니다(부가가치세법 제10조 제9항 제1호).","c":"상","v":1},"공인회2025_60-30-4":{"w":"부가가치세법 제10조 제3항 단서 제1호는 사업자 단위 과세 사업자가 판매 목적으로 자기의 다른 사업장에 반출하는 것을 재화의 공급으로 보지 않는다.","c":"상","v":1},"공인회2026_61-34-1":{"w":"부가가치세법 제17조 제3항 제1호는 계약서 등에 대금 청구시기(세금계산서 발급일)와 지급시기를 따로 적고 그 사이가 30일 이내이면 세금계산서 발급 후 7일이 지나 대가를 받아도 발급한 때를 공급시기로 본다.","c":"상","v":1},"공인회2026_61-34-2":{"w":"부가가치세법 시행령 제28조 제3항 제4호는 공급단위를 구획할 수 없는 재화를 계속 공급하는 경우 대가의 각 부분을 받기로 한 때를 공급시기로 본다.","c":"상","v":1},"공인회2026_61-34-3":{"w":"부가가치세법 시행령 제28조 제5항은 무인판매기로 재화를 공급하면 사업자가 현금을 꺼내는 때를 공급시기로 본다.","c":"상","v":1},"공인회2026_61-34-5":{"w":"부가가치세법 시행령 제28조 제7항은 보세구역 안에서 보세구역 밖의 국내로 재화를 공급하는 것이 재화의 수입에 해당하면 수입신고 수리일을 공급시기로 본다.","c":"상","v":1},"공인회2026_61-35-5":{"w":"부가가치세법 제3조 제3항 제2호와 같은 법 시행령 제5조의2 제2항 제4호는 자본시장법상 투자신탁을 위탁자가 신탁재산을 실질적으로 지배·통제하는 경우로 보아 위탁자를 납세의무자로 정한다.","c":"상","v":1},"공인회2016_51-33-2":{"w":"공급시기(3월 25일)가 지난 뒤 그 과세기간 확정신고기한(7월 25일)까지 발급한 지연발급이므로 부가가치세법 제60조 제2항 제1호에 따라 공급가액의 1%를 가산세로 더한다.","c":"상","v":1},"공인회2016_51-33-3":{"w":"공급자가 세금계산서를 발급하지 않으면 공급받은 사업자가 관할 세무서장의 확인을 받아 매입자발행세금계산서를 발행할 수 있다(부가가치세법 제34조의2 제1항). 확인신청 대상은 거래건당 공급대가 5만원 이상이므로(같은 법 시행령 제71조의2 제4항) 10만원 거래는 해당한다.","c":"상","v":1},"공인회2016_51-33-4":{"w":"부가가치세법 제32조 제2항은 법인사업자에게 전자세금계산서 발급의무를 지우고 같은 조 제3항은 발급일의 다음 날까지 발급명세를 국세청장에게 전송하도록 정한다.","c":"상","v":1},"공인회2016_51-33-5":{"w":"부가가치세법 시행령 제70조 제1항 제1호는 처음 공급한 재화가 환입되면 환입된 날을 작성일로 적어 음(-)의 수정세금계산서를 발급하도록 정한다. 그래서 환입일이 속하는 제2기 과세표준에서 뺀다.","c":"상","v":1},"공인회2016_51-35-1":{"w":"부가가치세법 제70조 제1항은 간이과세자가 일반과세자 규정을 적용받으려면 적용받으려는 달의 전달 마지막 날까지 간이과세 포기 신고를 하도록 정한다. 승인 절차는 없다.","c":"상","v":1},"공인회2016_51-35-2":{"w":"간이과세 포기 신고는 적용받으려는 달의 전달 마지막 날까지 하므로(부가가치세법 제70조 제1항) 포기신고서를 낸 달의 다음 달 1일부터 일반과세자 규정이 적용된다.","c":"상","v":1},"공인회2016_51-35-4":{"w":"부가가치세법 제70조 제3항 제1호는 간이과세를 포기한 개인사업자가 일반과세를 적용받으려는 달의 1일부터 3년이 되는 날이 속하는 과세기간까지 간이과세를 적용받지 못한다고 정한다. 2024년 7월부터 직전 연도 공급대가 4,800만원 이상 1억400만원 미만 등 요건을 갖추면 그 전에도 재적용을 신고할 수 있다(같은 조 제4항).","c":"상","v":1},"공인회2016_51-35-5":{"w":"부가가치세법 시행령 제116조 제2항은 간이과세 포기 후 3년의 기간이 지나 다시 간이과세를 적용받으려면 적용받으려는 과세기간 개시 10일 전까지 간이과세적용신고서를 제출하도록 정한다.","c":"상","v":1},"공인회2017_52-35-1":{"w":"부가가치세법 제61조 제3항은 신규 개인사업자가 사업자등록 신청 때 간이과세적용신고서를 내면 최초 과세기간에 간이과세를 적용하도록 정한다. 개업 연도에는 실제 매출액과 관계없이 간이과세자다.","c":"상","v":1},"공인회2017_52-35-2":{"w":"부가가치세법 제69조 제1항은 간이과세자의 과세기간 공급대가 합계액이 4,800만원 미만이면 납부의무를 면제한다. 2,300만원은 출제 당시 기준(2,400만원 미만)으로도 지금 기준으로도 면제 대상이다.","c":"상","v":1},"공인회2017_52-35-5":{"w":"부가가치세법 제63조 제1항은 간이과세자의 과세표준을 해당 과세기간(1월 1일부터 12월 31일)의 공급대가 합계액으로 정한다.","c":"상","v":1},"공인회2018_53-34-1":{"w":"부가가치세법 제39조 제1항 제7호와 같은 법 시행령 제80조는 건축물이 있는 토지를 취득해 건축물을 철거하고 토지만 사용하는 경우 철거한 건축물의 취득·철거 비용 관련 매입세액을 토지 관련 매입세액으로 보아 공제하지 않는다.","c":"상","v":1},"공인회2018_53-35-2":{"w":"부가가치세법 제17조 제2항은 공급시기 전에 세금계산서를 발급하고 발급일부터 7일 이내에 대가를 받으면 발급한 때를 공급시기로 본다. 7월 20일 발급 후 5일 뒤인 7월 25일에 대가를 받았다.","c":"상","v":1},"공인회2018_53-37-4":{"w":"직원에게 제품을 기념품으로 무상 지급하는 개인적 공급(부가가치세법 제10조 제4항) 등 공급의제는 세금계산서 발급의무가 없으므로(같은 법 시행령 제71조 제1항 제3호) 발급하지 않아도 세금계산서 관련 가산세가 없다.","c":"상","v":1},"공인회2019_54-31-1":{"w":"부가가치세법 시행령 제68조 제3항은 관할 세무서장이 전자세금계산서 의무발급 개인사업자에게 발급의무가 시작되는 날 1개월 전까지 그 사실을 통지하도록 정한다.","c":"상","v":1},"공인회2019_54-31-2":{"w":"부가가치세법 제32조 제3항은 전자세금계산서를 발급하면 발급일의 다음 날까지 발급명세를 국세청장에게 전송하도록 정한다.","c":"상","v":1},"공인회2019_54-31-3":{"w":"부가가치세법 제54조 제2항은 전자세금계산서 발급명세를 공급시기가 속하는 과세기간(예정신고는 예정신고기간) 마지막 날의 다음 달 11일까지 전송하면 매출·매입처별 세금계산서합계표를 제출하지 않아도 되게 한다.","c":"상","v":1},"공인회2019_54-31-5":{"w":"부가가치세법 제71조 제3항 단서는 전자세금계산서를 발급하고 발급명세를 국세청장에게 전송한 사업자는 세금계산서를 5년간 보존할 의무가 없다고 정한다.","c":"상","v":1},"공인회2019_54-33-1":{"w":"부가가치세법 제6조 제4항은 사업자 단위 과세 사업자의 납세지를 각 사업장 대신 본점 또는 주사무소 소재지로 정한다.","c":"상","v":1},"공인회2019_54-33-2":{"w":"사업자 단위로 등록하면 본점·주사무소 하나만 등록번호를 받으므로(부가가치세법 제8조 제3항) 세금계산서 발급·수취와 신고·납부를 모두 본점 또는 주사무소에서 사업자 단위로 한다(같은 법 제6조 제4항).","c":"상","v":1},"공인회2019_54-33-3":{"w":"부가가치세법 제53조의2 제1항은 국내사업장이 없는 비거주자·외국법인이 국내에 전자적 용역을 공급하면 사업 개시일부터 20일 이내에 간편사업자등록을 하도록 정한다.","c":"상","v":1},"공인회2019_54-33-5":{"w":"부가가치세법 시행령 제92조 제1항은 주사업장 총괄 납부의 주된 사업장을 법인은 본점(주사무소) 또는 지점(분사무소), 개인은 주사무소로 정한다.","c":"상","v":1},"공인회2019_54-37-1":{"w":"부가가치세법 제49조 제1항은 과세기간이 끝난 후 25일 이내에 확정신고하되 예정신고나 조기환급신고 때 이미 신고한 부분은 빼도록 정한다. 제1기 확정신고기한은 7월 25일이다.","c":"상","v":1},"공인회2019_54-37-2":{"w":"부가가치세법 제59조 제1항은 일반환급을 과세기간별로 확정신고기한이 지난 후 30일 이내에 하도록 정한다. 7월 15일에 신고했어도 기산점은 신고기한인 7월 25일이다.","c":"상","v":1},"공인회2019_54-37-3":{"w":"부가가치세법 제59조 제1항은 환급을 과세기간 단위로 확정신고기한이 지난 후에 하도록 정한다. 그래서 예정신고기간의 환급세액은 조기환급 대상이 아니면 바로 돌려주지 않고 확정신고 때 납부세액에서 뺀다.","c":"중","v":1},"공인회2019_54-37-4":{"w":"사업설비를 취득한 사업자는 조기환급을 신고할 수 있고(부가가치세법 제59조 제2항 제2호) 매월 단위 조기환급 신고를 하면 관할 세무서장은 조기환급 신고기한이 지난 후 15일 이내에 환급해야 한다(같은 법 시행령 제107조 제4항).","c":"상","v":1},"공인회2020_55-34-1":{"w":"부가가치세법 시행령 제71조 제1항 제3호는 공급의제 재화의 세금계산서 발급의무를 면제하되 판매 목적 타사업장 반출(부가가치세법 제10조 제3항)은 제외한다. 반출하는 사업장이 세금계산서를 발급해야 한다.","c":"상","v":1},"공인회2020_55-34-2":{"w":"부가가치세법 시행령 제71조 제1항 제6호는 부동산임대용역 중 전세금·임대보증금에 대한 간주임대료에 세금계산서를 발급하지 않도록 정한다.","c":"상","v":1},"공인회2020_55-34-3":{"w":"부가가치세법 시행령 제71조 제1항 제4호는 영세율 재화 중 내국신용장·구매확인서로 공급하는 재화를 세금계산서 발급의무 면제 대상에서 뺀다. 사업자 간 거래여서 발급의무가 있다.","c":"상","v":1},"공인회2020_55-34-4":{"w":"개인사업자는 직전 연도 과세·면세 공급가액 합계가 기준금액(지금 8천만원) 이상이면 그다음 해 7월 1일부터 전자세금계산서를 발급해야 한다(부가가치세법 제32조 제2항, 같은 법 시행령 제68조 제1항·제2항). 합계 4억원이므로 해당한다.","c":"상","v":1},"공인회2021_56-36-2":{"w":"부가가치세법 시행령 제75조 제3호는 공급시기 후에 발급받은 세금계산서라도 그 공급시기가 속하는 과세기간의 확정신고기한까지 발급받았으면 매입세액공제를 허용한다.","c":"상","v":1},"공인회2021_56-36-3":{"w":"부가가치세법 제46조 제3항은 일반과세자로부터 부가가치세액이 별도로 적힌 신용카드매출전표 등을 발급받고 그 수령명세서를 제출하며 확정신고기한 후 5년간 보관하는 등의 요건을 갖추면 매입세액을 공제하도록 정한다.","c":"상","v":1},"공인회2021_56-37-5":{"w":"대손세액공제(부가가치세법 제45조)는 매출세액에서 대손세액을 빼는 일반과세자의 납부세액 계산(같은 법 제37조 제2항)에 적용된다. 간이과세자는 공급대가에 업종별 부가가치율을 곱해 납부세액을 계산하므로(같은 법 제63조) 대손세액공제가 없다.","c":"중","v":1},"공인회2022_57-31-1":{"w":"부가가치세법 시행령 제8조 제4항 단서는 무인자동판매기를 통한 사업은 업무를 총괄하는 장소만 사업장으로 하고 그 밖의 장소를 추가 사업장으로 등록할 수 없게 한다.","c":"상","v":1},"공인회2022_57-31-2":{"w":"부가가치세법 시행령 제92조 제1항은 법인이 본점뿐 아니라 지점(분사무소)을 주된 사업장으로 하여 주사업장 총괄 납부를 신청할 수 있게 한다.","c":"상","v":1},"공인회2022_57-31-4":{"w":"부가가치세법 시행령 제8조 제5항은 사업장을 설치하지 않고 사업자등록도 하지 않았으면 결정·경정 당시 사업자의 주소 또는 거소를 사업장으로 한다.","c":"상","v":1},"공인회2022_57-31-5":{"w":"부가가치세법 제6조 제4항은 사업자 단위 과세 사업자의 납세지를 각 사업장 대신 본점 또는 주사무소 소재지로 정한다.","c":"상","v":1},"공인회2022_57-37-4":{"w":"부가가치세법 시행령 제90조 제1항은 예정신고·납부 때 가산세(부가가치세법 제60조, 국세기본법 제47조의2부터 제47조의4)는 적용하지 않고 신용카드매출전표 발급 세액공제(부가가치세법 제46조)와 전자세금계산서 발급 세액공제(제47조)는 적용하도록 정한다.","c":"상","v":1},"공인회2023_58-30-5":{"w":"부가가치세법 시행령 제17조 제3항은 사업자 단위 과세를 포기하면 포기한 날이 속하는 과세기간의 다음 과세기간부터 각 사업장별로 신고·납부하거나 주사업장 총괄 납부를 하도록 정한다.","c":"상","v":1},"공인회2023_58-35-2":{"w":"부가가치세법 시행령 제69조 제2항은 위탁판매에서 위탁자가 재화를 직접 인도하면 위탁자가 세금계산서를 발급할 수 있되 수탁자의 등록번호를 덧붙여 적도록 정한다.","c":"상","v":1},"공인회2023_58-35-4":{"w":"부가가치세법 시행령 제70조 제1항 제1호는 재화가 환입되면 환입된 날을 작성일로 하고 비고란에 처음 작성일을 덧붙여 붉은색 글씨나 음(-)의 표시로 수정세금계산서를 발급하도록 정한다.","c":"상","v":1},"공인회2023_58-35-5":{"w":"부가가치세법 제35조 제1항은 세관장이 수입되는 재화에 대해 수입하는 자에게 수입세금계산서를 발급하도록 정한다.","c":"상","v":1},"공인회2024_59-30-1":{"w":"부가가치세법 시행령 제8조 제1항의 사업장 표는 다단계판매원의 사업장을 그가 등록한 다단계판매업자의 주된 사업장으로 하되 다단계판매원이 상시 주재하여 거래하는 별도 장소가 있으면 그 장소로 정한다.","c":"중","v":1},"공인회2025_60-34-2":{"w":"부가가치세법 제33조 제2항은 신용카드매출전표 등을 발급한 경우 세금계산서를 발급하지 않도록 정한다. 소매업자가 상대방 요구로 세금계산서를 발급할 수 있는 경우(같은 법 제36조 제3항)도 신용카드매출전표를 발급했으면 해당하지 않는다.","c":"상","v":1},"공인회2025_60-37-1":{"w":"부가가치세법 제60조 제3항 제3호는 재화·용역을 공급하고 실제 공급자가 아닌 자 등의 명의로 세금계산서등을 발급하면 그 공급가액의 2%를 가산세로 정한다.","c":"상","v":1},"공인회2016_51-38-2":{"w":"비상장주식은 순손익가치와 순자산가치를 가중평균하는 것이 원칙이지만 상속세 및 증여세법 시행령 제54조 제4항 제2호는 사업개시 후 3년 미만인 법인의 주식을 순자산가치로만 평가하도록 정한다.","c":"상","v":1},"공인회2017_52-37-1":{"w":"상속세 및 증여세법 제3조 제1호는 피상속인이 거주자이면 국내외 모든 상속재산에, 비거주자이면 국내 상속재산에만 상속세를 부과하도록 정한다.","c":"상","v":1},"공인회2017_52-37-3":{"w":"상속세 및 증여세법 제9조 제2항은 피상속인이 신탁으로 타인으로부터 신탁의 이익을 받을 권리를 가지고 있으면 그 이익에 상당하는 가액을 상속재산에 포함한다.","c":"상","v":1},"공인회2017_52-37-4":{"w":"상속세 및 증여세법 제71조 제1항은 상속세나 증여세 납부세액이 2천만원을 초과하면 납세의무자의 신청을 받아 연부연납을 허가할 수 있게 한다.","c":"상","v":1},"공인회2017_52-37-5":{"w":"상속세 및 증여세법 제11조는 전쟁이나 대통령령으로 정하는 공무 수행 중 사망하거나 그 과정에서 입은 부상·질병으로 사망해 상속이 개시되면 상속세를 부과하지 않는다고 정한다.","c":"상","v":1},"공인회2017_52-38-2":{"w":"상속세 및 증여세법 제4조 제4항은 신고기한까지 반환하면 처음부터 증여가 없던 것으로 보고 신고기한 후 3개월 이내 반환하면 반환분만 비과세한다. 그 뒤에 반환하면 당초 증여와 반환 모두 증여세 대상이다.","c":"상","v":1},"공인회2017_52-38-3":{"w":"상속세 및 증여세법 제47조 제1항은 증여재산에 담보된 채무로서 수증자가 인수한 금액을 증여재산가액에서 뺀다. 배우자·직계존비속 간 부담부증여만 채무 인수가 없는 것으로 추정한다(같은 조 제3항).","c":"상","v":1},"공인회2017_52-38-4":{"w":"상속세 및 증여세법 제68조 제1항은 증여세 납부의무자가 증여받은 날이 속하는 달의 말일부터 3개월 이내에 과세가액과 과세표준을 신고하도록 정한다.","c":"상","v":1},"공인회2017_52-38-5":{"w":"상속세 및 증여세법 제53조 제2호는 직계존속으로부터 받은 증여의 공제액을 10년간 5천만원으로 하되 미성년자는 2천만원으로 정한다.","c":"상","v":1},"공인회2018_53-38-2":{"w":"상속세 및 증여세법 제12조 제1호는 국가·지방자치단체 또는 공공단체에 유증한 재산에 상속세를 부과하지 않는다고 정한다.","c":"상","v":1},"공인회2019_54-38-1":{"w":"상속세 및 증여세법 제29조는 거주자의 사망으로 외국에 있는 상속재산에 외국 상속세가 부과되면 그 외국납부세액 상당액을 상속세 산출세액에서 공제하도록 정한다.","c":"상","v":1},"공인회2019_54-38-2":{"w":"상속세 및 증여세법 제71조 제1항은 상속세 납부세액이 2천만원을 초과하면 신청을 받아 연부연납을 허가할 수 있게 한다.","c":"상","v":1},"공인회2019_54-38-3":{"w":"상속세 및 증여세법 제19조 제1항은 배우자가 실제 상속받은 금액을 법정상속분 기준 한도와 30억원 중 작은 금액 한도로 공제하고 같은 조 제4항은 실제 상속받은 금액이 없거나 5억원 미만이면 5억원을 공제한다.","c":"상","v":1},"공인회2019_54-38-5":{"w":"상속세 및 증여세법 제15조 제1항 제2호는 피상속인이 상속개시일 전 1년 이내에 2억원 이상(2년 이내 5억원 이상) 부담한 채무로서 용도가 객관적으로 명백하지 않으면 상속받은 것으로 추정해 과세가액에 산입한다.","c":"상","v":1},"공인회2021_56-38-1":{"w":"상속세 및 증여세법 제46조 제1호는 국가나 지방자치단체로부터 증여받은 재산의 가액에 증여세를 부과하지 않는다고 정한다.","c":"상","v":1},"공인회2021_56-38-3":{"w":"상속세 및 증여세법 제46조 제7호는 국가·지방자치단체 또는 공공단체가 증여받은 재산의 가액에 증여세를 부과하지 않는다고 정한다.","c":"상","v":1},"공인회2021_56-38-4":{"w":"상속세 및 증여세법 제46조 제10호는 설립근거 법령의 변경으로 비영리법인이 해산되거나 업무가 변경되어 다른 비영리법인이 재산과 권리·의무를 승계한 경우 승계받은 재산에 증여세를 부과하지 않는다고 정한다.","c":"상","v":1},"공인회2021_56-38-5":{"w":"상속세 및 증여세법 제52조는 공익신탁법에 따른 공익신탁으로서 종교·자선·학술 등 공익 목적 신탁을 통해 공익법인 등에 출연하는 재산을 증여세 과세가액에 산입하지 않는다고 정한다.","c":"상","v":1},"공인회2022_57-38-1":{"w":"상속세 및 증여세법 제4조의2 제1항 제1호는 수증자가 거주자(국내에 본점 등이 있는 비영리법인 포함)이면 과세대상 증여재산 전부에 증여세 납부의무를 지운다. 비거주자는 국내 증여재산 등에 한정된다(같은 항 제2호).","c":"상","v":1},"공인회2022_57-38-3":{"w":"상속세 및 증여세법 제47조 제2항은 증여일 전 10년 이내에 동일인(직계존속이면 그 배우자 포함)으로부터 받은 증여재산가액 합계가 1천만원 이상이면 증여세 과세가액에 가산하도록 정한다.","c":"상","v":1},"공인회2022_57-38-4":{"w":"상속세 및 증여세법 제4조의2 제2항은 명의신탁재산 증여의제(같은 법 제45조의2)의 경우 명의자가 아니라 실제소유자가 증여세를 납부할 의무를 진다고 정한다.","c":"상","v":1},"공인회2022_57-38-5":{"w":"상속세 및 증여세법 제4조 제4항은 금전이 아닌 증여재산을 합의에 따라 신고기한까지 증여자에게 반환하면(반환 전에 과세표준과 세액을 결정받은 경우 제외) 처음부터 증여가 없던 것으로 본다.","c":"상","v":1},"공인회2023_58-39-1":{"w":"상속세 및 증여세법 제2조 제3호는 상속재산을 피상속인에게 귀속되는 모든 재산으로 정의하면서 피상속인의 일신에 전속하는 것으로서 사망으로 소멸되는 것은 제외한다.","c":"상","v":1},"공인회2024_59-38-1":{"w":"상속세 및 증여세법 제8조 제1항은 피상속인의 사망으로 받는 생명보험·손해보험 보험금으로서 피상속인이 보험계약자인 계약에 따라 받는 것을 상속재산으로 본다.","c":"상","v":1},"공인회2024_59-38-2":{"w":"상속세 및 증여세법 제12조 제1호는 국가·지방자치단체 또는 공공단체에 유증한 재산에 상속세를 부과하지 않는다고 정한다.","c":"상","v":1},"공인회2024_59-38-3":{"w":"상속세 및 증여세법 제9조 제2항은 피상속인이 신탁으로 타인으로부터 신탁의 이익을 받을 권리를 가지고 있으면 그 이익 상당액을 상속재산에 포함한다.","c":"상","v":1},"공인회2024_59-38-4":{"w":"상속세 및 증여세법 제18조는 거주자나 비거주자의 사망으로 상속이 개시되면 상속세 과세가액에서 기초공제 2억원을 공제한다고 정한다.","c":"상","v":1},"공인회2017_52-35-4":{"old":1,"ow":"출제 당시 정답 O. 2020.12.22 개정(2021.7.1 시행)으로 간이과세자의 매입세액 공제는 세금계산서 등을 받은 공급대가에 0.5%를 곱한 금액이 되어, 매입세액에 업종별 부가가치율을 곱한다는 문장은 틀리다(부가가치세법 제63조 제3항)."},"공인회2019_54-04-2":{"old":1,"ow":"출제 당시 정답 O. 2024.12.31 개정으로 납부고지분 국세에 충당할 수 있는 소액 환급금 기준이 20만원 이하로 올라, 10만원 이하를 기준으로 적은 문장은 현행 조문과 맞지 않는다(국세기본법 제51조 제8항)."},"공인회2019_54-19-3":{"old":1,"ow":"출제 당시 정답 O. 2022.12.31 개정(2023.1.1 시행)으로 중소기업 중간예납 면제 기준이 50만원 미만으로 올라, 30만원 미만을 기준으로 적은 문장은 현행 조문과 맞지 않는다(법인세법 제63조 제1항 제2호)."},"공인회2020_55-38-2":{"old":1,"ow":"출제 당시 정답 O. 2022.12.31 개정(2023.1.1 시행)으로 가업상속공제에서 빠지는 중견기업 기준이 직전 3개 사업연도 매출액 평균 5천억원 이상으로 바뀌어, 3천억원 이상이면 제외된다는 문장은 틀리다(상속세 및 증여세법 제18조의2 제1항)."},"공인회2021_56-36-4":{"old":1,"ow":"출제 당시 정답 O. 2022.2.15 시행령 개정으로 공급시기 전에 받은 세금계산서의 매입세액 공제 요건이 발급일부터 6개월 이내 공급시기 도래로 늘어, 30일 이내를 요건으로 적은 문장은 현행 조문과 맞지 않는다(부가가치세법 시행령 제75조 제8호)."},"공인회2021_56-36-5":{"old":1,"ow":"출제 당시 정답 O. 2022.2.15 시행령 개정으로 확정신고기한 뒤 발급받은 세금계산서의 매입세액 공제 기한이 확정신고기한 다음 날부터 1년 이내로 늘어, 6개월 이내로 적은 문장은 현행 조문과 맞지 않는다(부가가치세법 시행령 제75조 제7호)."},"공인회2022_57-06-3":{"old":1,"ow":"출제 당시 정답 O. 2022.12.31 개정(2023.1.1 이후 증여분부터)으로 증여 후 우회양도를 증여자의 양도로 보는 기간이 증여일부터 10년 이내로 늘어, 5년 이내로 적은 문장은 현행 조문과 맞지 않는다(소득세법 제101조 제2항·제3항)."},"공인회2023_58-35-3":{"old":1,"ow":"출제 당시 정답 O. 2023.2.28 시행령 개정으로 매입자발행세금계산서의 거래사실 확인 신청기한이 공급시기가 속하는 과세기간 종료일부터 1년 이내로 늘어, 6개월 이내에 신청해야 한다는 문장은 틀리다(부가가치세법 시행령 제71조의2 제3항)."},"공인회2023_58-21-3":{"old":1,"ow":"출제 당시 정답 O. 2025년 개정(2026.1.1 이후 발생 소득분부터)으로 조림기간 5년 이상 임목의 벌채·양도소득 비과세 한도가 연 3천만원으로 올라, 연 600만원 이하를 한도로 적은 문장은 현행 조문과 맞지 않는다(소득세법 제12조 제2호 마목)."},"공인회2016_51-05-4":{"old":1,"ow":"출제 당시 정답 O로 처리됐다. 지금 국세기본법 제45조의2 제1항은 법정신고기한까지 과세표준신고서를 낸 자뿐 아니라 제45조의3 제1항에 따른 기한후과세표준신고서를 낸 자도 경정청구를 할 수 있게 한다. 기한 내 신고자여야 한다는 문장은 현행법과 맞지 않는다."},"공인회2024_59-01-4":{"old":1,"ow":"출제 당시 정답 O. 2024.12.31 국세기본법 개정(2025.1.1 시행)으로 전자송달 신청 철회 간주 요건이 2회 연속 미열람에서 3회 연속 미열람으로 바뀌었다. 지금은 3회 연속 열람하지 않아야 철회한 것으로 보고 납부고지서나 독촉장 세액을 납부기한까지 전액 납부하면 철회로 보지 않는다(국세기본법 제10조 제9항)."},"공인회2018_53-08-1":{"old":1,"ow":"출제 당시 정답 O(세무조정 필요). 당시 법인세법 시행령 제19조 제17호는 전시 미술품의 손금 한도를 거래단위별 500만원 이하로 정해 1천만원짜리는 손금불산입 대상이었다. 그 뒤 시행령 개정으로 한도가 1천만원 이하로 올라 지금은 비용 계상한 1천만원이 그대로 손금이어서 세무조정이 필요 없다."},"공인회2016_51-18-4":{"old":1,"ow":"출제 당시 정답 O. 2020.12.22 법인세법 개정(2021.1.1 이후 개시 사업연도부터)으로 외국법인세액을 손금에 산입하는 방법은 없어지고 세액공제만 남았다. 지금은 공제한도 내에서 세액공제하고 한도 초과액은 10년간 이월공제하며 그 기간에 공제받지 못한 금액만 손금에 산입한다(법인세법 제57조 제1항·제2항, 제21조 제1호)."},"공인회2016_51-18-5":{"old":1,"ow":"출제 당시 정답 O. 2016.12.20 법인세법 개정(2017.1.1 시행)으로 5년 기간 제한이 없어졌다. 지금은 경정일이 속하는 사업연도부터 각 사업연도 법인세액에서 과다납부세액의 20%를 한도로 공제하고 남은 금액은 이후 사업연도로 계속 이월해 공제한다(법인세법 제58조의3 제1항)."},"공인회2018_53-18-1":{"old":1,"ow":"출제 당시 정답 O. 법인세법 시행령 개정(2022.2.15)으로 신청기한 특례가 1개월에서 3개월로 늘었다. 지금은 재해발생일부터 신고기한까지 3개월 미만이면 재해발생일부터 3개월 안에 신청한다(법인세법 시행령 제95조 제5항 제1호)."},"공인회2022_57-06-1":{"old":1,"ow":"출제 당시 정답 O. 2023.12.31 소득세법 개정(2024.1.1 시행)으로 제2조의3 제2항에서 수익자가 특별히 정해지지 않거나 존재하지 않는 신탁을 위탁자 귀속으로 보는 부분이 삭제됐다. 지금은 위탁자가 신탁재산을 실질적으로 통제하는 등 같은 법 시행령 제4조의2 제4항의 요건을 갖춘 신탁만 위탁자에게 귀속시킨다."}};
